app = Flask(__name__)

@app.get('/api/engine-v2/status')
def engine_v2_status():
    model = _load_v2_frozen_model()
    proven = 0
    if isinstance(model, dict):
        proven += sum(1 for v in (model.get('groups') or {}).values() if v.get('proven'))
        proven += sum(1 for v in (model.get('families') or {}).values() if v.get('proven'))
    v3_2_status = {
        'engine_version': v3_2_engine.ENGINE_VERSION,
        'enabled': bool(V3_2_ENGINE_ENABLED),
        'production_authorized': bool(V3_2_PRODUCTION_AUTHORIZED),
        'signal_interval': V3_2_SIGNAL_INTERVAL,
        'execution_interval': V3_2_EXECUTION_INTERVAL,
        'label_model': V3_2_LABEL_MODEL,
        'cost_model_version': V3_2_COST_MODEL_VERSION,
        'requires_real_1m_for_paper': bool(V3_2_REQUIRE_REAL_1M_FOR_PAPER),
        'requires_quotes_for_live': bool(V3_2_REQUIRE_QUOTES_FOR_LIVE),
    }
    sources = {}
    try:
        with open(V2_MASTER_DATA_SOURCES_PATH, 'r', encoding='utf-8') as fh:
            sources = json.load(fh)
    except Exception:
        pass
    return jsonify({
        'engine_version': v2_engine.ENGINE_VERSION,
        'enabled': bool(V2_ENGINE_ENABLED),
        'edge_gate_enabled': bool(V2_EDGE_GATE_ENABLED),
        'require_proven_edge': bool(V2_REQUIRE_PROVEN_EDGE),
        'signal_interval': V2_SIGNAL_INTERVAL,
        'execution_interval': V2_EXECUTION_INTERVAL,
        'data_contract': V2_DATA_CONTRACT,
        'require_economic_edge': bool(V2_REQUIRE_ECONOMIC_EDGE),
        'min_net_edge_pct': V2_MIN_NET_EDGE_PCT,
        'slippage_stress_bps': V2_SLIPPAGE_STRESS_BPS,
        'frozen_model_path': V2_MODEL_PATH,
        'frozen_model_loaded': bool(model),
        'proven_buckets': proven,
        'master_data_sources': sources,
    })

@app.get('/api/engine-v3/status')
def engine_v3_status():
    sources = {}
    try:
        src = os.path.join(os.path.dirname(__file__), 'data', 'master_data_sources.json')
        with open(src, 'r', encoding='utf-8') as fh:
            sources = json.load(fh)
    except Exception:
        pass
    return jsonify({
        'engine_version': v3_core.ENGINE_VERSION,
        'data_acquisition_sources': v3_data_acquisition.source_catalog(),
        'real_1m_history_requirement': 'required_for_1m_execution_validation',
        'enabled': bool(V3_ENGINE_ENABLED),
        'production_authorized': bool(V3_PRODUCTION_AUTHORIZED),
        'require_proven_edge': bool(V3_REQUIRE_PROVEN_EDGE),
        'require_economic_edge': bool(V3_REQUIRE_ECONOMIC_EDGE),
        'signal_interval': V3_SIGNAL_INTERVAL,
        'execution_interval': V3_EXECUTION_INTERVAL,
        'data_contract': V3_DATA_CONTRACT,
        'capital': V3_CAPITAL,
        'notional': V3_NOTIONAL,
        'min_net_edge_pct': V3_MIN_NET_EDGE_PCT,
        'edge_to_cost_multiple': V3_EDGE_TO_COST_MULTIPLE,
        'stress_slippage_bps': V3_STRESS_SLIPPAGE_BPS,
        'live_execution_requires_real_1m': True,
        'master_data_sources': sources,
    })

