init_db()


def iter_chunks(items: List[str], size: int) -> Iterable[List[str]]:
    for i in range(0, len(items), size):
        yield items[i:i + size]


# Some exchange symbols change after mergers/demergers/name changes. Keep the
# app from repeatedly asking yfinance for stale symbols that now return 404.
# Users can override the full universe with MARKET_UNIVERSE_IN/US/GLOBAL.
KNOWN_TICKER_ALIASES = {
    'TATAMOTORS.NS': 'TMCV.NS',      # Tata Motors post-demerger/current Yahoo/NSE symbol
    'ADANITRANS.NS': 'ADANIENSOL.NS',
}


def clean_tickers(tickers: Iterable[str]) -> List[str]:
    seen = set()
    cleaned = []
    for raw in tickers:
        t = str(raw).strip().upper()
        if not t or t.startswith('#'):
            continue
        # Replace old/stale symbols with the current data-provider symbol.
        # This prevents backtests from failing on known 404 symbols like TATAMOTORS.NS.
        t = KNOWN_TICKER_ALIASES.get(t, t)
        if not t or t in seen:
            continue
        seen.add(t)
        cleaned.append(t)
    return cleaned


def load_market_universe(market: str) -> List[str]:
    env_key = f"MARKET_UNIVERSE_{market.upper()}"
    if os.environ.get(env_key):
        return clean_tickers(os.environ[env_key].replace('\n', ',').split(','))

    file_path = os.path.join(os.path.dirname(__file__), 'data', f'universe_{market}.txt')
    if os.path.exists(file_path):
        with open(file_path, 'r', encoding='utf-8') as f:
            return clean_tickers(f.read().replace('\n', ',').split(','))

    return clean_tickers(DEFAULT_UNIVERSES.get(market, DEFAULT_UNIVERSES['IN']))


def compute_rsi(prices, period=14):
    if len(prices) < period + 1:
        return None
    deltas = np.diff(prices)
    gains = np.where(deltas > 0, deltas, 0.0)
    losses = np.where(deltas < 0, -deltas, 0.0)
    avg_gain = float(np.mean(gains[-period:]))
    avg_loss = float(np.mean(losses[-period:]))
    if avg_loss == 0:
        return 100.0
    rs = avg_gain / avg_loss
    return round(100 - (100 / (1 + rs)), 1)


def compute_ema(prices, span):
    if len(prices) == 0:
        return None
    k = 2 / (span + 1)
    ema = float(prices[0])
    for p in prices[1:]:
        ema = float(p) * k + ema * (1 - k)
    return ema


def compute_macd(prices):
    if len(prices) < 35:
        return None, None, None
    ema12 = compute_ema(prices[-60:], 12)
    ema26 = compute_ema(prices[-60:], 26)
    if ema12 is None or ema26 is None:
        return None, None, None
    macd = ema12 - ema26

    macd_series = []
    recent = prices[-60:]
    for i in range(26, len(recent) + 1):
        e12 = compute_ema(recent[:i], 12)
        e26 = compute_ema(recent[:i], 26)
        if e12 is not None and e26 is not None:
            macd_series.append(e12 - e26)
    signal = compute_ema(macd_series[-9:], 9) if len(macd_series) >= 9 else macd
    hist = macd - signal
    return round(macd, 4), round(signal, 4), round(hist, 4)


def pct_change(current: float, past: Optional[float]) -> Optional[float]:
    if not past or past == 0:
        return None
    return round(((current - float(past)) / float(past)) * 100, 2)


def build_stock_snapshot(ticker: str, hist) -> Optional[Dict[str, Any]]:
    try:
        if hist is None or hist.empty or 'Close' not in hist:
            return None
        hist = hist.dropna(subset=['Close'])
        if hist.empty or len(hist) < 30:
            return None

        closes = hist['Close'].astype(float).values
        highs = hist['High'].astype(float).values if 'High' in hist else closes
        lows = hist['Low'].astype(float).values if 'Low' in hist else closes
        volumes = hist['Volume'].fillna(0).astype(float).values if 'Volume' in hist else np.zeros(len(closes))

        current = round(float(closes[-1]), 2)
        if current <= 0:
            return None
        prev = float(closes[-2]) if len(closes) >= 2 else current
        day_chg = pct_change(current, prev)
        week_chg = pct_change(current, closes[-5]) if len(closes) >= 5 else None
        month_chg = pct_change(current, closes[-22]) if len(closes) >= 22 else None
        quarter_chg = pct_change(current, closes[-63]) if len(closes) >= 63 else None
        six_month_chg = pct_change(current, closes[-126]) if len(closes) >= 126 else None

        rsi = compute_rsi(closes)
        macd, macd_sig, macd_hist = compute_macd(closes)
        ma20 = round(float(np.mean(closes[-20:])), 2) if len(closes) >= 20 else None
        ma50 = round(float(np.mean(closes[-50:])), 2) if len(closes) >= 50 else None
        ma200 = round(float(np.mean(closes[-200:])), 2) if len(closes) >= 200 else None
        avg_vol_20 = int(np.mean(volumes[-20:])) if len(volumes) >= 20 else int(np.mean(volumes))
        avg_vol_50 = int(np.mean(volumes[-50:])) if len(volumes) >= 50 else avg_vol_20
        vol_ratio = round(float(volumes[-1]) / avg_vol_20, 2) if avg_vol_20 > 0 else 1.0
        avg_dollar_volume_20 = round(avg_vol_20 * current, 2)

        year_high = round(float(max(highs[-252:] if len(highs) >= 252 else highs)), 2)
        year_low = round(float(min(lows[-252:] if len(lows) >= 252 else lows)), 2)
        pct_from_high = pct_change(current, year_high)
        pct_from_low = pct_change(current, year_low)

        if len(closes) >= 20:
            std20 = float(np.std(closes[-20:]))
            bb_upper = round(ma20 + 2 * std20, 2)
            bb_lower = round(ma20 - 2 * std20, 2)
            bb_position = round((current - bb_lower) / (bb_upper - bb_lower) * 100, 1) if (bb_upper - bb_lower) != 0 else 50.0
        else:
            bb_upper = bb_lower = bb_position = None

        support_20 = round(float(min(lows[-20:])), 2)
        resistance_20 = round(float(max(highs[-20:])), 2)
        support_distance_pct = round(((current - support_20) / current) * 100, 2) if current else None
        resistance_distance_pct = round(((resistance_20 - current) / current) * 100, 2) if current else None

        return {
            'ticker': ticker,
            'company': ticker,
            'sector': 'N/A',
            'current_price': current,
            'day_change_pct': day_chg,
            'week_change_pct': week_chg,
            'month_change_pct': month_chg,
            'quarter_change_pct': quarter_chg,
            'six_month_change_pct': six_month_chg,
            'rsi_14': rsi,
            'macd': macd,
            'macd_signal': macd_sig,
            'macd_histogram': macd_hist,
            'macd_crossover': 'bullish' if (macd is not None and macd_sig is not None and macd > macd_sig) else 'bearish',
            'ma20': ma20,
            'ma50': ma50,
            'ma200': ma200,
            'price_vs_ma20_pct': round(((current - ma20) / ma20) * 100, 2) if ma20 else None,
            'price_vs_ma50_pct': round(((current - ma50) / ma50) * 100, 2) if ma50 else None,
            'price_vs_ma200_pct': round(((current - ma200) / ma200) * 100, 2) if ma200 else None,
            'bb_upper': bb_upper,
            'bb_lower': bb_lower,
            'bb_position_pct': bb_position,
            'volume_ratio_vs_20d_avg': vol_ratio,
            'avg_volume_20': avg_vol_20,
            'avg_volume_50': avg_vol_50,
            'avg_dollar_volume_20': avg_dollar_volume_20,
            '52w_high': year_high,
            '52w_low': year_low,
            'pct_from_52w_high': pct_from_high,
            'pct_from_52w_low': pct_from_low,
            'support_20': support_20,
            'resistance_20': resistance_20,
            'support_distance_pct': support_distance_pct,
            'resistance_distance_pct': resistance_distance_pct,
        }
    except Exception as e:
        print(f"[WARN] Snapshot failed for {ticker}: {e}")
        return None


def extract_ticker_frame(data, ticker: str, chunk_size: int):
    if data is None or data.empty:
        return None
    try:
        if hasattr(data.columns, 'nlevels') and data.columns.nlevels > 1:
            if ticker in data.columns.get_level_values(0):
                return data[ticker].dropna(how='all')
            return None
        return data.dropna(how='all') if chunk_size == 1 else None
    except Exception:
        return None


def download_universe_snapshots(tickers: List[str]) -> List[Dict[str, Any]]:
    snapshots = []
    for chunk in iter_chunks(tickers, BATCH_SIZE):
        try:
            data = yf.download(
                tickers=' '.join(chunk),
                period='1y',
                interval='1d',
                group_by='ticker',
                auto_adjust=False,
                threads=True,
                progress=False,
                timeout=YF_TIMEOUT,
            )
        except Exception as e:
            print(f"[WARN] Batch download failed for {len(chunk)} tickers: {e}")
            data = None

        for ticker in chunk:
            frame = extract_ticker_frame(data, ticker, len(chunk))
            snapshot = build_stock_snapshot(ticker, frame)
            if snapshot:
                snapshots.append(snapshot)
    return snapshots


def liquidity_filter(snapshots: List[Dict[str, Any]], market: str) -> List[Dict[str, Any]]:
    rules = LIQUIDITY_RULES.get(market, LIQUIDITY_RULES['IN'])
    liquid = []
    for s in snapshots:
        if s.get('avg_volume_20', 0) >= rules['min_avg_volume_20'] and s.get('avg_dollar_volume_20', 0) >= rules['min_avg_dollar_volume_20']:
            s['quality_gate'] = {'passed': True, 'reason': 'Active/liquid enough for scan', 'rules': rules}
            liquid.append(s)
        else:
            s['quality_gate'] = {'passed': False, 'reason': 'Skipped: low average volume or low value traded', 'rules': rules}
    return liquid


def snapshot_passes_liquidity(snapshot: Dict[str, Any], market: str) -> Tuple[bool, str]:
    rules = LIQUIDITY_RULES.get(market, LIQUIDITY_RULES['IN'])
    vol = float(snapshot.get('avg_volume_20') or 0)
    value = float(snapshot.get('avg_dollar_volume_20') or 0)
    if vol < float(rules.get('min_avg_volume_20') or 0):
        return False, f'low average volume {round(vol):,}; needs {rules.get("min_avg_volume_20"):,}+'
    if value < float(rules.get('min_avg_dollar_volume_20') or 0):
        return False, f'low average traded value {round(value):,}; needs {rules.get("min_avg_dollar_volume_20"):,}+'
    return True, 'liquidity passed'


def score_momentum(s: Dict[str, Any]) -> float:
    score = 0.0
    for key, weight in [('week_change_pct', 0.65), ('month_change_pct', 0.45), ('quarter_change_pct', 0.25)]:
        val = s.get(key)
        if val is not None:
            score += max(min(float(val), 25), -25) * weight
    if s.get('price_vs_ma20_pct') is not None:
        score += max(min(float(s['price_vs_ma20_pct']), 12), -12) * 0.8
    if s.get('price_vs_ma50_pct') is not None:
        score += max(min(float(s['price_vs_ma50_pct']), 18), -18) * 0.5
    if s.get('volume_ratio_vs_20d_avg') is not None:
        score += min(max(float(s['volume_ratio_vs_20d_avg']) - 1.0, 0), 3.0) * 8
    if s.get('macd_histogram') is not None and s['macd_histogram'] > 0:
        score += 8
    if s.get('rsi_14') is not None:
        rsi = float(s['rsi_14'])
        if 45 <= rsi <= 68:
            score += 12
        elif 35 <= rsi < 45:
            score += 5
        elif rsi > 76:
            score -= 10
    return round(score, 2)


def score_technical(s: Dict[str, Any]) -> float:
    score = 0.0
    current = s.get('current_price')
    ma20, ma50, ma200 = s.get('ma20'), s.get('ma50'), s.get('ma200')
    if current and ma20 and ma50 and current > ma20 > ma50:
        score += 20
    elif current and ma20 and current > ma20:
        score += 9
    if ma50 and ma200 and ma50 > ma200:
        score += 12
    if s.get('macd_histogram') is not None:
        score += 14 if s['macd_histogram'] > 0 else -6
    if s.get('rsi_14') is not None:
        rsi = float(s['rsi_14'])
        if 50 <= rsi <= 65:
            score += 16
        elif 40 <= rsi < 50:
            score += 8
        elif 30 <= rsi < 40:
            score += 5
        elif rsi > 72:
            score -= 9
    if s.get('bb_position_pct') is not None:
        bb = float(s['bb_position_pct'])
        if 25 <= bb <= 75:
            score += 8
        elif bb < 20:
            score += 5
        elif bb > 90:
            score -= 8
    if s.get('resistance_distance_pct') is not None and s.get('support_distance_pct') is not None:
        upside = max(float(s['resistance_distance_pct']), 0.01)
        downside = max(float(s['support_distance_pct']), 0.01)
        rr_proxy = upside / downside
        score += min(rr_proxy * 5, 15)
    if s.get('volume_ratio_vs_20d_avg') is not None and s['volume_ratio_vs_20d_avg'] >= 1.3:
        score += 8
    return round(score, 2)


def apply_momentum_stage(liquid: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    for s in liquid:
        s['momentum_score'] = score_momentum(s)
    return sorted(liquid, key=lambda x: x.get('momentum_score', 0), reverse=True)[:MOMENTUM_STAGE_LIMIT]


def apply_technical_stage(candidates: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    for s in candidates:
        s['technical_score'] = score_technical(s)
        s['preliminary_score'] = round((s.get('momentum_score', 0) * 0.45) + (s.get('technical_score', 0) * 0.55), 2)
    return sorted(candidates, key=lambda x: x.get('preliminary_score', 0), reverse=True)[:TECHNICAL_STAGE_LIMIT]


def get_recent_news(stock, limit=3):
    try:
        raw = stock.news or []
    except Exception:
        return []
    headlines = []
    for item in raw[:limit]:
        node = item.get('content', item) if isinstance(item, dict) else {}
        title = node.get('title')
        provider = node.get('provider')
        publisher = provider.get('displayName') if isinstance(provider, dict) else node.get('publisher')
        if title:
            headlines.append({'title': title, 'source': publisher or 'unknown'})
    return headlines


POSITIVE_NEWS_WORDS = {
    'beat', 'beats', 'upgrade', 'upgraded', 'raises', 'raised', 'growth', 'record', 'profit', 'profits',
    'approval', 'approved', 'partnership', 'contract', 'buyback', 'dividend', 'launch', 'surge', 'rally',
    'strong', 'outperform', 'wins', 'expands', 'expansion'
}
NEGATIVE_NEWS_WORDS = {
    'miss', 'misses', 'downgrade', 'downgraded', 'cuts', 'cut', 'lawsuit', 'probe', 'investigation',
    'fraud', 'recall', 'slump', 'falls', 'fall', 'weak', 'loss', 'losses', 'layoffs', 'warning',
    'regulatory', 'penalty', 'fine', 'bankruptcy', 'default'
}


def score_news_sentiment(headlines: List[Dict[str, str]]) -> Tuple[int, str]:
    if not headlines:
        return 0, 'No material recent headlines found; technical and fundamental setup carries more weight.'
    score = 0
    titles = []
    for h in headlines:
        title = h.get('title', '')
        titles.append(title)
        tokens = set(re.findall(r"[a-zA-Z]+", title.lower()))
        score += 6 * len(tokens & POSITIVE_NEWS_WORDS)
        score -= 8 * len(tokens & NEGATIVE_NEWS_WORDS)
    score = max(min(score, 20), -25)
    if score > 0:
        summary = 'Recent headlines lean positive and support the setup.'
    elif score < 0:
        summary = 'Recent headlines contain negative-risk language; confidence is reduced.'
    else:
        summary = 'Recent headlines look neutral; no obvious catalyst edge from news.'
    return score, summary


MACRO_RISK_KEYWORDS = {
    'war/geopolitical shock': {'war','wars','attack','attacks','missile','conflict','invasion','border','sanction','sanctions','geopolitical','hostage','terror','escalation'},
    'tariff/trade policy': {'tariff','tariffs','duties','duty','trade','trade-deal','deal','import','export','quota','protectionism'},
    'rates/inflation': {'inflation','rate','rates','fed','rbi','yield','yields','hawkish','recession','slowdown','cpi','policy'},
    'oil/energy shock': {'oil','crude','brent','opec','gas','energy','fuel'},
    'currency/rupee-dollar risk': {'dollar','rupee','usd','currency','forex','devaluation'},
    'regulation/legal risk': {'regulatory','probe','investigation','lawsuit','ban','penalty','fine','fraud'},
    'positive trade/easing catalyst': {'ceasefire','easing','stimulus','cut','cuts','deal','agreement','approval','peace','record','beat','growth'},
}


def macro_news_tickers(market: str) -> List[str]:
    return ['^NSEI', '^NSEBANK', 'INDA', 'INR=X', 'CL=F', 'GC=F']


def get_macro_event_context(market: str) -> Dict[str, Any]:
    """Current macro/news risk used only for forward-looking decisions.

    This does not promise to catch every event. It uses free/yfinance headlines
    plus optional manual override env vars. For live capital, connect a proper
    news provider and keep manual risk overrides available during shocks.
    """
    if not MACRO_RISK_ENABLED:
        return {'enabled': False, 'risk_level': 'not_used', 'risk_score': 0, 'decision': 'not_used', 'factors': [], 'headlines': []}
    manual_map = {'low': 0, 'caution': MACRO_RISK_CAUTION_THRESHOLD, 'high': MACRO_RISK_BLOCK_THRESHOLD, 'block': MACRO_RISK_BLOCK_THRESHOLD + 10}
    headlines: List[Dict[str, Any]] = []
    factors: Dict[str, int] = {}
    risk_score = 0.0
    positive_offset = 0.0
    try:
        for t in macro_news_tickers(market):
            if len(headlines) >= MACRO_RISK_HEADLINE_LIMIT:
                break
            for h in get_recent_news(yf.Ticker(t), limit=4):
                title = h.get('title') or ''
                low = title.lower()
                tokens = set(re.findall(r"[a-zA-Z-]+", low))
                local_score = 0
                local_factors = []
                for label, words in MACRO_RISK_KEYWORDS.items():
                    hit = tokens & words
                    if not hit:
                        continue
                    local_factors.append(label)
                    factors[label] = factors.get(label, 0) + len(hit)
                    if label.startswith('positive'):
                        positive_offset += 4 * len(hit)
                    elif label in ('war/geopolitical shock', 'tariff/trade policy'):
                        local_score += 10 * len(hit)
                    elif label in ('rates/inflation', 'oil/energy shock'):
                        local_score += 7 * len(hit)
                    else:
                        local_score += 6 * len(hit)
                if local_score or local_factors:
                    headlines.append({**h, 'ticker': t, 'risk_score': local_score, 'factors': local_factors})
                    risk_score += local_score
        risk_score = max(0.0, min(80.0, risk_score - min(positive_offset, 18)))
    except Exception as e:
        return {'enabled': True, 'risk_level': 'unknown', 'risk_score': 0, 'decision': 'normal', 'factors': [], 'headlines': [], 'warning': str(e)[:160]}
    if MACRO_RISK_MANUAL_LEVEL in manual_map:
        risk_score = max(risk_score, float(manual_map[MACRO_RISK_MANUAL_LEVEL]))
        headlines.insert(0, {'title': MACRO_RISK_MANUAL_NOTE or f'Manual macro risk override: {MACRO_RISK_MANUAL_LEVEL}', 'source': 'manual override', 'ticker': market, 'risk_score': risk_score, 'factors': ['manual override']})
        factors['manual override'] = factors.get('manual override', 0) + 1
    if risk_score >= MACRO_RISK_BLOCK_THRESHOLD:
        risk_level = 'high_risk'
        decision = 'block_or_reduce_new_entries'
        note = 'Major event risk detected. System should avoid new trades unless setup is exceptional and risk controls are tight.'
    elif risk_score >= MACRO_RISK_CAUTION_THRESHOLD:
        risk_level = 'caution'
        decision = 'reduce_confidence_and_size'
        note = 'Macro/news risk exists. System should reduce confidence, demand stronger confirmation, and trade less.'
    else:
        risk_level = 'normal'
        decision = 'normal'
        note = 'No major macro/news risk detected from available free headlines.'
    return {
        'enabled': True,
        'risk_level': risk_level,
        'risk_score': round(risk_score, 2),
        'decision': decision,
        'note': note,
        'factors': sorted(factors.items(), key=lambda kv: kv[1], reverse=True)[:8],
        'headlines': headlines[:MACRO_RISK_HEADLINE_LIMIT],
        'thresholds': {'caution': MACRO_RISK_CAUTION_THRESHOLD, 'block': MACRO_RISK_BLOCK_THRESHOLD},
        'important_note': 'Current macro/news layer is used for forward scans/trading. Historical backtests intentionally do not use today’s news to avoid lookahead bias.',
    }


def merge_macro_into_market_context(base_context: Optional[Dict[str, Any]], market: str) -> Dict[str, Any]:
    ctx = dict(base_context or {})
    macro = get_macro_event_context(market)
    ctx['macro_event_risk'] = macro
    if macro.get('risk_level') == 'high_risk':
        ctx['regime'] = 'risk_off_or_high_vol'
        ctx['macro_block_new_trades'] = True
    elif macro.get('risk_level') == 'caution':
        ctx['macro_caution'] = True
    return ctx


def score_fundamentals(info: Dict[str, Any]) -> Tuple[float, Dict[str, Any]]:
    revenue_growth = info.get('revenueGrowth')
    earnings_growth = info.get('earningsQuarterlyGrowth')
    roe = info.get('returnOnEquity')
    debt_to_equity = info.get('debtToEquity')
    free_cashflow = info.get('freeCashflow')
    operating_cashflow = info.get('operatingCashflow')
    trailing_eps = info.get('trailingEps')
    profit_margins = info.get('profitMargins')
    current_ratio = info.get('currentRatio')

    score = 0.0
    if revenue_growth is not None:
        score += max(min(float(revenue_growth) * 100, 25), -20)
    if earnings_growth is not None:
        score += max(min(float(earnings_growth) * 60, 20), -20)
    if roe is not None:
        score += max(min(float(roe) * 80, 18), -10)
    if debt_to_equity is not None:
        score += 8 if float(debt_to_equity) < 80 else (-8 if float(debt_to_equity) > 200 else 0)
    if free_cashflow is not None:
        score += 8 if float(free_cashflow) > 0 else -8
    if operating_cashflow is not None:
        score += 6 if float(operating_cashflow) > 0 else -6
    if trailing_eps is not None:
        score += 6 if float(trailing_eps) > 0 else -6
    if profit_margins is not None:
        score += max(min(float(profit_margins) * 50, 10), -8)
    if current_ratio is not None:
        score += 4 if float(current_ratio) >= 1 else -4

    readings = {
        'revenue_growth_pct': round(float(revenue_growth) * 100, 1) if revenue_growth is not None else None,
        'earnings_growth_pct': round(float(earnings_growth) * 100, 1) if earnings_growth is not None else None,
        'roe_pct': round(float(roe) * 100, 1) if roe is not None else None,
        'debt_to_equity': round(float(debt_to_equity), 1) if debt_to_equity is not None else None,
        'free_cashflow_bn': round(float(free_cashflow) / 1e9, 2) if free_cashflow is not None else None,
        'operating_cashflow_bn': round(float(operating_cashflow) / 1e9, 2) if operating_cashflow is not None else None,
        'trailing_eps': round(float(trailing_eps), 2) if trailing_eps is not None else None,
        'profit_margin_pct': round(float(profit_margins) * 100, 1) if profit_margins is not None else None,
        'current_ratio': round(float(current_ratio), 2) if current_ratio is not None else None,
        'trailing_pe': round(float(info.get('trailingPE')), 1) if info.get('trailingPE') is not None else None,
        'forward_pe': round(float(info.get('forwardPE')), 1) if info.get('forwardPE') is not None else None,
        'market_cap_bn': round(float(info.get('marketCap')) / 1e9, 1) if info.get('marketCap') is not None else None,
    }
    return round(score, 2), readings


def enrich_candidate(ticker_candidate: Dict[str, Any]) -> Dict[str, Any]:
    ticker = ticker_candidate['ticker']
    enriched = dict(ticker_candidate)
    try:
        stock = yf.Ticker(ticker)
        info = stock.info or {}
    except Exception as e:
        print(f"[WARN] Fundamentals failed for {ticker}: {e}")
        info = {}

    company_name = info.get('longName') or info.get('shortName') or ticker
    sector = info.get('sector') or 'N/A'
    fundamental_score, fundamental_readings = score_fundamentals(info)
    news = get_recent_news(yf.Ticker(ticker), limit=3)
    news_score, news_reading = score_news_sentiment(news)

    enriched.update({
        'company': company_name,
        'sector': sector,
        'pe_ratio': fundamental_readings.get('trailing_pe'),
        'market_cap_bn': fundamental_readings.get('market_cap_bn'),
        'fundamental_score': fundamental_score,
        'fundamentals': fundamental_readings,
        'recent_news': news,
        'news_score': news_score,
        'news_reading': news_reading,
    })
    enriched['final_pre_ai_score'] = round(
        (enriched.get('momentum_score', 0) * 0.30) +
        (enriched.get('technical_score', 0) * 0.40) +
        (enriched.get('fundamental_score', 0) * 0.20) +
        (enriched.get('news_score', 0) * 0.10),
        2,
    )
    return enriched


def enrich_deep_candidates(candidates: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    deep_seed = sorted(candidates, key=lambda x: x.get('preliminary_score', 0), reverse=True)[:DEEP_ANALYSIS_LIMIT]
    enriched = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_BACKGROUND_WORKERS) as executor:
        futures = [executor.submit(enrich_candidate, c) for c in deep_seed]
        for f in concurrent.futures.as_completed(futures):
            try:
                enriched.append(f.result())
            except Exception as e:
                print(f"[WARN] enrich_deep_candidates item failed: {e}")
    return sorted(enriched, key=lambda x: x.get('final_pre_ai_score', 0), reverse=True)


def market_trend_index_ticker(market: str) -> str:
    return '^NSEI'


def get_market_trend_context(market: str) -> Dict[str, Any]:
    ticker = market_trend_index_ticker(market)
    try:
        h = yf.Ticker(ticker).history(period='1y', interval='1d', timeout=YF_TIMEOUT)
        if h is None or h.empty or 'Close' not in h or len(h) < 60:
            return {'index': ticker, 'direction': 'unknown', 'note': 'Not enough index trend data.'}
        close = h['Close'].dropna().astype(float)
        if len(close) < 60:
            return {'index': ticker, 'direction': 'unknown', 'note': 'Not enough clean index trend data.'}
        last = float(close.iloc[-1])
        ma20 = float(close.tail(20).mean())
        ma50 = float(close.tail(50).mean())
        ma200 = float(close.tail(min(200, len(close))).mean())
        ret20 = ((last / float(close.iloc[-20])) - 1) * 100 if len(close) >= 20 and float(close.iloc[-20]) else 0
        ret63 = ((last / float(close.iloc[-63])) - 1) * 100 if len(close) >= 63 and float(close.iloc[-63]) else 0
        if last > ma50 and ma20 > ma50 and ret20 > 1.0:
            direction = 'bullish'
        elif last < ma50 and ma20 < ma50 and ret20 < -1.0:
            direction = 'bearish'
        else:
            direction = 'sideways'
        return {
            'index': ticker,
            'direction': direction,
            'side': position_side,
        'last': round(last, 2),
            'ma20': round(ma20, 2),
            'ma50': round(ma50, 2),
            'ma200': round(ma200, 2),
            'return_20d_pct': round(ret20, 2),
            'return_63d_pct': round(ret63, 2),
            'plain': f'Market trend is {direction}: index vs MA50 and recent 20-day return are checked before allowing new trades.'
        }
    except Exception as e:
        return {'index': ticker, 'direction': 'unknown', 'note': str(e)[:160]}


def get_intraday_index_context(market: str) -> Dict[str, Any]:
    # Today's actual index move so far (not the 1y daily trend above). Used to (a) caution
    # against buying into a falling index and (b) measure a candidate's relative strength
    # vs the index, which the score previously had no way to account for.
    ticker = market_trend_index_ticker(market)
    try:
        hist = yf.Ticker(ticker).history(period='1d', interval=INTRADAY_DATA_INTERVAL, timeout=YF_TIMEOUT)
        if hist is None or hist.empty or 'Close' not in hist:
            return {'index': ticker, 'change_pct': None, 'note': 'no intraday index data'}
        close = hist['Close'].dropna()
        opens = hist['Open'].dropna()
        if close.empty or opens.empty:
            return {'index': ticker, 'change_pct': None, 'note': 'incomplete intraday index data'}
        open_price = float(opens.iloc[0])
        last = float(close.iloc[-1])
        change_pct = ((last - open_price) / open_price) * 100 if open_price else 0
        return {'index': ticker, 'open': round(open_price, 2), 'last': round(last, 2), 'change_pct': round(change_pct, 2)}
    except Exception as e:
        return {'index': ticker, 'change_pct': None, 'note': str(e)[:160]}


# Short-lived in-process cache for sector index context (report fix #8): many
# candidates in the same scan share a sector, so this avoids re-fetching the same
# sector index's intraday move once per stock. Deliberately process-local and
# TTL-based rather than DB-backed -- this is a live-only convenience (see the
# is_replay guard at every call site), not evidence the app persists.
_SECTOR_CONTEXT_CACHE: Dict[str, Tuple[float, Dict[str, Any]]] = {}
_SECTOR_CONTEXT_CACHE_TTL_SECONDS = 60.0


def get_intraday_sector_context(sector: Optional[str], market: str = 'IN') -> Dict[str, Any]:
    """Today's actual move so far in a stock's own NIFTY sectoral index (report
    fix #8 -- 'sector context is still missing'). Mirrors get_intraday_index_context
    but for a sector instead of the broad market index, so a candidate's relative
    strength can be judged against its own peers, not just NIFTY as a whole.

    LIVE-ONLY BY DESIGN: this makes a live API call, so it must never be called
    from inside a historical replay tick. Its only caller, _attach_sector_context,
    gates this correctly on settings.get('_sim_now') is None (the same signal
    already used for the session-phase and cooldown replay-parity fixes) --
    NOT row['is_replay'], which isn't set yet at the point that check needs to
    run (see _attach_support_resistance_features's docstring for why). Replay
    instead gets a real point-in-time sector reading via build_historical_
    sector_context, computed once per tick from data downloaded at run start
    (download_replay_sector_index_history) -- it is not left without a signal.

    Returns change_pct=None (never raises, never blocks) for any ticker whose
    sector isn't in sector_data.SECTOR_MAP, or if the sector index itself fails
    to resolve/fetch -- both are treated as 'no sector context available'.
    """
    if not sector:
        return {'sector': None, 'change_pct': None, 'note': 'ticker not in the sector map'}
    now = time.time()
    cached = _SECTOR_CONTEXT_CACHE.get(sector)
    if cached and (now - cached[0]) < _SECTOR_CONTEXT_CACHE_TTL_SECONDS:
        return cached[1]
    index_ticker = sector_data.SECTOR_INDEX_TICKER.get(sector)
    if not index_ticker:
        result = {'sector': sector, 'change_pct': None, 'note': 'no sector index mapped for this sector'}
        _SECTOR_CONTEXT_CACHE[sector] = (now, result)
        return result
    try:
        hist = yf.Ticker(index_ticker).history(period='1d', interval=INTRADAY_DATA_INTERVAL, timeout=YF_TIMEOUT)
        if hist is None or hist.empty or 'Close' not in hist:
            result = {'sector': sector, 'index': index_ticker, 'change_pct': None, 'note': 'no intraday sector index data'}
        else:
            close = hist['Close'].dropna()
            opens = hist['Open'].dropna()
            if close.empty or opens.empty:
                result = {'sector': sector, 'index': index_ticker, 'change_pct': None, 'note': 'incomplete intraday sector index data'}
            else:
                open_price = float(opens.iloc[0])
                last = float(close.iloc[-1])
                change_pct = ((last - open_price) / open_price) * 100 if open_price else 0
                result = {'sector': sector, 'index': index_ticker, 'open': round(open_price, 2),
                          'last': round(last, 2), 'change_pct': round(change_pct, 2)}
    except Exception as e:
        result = {'sector': sector, 'index': index_ticker, 'change_pct': None, 'note': str(e)[:160]}
    _SECTOR_CONTEXT_CACHE[sector] = (now, result)
    return result


def build_historical_market_trend_context(ticker: str, daily_close_upto_day) -> Dict[str, Any]:
    """Point-in-time equivalent of get_market_trend_context(): identical math,
    fed a daily Close series that only contains bars strictly BEFORE the
    simulated trading day (so a historical replay of e.g. 05 Sep never sees
    trend data from 06 Sep onward)."""
    close = daily_close_upto_day
    if close is None or len(close) < 60:
        return {'index': ticker, 'direction': 'unknown', 'note': 'Not enough index trend data.'}
    last = float(close.iloc[-1])
    ma20 = float(close.tail(20).mean())
    ma50 = float(close.tail(50).mean())
    ma200 = float(close.tail(min(200, len(close))).mean())
    ret20 = ((last / float(close.iloc[-20])) - 1) * 100 if len(close) >= 20 and float(close.iloc[-20]) else 0
    ret63 = ((last / float(close.iloc[-63])) - 1) * 100 if len(close) >= 63 and float(close.iloc[-63]) else 0
    if last > ma50 and ma20 > ma50 and ret20 > 1.0:
        direction = 'bullish'
    elif last < ma50 and ma20 < ma50 and ret20 < -1.0:
        direction = 'bearish'
    else:
        direction = 'sideways'
    return {
        'index': ticker, 'direction': direction, 'last': round(last, 2), 'ma20': round(ma20, 2),
        'ma50': round(ma50, 2), 'ma200': round(ma200, 2), 'return_20d_pct': round(ret20, 2), 'return_63d_pct': round(ret63, 2),
        'plain': f'Market trend is {direction} (as of the replayed day): index vs MA50 and recent 20-day return, computed only from data available before this historical day.',
    }


def build_historical_intraday_index_context(ticker: str, index_day_df, upto_idx: int) -> Dict[str, Any]:
    """Point-in-time equivalent of get_intraday_index_context(): the index's
    own move so far TODAY (the replayed day), truncated at the current
    simulated tick -- recomputed every tick since it's cheap (a slice of an
    already-loaded small dataframe, no API call)."""
    if index_day_df is None or index_day_df.empty:
        return {'index': ticker, 'change_pct': None, 'note': 'no historical intraday index data'}
    window = index_day_df.iloc[:upto_idx + 1]
    if window.empty or 'Open' not in window or 'Close' not in window:
        return {'index': ticker, 'change_pct': None, 'note': 'incomplete historical intraday index data'}
    open_price = float(window['Open'].iloc[0])
    last = float(window['Close'].iloc[-1])
    change_pct = ((last - open_price) / open_price) * 100 if open_price else 0
    return {'index': ticker, 'open': round(open_price, 2), 'last': round(last, 2), 'change_pct': round(change_pct, 2)}


def build_historical_vix_context(vix_ticker: str, vix_close_upto_day) -> Dict[str, Any]:
    """Point-in-time equivalent of the VIX portion of get_market_context():
    same regime thresholds, fed only VIX closes strictly before the
    simulated day."""
    close = vix_close_upto_day
    if close is None or close.empty:
        return {}
    level = round(float(close.iloc[-1]), 2)
    prev = round(float(close.iloc[-2]), 2) if len(close) > 1 else level
    chg_pct = round(((level - prev) / prev) * 100, 2) if prev else 0
    if level < 13:
        regime = 'low volatility / complacent'
    elif level < 20:
        regime = 'normal volatility'
    elif level < 30:
        regime = 'elevated volatility / cautious'
    else:
        regime = 'high volatility / risk-off'
    return {'index': vix_ticker, 'level': level, 'change_pct': chg_pct, 'regime': regime}


def download_replay_index_history(market: str, start_date: datetime.date, end_date: datetime.date, interval: str) -> Dict[str, Any]:
    """One-time download of the market's trend/VIX index history for building
    a point-in-time market_context per simulated day (see
    build_historical_market_context_for_day). Downloads:
      - the trend index (NIFTY/whatever market_trend_index_ticker returns),
        DAILY closes going back ~1.5y before the run so the 200-day MA has
        enough history for the FIRST selected replay day too;
      - that same index's own INTRADAY bars for the replay window (for the
        per-tick "index move so far today" context);
      - the VIX-equivalent ticker's DAILY closes over the same long window.
    """
    trend_ticker = market_trend_index_ticker(market)
    vix_ticker = VIX_TICKERS.get(market)
    daily_start = start_date - datetime.timedelta(days=540)
    result: Dict[str, Any] = {'trend_ticker': trend_ticker, 'vix_ticker': vix_ticker}
    try:
        daily_hist = yf.Ticker(trend_ticker).history(interval='1d', start=daily_start.isoformat(), end=(end_date + datetime.timedelta(days=1)).isoformat(), timeout=YF_TIMEOUT)
        result['trend_daily'] = daily_hist if daily_hist is not None else pd.DataFrame()
    except Exception as e:
        print(f"[WARN] historical trend index download failed: {e}")
        result['trend_daily'] = pd.DataFrame()
    try:
        intraday_hist = yf.Ticker(trend_ticker).history(interval=interval, start=(start_date - datetime.timedelta(days=INTRADAY_REPLAY_WARMUP_DAYS)).isoformat(), end=(end_date + datetime.timedelta(days=1)).isoformat(), timeout=YF_TIMEOUT)
        result['trend_intraday_by_day'] = group_intraday_frame_by_day(intraday_hist)
    except Exception as e:
        print(f"[WARN] historical intraday index download failed: {e}")
        result['trend_intraday_by_day'] = {}
    if vix_ticker:
        try:
            vix_hist = yf.Ticker(vix_ticker).history(interval='1d', start=daily_start.isoformat(), end=(end_date + datetime.timedelta(days=1)).isoformat(), timeout=YF_TIMEOUT)
            result['vix_daily'] = vix_hist if vix_hist is not None else pd.DataFrame()
        except Exception as e:
            print(f"[WARN] historical VIX download failed: {e}")
            result['vix_daily'] = pd.DataFrame()
    else:
        result['vix_daily'] = pd.DataFrame()
    return result


def build_historical_market_context_for_day(index_history: Dict[str, Any], day: datetime.date) -> Dict[str, Any]:
    """Recomputed ONCE per simulated trading day (not per tick -- the trend
    regime/VIX regime this drives don't meaningfully change within a single
    day, and recomputing per-tick across a 300-stock/multi-day replay for no
    behavioral benefit isn't worth the extra CPU). The per-tick-fresh piece
    (today's index move so far) is layered in separately every tick via
    build_historical_intraday_index_context, which IS cheap enough to redo
    every 5 minutes."""
    trend_ticker = index_history.get('trend_ticker')
    vix_ticker = index_history.get('vix_ticker')
    trend_daily = index_history.get('trend_daily')
    vix_daily = index_history.get('vix_daily')
    base: Dict[str, Any] = {}
    if vix_daily is not None and not vix_daily.empty and 'Close' in vix_daily:
        vix_upto = vix_daily[vix_daily.index.date < day]
        base = build_historical_vix_context(vix_ticker, vix_upto['Close'].dropna().astype(float) if not vix_upto.empty else None)
    trend_ctx = {'index': trend_ticker, 'direction': 'unknown', 'note': 'Not enough index trend data.'}
    if trend_daily is not None and not trend_daily.empty and 'Close' in trend_daily:
        trend_upto = trend_daily[trend_daily.index.date < day]
        trend_ctx = build_historical_market_trend_context(trend_ticker, trend_upto['Close'].dropna().astype(float) if not trend_upto.empty else None)
    base['market_trend'] = trend_ctx
    trend_dir = trend_ctx.get('direction')
    if trend_dir == 'bearish' and not str(base.get('regime') or '').lower().startswith('high'):
        base['trend_caution'] = True
        base['regime'] = base.get('regime') or 'bearish market / caution'
    base['intraday_index'] = {'index': trend_ticker, 'change_pct': None, 'note': 'not yet computed for this tick'}
    return base


# ---------------------------------------------------------------------------
# REPLAY PARITY: sector-relative strength + support/resistance (report -- both
# were flagged as "Live-only, absent in Replay", a genuine parity gap: a Replay
# result cannot be said to have tested this intelligence if Replay never saw it.
# Both follow the EXACT pattern already established just above for the market-
# wide NIFTY index: one bulk download per run (never per tick, never live), then
# a point-in-time slice/lookup per simulated day that only ever sees data
# strictly BEFORE the day being replayed.
# ---------------------------------------------------------------------------

def download_replay_sector_index_history(market: str, start_date: datetime.date, end_date: datetime.date,
                                          interval: str) -> Dict[str, Dict[str, Any]]:
    """One-time download of every NIFTY sectoral index's intraday bars for the
    replay window (see sector_data.SECTOR_INDEX_TICKER) -- the sector-context
    equivalent of download_replay_index_history's trend index download. Bounded
    and cheap: there are only ~11 sector indices, regardless of how large the
    stock universe being replayed is, so this never scales with universe size.
    """
    result: Dict[str, Dict[str, Any]] = {}
    for sector, ticker in sector_data.SECTOR_INDEX_TICKER.items():
        entry: Dict[str, Any] = {'ticker': ticker}
        try:
            intraday_hist = yf.Ticker(ticker).history(
                interval=interval, start=start_date.isoformat(),
                end=(end_date + datetime.timedelta(days=1)).isoformat(), timeout=YF_TIMEOUT)
            entry['intraday_by_day'] = group_intraday_frame_by_day(intraday_hist)
        except Exception as e:
            print(f"[WARN] historical sector index download failed for {sector} ({ticker}): {e}")
            entry['intraday_by_day'] = {}
        result[sector] = entry
    return result


def build_historical_sector_context(sector_index_history: Dict[str, Dict[str, Any]], sector: Optional[str],
                                     day: datetime.date, upto_idx: int) -> Dict[str, Any]:
    """Point-in-time equivalent of get_intraday_sector_context: the sector
    index's own move so far on the REPLAYED day, truncated at the current
    simulated tick -- mirrors build_historical_intraday_index_context exactly,
    just keyed by sector instead of by the one market-wide index."""
    if not sector:
        return {'sector': None, 'change_pct': None, 'note': 'ticker not in the sector map'}
    entry = (sector_index_history or {}).get(sector)
    if not entry:
        return {'sector': sector, 'change_pct': None, 'note': 'no sector index history loaded for this run'}
    by_day = entry.get('intraday_by_day') or {}
    day_df = by_day.get(day)
    if day_df is None or day_df.empty:
        return {'sector': sector, 'index': entry.get('ticker'), 'change_pct': None,
                'note': 'no historical intraday sector index data for this day'}
    window = day_df.iloc[:upto_idx + 1]
    if window.empty or 'Open' not in window or 'Close' not in window:
        return {'sector': sector, 'index': entry.get('ticker'), 'change_pct': None,
                'note': 'incomplete historical intraday sector index data'}
    open_price = float(window['Open'].iloc[0])
    last = float(window['Close'].iloc[-1])
    change_pct = ((last - open_price) / open_price) * 100 if open_price else 0
    return {'sector': sector, 'index': entry.get('ticker'), 'open': round(open_price, 2),
            'last': round(last, 2), 'change_pct': round(change_pct, 2)}


def download_replay_universe_daily_history(tickers: List[str], start_date: datetime.date, market: str = 'IN') -> Dict[str, Any]:
    """One bulk DAILY-interval (not 5-minute) download for the whole replay
    universe, going back ~50 calendar days before the run's first selected day,
    so compute_historical_support_resistance_levels can derive each ticker's
    previous-session high/low and a multi-session swing high/low from data that
    is STRICTLY BEFORE the day being replayed.

    Deliberately a SEPARATE download from download_replay_universe_history's
    5-minute bars: reusing that function's warm-up window to get a handful of
    daily highs/lows would multiply the whole universe's INTRADAY fetch volume
    several-fold, when daily-interval bars give the same highs/lows directly and
    far more cheaply (one row per ticker per day instead of ~75).
    """
    if not tickers:
        return {}
    fetch_start = start_date - datetime.timedelta(days=50)
    fetch_end = start_date  # exclusive of `day` is handled by the caller anyway
    result: Dict[str, Any] = {}
    chunk_size = 5
    chunks = [tickers[i:i + chunk_size] for i in range(0, len(tickers), chunk_size)]
    workers = min(max(1, INTRADAY_MAX_WORKERS), max(1, len(chunks)))
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            future_map = {
                executor.submit(yf.history_batch, chunk, interval='1d',
                                 start=fetch_start.isoformat(),
                                 end=(fetch_end + datetime.timedelta(days=1)).isoformat(),
                                 timeout=YF_TIMEOUT): chunk
                for chunk in chunks
            }
            for fut in concurrent.futures.as_completed(future_map):
                try:
                    hist_map = fut.result()
                except Exception:
                    continue
                for ticker, h in (hist_map or {}).items():
                    if h is not None and not h.empty:
                        result[ticker] = h
    except Exception as e:
        print(f'[WARN] replay universe daily history download failed: {e}')
    return result


def compute_historical_support_resistance_levels(daily_hist: Any, day: datetime.date) -> Dict[str, Any]:
    """Point-in-time equivalent of compute_support_resistance_levels: identical
    math (previous session's high/low + a swing high/low), fed only daily bars
    STRICTLY BEFORE `day` so Replay judges each candidate against the same kind
    of level Live does, without ever looking at the simulated day itself or any
    day after it. Returns ok=False (never raises) exactly like the live version,
    with the same "can only fail to help, never block" guarantee."""
    if daily_hist is None or daily_hist.empty:
        return {'ok': False, 'note': 'no_daily_history'}
    try:
        prior = daily_hist[daily_hist.index.date < day]
    except Exception:
        return {'ok': False, 'note': 'bad_daily_history_index'}
    if prior is None or prior.empty:
        return {'ok': False, 'note': 'no_prior_session_data'}
    try:
        prev_bar = prior.iloc[-1]
        prev_close = float(prev_bar['Close'])
        prev_day_high = float(prev_bar['High'])
        prev_day_low = float(prev_bar['Low'])
        swing_window = prior.tail(20)
        swing_high = float(swing_window['High'].max())
        swing_low = float(swing_window['Low'].min())
    except Exception as e:
        return {'ok': False, 'note': str(e)[:120]}
    return {
        'ok': True, 'prev_close': round(prev_close, 2),
        'prev_day_high': round(prev_day_high, 2), 'prev_day_low': round(prev_day_low, 2),
        'swing_high_20d': round(swing_high, 2), 'swing_low_20d': round(swing_low, 2),
        'swing_window_days': int(len(swing_window)),
    }




def get_market_context(market):

    vix_ticker = VIX_TICKERS.get(market, '^VIX')
    base: Dict[str, Any] = {}
    try:
        hist = yf.Ticker(vix_ticker).history(period='5d', timeout=YF_TIMEOUT)
        if hist is not None and not hist.empty:
            level = round(float(hist['Close'].iloc[-1]), 2)
            prev = round(float(hist['Close'].iloc[-2]), 2) if len(hist) > 1 else level
            chg_pct = round(((level - prev) / prev) * 100, 2) if prev else 0
            if level < 13:
                regime = 'low volatility / complacent'
            elif level < 20:
                regime = 'normal volatility'
            elif level < 30:
                regime = 'elevated volatility / cautious'
            else:
                regime = 'high volatility / risk-off'
            base = {'index': vix_ticker, 'level': level, 'change_pct': chg_pct, 'regime': regime}
    except Exception as e:
        print(f"[WARN] VIX fetch failed for {market}: {e}")
    base['market_trend'] = get_market_trend_context(market)
    trend = (base.get('market_trend') or {}).get('direction')
    if trend == 'bearish' and not str(base.get('regime') or '').lower().startswith('high'):
        base['trend_caution'] = True
        base['regime'] = base.get('regime') or 'bearish market / caution'
    base['intraday_index'] = get_intraday_index_context(market)
    return merge_macro_into_market_context(base, market)


def parse_rr(rr_text: str) -> Optional[float]:
    if not rr_text:
        return None
    try:
        return float(str(rr_text).split(':')[0])
    except Exception:
        return None


def make_tags(candidate: Dict[str, Any]) -> List[str]:
    tags = []
    if candidate.get('momentum_score', 0) > 15:
        tags.append('Momentum')
    if candidate.get('volume_ratio_vs_20d_avg', 1) >= 1.4:
        tags.append('Volume Surge')
    if candidate.get('macd_histogram') is not None and candidate['macd_histogram'] > 0:
        tags.append('MACD Signal')
    if candidate.get('price_vs_ma20_pct', 0) and candidate.get('price_vs_ma50_pct', 0) and candidate['price_vs_ma20_pct'] > 0 and candidate['price_vs_ma50_pct'] > 0:
        tags.append('Trend Following')
    if candidate.get('bb_position_pct') is not None and candidate['bb_position_pct'] < 25:
        tags.append('Oversold Bounce')
    if candidate.get('news_score', 0) > 0:
        tags.append('News Catalyst')
    if candidate.get('news_score', 0) < 0:
        tags.append('Negative News Risk')
    return tags[:3] or ['Technical Setup', 'Risk Managed']


def deterministic_rank_candidates(candidates: List[Dict[str, Any]], market: str, horizon: str) -> List[Dict[str, Any]]:
    picks = []
    horizon_mult = 1.0 if horizon == 'day' else 1.8
    for i, c in enumerate(sorted(candidates, key=lambda x: x.get('final_pre_ai_score', 0), reverse=True)[:FINAL_PICK_LIMIT], start=1):
        current = float(c['current_price'])
        score = float(c.get('final_pre_ai_score', 0))
        predicted_gain = round(max(min((score / 20) * horizon_mult, 8.0 if horizon == 'day' else 14.0), 1.2), 1)
        support = float(c.get('support_20') or current * 0.97)
        resistance = float(c.get('resistance_20') or current * 1.04)
        stop_pct = round(max(min(((current - support) / current) * 100, 5.5), 1.5), 1)
        target_pct = round(max(predicted_gain, ((resistance - current) / current) * 100), 1)
        target_price = round(current * (1 + target_pct / 100), 2)
        stop_price = round(current * (1 - stop_pct / 100), 2)
        rr = round(target_pct / stop_pct, 1) if stop_pct else 0
        confidence = int(max(min(50 + score * 0.45 + c.get('news_score', 0) * 0.25, 92), 35))
        signal = 'BUY' if confidence >= 58 and rr >= 1.2 else 'WATCH'
        picks.append({
            'rank': i,
            'ticker': c['ticker'],
            'company': c.get('company', c['ticker']),
            'sector': c.get('sector', 'N/A'),
            'current_price': current,
            'signal': signal,
            'predicted_gain': f"+{target_pct}%",
            'gain_number': target_pct,
            'entry_price': current,
            'target_exit_pct': f"+{target_pct}%",
            'stop_loss_pct': f"-{stop_pct}%",
            'target_price': target_price,
            'stop_price': stop_price,
            'risk_reward': f"{rr}:1",
            'confidence': confidence,
            'rsi_reading': f"{c.get('rsi_14')} — {'bullish momentum zone' if c.get('rsi_14') and 50 <= c.get('rsi_14') <= 65 else 'watch for confirmation'}",
            'macd_reading': f"{c.get('macd_crossover', 'neutral')} crossover; histogram {c.get('macd_histogram')}",
            'volume_reading': f"{c.get('volume_ratio_vs_20d_avg')}x 20-day average volume",
            'fundamental_reading': format_fundamental_reading(c.get('fundamentals', {})),
            'news_reading': c.get('news_reading', 'No material recent headlines found.'),
            'horizon_tags': make_tags(c),
            'reasoning': (
                f"Ranked through liquidity, momentum, technical, fundamental and news filters. "
                f"RSI {c.get('rsi_14')}, MACD histogram {c.get('macd_histogram')}, price vs MA20 {c.get('price_vs_ma20_pct')}%, "
                f"and 20-day volume ratio {c.get('volume_ratio_vs_20d_avg')}x support the setup; support is near {c.get('support_20')} and resistance near {c.get('resistance_20')}."
            ),
        })
    return picks


def format_fundamental_reading(f: Dict[str, Any]) -> str:
    bits = []
    if f.get('revenue_growth_pct') is not None:
        bits.append(f"revenue growth {f['revenue_growth_pct']}%")
    if f.get('roe_pct') is not None:
        bits.append(f"ROE {f['roe_pct']}%")
    if f.get('debt_to_equity') is not None:
        bits.append(f"debt/equity {f['debt_to_equity']}")
    if f.get('free_cashflow_bn') is not None:
        bits.append(f"FCF {f['free_cashflow_bn']}B")
    return ', '.join(bits[:4]) if bits else 'Fundamental data unavailable or limited; ranking relies more on technicals/news.'


def log_api_cost(call_type: str, market: Optional[str], horizon: Optional[str], model: str,
                 input_tokens: int = 0, output_tokens: int = 0, notes: str = '', metadata: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    cost = calculate_claude_cost(input_tokens, output_tokens)
    conn = get_db_connection()
    if conn is not None:
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute("""
                        INSERT INTO api_cost_log
                            (call_type, market, horizon, model, input_tokens, output_tokens, cost_usd, cost_inr, notes, metadata_json)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                    """, (
                        call_type, market, horizon, model, int(input_tokens or 0), int(output_tokens or 0),
                        cost['cost_usd'], cost['cost_inr'], notes, json.dumps(metadata or {}, default=_json_safe)
                    ))
        except Exception as e:
            print(f"[WARN] Could not log API cost: {e}")
        finally:
            conn.close()
    return cost


def estimate_next_scan_cost(market: str, horizon: str) -> Dict[str, Any]:
    market, horizon = validate_market_horizon(market, horizon) if 'validate_market_horizon' in globals() else (market, horizon)
    universe_size = len(load_market_universe(market))
    estimated_deep = min(DEEP_ANALYSIS_LIMIT, TECHNICAL_STAGE_LIMIT, max(universe_size, 1))
    input_tokens = SCAN_ESTIMATED_INPUT_TOKENS_BASE + estimated_deep * SCAN_ESTIMATED_INPUT_TOKENS_PER_CANDIDATE
    output_tokens = SCAN_ESTIMATED_OUTPUT_TOKENS
    claude = calculate_claude_cost(input_tokens, output_tokens)
    budget = get_ai_budget_status(claude.get('cost_inr', 0))
    locked = get_locked_cached_scan(market, horizon) if DATABASE_URL else None
    yfinance_calls = math.ceil(max(universe_size, 1) / max(BATCH_SIZE, 1)) + estimated_deep * 2 + 1
    return {
        'market': market,
        'horizon': horizon,
        'locked_prediction_exists': bool(locked),
        'paid_cost_if_user_clicks_load_cached_scan_inr': 0,
        'paid_cost_if_locked_prediction_exists_inr': 0,
        'estimated_paid_cost_if_first_scan_runs': claude,
        'ai_budget': budget,
        'paid_ai_will_run_if_first_scan_needed': bool(not locked and budget.get('allowed')),
        'paid_ai_fallback_if_blocked': 'deterministic_ranker',
        'estimated_input_tokens': input_tokens,
        'estimated_output_tokens': output_tokens,
        'estimated_yfinance_fetches': yfinance_calls,
        'yfinance_cost': 0,
        'note': 'Load Cached Scan costs ₹0. Run First Scan costs ₹0 if a current locked prediction already exists. If a new lock is needed, Claude runs only when AI budget allows; otherwise deterministic ranking is used.',
    }


def get_learning_context(market: str, horizon: str, limit: int = MAX_LEARNING_LESSONS) -> Dict[str, Any]:
    conn = get_db_connection()
    if conn is None:
        return {'available': False, 'lessons': [], 'patterns': {}}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT signal, outcome_label, outcome_status, failure_reason, lesson_summary, actual_gain_pct, features_json, created_at
                FROM prediction_lessons
                WHERE market=%s AND horizon=%s AND created_at >= NOW() - (%s || ' days')::interval
                ORDER BY created_at DESC
                LIMIT %s
            """, (market, horizon, LESSON_LOOKBACK_DAYS, limit))
            rows = cur.fetchall()
    except Exception as e:
        print(f"[WARN] Could not load learning context: {e}")
        rows = []
    finally:
        conn.close()

    patterns: Dict[str, int] = {}
    combo_stats: Dict[str, Dict[str, Any]] = {}
    lessons = []
    for r in rows:
        reason = r.get('failure_reason') or r.get('outcome_status') or 'general'
        features = r.get('features_json') or {}
        if isinstance(features, str):
            try:
                features = json.loads(features)
            except Exception:
                features = {}
        combo = backtest_pattern_key(features)
        bucket = combo_stats.setdefault(combo, {'total': 0, 'failed': 0, 'success': 0, 'reasons': {}})
        bucket['total'] += 1
        if r.get('outcome_status') in ('failed', 'missed_opportunity') or r.get('failure_reason'):
            bucket['failed'] += 1
            bucket['reasons'][reason] = bucket['reasons'].get(reason, 0) + 1
        elif r.get('outcome_status') == 'success':
            bucket['success'] += 1
        patterns[reason] = patterns.get(reason, 0) + 1
        lessons.append({
            'signal': r.get('signal'),
            'outcome_label': r.get('outcome_label'),
            'failure_reason': reason,
            'pattern_key': combo,
            'lesson_summary': r.get('lesson_summary'),
            'actual_gain_pct': float(r['actual_gain_pct']) if r.get('actual_gain_pct') is not None else None,
            'features': features,
        })
    pattern_memory = {}
    for combo, stat in combo_stats.items():
        total = stat.get('total') or 0
        if total >= LEARNING_PATTERN_MIN_TRADES:
            fail_rate = (stat.get('failed', 0) / total) * 100
            top_reason = max(stat.get('reasons', {}).items(), key=lambda kv: kv[1])[0] if stat.get('reasons') else None
            pattern_memory[combo] = {'total': total, 'failed': stat.get('failed', 0), 'success': stat.get('success', 0), 'failure_rate_pct': round(fail_rate, 1), 'top_reason': top_reason}
    return {'available': True, 'lessons': lessons[:20], 'patterns': patterns, 'pattern_memory': pattern_memory, 'lookback_days': LESSON_LOOKBACK_DAYS}


def learning_penalty_for_candidate(candidate: Dict[str, Any], learning_context: Dict[str, Any]) -> float:
    patterns = learning_context.get('patterns') or {}
    if not patterns:
        return 0.0
    penalty = 0.0
    vol = candidate.get('volume_ratio_vs_20d_avg') or 1.0
    rsi = candidate.get('rsi_14') or 50
    news_score = candidate.get('news_score', 0)
    rr_proxy = 0.0
    try:
        current = float(candidate.get('current_price') or 0)
        support = float(candidate.get('support_20') or current * 0.97)
        resistance = float(candidate.get('resistance_20') or current * 1.04)
        rr_proxy = ((resistance - current) / current) / max(((current - support) / current), 0.01)
    except Exception:
        rr_proxy = 1.0

    if patterns.get('low_volume_confirmation', 0) and vol < 0.8:
        penalty += min(6, patterns['low_volume_confirmation'] * 1.5)
    if patterns.get('overextended_or_chasing', 0) and rsi > 68:
        penalty += min(6, patterns['overextended_or_chasing'] * 1.5)
    if patterns.get('weak_risk_reward', 0) and rr_proxy < MIN_BUY_RISK_REWARD:
        penalty += min(5, patterns['weak_risk_reward'] * 1.2)
    if patterns.get('no_news_catalyst', 0) and news_score <= 0:
        penalty += min(4, patterns['no_news_catalyst'] * 1.0)
    if patterns.get('negative_news_or_event_risk', 0) and news_score < 0:
        penalty += min(6, patterns['negative_news_or_event_risk'] * 1.5)
    pattern_memory = learning_context.get('pattern_memory') or {}
    candidate_key = backtest_pattern_key({**candidate, 'rr_proxy': rr_proxy})
    candidate_pattern = pattern_memory.get(candidate_key)
    if candidate_pattern and candidate_pattern.get('failure_rate_pct', 0) >= 60:
        penalty += min(8, 2 + candidate_pattern.get('failed', 0) * 1.5)
        candidate['prediction_lesson_pattern_warning'] = f"Repeated failed pattern: {candidate_key}; top reason: {candidate_pattern.get('top_reason') or 'mixed'}"
    return round(penalty, 2)


def apply_learning_adjustments(candidates: List[Dict[str, Any]], learning_context: Dict[str, Any]) -> List[Dict[str, Any]]:
    for c in candidates:
        penalty = learning_penalty_for_candidate(c, learning_context)
        c['learning_penalty'] = penalty
        c['learning_patterns_considered'] = learning_context.get('patterns') or {}
        if penalty:
            c['final_pre_ai_score'] = float(c.get('final_pre_ai_score', 0)) - penalty
    return sorted(candidates, key=lambda x: x.get('final_pre_ai_score', 0), reverse=True)





def normalize_history_frame(hist):
    """Return a compact OHLCV dataframe with single-level columns when yfinance returns odd shapes."""
    try:
        if hist is None or getattr(hist, 'empty', True):
            return hist
        frame = hist.copy()
        # yfinance can occasionally return MultiIndex columns or duplicate columns.
        cols = getattr(frame, 'columns', None)
        if cols is not None and hasattr(cols, 'nlevels') and getattr(cols, 'nlevels', 1) > 1:
            # Prefer the OHLCV field level if present; otherwise flatten to the first matching label.
            wanted = {'Open', 'High', 'Low', 'Close', 'Adj Close', 'Volume'}
            new_cols = []
            for col in cols:
                picked = None
                for part in col if isinstance(col, tuple) else (col,):
                    if str(part) in wanted:
                        picked = str(part)
                        break
                new_cols.append(picked or str(col[-1] if isinstance(col, tuple) else col))
            frame.columns = new_cols
        # Remove duplicate OHLCV columns if present; keep first.
        try:
            frame = frame.loc[:, ~frame.columns.duplicated()]
        except Exception:
            pass
        return frame
    except Exception:
        return hist


def history_series(hist, col: str, fallback_col: Optional[str] = None):
    """Safely extract a numeric Series from a yfinance history frame.

    This avoids Render/Gunicorn crashes caused by odd pandas objects, duplicate columns,
    or MultiIndex outputs during long backtests.
    """
    try:
        frame = normalize_history_frame(hist)
        if frame is None or getattr(frame, 'empty', True):
            return None
        if col in frame:
            series = frame[col]
        elif fallback_col and fallback_col in frame:
            series = frame[fallback_col]
        elif 'Close' in frame:
            series = frame['Close']
        else:
            return None
        # Duplicate columns can make frame[col] a DataFrame; use the first column.
        if hasattr(series, 'columns'):
            series = series.iloc[:, 0]
        series = series.dropna().astype(float)
        return series
    except BaseException:
        # BaseException intentionally catches worker-timeout SystemExit from nested pandas ops
        # while keeping the backtest from killing the whole web worker.
        return None

def classify_regime_from_history(hist) -> Dict[str, Any]:
    """Classify market regime from information available up to the current bar."""
    unknown = {'regime': 'unknown', 'trend': 'unknown', 'volatility': 'unknown', 'realized_vol_pct': None, 'adx_proxy': None}
    try:
        if hist is None or getattr(hist, 'empty', True) or len(hist) < 50:
            return unknown
        frame = normalize_history_frame(hist)
        closes = history_series(frame, 'Close')
        if closes is None or len(closes) < 50:
            return unknown
        highs = history_series(frame, 'High', fallback_col='Close')
        lows = history_series(frame, 'Low', fallback_col='Close')
        if highs is None or len(highs) == 0:
            highs = closes
        if lows is None or len(lows) == 0:
            lows = closes
        ma20 = float(closes.tail(20).mean())
        ma50 = float(closes.tail(50).mean())
        base_20 = float(closes.iloc[-20]) if len(closes) >= 20 else 0.0
        ret20 = ((float(closes.iloc[-1]) / base_20) - 1) * 100 if base_20 else 0.0
        returns = closes.pct_change().dropna().tail(20)
        realized_vol = float(returns.std() * (252 ** 0.5) * 100) if not returns.empty else 0.0
        high_tail = highs.tail(14)
        low_tail = lows.tail(14)
        recent_range = (float(high_tail.max()) - float(low_tail.min())) / max(float(closes.iloc[-1]), 0.01) * 100
        adx_proxy = abs(ret20) / max(float(recent_range), 0.01) * 25
        if ma20 > ma50 and ret20 > 2.5:
            trend = 'uptrend'
        elif ma20 < ma50 and ret20 < -2.5:
            trend = 'downtrend'
        else:
            trend = 'sideways'
        if realized_vol >= 35:
            volatility = 'high_vol'
        elif realized_vol <= 16:
            volatility = 'low_vol'
        else:
            volatility = 'normal_vol'
        if trend == 'uptrend' and volatility != 'high_vol':
            regime = 'trending_bull'
        elif trend == 'downtrend' or volatility == 'high_vol':
            regime = 'risk_off_or_high_vol'
        else:
            regime = 'choppy_sideways'
        return {'regime': regime, 'trend': trend, 'volatility': volatility, 'realized_vol_pct': round(realized_vol, 2), 'adx_proxy': round(float(adx_proxy), 2)}
    except BaseException as e:
        return {**unknown, 'error': str(e)[:180]}


def compute_atr_pct_from_history(hist, period: int = 14) -> Optional[float]:
    try:
        if hist is None or getattr(hist, 'empty', True) or len(hist) < period + 1:
            return None
        frame = normalize_history_frame(hist)
        high_s = history_series(frame, 'High', fallback_col='Close')
        low_s = history_series(frame, 'Low', fallback_col='Close')
        close_s = history_series(frame, 'Close')
        if high_s is None or low_s is None or close_s is None:
            return None
        n = min(len(high_s), len(low_s), len(close_s))
        if n < period + 1:
            return None
        high = high_s.tail(n).values
        low = low_s.tail(n).values
        close = close_s.tail(n).values
        trs = []
        for i in range(1, len(close)):
            trs.append(max(high[i] - low[i], abs(high[i] - close[i-1]), abs(low[i] - close[i-1])))
        atr = float(np.mean(trs[-period:]))
        current = float(close[-1])
        return round((atr / current) * 100, 2) if current else None
    except BaseException:
        return None


def backtest_pattern_key(features: Dict[str, Any]) -> str:
    parts = []
    rsi = features.get('rsi_14')
    vol = features.get('volume_ratio_vs_20d_avg')
    rr = features.get('rr_proxy')
    if rsi is not None:
        parts.append('rsi_high' if rsi >= 68 else 'rsi_bull' if rsi >= 50 else 'rsi_weak')
    if vol is not None:
        parts.append('vol_strong' if vol >= 1.3 else 'vol_low' if vol < 0.8 else 'vol_normal')
    if rr is not None:
        parts.append('rr_good' if rr >= 1.6 else 'rr_weak')
    parts.append('macd_pos' if (features.get('macd_histogram') or 0) > 0 else 'macd_neg')
    return '+'.join(parts[:5]) or 'general'




def pattern_verdict_from_stats(trades: int, win_rate: Optional[float], expectancy: Optional[float]) -> str:
    """Turn historical evidence into an actionable memory label."""
    if trades < LEARNING_PATTERN_MIN_TRADES or win_rate is None or expectancy is None:
        return 'insufficient_evidence'
    if win_rate <= LEARNING_BAD_PATTERN_WIN_RATE_PCT or expectancy < 0:
        return 'avoid_or_require_stronger_confirmation'
    if win_rate >= LEARNING_GOOD_PATTERN_WIN_RATE_PCT and expectancy > 0:
        return 'favorable_pattern'
    return 'neutral_pattern'


def explain_backtest_failure(trade: Dict[str, Any]) -> Dict[str, Any]:
    """Explain why a simulated trade failed using only stored historical features."""
    ret = float(trade.get('net_return_pct') or 0)
    outcome = trade.get('outcome') or 'unknown'
    features = trade.get('features') or {}
    reasons = []
    if ret > 0:
        return {
            'failure_reason': None,
            'pattern_verdict': 'worked',
            'lesson_summary': f"{trade.get('ticker')} pattern worked historically in {trade.get('regime') or 'unknown'} regime; similar setups can receive normal or positive weighting."
        }
    if outcome == 'stop_loss_hit':
        reasons.append('stop_loss_hit')
    if float(features.get('volume_ratio_vs_20d_avg') or 1) < 0.8:
        reasons.append('low_volume_confirmation')
    if float(features.get('rsi_14') or 50) >= 68:
        reasons.append('overextended_or_chasing')
    if float(features.get('rr_proxy') or 1.5) < MIN_BUY_RISK_REWARD:
        reasons.append('weak_risk_reward')
    if float(features.get('price_vs_ma20_pct') or 0) < 0:
        reasons.append('below_short_term_trend')
    if float(features.get('macd_histogram') or 0) <= 0:
        reasons.append('weak_or_negative_macd')
    if not reasons:
        reasons.append('setup_did_not_follow_through')
    reason = '+'.join(reasons[:4])
    ticker = trade.get('ticker')
    regime = trade.get('regime') or 'unknown'
    return {
        'failure_reason': reason,
        'pattern_verdict': 'failed',
        'lesson_summary': f"{ticker} lost {round(ret, 2)}% in backtest; likely issue: {reason.replace('_', ' ')} during {regime}. Future scans should reduce confidence or require stronger volume/RR confirmation for this pattern."
    }

def get_strategy_memory(market: str, horizon: str, regime: Optional[str] = None, limit: int = 40) -> Dict[str, Any]:
    conn = get_db_connection()
    if conn is None:
        return {'available': False, 'patterns': []}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            if regime:
                cur.execute("""
                    SELECT regime, pattern_key, trades, win_rate_pct, expectancy_pct, confidence_adjustment, notes
                    FROM strategy_signal_stats
                    WHERE market=%s AND horizon=%s AND (regime=%s OR regime='all')
                    ORDER BY trades DESC, updated_at DESC
                    LIMIT %s
                """, (market, horizon, regime, limit))
            else:
                cur.execute("""
                    SELECT regime, pattern_key, trades, win_rate_pct, expectancy_pct, confidence_adjustment, notes
                    FROM strategy_signal_stats
                    WHERE market=%s AND horizon=%s
                    ORDER BY trades DESC, updated_at DESC
                    LIMIT %s
                """, (market, horizon, limit))
            rows = cur.fetchall()
    except Exception as e:
        print(f"[WARN] Strategy memory load failed: {e}")
        rows = []
    finally:
        conn.close()
    return {'available': True, 'patterns': [dict(r) for r in rows]}


def strategy_memory_adjustment(candidate: Dict[str, Any], memory: Dict[str, Any], regime: Optional[str] = None) -> float:
    if not memory.get('patterns'):
        return 0.0
    key = backtest_pattern_key(candidate)
    adjustment = 0.0
    for row in memory.get('patterns', []):
        if row.get('pattern_key') == key and (not regime or row.get('regime') in (regime, 'all')):
            adjustment += float(row.get('confidence_adjustment') or 0)
    return round(adjustment, 2)


def apply_strategy_memory_adjustments(candidates: List[Dict[str, Any]], market: str, horizon: str, market_context: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    regime = market_context.get('regime') if isinstance(market_context, dict) else None
    memory = get_strategy_memory(market, horizon, regime=regime)
    for c in candidates:
        try:
            current = float(c.get('current_price') or 0)
            support = float(c.get('support_20') or current * 0.97)
            resistance = float(c.get('resistance_20') or current * 1.04)
            c['rr_proxy'] = round(((resistance-current)/max(current,0.01)) / max(((current-support)/max(current,0.01)), 0.01), 2)
        except Exception:
            c['rr_proxy'] = None
        adj = strategy_memory_adjustment(c, memory, regime=regime)
        c['strategy_memory_adjustment'] = adj
        c['strategy_pattern_key'] = backtest_pattern_key(c)
        if adj:
            c['final_pre_ai_score'] = float(c.get('final_pre_ai_score', 0)) + adj
    return sorted(candidates, key=lambda x: x.get('final_pre_ai_score', 0), reverse=True)




def _num(value: Any, default: Optional[float] = None) -> Optional[float]:
    try:
        if value is None:
            return default
        if isinstance(value, Decimal):
            return float(value)
        if isinstance(value, (int, float, np.generic)):
            return float(value)
        text = str(value).replace('%', '').replace('₹', '').replace('$', '').strip()
        if ':' in text:
            text = text.split(':')[0]
        return float(text)
    except Exception:
        return default


def get_stock_backtest_strength(market: str, horizon: str, tickers: Optional[List[str]] = None) -> Dict[str, Dict[str, Any]]:
    """Per-stock daily/weekly backtest memory used by the main prediction engine."""
    conn = get_db_connection()
    if conn is None:
        return {}
    params: List[Any] = [market, horizon]
    ticker_clause = ''
    if tickers:
        ticker_clause = ' AND ticker = ANY(%s)'
        params.append([str(t).upper() for t in tickers])
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"""
                SELECT ticker,
                       COUNT(*) AS trades,
                       AVG(CASE WHEN net_return_pct > 0 THEN 1 ELSE 0 END) * 100 AS win_rate_pct,
                       AVG(net_return_pct) AS expectancy_pct,
                       SUM(CASE WHEN outcome='target_hit' THEN 1 ELSE 0 END) AS target_hits,
                       SUM(CASE WHEN outcome='stop_loss_hit' THEN 1 ELSE 0 END) AS stop_hits,
                       MIN(signal_date) AS first_signal_date,
                       MAX(signal_date) AS last_signal_date
                FROM backtest_trades
                WHERE market=%s AND horizon=%s {ticker_clause}
                GROUP BY ticker
            """, params)
            return {str(r['ticker']).upper(): {k: (float(v) if hasattr(v, 'as_tuple') else v) for k, v in dict(r).items()} for r in cur.fetchall()}
    except Exception as e:
        print(f"[WARN] Could not load stock backtest strength: {e}")
        return {}
    finally:
        conn.close()


def get_closed_trade_history_strength(market: str, horizon: Optional[str] = None, engine: str = 'trading', before_ts: Optional[datetime.datetime] = None) -> Dict[str, Dict[str, Any]]:
    """Closed/paper/live trade memory used by trading automation or intraday.

    before_ts (optional): only count trades CLOSED strictly before this
    instant. Used by run_intraday_replay() so a historical day's "learning"
    only reflects what had actually closed by that point in history -- e.g.
    replaying September 5 must not let a September 8 trade result influence
    the September 5 decision (look-ahead via the learning-memory path).
    Leaving this None (the default) reproduces the exact previous behavior
    for every existing caller."""
    conn = get_db_connection()
    if conn is None:
        return {}
    filters = ["status='CLOSED'", "market=%s", "pnl_pct IS NOT NULL"]
    params: List[Any] = [market]
    if before_ts is not None:
        filters.append("closed_at < %s")
        params.append(before_ts)
    if engine == 'intraday':
        filters.append("COALESCE(engine, CASE WHEN horizon='intraday' THEN 'intraday' ELSE 'trading_automation' END)='intraday'")
    else:
        filters.append("COALESCE(engine, CASE WHEN horizon='intraday' THEN 'intraday' ELSE 'trading_automation' END) <> 'intraday'")
        if horizon:
            filters.append("horizon=%s")
            params.append(horizon)
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"""
                SELECT ticker,
                       COUNT(*) AS trades,
                       AVG(CASE WHEN pnl_pct > 0 THEN 1 ELSE 0 END) * 100 AS win_rate_pct,
                       AVG(pnl_pct) AS expectancy_pct,
                       AVG(CASE WHEN exit_reason LIKE 'TARGET%%' OR exit_reason LIKE '%%PROFIT%%' THEN 1 ELSE 0 END) * 100 AS positive_exit_rate_pct,
                       MAX(closed_at) AS last_closed_at,
                       (ARRAY_AGG(pnl_pct ORDER BY closed_at DESC))[1] AS last_trade_pnl_pct
                FROM trade_positions
                WHERE {' AND '.join(filters)}
                GROUP BY ticker
            """, params)
            return {str(r['ticker']).upper(): {k: (float(v) if hasattr(v, 'as_tuple') else v) for k, v in dict(r).items()} for r in cur.fetchall()}
    except Exception as e:
        print(f"[WARN] Could not load {engine} trade history strength: {e}")
        return {}
    finally:
        conn.close()


def strict_learning_architecture() -> Dict[str, Any]:
    return {
        'enabled': STRICT_LEARNING_ENABLED,
        'plain_summary': 'Daily backtests improve main predictions. Closed trade history improves trading automation. Intraday history improves the intraday engine. Weak setups are downgraded or skipped instead of forcing trades.',
        'paths': [
            {'source': 'Research Lab daily backtest', 'improves': 'Main prediction engine', 'uses': 'daily/weekly RSI, MACD, volume, reward/risk, regime, per-stock history'},
            {'source': 'Trade History', 'improves': 'Trading automation', 'uses': 'actual or paper entries, exits, target hits, stop hits, P/L, repeated stock failures'},
            {'source': 'Intraday History', 'improves': 'Intraday engine', 'uses': '5-minute breakout quality, VWAP hold/fail, volume spike, quick target/stop result, time-of-day behavior'},
        ],
        'strict_rules': [
            'Minimum score filter',
            'Minimum reward/risk filter',
            'Volume confirmation filter',
            'Market regime filter',
            'Pattern reliability filter',
            'Bad-pattern penalty',
            'Per-stock historical strength filter',
            'Training vs validation split',
            'Benchmark comparison',
            'No-trade recommendation when edge is weak',
        ],
        'thresholds': {
            'min_score': STRICT_MIN_SCORE,
            'buy_min_score': STRICT_BUY_MIN_SCORE,
            'backtest_min_score': STRICT_BACKTEST_MIN_SCORE,
            'min_risk_reward': STRICT_MIN_RISK_REWARD,
            'min_volume_ratio': STRICT_MIN_VOLUME_RATIO,
            'backtest_min_risk_reward': STRICT_BACKTEST_MIN_RISK_REWARD,
            'backtest_min_volume_ratio': STRICT_BACKTEST_MIN_VOLUME_RATIO,
            'backtest_allow_watch_only': STRICT_BACKTEST_ALLOW_WATCH_ONLY,
            'pattern_reliable_min_trades': STRICT_PATTERN_RELIABLE_MIN_TRADES,
            'per_stock_min_trades': STRICT_PER_STOCK_MIN_TRADES,
        }
    }


def strict_learning_review(candidate: Dict[str, Any], market: str, horizon: str, engine: str = 'prediction',
                           market_context: Optional[Dict[str, Any]] = None,
                           stock_memory: Optional[Dict[str, Dict[str, Any]]] = None,
                           trade_memory: Optional[Dict[str, Dict[str, Any]]] = None,
                           now_utc: Optional[datetime.datetime] = None) -> Dict[str, Any]:
    """One conservative reviewer used by all engines with engine-specific memory.

    It does not predict prices. It decides whether the edge is strong enough to
    allow a BUY/entry, or whether the system should WATCH/AVOID/no-trade.

    BUGFIX (replay session-phase): now_utc lets a caller pass the SIMULATED
    "current instant" (the replay's sim_now, tz-aware or naive-UTC). Without
    this, the late-session/square-off check below always fell back to the
    real wall-clock time even during a historical replay -- so a replay tick
    at 09:37 on a day in the past could get judged against how close the
    REAL current time is to today's close. If that replay happened to be run
    late in the trading day (or after hours), every single candidate got
    incorrectly classified as being in the square-off window and blocked.
    Leaving now_utc=None (the default) reproduces the exact previous
    behavior for the live engines, which have no simulated clock of their
    own.
    """
    if not STRICT_LEARNING_ENABLED:
        return {'enabled': False, 'allowed': True, 'score_adjustment': 0.0, 'rules': []}
    ticker = str(candidate.get('ticker') or '').upper()
    score = _num(candidate.get('final_pre_ai_score'), _num(candidate.get('score'), _num(candidate.get('confidence'), 0.0))) or 0.0
    if engine == 'backtest':
        min_score_needed = STRICT_BACKTEST_MIN_SCORE
    elif engine == 'intraday':
        # Use the Intraday tab's saved Minimum score, not the global env default.
        # This fixes the UI mismatch where the screen showed 60 but strict learning
        # still blocked candidates with "needs 70+".
        min_score_needed = _num(candidate.get('min_score'), INTRADAY_MIN_SCORE) or INTRADAY_MIN_SCORE
    elif engine == 'trading_automation':
        min_score_needed = _num(candidate.get('min_score'), STRICT_MIN_SCORE) or STRICT_MIN_SCORE
    else:
        min_score_needed = STRICT_MIN_SCORE
    late_session_phase = None
    square_off_block = False
    if engine in ('intraday', 'trading_automation'):
        # Graduated late-session selectivity: instead of trading exactly the same way all
        # day and then hard-cutting off at one clock time, new entries have to clear a
        # progressively higher bar as the session runs out of room to manage them.
        # BUGFIX: pass now_utc through so a historical replay is judged against its own
        # simulated clock, not the real wall-clock time (see the now_utc docstring above).
        phase_info = get_intraday_session_phase(market, now_utc=now_utc)
        late_session_phase = phase_info.get('phase')
        if late_session_phase == 'late':
            min_score_needed += 8
        elif late_session_phase == 'critical':
            min_score_needed += 15
        elif late_session_phase == 'square_off':
            # No brand-new intraday entries inside the hard square-off window — there isn't
            # enough session left to manage a fresh position responsibly. This used to be
            # implemented as an artificially high min_score_needed (1000+), which produced
            # confusing/nonsensical log lines like "score 100.0; needs 1006.0+" (a threshold
            # above the maximum possible score). It's now its own explicit hard block so the
            # reason is legible and never mistaken for a real, reachable score gate.
            square_off_block = True
    rr = _num(candidate.get('rr_proxy'), None)
    if rr is None:
        rr = _num(candidate.get('risk_reward'), None)
    if rr is None:
        try:
            entry = _num(candidate.get('entry_price'), _num(candidate.get('current_price'), _num(candidate.get('last'), 0))) or 0
            target = _num(candidate.get('target_price'), 0) or 0
            stop = _num(candidate.get('stop_price'), 0) or 0
            rr = ((target-entry)/max(entry,0.01)) / max(((entry-stop)/max(entry,0.01)), 0.01) if entry and target > entry and stop < entry else 0.0
        except Exception:
            rr = 0.0
    vol = _num(candidate.get('volume_ratio_vs_20d_avg'), _num(candidate.get('volume_multiplier'), 1.0))
    regime = None
    if isinstance(market_context, dict):
        regime = market_context.get('regime')
    if not regime:
        regime = candidate.get('regime') or (candidate.get('regime_info') or {}).get('regime')
    regime_lower = str(regime or '').lower()
    if engine in ('intraday', 'trading_automation'):
        # Market regime as a true GATE, not just a scoring nudge: a "high volatility /
        # risk-off" (or bearish-override) regime raises min_score sharply instead of only
        # ever being a downgrade a candidate can still out-score its way past.
        if 'high volatility' in regime_lower or 'risk-off' in regime_lower or 'risk_off' in regime_lower:
            min_score_needed += 25
        elif 'elevated volatility' in regime_lower or 'cautious' in regime_lower or 'bearish' in regime_lower:
            min_score_needed += 12
        elif 'low volatility' in regime_lower or 'complacent' in regime_lower:
            # Complacent/low-vol regimes are exactly where breakouts most often fail to
            # follow through — still stricter than normal, just less than an outright
            # risk-off regime.
            min_score_needed += 6
    # SANITY CHECK: late-session and regime adjustments stack additively, so a bad
    # combination (e.g. "critical" phase + "high volatility" regime) could otherwise push
    # min_score_needed above 100 -- the maximum possible score -- making the gate
    # mathematically unreachable and silently blocking every candidate for reasons that
    # look like a normal (if strict) score gate. Cap it so any "needs X+" message a person
    # sees always describes a real, reachable requirement.
    if not square_off_block:
        min_score_needed = min(min_score_needed, 100.0)
    pattern_key = candidate.get('strategy_pattern_key') or candidate.get('pattern_key') or backtest_pattern_key({**candidate, 'rr_proxy': rr})
    raw_adj = _num(candidate.get('strategy_memory_adjustment'), 0.0) or 0.0
    adjustment = raw_adj
    hard_blocks: List[str] = []
    cautions: List[str] = []
    boosts: List[str] = []
    rules: List[Dict[str, Any]] = []

    def add_rule(name: str, passed: bool, action: str, detail: str):
        rules.append({'name': name, 'passed': bool(passed), 'action': action, 'detail': detail})
        if not passed and action in ('block', 'avoid'):
            hard_blocks.append(detail)
        elif not passed:
            cautions.append(detail)
        elif action == 'boost':
            boosts.append(detail)

    if square_off_block:
        add_rule('Square-off window', False, 'block',
                 f"no new intraday entries inside the square-off window (score {round(score,1)}; session phase: square_off)")
    else:
        # For intraday: this used to be a hard 'block' the instant raw score fell short.
        # Downgraded to feed the unified adjusted-score check near the end of this
        # function instead (score + every adjustment below, vs. this same threshold),
        # so a strong strategy confidence can still clear the bar after later boosts
        # (relative strength, favorable per-stock/pattern history) are counted -- see
        # that check for why. trading_automation (live-money automation) keeps the
        # stricter immediate-block behavior unchanged.
        add_rule('Minimum setup score', score >= min_score_needed, 'block' if engine == 'trading_automation' else 'downgrade',
                 f"score {round(score,1)}; needs {min_score_needed}+" + (f" (session phase: {late_session_phase})" if late_session_phase and late_session_phase != 'normal' else ""))
    if str(candidate.get('signal') or '').upper() == 'BUY':
        add_rule('Minimum BUY score', score >= STRICT_BUY_MIN_SCORE, 'downgrade', f"BUY score {round(score,1)}; needs {STRICT_BUY_MIN_SCORE}+")
    if engine == 'backtest':
        rr_threshold = STRICT_BACKTEST_MIN_RISK_REWARD
        vol_threshold = STRICT_BACKTEST_MIN_VOLUME_RATIO
    elif engine == 'intraday':
        rr_threshold = _num(candidate.get('min_risk_reward'), INTRADAY_MIN_RISK_REWARD) or INTRADAY_MIN_RISK_REWARD
        vol_threshold = _num(candidate.get('min_volume_multiplier'), INTRADAY_MIN_VOLUME_MULTIPLIER) or INTRADAY_MIN_VOLUME_MULTIPLIER
    else:
        rr_threshold = STRICT_MIN_RISK_REWARD
        vol_threshold = STRICT_MIN_VOLUME_RATIO
    add_rule('Minimum reward vs risk', rr >= rr_threshold, 'block' if engine in ('trading_automation','intraday') else 'downgrade', f"reward/risk {round(rr or 0,2)}; needs {rr_threshold}+")
    volume_unavailable = bool(candidate.get('volume_data_reliable') is False or candidate.get('volume_data_available') is False)
    if engine == 'intraday' and volume_unavailable:
        rules.append({'name': 'Volume confirmation', 'passed': True, 'action': 'neutral', 'detail': 'provider volume missing/zero; not blocking intraday setup on free data'})
    else:
        # Each of the 10 strategies already encodes its OWN volume requirement inside its
        # eligibility function (Opening Breakout/Volume Expansion need strong volume to even
        # be selected; VWAP Reclaim/Pullback/Relative Strength don't). Re-applying one
        # universal hard volume gate on top of that ignores those per-strategy judgments and
        # blocks setups the strategy itself already decided didn't need heavy volume. So for
        # intraday candidates that came through the multi-strategy engine (have a
        # strategy_id), this is always a score downgrade, never a block; the legacy/no-
        # strategy path keeps the original configurable hard/soft mode.
        if engine == 'intraday' and candidate.get('strategy_id'):
            vol_action = 'downgrade'
        else:
            vol_action = 'block' if (engine == 'intraday' and INTRADAY_VOLUME_CONFIRMATION_MODE == 'hard') else 'downgrade'
        add_rule('Volume confirmation', (vol is None or vol >= vol_threshold), vol_action, f"volume {round(vol or 0,2)}x; needs {vol_threshold}x+")
    risk_off = bool(regime and ('risk_off' in str(regime) or 'high volatility' in str(regime).lower() or 'risk-off' in str(regime).lower()))
    if engine == 'intraday':
        # DEAD-FLAG BUGFIX: the old version of this branch set regime_action='block'
        # unconditionally whenever risk_off was True, and only ever consulted
        # STRICT_INTRADAY_BLOCK_RISK_OFF in the risk_off=False branch below. But
        # add_rule() only looks at `action` when `passed` is False, and `passed` here is
        # `not (STRICT_AVOID_RISK_OFF and risk_off)` -- which is always True when
        # risk_off is False. So the flag was being read in the one branch where it could
        # never do anything, and ignored in the one branch (risk_off True) where it was
        # supposed to matter. Net effect: STRICT_INTRADAY_BLOCK_RISK_OFF=false (the
        # configured value) had zero effect, and every risk-off regime hard-blocked
        # every intraday candidate regardless of strategy confidence -- one soft-signal
        # regime read vetoing an otherwise-strong setup, the exact "learning has too
        # much authority" pattern this file is trying to avoid everywhere else. Fixed so
        # the flag now does what its name says: hard block only if explicitly enabled,
        # otherwise a strong (but overridable) score penalty that still lets a
        # confident, well-adjusted setup clear the unified adjusted-score gate below.
        if risk_off:
            if STRICT_INTRADAY_BLOCK_RISK_OFF:
                regime_action = 'block'
            else:
                regime_action = 'downgrade'
                adjustment -= 8.0
        else:
            # Elevated/cautious/complacent regimes still just raise the score bar (handled
            # above) rather than blocking outright — only a genuinely severe regime is a
            # hard gate, and only when explicitly configured to be one.
            regime_action = 'downgrade'
    else:
        regime_action = 'block' if (engine == 'trading_automation' or (engine == 'backtest' and STRICT_BACKTEST_REJECT_RISK_OFF)) else 'downgrade'
    add_rule('Market regime safety', not (STRICT_AVOID_RISK_OFF and risk_off), regime_action, f"market type is {regime or 'unknown'}")
    trend_direction = ((market_context or {}).get('market_trend') or {}).get('direction') if isinstance(market_context, dict) else None
    if trend_direction == 'bearish':
        adjustment -= 2.5
        add_rule('Bullish/bearish market direction', False, 'downgrade', 'broad market trend is bearish; require stronger confirmation or no trade')
    elif trend_direction == 'bullish':
        boosts.append('broad market trend is bullish')
        add_rule('Bullish/bearish market direction', True, 'boost', 'broad market trend is bullish')
    else:
        add_rule('Bullish/bearish market direction', True, 'neutral', f'broad market trend is {trend_direction or "unknown"}')

    # Today's actual index move + relative strength — separate from the 1y trend above.
    # Buying a long when NIFTY is red today and this stock isn't clearly outperforming it
    # means fighting the tape rather than riding a genuine setup.
    intraday_index = (market_context or {}).get('intraday_index') if isinstance(market_context, dict) else None
    if engine in ('intraday', 'trading_automation') and isinstance(intraday_index, dict) and intraday_index.get('change_pct') is not None:
        index_chg = _num(intraday_index.get('change_pct'), None)
        cand_chg = _num(candidate.get('change_pct'), None)
        if index_chg is not None and cand_chg is not None:
            rel_strength = cand_chg - index_chg
            if index_chg <= -0.4 and rel_strength < 0.5:
                action = 'block' if engine == 'trading_automation' else 'downgrade'
                add_rule('Index confirmation (NIFTY, today)', False, action,
                         f"NIFTY is {index_chg}% today; this stock is only {round(rel_strength, 2)} pts stronger than the index, not enough relative strength to buy into a falling market")
            elif rel_strength >= 1.0:
                boosts.append(f'outperforming NIFTY by {round(rel_strength, 2)} pts today')
                add_rule('Index confirmation (NIFTY, today)', True, 'boost', f'outperforming NIFTY by {round(rel_strength, 2)} pts today')
            else:
                add_rule('Index confirmation (NIFTY, today)', True, 'neutral', f'NIFTY {index_chg}% today, stock relative strength {round(rel_strength, 2)} pts')

    # SECTOR-RELATIVE STRENGTH (report #8): "stock vs NIFTY" alone misses cases like
    # a stock +2.0% while its OWN sector is +1.2% (unremarkable -- it's just riding a
    # hot sector) vs the same +2.0% while its sector is -1.0% (genuinely strong).
    # PARITY FIX: reads candidate['sector_context'], attached once by
    # _attach_sector_context (in attach_intraday_strategy_engine) for BOTH Live and
    # Replay -- Replay now gets a real point-in-time sector reading instead of no
    # signal at all (previously this called a live-only function directly and
    # skipped entirely whenever now_utc was set, i.e. every Replay tick).
    # Never a hard block (even for trading_automation): sector coverage is a
    # best-effort static map (sector_data.SECTOR_MAP), not a validated feed, so an
    # unmapped or misclassified ticker must only ever fail to help, never actively
    # veto a trade.
    if engine in ('intraday', 'trading_automation'):
        sector_ctx = candidate.get('sector_context')
        if sector_ctx and sector_ctx.get('sector'):
            sector = sector_ctx['sector']
            sector_chg = _num(sector_ctx.get('change_pct'), None)
            cand_chg = _num(candidate.get('change_pct'), None)
            if sector_chg is not None and cand_chg is not None:
                sector_rel_strength = cand_chg - sector_chg
                if sector_chg <= -0.4 and sector_rel_strength < 0.5:
                    add_rule('Sector confirmation (today)', False, 'downgrade',
                             f"{sector} sector is {sector_chg}% today; this stock is only {round(sector_rel_strength, 2)} "
                             f"pts stronger than its own sector, not enough sector-relative strength to buy into a falling sector")
                elif sector_rel_strength >= 1.0:
                    boosts.append(f'outperforming its {sector} sector by {round(sector_rel_strength, 2)} pts today')
                    add_rule('Sector confirmation (today)', True, 'boost',
                             f'outperforming {sector} sector by {round(sector_rel_strength, 2)} pts today')
                else:
                    add_rule('Sector confirmation (today)', True, 'neutral',
                             f'{sector} sector {sector_chg}% today, stock sector-relative strength {round(sector_rel_strength, 2)} pts')

    macro = (market_context or {}).get('macro_event_risk') if isinstance(market_context, dict) else None
    if isinstance(macro, dict) and macro.get('enabled'):
        macro_level = macro.get('risk_level')
        macro_score = _num(macro.get('risk_score'), 0.0) or 0.0
        if macro_level == 'high_risk' or macro_score >= MACRO_RISK_BLOCK_THRESHOLD:
            if engine == 'intraday':
                action = 'block' if STRICT_INTRADAY_BLOCK_MACRO_RISK else 'downgrade'
            else:
                action = 'block' if engine == 'trading_automation' else 'downgrade'
            adjustment -= 6.0
            add_rule('Major news/macro risk', False, action, f"macro/news risk high ({round(macro_score,1)}): {macro.get('decision') or 'avoid new trades'}")
        elif macro_level == 'caution' or macro_score >= MACRO_RISK_CAUTION_THRESHOLD:
            adjustment -= 2.0
            add_rule('Major news/macro risk', False, 'downgrade', f"macro/news caution ({round(macro_score,1)}): require stronger confirmation")
        else:
            add_rule('Major news/macro risk', True, 'neutral', 'no major macro/news block detected')

    if raw_adj <= STRICT_BAD_PATTERN_MIN_PENALTY:
        adjustment += raw_adj  # make bad historical pattern count harder in strict mode
        add_rule('Bad-pattern penalty', False, 'downgrade', f"similar pattern has negative memory ({round(raw_adj,2)})")
    elif raw_adj > 0:
        boosts.append(f"similar pattern has positive memory (+{round(raw_adj,2)})")
        add_rule('Pattern reliability', True, 'boost', f"pattern memory adjustment +{round(raw_adj,2)}")
    else:
        add_rule('Pattern reliability', True, 'neutral', 'no strong pattern memory yet')

    stock_stat = (stock_memory or {}).get(ticker)
    if stock_stat and int(stock_stat.get('trades') or 0) >= STRICT_PER_STOCK_MIN_TRADES:
        sw = float(stock_stat.get('win_rate_pct') or 0)
        se = float(stock_stat.get('expectancy_pct') or 0)
        if sw < STRICT_PER_STOCK_MIN_WIN_RATE or se < STRICT_PER_STOCK_MIN_EXPECTANCY:
            adjustment -= 3.0
            add_rule('Per-stock historical strength', False, 'downgrade', f"{ticker} backtest history weak: {round(sw,1)}% win, avg {round(se,3)}%")
        else:
            adjustment += min(3.0, max(0.0, se * 2))
            add_rule('Per-stock historical strength', True, 'boost', f"{ticker} backtest history acceptable: {round(sw,1)}% win, avg {round(se,3)}%")
    else:
        add_rule('Per-stock historical strength', True, 'neutral', 'not enough stock-specific history yet')

    hist_stat = (trade_memory or {}).get(ticker)
    min_hist = STRICT_INTRADAY_HISTORY_MIN_TRADES if engine == 'intraday' else STRICT_TRADE_HISTORY_MIN_TRADES
    if hist_stat and int(hist_stat.get('trades') or 0) >= min_hist:
        hw = float(hist_stat.get('win_rate_pct') or 0)
        he = float(hist_stat.get('expectancy_pct') or 0)
        label = 'Intraday history' if engine == 'intraday' else 'Automation trade history'
        if hw < STRICT_PER_STOCK_MIN_WIN_RATE or he < 0:
            adjustment -= 4.0
            # Was a hard 'block' for intraday: one ticker's thin/weak trade history
            # vetoing an otherwise strong strategy signal outright is exactly the
            # "learning has too much authority" pattern -- it should weigh in as a risk
            # adjustment (the -4.0 above) that a confident setup can still overcome, not
            # an instant veto. trading_automation is unchanged (live-money automation).
            add_rule(label, False, 'block' if engine == 'trading_automation' else 'downgrade', f"actual/paper history weak: {round(hw,1)}% win, avg {round(he,3)}%")
        else:
            adjustment += min(3.0, max(0.0, he * 2))
            add_rule(label, True, 'boost', f"actual/paper history acceptable: {round(hw,1)}% win, avg {round(he,3)}%")

    # SAME-TICKER COOLDOWN AFTER A LOSS: without this, the engine can lose on a ticker and
    # immediately re-enter the same (or nearly the same) setup minutes later — the ERIS/
    # ICICIPRULI/ELGIEQUIP clustering pattern. If the most recent closed trade on this ticker
    # was a loss and it closed within the cooldown window, block/downgrade a fresh entry.
    if hist_stat and engine in ('intraday', 'trading_automation'):
        last_closed_at = hist_stat.get('last_closed_at')
        last_trade_pnl_pct = hist_stat.get('last_trade_pnl_pct')
        if last_closed_at is not None and last_trade_pnl_pct is not None and float(last_trade_pnl_pct) <= 0:
            minutes_since_loss = None
            try:
                closed_dt = last_closed_at
                if isinstance(closed_dt, str):
                    closed_dt = datetime.datetime.fromisoformat(closed_dt.replace('Z', '+00:00'))
                if getattr(closed_dt, 'tzinfo', None) is not None:
                    closed_dt = closed_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                # BUGFIX (report #4 -- replay cooldown clock parity): this must be judged
                # against the SAME clock the rest of this function already uses (see the
                # now_utc docstring above) -- not the real wall clock. Without this, a
                # historical replay compares a loss timestamped in the past against
                # today's real time, so "7 minutes since loss" in the simulation could
                # read as weeks/months, silently disabling the same-ticker cooldown
                # during Replay while it works correctly in Live/Paper.
                effective_now = now_utc if now_utc is not None else utc_now_naive()
                if getattr(effective_now, 'tzinfo', None) is not None:
                    effective_now = effective_now.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                minutes_since_loss = (effective_now - closed_dt).total_seconds() / 60
            except Exception:
                minutes_since_loss = None
            cooldown_minutes = float(INTRADAY_TICKER_COOLDOWN_MINUTES)
            if minutes_since_loss is not None and 0 <= minutes_since_loss < cooldown_minutes:
                action = 'block' if engine in ('intraday', 'trading_automation') else 'downgrade'
                add_rule('Same-ticker cooldown after loss', False, action,
                         f"last closed trade on {ticker} lost {round(float(last_trade_pnl_pct), 2)}% only {round(minutes_since_loss, 1)} min ago; cooldown is {cooldown_minutes} min before re-entering the same stock")

    verdict = 'allow_buy'
    if hard_blocks:
        verdict = 'no_trade'
    elif cautions:
        verdict = 'watch_only'
    elif boosts:
        verdict = 'favorable'
    allowed = not hard_blocks
    if engine == 'prediction':
        # Predictions can remain visible as WATCH/AVOID even when strict mode blocks BUY.
        allowed = True
    elif engine == 'trading_automation' and verdict == 'watch_only':
        # Unchanged for live-money automation: any caution at all still blocks execution
        # there. Not touched by the intraday/replay fix below -- this engine wasn't part
        # of what Replay 8 tested, so it keeps its original, more conservative behavior.
        allowed = False
    elif engine == 'intraday' and not hard_blocks:
        # UNIFIED ADJUSTED-SCORE GATE (replaces the old "any caution at all -> no_trade"
        # rule, which is what actually caused Replay 8's 0-trades-from-84,524-strategy-
        # evaluations result). That old rule meant a single soft caution -- e.g. "broad
        # market trend is bearish" (explicitly authored as a 'downgrade' a few dozen
        # lines up, not a 'block') -- fully vetoed a strategy-confirmed 81-score setup,
        # collapsing the whole block/downgrade distinction this function otherwise
        # carefully builds back into "any negative signal = no trade".
        #
        # Every non-hard rule above already accumulates into `adjustment` (bearish
        # market -2.5, weak per-stock/ticker history -3/-4, bad pattern memory, macro
        # caution -2, etc.) or into `boosts` (relative strength, bullish trend, good
        # history). The model this implements: strategy confidence is the base case,
        # every softer signal adjusts it up or down, and ONE final check decides --
        # exactly "Level 1 conviction -> Level 2 risk adjustment -> Level 3 execution
        # check" rather than N independent veto points. Only a genuine hard_blocks entry
        # (RR floor, square-off window, risk-off regime, same-ticker cooldown, etc. --
        # the things that stayed 'block' above) can still veto outright regardless of
        # how the adjusted score looks.
        adjusted_score = round(score + adjustment, 2)
        if adjusted_score < min_score_needed:
            allowed = False
            hard_blocks.append(f"adjusted score {adjusted_score} (base {round(score,1)} {'+' if adjustment >= 0 else ''}{round(adjustment,1)}) below required {min_score_needed}+")
            verdict = 'no_trade'
        else:
            allowed = True
            if verdict == 'watch_only':
                verdict = 'favorable' if adjustment > 0 else 'allow_buy'
    return {
        'enabled': True,
        'engine': engine,
        'ticker': ticker,
        'pattern_key': pattern_key,
        'allowed': allowed,
        'verdict': verdict,
        'hard_blocks': hard_blocks,
        'cautions': cautions,
        'boosts': boosts,
        'rules': rules,
        'score_before': round(score, 2),
        'score_adjustment': round(adjustment, 2),
        'score_after': round(score + adjustment, 2),
        'risk_reward': round(rr or 0, 2),
        'volume_confirmation': round(vol, 2) if vol is not None else None,
        'market_regime': regime,
    }


def apply_strict_learning_to_picks(picks: List[Dict[str, Any]], candidates: List[Dict[str, Any]], market: str, horizon: str,
                                   market_context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if not STRICT_LEARNING_ENABLED:
        return {'picks': picks, 'summary': {'enabled': False}}
    candidate_map = {str(c.get('ticker','')).upper(): c for c in candidates}
    stock_memory = get_stock_backtest_strength(market, horizon, list(candidate_map.keys()))
    buy_count_before = sum(1 for p in picks if p.get('signal') == 'BUY')
    downgraded = 0
    blocked_buy = 0
    for p in picks:
        t = str(p.get('ticker') or '').upper()
        c = dict(candidate_map.get(t) or {})
        # Merge candidate technical data with final pick prices/RR.
        merged = {**c, **p}
        review = strict_learning_review(merged, market, horizon, engine='prediction', market_context=market_context, stock_memory=stock_memory)
        p['strict_learning'] = review
        p['strict_learning_verdict'] = review.get('verdict')
        p['strict_learning_note'] = '; '.join((review.get('hard_blocks') or review.get('cautions') or review.get('boosts') or [])[:2])
        p['features_json'] = {**(p.get('features_json') or {}), 'strict_learning': review}
        if review.get('enabled'):
            # Strong future predictions should not remain BUY if strict mode sees weak edge.
            if p.get('signal') == 'BUY' and review.get('verdict') in ('no_trade', 'watch_only'):
                p['signal'] = 'WATCH' if review.get('verdict') == 'watch_only' else 'AVOID'
                p['confidence'] = max(0, min(int(p.get('confidence') or 50), 62 if p['signal'] == 'AVOID' else 68))
                p['reasoning'] = (p.get('reasoning') or '') + f" Strict Learning Mode downgraded it because {p.get('strict_learning_note') or 'edge is not strong enough'}."
                downgraded += 1
                if review.get('verdict') == 'no_trade':
                    blocked_buy += 1
    buy_count_after = sum(1 for p in picks if p.get('signal') == 'BUY')
    no_trade = STRICT_NO_TRADE_IF_NO_BUY and buy_count_after == 0
    return {
        'picks': picks,
        'summary': {
            'enabled': True,
            'buy_count_before': buy_count_before,
            'buy_count_after': buy_count_after,
            'downgraded': downgraded,
            'blocked_buy': blocked_buy,
            'no_trade_recommendation': no_trade,
            'message': 'Strict Learning Mode found no strong BUY today. Best action is WATCH / no trade.' if no_trade else 'Strict Learning Mode kept only stronger BUY setups.',
            'rules': strict_learning_architecture().get('strict_rules')
        }
    }


def compute_split_and_benchmark_metrics(trades: List[Dict[str, Any]], all_hist: Dict[str, Any], start_dt: datetime.date, end_dt: datetime.date) -> Dict[str, Any]:
    """Add training/validation and simple benchmark comparison to every backtest."""
    out: Dict[str, Any] = {}
    try:
        sorted_trades = sorted(trades, key=lambda t: str(t.get('signal_date') or ''))
        if sorted_trades:
            split_idx = max(1, int(len(sorted_trades) * 0.7))
            train = compute_backtest_metrics(sorted_trades[:split_idx])
            valid = compute_backtest_metrics(sorted_trades[split_idx:]) if len(sorted_trades[split_idx:]) else {}
            out['training_validation'] = {
                'policy': 'First 70% of simulated trades is training/readout; last 30% is validation/unseen-style check.',
                'training': {k: train.get(k) for k in ('total_trades','win_rate_pct','expectancy_pct','profit_factor','sharpe','max_drawdown_pct')},
                'validation': {k: valid.get(k) for k in ('total_trades','win_rate_pct','expectancy_pct','profit_factor','sharpe','max_drawdown_pct')},
                'validation_positive': bool((valid.get('total_trades') or 0) > 0 and (valid.get('expectancy_pct') or 0) > 0 and (valid.get('profit_factor') or 0) >= 1.0)
            }
    except Exception as e:
        out['training_validation'] = {'error': str(e)[:160]}
    try:
        universe_returns = []
        for ticker, h in all_hist.items():
            frame = normalize_history_frame(h)
            close = history_series(frame, 'Close')
            if close is None or len(close) < 2:
                continue
            period = [v for i, v in close.items() if i.date() >= start_dt and i.date() <= end_dt]
            if len(period) >= 2 and period[0]:
                universe_returns.append(((float(period[-1]) / float(period[0])) - 1) * 100)
        strat_sum = round(sum(float(t.get('net_return_pct') or 0) for t in trades), 3)
        bench = round(float(np.mean(universe_returns)), 3) if universe_returns else None
        out['benchmark_comparison'] = {
            'benchmark': 'Equal-weight buy-and-hold of loaded universe over same period',
            'benchmark_return_pct': bench,
            'strategy_sum_return_pct': strat_sum,
            'strategy_minus_benchmark_pct': round(strat_sum - bench, 3) if bench is not None else None,
            'note': 'Benchmark is a simple reference, not a guarantee. It helps check whether the strategy adds value versus just holding the tested universe.'
        }
    except Exception as e:
        out['benchmark_comparison'] = {'error': str(e)[:160]}
    return out

def historical_snapshot_at(ticker: str, hist, end_idx: int) -> Optional[Dict[str, Any]]:
    hist = normalize_history_frame(hist)
    frame = hist.iloc[:end_idx + 1].copy()
    snap = build_stock_snapshot(ticker, frame)
    if snap:
        snap['atr_pct'] = compute_atr_pct_from_history(frame)
        snap['regime_info'] = classify_regime_from_history(frame)
        try:
            current = float(snap.get('current_price') or 0)
            support = float(snap.get('support_20') or current * 0.97)
            resistance = float(snap.get('resistance_20') or current * 1.04)
            snap['rr_proxy'] = round(((resistance-current)/max(current,0.01)) / max(((current-support)/max(current,0.01)), 0.01), 2)
        except Exception:
            snap['rr_proxy'] = None
    return snap


def score_historical_candidate(snapshot: Dict[str, Any], market: str, horizon: str) -> Dict[str, Any]:
    snapshot['momentum_score'] = score_momentum(snapshot)
    snapshot['technical_score'] = score_technical(snapshot)
    snapshot['fundamental_score'] = 0
    snapshot['news_score'] = 0
    snapshot['final_pre_ai_score'] = round(snapshot['momentum_score'] * 0.45 + snapshot['technical_score'] * 0.55, 2)
    return snapshot


def backtest_exit_learning_policy() -> Dict[str, Any]:
    return {
        'enabled': BACKTEST_EXIT_AWARE_ENABLED,
        'return_mode': BACKTEST_RETURN_MODE,
        'plain_summary': (
            'Raw baseline shows what the original trade would have done with only target/stop/time exit. '
            'Protected result replays the same trade with post-entry capital/profit protection. '
            'Learning keeps both so an avoided loss still teaches why the entry became risky.'
        ),
        'rules': {
            'min_weak_signals': BACKTEST_PROTECTED_MIN_WEAK_SIGNALS,
            'loss_exit_pct': BACKTEST_PROTECTED_LOSS_EXIT_PCT,
            'profit_fade_min_pct': BACKTEST_PROTECTED_PROFIT_FADE_MIN_PCT,
            'exit_price_model': BACKTEST_PROTECTED_EXIT_PRICE_MODEL,
            'bar_level_note': (
                'Daily/week backtests use OHLC bars, not tick-by-tick execution. '
                'In threshold mode, if the candle proves the protective threshold was touched and stacked weakness exists, '
                'protected replay exits at the threshold price; if price gaps beyond it, it exits at the bar open. '
                'For exact timing, intraday historical candles or broker/exchange tick data are needed.'
            )
        }
    }


def backtest_bar_weakness_signals(hist, i: int, snapshot: Dict[str, Any], entry_price: float) -> Tuple[List[str], float]:
    """Detect bar-level weakening after entry without using future bars beyond the current bar.

    This is intentionally conservative: one weak candle should not panic-exit. It returns
    multiple reasons and a score so protected backtests only exit when risk evidence stacks up.
    """
    signals: List[str] = []
    try:
        close = float(hist['Close'].iloc[i]) if 'Close' in hist else entry_price
        open_p = float(hist['Open'].iloc[i]) if 'Open' in hist else close
        high = float(hist['High'].iloc[i]) if 'High' in hist else close
        low = float(hist['Low'].iloc[i]) if 'Low' in hist else close
        prev_close = float(hist['Close'].iloc[i-1]) if i > 0 and 'Close' in hist else close
        prev_high = float(hist['High'].iloc[i-1]) if i > 0 and 'High' in hist else high
        pnl_pct = ((close - entry_price) / entry_price) * 100 if entry_price else 0.0
        # Only use bars up to current index for rolling context.
        recent = hist.iloc[max(0, i-5):i+1]
        closes = recent['Close'].astype(float) if 'Close' in recent else None
        vols = recent['Volume'].astype(float) if 'Volume' in recent else None
        ma3 = float(closes.tail(3).mean()) if closes is not None and len(closes) >= 3 else close
        vol_now = float(vols.iloc[-1]) if vols is not None and len(vols) else 0.0
        vol_avg = float(vols.tail(5).mean()) if vols is not None and len(vols) >= 3 else vol_now
        if close < prev_close:
            signals.append('price closed below previous close')
        if close < ma3:
            signals.append('price fell below short-term average')
        if high < prev_high and close < open_p:
            signals.append('lower high with red candle')
        if vol_avg > 0 and vol_now < vol_avg * 0.65:
            signals.append('volume confirmation faded')
        if pnl_pct < BACKTEST_PROTECTED_LOSS_EXIT_PCT:
            signals.append('trade moved into capital-risk zone')
        if float(snapshot.get('volume_ratio_vs_20d_avg') or 1.0) < 0.8:
            signals.append('original setup had weak volume')
        if float(snapshot.get('rr_proxy') or 0) < 1.1:
            signals.append('original reward/risk was weak')
        regime = (snapshot.get('regime_info') or {}).get('regime') or ''
        if regime in ('risk_off_or_high_vol', 'bearish'):
            signals.append('market type was risky')
        pattern_verdict = str(snapshot.get('pattern_verdict') or snapshot.get('strict_learning_verdict') or '').lower()
        if 'avoid' in pattern_verdict or pattern_verdict == 'no_trade':
            signals.append('historical pattern memory was risky')
        # De-duplicate while preserving order.
        deduped = []
        for sig in signals:
            if sig not in deduped:
                deduped.append(sig)
        score = 0.0
        for sig in deduped:
            if 'capital-risk' in sig or 'risky' in sig or 'weak reward' in sig or 'pattern memory' in sig:
                score += 25
            elif 'volume' in sig:
                score += 18
            else:
                score += 14
        return deduped, min(score, 100.0)
    except Exception:
        return [], 0.0


def simulate_backtest_trade(ticker: str, hist, signal_idx: int, snapshot: Dict[str, Any], horizon: str) -> Optional[Dict[str, Any]]:
    try:
        hold_sessions = 1 if horizon == 'day' else 5
        if signal_idx + 1 >= len(hist):
            return None
        entry_idx = signal_idx + 1
        exit_limit_idx = min(signal_idx + hold_sessions, len(hist) - 1)
        if entry_idx > exit_limit_idx:
            return None
        entry_open = float(hist['Open'].iloc[entry_idx]) if 'Open' in hist else float(hist['Close'].iloc[entry_idx])
        if entry_open <= 0:
            return None
        atr_pct = snapshot.get('atr_pct') or 2.0
        score = float(snapshot.get('final_pre_ai_score') or 0)
        target_pct = max(0.8 if horizon == 'day' else 2.0, min((score / 28) * (1.0 if horizon == 'day' else 1.8), 6.0 if horizon == 'day' else 12.0))
        stop_pct = max(0.45 if horizon == 'day' else 1.2, min(float(atr_pct) * VOL_TARGET_ATR_RISK_MULTIPLIER, 4.0 if horizon == 'day' else 7.0))
        target_price = entry_open * (1 + target_pct / 100)
        stop_price = entry_open * (1 - stop_pct / 100)
        execution_cost_pct = (EXECUTION_SLIPPAGE_BPS + EXECUTION_SPREAD_BPS + EXECUTION_FEE_BPS) / 100.0

        def d(x):
            return x.date().isoformat() if hasattr(x, 'date') else str(x)[:10]

        def baseline_exit():
            outcome = 'horizon_exit'
            exit_price = float(hist['Close'].iloc[exit_limit_idx])
            actual_idx = exit_limit_idx
            for j in range(entry_idx, exit_limit_idx + 1):
                high = float(hist['High'].iloc[j]) if 'High' in hist else float(hist['Close'].iloc[j])
                low = float(hist['Low'].iloc[j]) if 'Low' in hist else float(hist['Close'].iloc[j])
                # Conservative ordering for daily bars when both target and stop are inside same candle.
                if low <= stop_price:
                    return stop_price, j, 'stop_loss_hit'
                if high >= target_price:
                    return target_price, j, 'target_hit'
            return exit_price, actual_idx, outcome

        unprotected_exit_price, unprotected_idx, unprotected_outcome = baseline_exit()
        unprotected_raw_return_pct = ((unprotected_exit_price - entry_open) / entry_open) * 100
        unprotected_net_return_pct = unprotected_raw_return_pct - execution_cost_pct

        protected_exit_price, protected_idx, protected_outcome = unprotected_exit_price, unprotected_idx, unprotected_outcome
        protected_action = 'RAW_BASELINE_ONLY'
        protected_reason = 'Exit-aware backtest disabled or raw mode selected.'
        if BACKTEST_EXIT_AWARE_ENABLED:
            protected_action = 'HOLD_BASELINE'
            protected_reason = 'No stacked weakening/capital-risk signals before baseline exit.'
            for j in range(entry_idx, exit_limit_idx + 1):
                high = float(hist['High'].iloc[j]) if 'High' in hist else float(hist['Close'].iloc[j])
                open_j = float(hist['Open'].iloc[j]) if 'Open' in hist else entry_open
                low = float(hist['Low'].iloc[j]) if 'Low' in hist else float(hist['Close'].iloc[j])
                close_j = float(hist['Close'].iloc[j]) if 'Close' in hist else entry_open
                if low <= stop_price:
                    protected_exit_price, protected_idx, protected_outcome = stop_price, j, 'stop_loss_hit'
                    protected_action = 'STOP_LOSS'
                    protected_reason = 'Stop-loss was touched before protective exit conditions could act.'
                    break
                if high >= target_price:
                    protected_exit_price, protected_idx, protected_outcome = target_price, j, 'target_hit'
                    protected_action = 'TARGET_HIT'
                    protected_reason = 'Target was reached while setup remained valid.'
                    break
                weak_signals, risk_score = backtest_bar_weakness_signals(hist, j, snapshot, entry_open)
                pnl_now = ((close_j - entry_open) / entry_open) * 100
                enough_weak = len(weak_signals) >= BACKTEST_PROTECTED_MIN_WEAK_SIGNALS
                # Protect capital only when the trade is already losing and weakness is confirmed.
                if pnl_now <= BACKTEST_PROTECTED_LOSS_EXIT_PCT and enough_weak and risk_score >= 55:
                    protective_threshold_price = entry_open * (1 + BACKTEST_PROTECTED_LOSS_EXIT_PCT / 100.0)
                    threshold_touched = low <= protective_threshold_price
                    if BACKTEST_PROTECTED_EXIT_PRICE_MODEL == 'threshold' and threshold_touched:
                        # If a later daily bar opens beyond the threshold, assume the protective order
                        # fills at the worse open. Otherwise use the configured protective threshold.
                        simulated_protective_price = open_j if (j > entry_idx and open_j < protective_threshold_price) else protective_threshold_price
                        model_note = f"protective threshold touched; simulated exit at {simulated_protective_price:.2f}"
                    else:
                        simulated_protective_price = close_j
                        model_note = 'close-only protective replay; no earlier threshold fill assumed'
                    protected_exit_price, protected_idx, protected_outcome = simulated_protective_price, j, 'protected_capital_exit'
                    protected_action = 'CAPITAL_PROTECTION_EXIT'
                    protected_reason = '; '.join(weak_signals[:4] + [model_note])
                    break
                # Protect profit only when there is profit to protect and weakness is confirmed.
                if pnl_now >= BACKTEST_PROTECTED_PROFIT_FADE_MIN_PCT and enough_weak and risk_score >= 70:
                    protected_exit_price, protected_idx, protected_outcome = close_j, j, 'protected_profit_exit'
                    protected_action = 'PROFIT_PROTECTION_EXIT'
                    protected_reason = '; '.join(weak_signals[:4])
                    break
        protected_raw_return_pct = ((protected_exit_price - entry_open) / entry_open) * 100
        protected_net_return_pct = protected_raw_return_pct - execution_cost_pct
        use_protected = BACKTEST_EXIT_AWARE_ENABLED and BACKTEST_RETURN_MODE == 'protected'
        final_exit_price = protected_exit_price if use_protected else unprotected_exit_price
        final_idx = protected_idx if use_protected else unprotected_idx
        final_outcome = protected_outcome if use_protected else unprotected_outcome
        final_raw_return_pct = protected_raw_return_pct if use_protected else unprotected_raw_return_pct
        final_net_return_pct = protected_net_return_pct if use_protected else unprotected_net_return_pct

        idx_signal = hist.index[signal_idx]
        idx_entry = hist.index[entry_idx]
        idx_exit = hist.index[final_idx]
        features = {k: snapshot.get(k) for k in ['rsi_14','macd_histogram','volume_ratio_vs_20d_avg','price_vs_ma20_pct','price_vs_ma50_pct','atr_pct','rr_proxy']}
        pattern_key = backtest_pattern_key({**features, 'macd_histogram': snapshot.get('macd_histogram')})
        avoided_loss_pct = max(0.0, protected_net_return_pct - unprotected_net_return_pct)
        # Missed profit is possible if protection exits earlier and baseline later reached a better result.
        missed_profit_pct = max(0.0, unprotected_net_return_pct - protected_net_return_pct)
        trade = {
            'ticker': ticker, 'signal_date': d(idx_signal), 'entry_date': d(idx_entry), 'exit_date': d(idx_exit),
            'entry_price': round(entry_open, 4), 'exit_price': round(final_exit_price, 4), 'target_price': round(target_price, 4), 'stop_price': round(stop_price, 4),
            'raw_return_pct': round(final_raw_return_pct, 4), 'net_return_pct': round(final_net_return_pct, 4), 'outcome': final_outcome,
            'regime': (snapshot.get('regime_info') or {}).get('regime', 'unknown'), 'score': round(float(snapshot.get('final_pre_ai_score') or 0), 2),
            'rsi': snapshot.get('rsi_14'), 'volume_ratio': snapshot.get('volume_ratio_vs_20d_avg'), 'atr_pct': snapshot.get('atr_pct'),
            'pattern_key': pattern_key, 'features': features,
            'unprotected_exit_price': round(unprotected_exit_price, 4),
            'unprotected_net_return_pct': round(unprotected_net_return_pct, 4),
            'unprotected_outcome': unprotected_outcome,
            'protected_exit_price': round(protected_exit_price, 4),
            'protected_net_return_pct': round(protected_net_return_pct, 4),
            'protected_outcome': protected_outcome,
            'protected_action': protected_action,
            'protected_reason': protected_reason,
            'avoided_loss_pct': round(avoided_loss_pct, 4),
            'missed_profit_pct': round(missed_profit_pct, 4),
            'entry_learning_return_pct': round(unprotected_net_return_pct, 4),
            'exit_learning_delta_pct': round(protected_net_return_pct - unprotected_net_return_pct, 4),
            'exit_aware_enabled': BACKTEST_EXIT_AWARE_ENABLED,
            'return_mode': BACKTEST_RETURN_MODE,
        }
        # Entry learning deliberately uses raw/unprotected outcome so avoided losses
        # still teach the system why the original setup was risky.
        lesson_trade = dict(trade)
        lesson_trade['net_return_pct'] = trade['entry_learning_return_pct']
        lesson_trade['outcome'] = trade['unprotected_outcome']
        lesson = explain_backtest_failure(lesson_trade)
        if avoided_loss_pct > 0 and trade.get('lesson_summary'):
            lesson['lesson_summary'] = (lesson.get('lesson_summary') or '') + f" Exit-aware replay reduced historical loss by {avoided_loss_pct:.2f} percentage points, but entry pattern still gets learned from the raw baseline."
        elif avoided_loss_pct > 0:
            lesson['lesson_summary'] = f"Exit-aware replay reduced historical loss by {avoided_loss_pct:.2f} percentage points; keep entry-risk learning separate from exit-quality learning."
        trade.update(lesson)
        return trade
    except Exception as e:
        print(f"[WARN] simulate_backtest_trade failed for {ticker}: {e}")
        return None


def compute_backtest_metrics(trades: List[Dict[str, Any]]) -> Dict[str, Any]:
    # returns = selected reporting return. In protected mode this uses the
    # exit-aware result. entry_returns always uses raw/unprotected baseline so
    # bad entry patterns still teach the learning engine even if protection saved loss.
    returns = [float(t.get('net_return_pct') or 0) for t in trades]
    entry_returns = [float(t.get('entry_learning_return_pct') if t.get('entry_learning_return_pct') is not None else (t.get('unprotected_net_return_pct') if t.get('unprotected_net_return_pct') is not None else t.get('net_return_pct') or 0)) for t in trades]
    if not returns:
        return {'total_trades': 0, 'win_rate_pct': None, 'expectancy_pct': None, 'sharpe': None, 'sortino': None, 'max_drawdown_pct': None}
    wins = [r for r in returns if r > 0]
    losses = [r for r in returns if r <= 0]
    avg = float(np.mean(returns))
    std = float(np.std(returns)) if len(returns) > 1 else 0.0
    downside = float(np.std([min(r,0) for r in returns])) if len(returns) > 1 else 0.0
    sharpe = (avg / std) * math.sqrt(252) if std > 0 else None
    sortino = (avg / downside) * math.sqrt(252) if downside > 0 else None
    equity = 100.0
    peak = 100.0
    max_dd = 0.0
    for r in returns:
        equity *= (1 + r / 100)
        peak = max(peak, equity)
        max_dd = min(max_dd, ((equity - peak) / peak) * 100)
    profit_factor = (sum(wins) / abs(sum(losses))) if losses and abs(sum(losses)) > 0 else (999.0 if wins else None)
    by_regime, by_pattern = {}, {}
    # Regime/pattern learning uses raw entry-return evidence to avoid hiding bad
    # setups that were rescued by protected exits. Overall performance cards still
    # use the selected reporting return above.
    for t, r in zip(trades, entry_returns):
        by_regime.setdefault(t.get('regime') or 'unknown', []).append(r)
        by_pattern.setdefault(t.get('pattern_key') or 'general', []).append(r)
    regime_stats = {k: {'trades': len(v), 'win_rate_pct': round(sum(1 for x in v if x > 0)/len(v)*100, 1), 'expectancy_pct': round(float(np.mean(v)), 3)} for k,v in by_regime.items() if v}
    pattern_stats = {k: {'trades': len(v), 'win_rate_pct': round(sum(1 for x in v if x > 0)/len(v)*100, 1), 'expectancy_pct': round(float(np.mean(v)), 3)} for k,v in by_pattern.items() if len(v) >= 3}
    best_regime = max(regime_stats.items(), key=lambda kv: kv[1]['expectancy_pct'])[0] if regime_stats else None
    worst_regime = min(regime_stats.items(), key=lambda kv: kv[1]['expectancy_pct'])[0] if regime_stats else None
    by_stock = {}
    for t, r in zip(trades, returns):
        ticker = t.get('ticker') or 'UNKNOWN'
        bucket = by_stock.setdefault(ticker, [])
        bucket.append((r, t))
    saved = [float(t.get('avoided_loss_pct') or 0) for t in trades]
    missed = [float(t.get('missed_profit_pct') or 0) for t in trades]
    protected_exits = [t for t in trades if str(t.get('protected_action') or '').upper() in ('CAPITAL_PROTECTION_EXIT','PROFIT_PROTECTION_EXIT')]
    exit_aware_summary = {
        'enabled': BACKTEST_EXIT_AWARE_ENABLED,
        'return_mode': BACKTEST_RETURN_MODE,
        'raw_entry_avg_pct': round(float(np.mean(entry_returns)), 3) if entry_returns else None,
        'protected_avg_pct': round(float(np.mean(returns)), 3) if returns else None,
        'protection_exits': len(protected_exits),
        'total_avoided_loss_pct': round(sum(saved), 3),
        'avg_avoided_loss_pct': round(float(np.mean([x for x in saved if x > 0])), 3) if any(x > 0 for x in saved) else 0,
        'total_missed_profit_pct': round(sum(missed), 3),
        'plain_summary': 'Overall result uses protected exits when enabled, but learning rules still use raw entry baseline so avoided losses do not hide weak patterns.'
    }
    stock_stats = []
    for ticker, values in by_stock.items():
        stock_returns = [v[0] for v in values]
        stock_wins = [x for x in stock_returns if x > 0]
        stock_losses = [x for x in stock_returns if x <= 0]
        outcomes = {}
        reasons = {}
        regimes = {}
        for _, trade in values:
            outcomes[trade.get('outcome') or 'unknown'] = outcomes.get(trade.get('outcome') or 'unknown', 0) + 1
            if trade.get('failure_reason'):
                reasons[trade.get('failure_reason')] = reasons.get(trade.get('failure_reason'), 0) + 1
            regimes[trade.get('regime') or 'unknown'] = regimes.get(trade.get('regime') or 'unknown', 0) + 1
        stock_stats.append({
            'ticker': ticker,
            'trades': len(stock_returns),
            'win_rate_pct': round((len(stock_wins) / len(stock_returns)) * 100, 1) if stock_returns else None,
            'expectancy_pct': round(float(np.mean(stock_returns)), 3) if stock_returns else None,
            'avg_win_pct': round(float(np.mean(stock_wins)), 3) if stock_wins else None,
            'avg_loss_pct': round(float(np.mean(stock_losses)), 3) if stock_losses else None,
            'best_trade_pct': round(max(stock_returns), 3) if stock_returns else None,
            'worst_trade_pct': round(min(stock_returns), 3) if stock_returns else None,
            'target_hits': outcomes.get('target_hit', 0),
            'stop_hits': outcomes.get('stop_loss_hit', 0),
            'horizon_exits': outcomes.get('horizon_exit', 0),
            'top_failure_reason': max(reasons.items(), key=lambda kv: kv[1])[0] if reasons else None,
            'dominant_regime': max(regimes.items(), key=lambda kv: kv[1])[0] if regimes else None,
        })
    stock_stats.sort(key=lambda x: (x.get('trades') or 0, x.get('expectancy_pct') or -999), reverse=True)

    return {
        'total_trades': len(returns), 'win_rate_pct': round((len(wins)/len(returns))*100, 1), 'expectancy_pct': round(avg, 3), 'avg_trade_pct': round(avg, 3),
        'avg_win_pct': round(float(np.mean(wins)), 3) if wins else None, 'avg_loss_pct': round(float(np.mean(losses)), 3) if losses else None,
        'avg_win_loss_ratio': round((float(np.mean(wins)) / abs(float(np.mean(losses)))), 2) if wins and losses and abs(float(np.mean(losses))) > 0 else None,
        'profit_factor': round(float(profit_factor), 3) if profit_factor is not None else None,
        'sharpe': round(float(sharpe), 3) if sharpe is not None else None, 'sortino': round(float(sortino), 3) if sortino is not None else None,
        'max_drawdown_pct': round(max_dd, 3), 'final_equity_index': round(equity, 2),
        'regime_stats': regime_stats, 'pattern_stats': pattern_stats, 'stock_stats': stock_stats[:BACKTEST_STOCK_STATS_LIMIT], 'best_regime': best_regime, 'worst_regime': worst_regime,
        'execution_assumptions': {'slippage_bps': EXECUTION_SLIPPAGE_BPS, 'spread_bps': EXECUTION_SPREAD_BPS, 'fee_bps': EXECUTION_FEE_BPS},
        'exit_aware_learning': exit_aware_summary,
    }


def update_strategy_signal_stats(cur, market: str, horizon: str, metrics: Dict[str, Any]):
    for regime, stat in (metrics.get('regime_stats') or {}).items():
        adj = max(min((float(stat.get('expectancy_pct') or 0) * 1.8), 5.0), -7.0)
        cur.execute("""
            INSERT INTO strategy_signal_stats
                (market, horizon, regime, pattern_key, trades, win_rate_pct, expectancy_pct, avg_return_pct, confidence_adjustment, notes, updated_at)
            VALUES (%s,%s,%s,'all',%s,%s,%s,%s,%s,%s,NOW())
            ON CONFLICT (market, horizon, regime, pattern_key) DO UPDATE SET
                trades=EXCLUDED.trades, win_rate_pct=EXCLUDED.win_rate_pct, expectancy_pct=EXCLUDED.expectancy_pct,
                avg_return_pct=EXCLUDED.avg_return_pct, confidence_adjustment=EXCLUDED.confidence_adjustment,
                notes=EXCLUDED.notes, updated_at=NOW()
        """, (market, horizon, regime, stat.get('trades'), stat.get('win_rate_pct'), stat.get('expectancy_pct'), stat.get('expectancy_pct'), adj, 'Updated from historical backtest regime expectancy.'))
    for pattern, stat in (metrics.get('pattern_stats') or {}).items():
        if int(stat.get('trades') or 0) < 3:
            continue
        adj = max(min((float(stat.get('expectancy_pct') or 0) * 1.5), 4.0), -6.0)
        cur.execute("""
            INSERT INTO strategy_signal_stats
                (market, horizon, regime, pattern_key, trades, win_rate_pct, expectancy_pct, avg_return_pct, confidence_adjustment, notes, updated_at)
            VALUES (%s,%s,'all',%s,%s,%s,%s,%s,%s,%s,NOW())
            ON CONFLICT (market, horizon, regime, pattern_key) DO UPDATE SET
                trades=EXCLUDED.trades, win_rate_pct=EXCLUDED.win_rate_pct, expectancy_pct=EXCLUDED.expectancy_pct,
                avg_return_pct=EXCLUDED.avg_return_pct, confidence_adjustment=EXCLUDED.confidence_adjustment,
                notes=EXCLUDED.notes, updated_at=NOW()
        """, (market, horizon, pattern, stat.get('trades'), stat.get('win_rate_pct'), stat.get('expectancy_pct'), stat.get('expectancy_pct'), adj, 'Updated from historical backtest pattern expectancy.'))


def persist_backtest_result(market: str, horizon: str, start_dt: datetime.date, end_dt: datetime.date, universe_limit: int, top_n: int, step: int,
                            trades: List[Dict[str, Any]], metrics: Dict[str, Any], started_at: datetime.datetime,
                            fingerprint_hash: Optional[str] = None, fingerprint_payload: Optional[Dict[str, Any]] = None,
                            duplicate_of_run_id: Optional[int] = None, learning_applied: bool = True) -> Optional[int]:
    conn = get_db_connection()
    if conn is None:
        return None
    try:
        with conn:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute("""
                    INSERT INTO backtest_runs
                        (created_at, market, horizon, start_date, end_date, universe_limit, top_n, rebalance_step_days,
                         total_trades, win_rate_pct, expectancy_pct, avg_trade_pct, avg_win_pct, avg_loss_pct,
                         profit_factor, sharpe, sortino, max_drawdown_pct, best_regime, worst_regime,
                         status, metrics_json, config_json, fingerprint_hash, duplicate_of_run_id, learning_applied)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'complete',%s::jsonb,%s::jsonb,%s,%s,%s)
                    RETURNING id
                """, (
                    started_at, market, horizon, start_dt, end_dt, universe_limit, top_n, step,
                    metrics.get('total_trades') or 0, metrics.get('win_rate_pct'), metrics.get('expectancy_pct'),
                    metrics.get('avg_trade_pct'), metrics.get('avg_win_pct'), metrics.get('avg_loss_pct'),
                    metrics.get('profit_factor'), metrics.get('sharpe'), metrics.get('sortino'),
                    metrics.get('max_drawdown_pct'), metrics.get('best_regime'), metrics.get('worst_regime'),
                    json.dumps(metrics, default=_json_safe),
                    json.dumps({
                        'execution_assumptions': metrics.get('execution_assumptions'),
                        'source': metrics.get('source'),
                        'fingerprint_hash': fingerprint_hash,
                        'fingerprint_payload': fingerprint_payload,
                        'duplicate_of_run_id': duplicate_of_run_id,
                        'learning_applied': learning_applied,
                    }, default=_json_safe),
                    fingerprint_hash, duplicate_of_run_id, learning_applied
                ))
                run_id = cur.fetchone()['id']
                for t in trades[:5000]:
                    cur.execute("""
                        INSERT INTO backtest_trades
                            (run_id, ticker, market, horizon, signal_date, entry_date, exit_date, entry_price, exit_price,
                             target_price, stop_price, raw_return_pct, net_return_pct, outcome, regime, score, rsi,
                             volume_ratio, atr_pct, failure_reason, lesson_summary, pattern_key, pattern_verdict,
                             unprotected_exit_price, unprotected_net_return_pct, unprotected_outcome,
                             protected_exit_price, protected_net_return_pct, protected_outcome, protected_action, protected_reason,
                             avoided_loss_pct, missed_profit_pct, entry_learning_return_pct, exit_learning_delta_pct, features_json)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                    """, (
                        run_id, t.get('ticker'), market, horizon, t.get('signal_date'), t.get('entry_date'), t.get('exit_date'),
                        t.get('entry_price'), t.get('exit_price'), t.get('target_price'), t.get('stop_price'),
                        t.get('raw_return_pct'), t.get('net_return_pct'), t.get('outcome'), t.get('regime'),
                        t.get('score'), t.get('rsi'), t.get('volume_ratio'), t.get('atr_pct'),
                        t.get('failure_reason'), t.get('lesson_summary'), t.get('pattern_key'), t.get('pattern_verdict'),
                        t.get('unprotected_exit_price'), t.get('unprotected_net_return_pct'), t.get('unprotected_outcome'),
                        t.get('protected_exit_price'), t.get('protected_net_return_pct'), t.get('protected_outcome'),
                        t.get('protected_action'), t.get('protected_reason'), t.get('avoided_loss_pct'), t.get('missed_profit_pct'),
                        t.get('entry_learning_return_pct'), t.get('exit_learning_delta_pct'),
                        json.dumps({**(t.get('features') or {}), 'pattern_key': t.get('pattern_key'), 'failure_reason': t.get('failure_reason'), 'lesson_summary': t.get('lesson_summary'), 'exit_aware_learning': {'enabled': t.get('exit_aware_enabled'), 'return_mode': t.get('return_mode'), 'unprotected_outcome': t.get('unprotected_outcome'), 'unprotected_net_return_pct': t.get('unprotected_net_return_pct'), 'protected_outcome': t.get('protected_outcome'), 'protected_net_return_pct': t.get('protected_net_return_pct'), 'protected_action': t.get('protected_action'), 'protected_reason': t.get('protected_reason'), 'avoided_loss_pct': t.get('avoided_loss_pct'), 'missed_profit_pct': t.get('missed_profit_pct')}}, default=_json_safe)
                    ))
                if learning_applied:
                    update_strategy_signal_stats(cur, market, horizon, metrics)
                return run_id
    except Exception as e:
        print(f"[WARN] persist_backtest_result failed: {e}")
        return None
    finally:
        conn.close()


def strict_rejection_label_from_review(review: Dict[str, Any]) -> str:
    """Turn strict rule failures into short dashboard labels."""
    try:
        failed = [r for r in (review.get('rules') or []) if not r.get('passed')]
        names = ' | '.join(str(r.get('name') or '') for r in failed).lower()
        details = ' | '.join(str(r.get('detail') or '') for r in failed).lower()
        blob = names + ' ' + details
        if 'score' in blob:
            return 'low setup score'
        if 'reward' in blob or 'risk' in blob:
            return 'weak reward vs risk'
        if 'volume' in blob:
            return 'weak volume confirmation'
        if 'regime' in blob or 'risk_off' in blob or 'high volatility' in blob:
            return 'risky market type'
        if 'bearish' in blob:
            return 'bearish broad market'
        if 'macro' in blob or 'news' in blob:
            return 'major news/macro risk'
        if 'pattern' in blob:
            return 'bad historical pattern'
        if 'stock' in blob:
            return 'weak stock-specific history'
    except Exception:
        pass
    return 'strict filter'


def bump_count(bucket: Dict[str, int], label: str, by: int = 1) -> None:
    bucket[label] = int(bucket.get(label) or 0) + by


def strategy_memory_signature(market: str, horizon: str) -> str:
    """Hash of the current learned pattern/regime memory state.

    Included in the fingerprint for 'learned' mode runs so that re-running the
    exact same window/settings AFTER new learning has accumulated is treated as
    a fresh, comparable test instead of being silently deduped against an older
    result computed with a different (or empty) memory state.
    """
    memory = get_strategy_memory(market, horizon, regime=None, limit=500)
    rows = memory.get('patterns') or []
    normalized = sorted([
        {
            'regime': r.get('regime'),
            'pattern_key': r.get('pattern_key'),
            'trades': r.get('trades'),
            'confidence_adjustment': float(r.get('confidence_adjustment') or 0),
        }
        for r in rows
    ], key=lambda x: (str(x['regime']), str(x['pattern_key'])))
    raw = json.dumps(normalized, sort_keys=True, default=_json_safe, separators=(',', ':'))
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()[:16]


def backtest_fingerprint_payload(market: str, horizon: str, start_dt: datetime.date, end_dt: datetime.date,
                                 universe_limit: int, top_n: int, step: int, universe: List[str],
                                 learning_mode: str = 'raw') -> Dict[str, Any]:
    """Build the exact evidence signature used for duplicate-learning protection."""
    payload = {
        'version': BACKTEST_FINGERPRINT_VERSION,
        'market': market,
        'horizon': horizon,
        'start_date': start_dt.isoformat(),
        'end_date': end_dt.isoformat(),
        'universe_limit': int(universe_limit),
        'top_n': int(top_n),
        'rebalance_step_days': int(step),
        'universe': list(universe),
        'learning_mode': learning_mode,
        # Only stamped for 'learned' mode: makes a rerun after new learning has
        # accumulated a genuinely different, non-duplicate fingerprint.
        'strategy_memory_signature': strategy_memory_signature(market, horizon) if learning_mode == 'learned' else None,
        'quality_filter': {
            'enabled': QUALITY_STOCK_FILTER_ENABLED,
            'thresholds': quality_thresholds_for_market(market),
            'min_price': QUALITY_MIN_PRICE,
            'max_zero_volume_days': QUALITY_MAX_ZERO_VOLUME_DAYS,
            'min_recent_bars': QUALITY_MIN_RECENT_BARS,
            'min_avg_volume_multiplier': QUALITY_MIN_AVG_VOLUME_MULTIPLIER,
            'min_turnover_multiplier': QUALITY_MIN_TURNOVER_MULTIPLIER,
        },
        'strict_learning': {
            'enabled': STRICT_LEARNING_ENABLED,
            'backtest_min_score': STRICT_BACKTEST_MIN_SCORE,
            'backtest_allow_watch_only': STRICT_BACKTEST_ALLOW_WATCH_ONLY,
            'backtest_min_risk_reward': STRICT_BACKTEST_MIN_RISK_REWARD,
            'backtest_min_volume_ratio': STRICT_BACKTEST_MIN_VOLUME_RATIO,
            'backtest_reject_risk_off': STRICT_BACKTEST_REJECT_RISK_OFF,
            'pattern_reliable_min_trades': STRICT_PATTERN_RELIABLE_MIN_TRADES,
            'per_stock_min_trades': STRICT_PER_STOCK_MIN_TRADES,
        },
        'execution_costs': {
            'slippage_bps': EXECUTION_SLIPPAGE_BPS,
            'spread_bps': EXECUTION_SPREAD_BPS,
            'fee_bps': EXECUTION_FEE_BPS,
        },
        'data_provider': MARKET_DATA_PROVIDER,
        'price_mode': get_backtest_price_mode_info(),
        'data_integrity_guard': data_integrity_thresholds(),
        'exit_aware_learning': backtest_exit_learning_policy(),
        'ticker_aliases': KNOWN_TICKER_ALIASES,
    }
    return payload


def backtest_fingerprint_hash(payload: Dict[str, Any]) -> str:
    raw = json.dumps(payload, sort_keys=True, default=_json_safe, separators=(',', ':'))
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()


def find_duplicate_backtest_run(fingerprint_hash: str) -> Optional[Dict[str, Any]]:
    if not fingerprint_hash or not BACKTEST_DUPLICATE_PROTECTION:
        return None
    conn = get_db_connection()
    if conn is None:
        return None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT id, created_at, market, horizon, start_date, end_date, universe_limit, top_n,
                       rebalance_step_days, total_trades, win_rate_pct, expectancy_pct, max_drawdown_pct,
                       fingerprint_hash, learning_applied, metrics_json
                FROM backtest_runs
                WHERE fingerprint_hash=%s AND status='complete'
                ORDER BY created_at DESC
                LIMIT 1
            """, (fingerprint_hash,))
            row = cur.fetchone()
            return dict(row) if row else None
    except Exception as e:
        print(f"[WARN] duplicate backtest lookup failed: {e}")
        return None
    finally:
        conn.close()


def load_backtest_run_payload(run_id: int) -> Dict[str, Any]:
    """Internal version of the detail endpoint, used for duplicate-cache returns."""
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT id, created_at, market, horizon, start_date, end_date, universe_limit, top_n,
                       rebalance_step_days, total_trades, win_rate_pct, expectancy_pct, avg_trade_pct,
                       avg_win_pct, avg_loss_pct, profit_factor, sharpe, sortino, max_drawdown_pct,
                       best_regime, worst_regime, status, error, metrics_json, config_json,
                       fingerprint_hash, duplicate_of_run_id, learning_applied
                FROM backtest_runs
                WHERE id=%s
            """, (run_id,))
            run = cur.fetchone()
            if not run:
                return {'ok': False, 'error': 'Backtest run not found.'}
            cur.execute("""
                SELECT id, ticker, market, horizon, signal_date, entry_date, exit_date, entry_price, exit_price,
                       target_price, stop_price, raw_return_pct, net_return_pct, outcome, regime, score,
                       rsi, volume_ratio, atr_pct, failure_reason, lesson_summary, pattern_key, pattern_verdict,
                       unprotected_exit_price, unprotected_net_return_pct, unprotected_outcome,
                       protected_exit_price, protected_net_return_pct, protected_outcome, protected_action, protected_reason,
                       avoided_loss_pct, missed_profit_pct, entry_learning_return_pct, exit_learning_delta_pct, features_json
                FROM backtest_trades
                WHERE run_id=%s
                ORDER BY signal_date DESC, ticker ASC
                LIMIT 10000
            """, (run_id,))
            trades = [dict(r) for r in cur.fetchall()]
        metrics = run.get('metrics_json') or {}
        if isinstance(metrics, str):
            try:
                metrics = json.loads(metrics)
            except Exception:
                metrics = {}
        run_dict = dict(run)
        per_stock = aggregate_stock_backtest_rows(trades)
        prev_run = None
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur2:
            prev_run = find_previous_same_config_run(cur2, run_dict)
            if prev_run:
                cur2.execute("""
                    SELECT ticker, net_return_pct, outcome, regime, failure_reason, lesson_summary,
                           pattern_key, pattern_verdict, score, rsi, volume_ratio, atr_pct
                    FROM backtest_trades WHERE run_id=%s
                """, (prev_run.get('id'),))
                prev_trades = [dict(r) for r in cur2.fetchall()]
                prev_per_stock = {s['ticker']: s for s in aggregate_stock_backtest_rows(prev_trades)}
                for s in per_stock:
                    prev_s = prev_per_stock.get(s.get('ticker'))
                    if prev_s:
                        s['prev_run_id'] = prev_run.get('id')
                        s['prev_win_rate_pct'] = prev_s.get('win_rate_pct')
                        s['prev_expectancy_pct'] = prev_s.get('expectancy_pct')
                        s['delta_win_rate_pct'] = (round(s.get('win_rate_pct') - prev_s.get('win_rate_pct'), 1)
                                                   if s.get('win_rate_pct') is not None and prev_s.get('win_rate_pct') is not None else None)
                        s['delta_expectancy_pct'] = (round(s.get('expectancy_pct') - prev_s.get('expectancy_pct'), 3)
                                                     if s.get('expectancy_pct') is not None and prev_s.get('expectancy_pct') is not None else None)
        run_dict['rerun_info'] = _rerun_delta(prev_run, run_dict) if prev_run else {'is_rerun': False}
        return {
            'ok': True,
            'run': run_dict,
            'metrics': metrics,
            'trades': trades,
            'per_stock': per_stock,
            'plain_note': 'This is the full history of one past backtest run. It shows old simulated trades used for research/learning, not tomorrow’s live picks.'
        }
    except Exception as e:
        return {'ok': False, 'error': str(e)}
    finally:
        conn.close()


def get_intraday_backtest_config() -> Dict[str, Any]:
    """Minute-bar data now comes from INDstocks (IndMoney) via market_data.py, not
    yfinance -- see indstocks_client.py. INDstocks caps each individual historical
    call to a 7-day span for minute intervals (MAX_RANGE_DAYS), but market_data.py's
    get_historical() already walks that window-by-window under the hood, so total
    depth isn't hard-capped at 7 days the way it would be with a single yfinance call.
    59 days is kept as a conservative default (not a hard provider limit) so a
    single backtest run doesn't fire off an excessive number of chained API calls
    per ticker. Raise it from the Intraday Lab settings if your INDstocks plan
    serves deeper 5-minute history and you want to test further back."""
    return {'interval': '5m', 'max_lookback_days': 59}


def group_intraday_frame_by_day(h) -> Dict[Any, Any]:
    """Split one ticker's flat minute-bar DataFrame into per-IST-trading-day frames.
    Shared by fetch_intraday_bars_for_backtest() (single-ticker path) and the
    batched fetch in run_intraday_historical_backtest()/run_intraday_replay() so
    all three group days identically.

    BUG FIX: market_data.py (the INDstocks-backed shim that replaced yfinance)
    already returns tz-naive timestamps that are IST wall-clock local time (see
    market_data._candles_to_df, which builds the index from IST_OFFSET directly).
    This used to tz_localize('UTC') first and then tz_convert to Asia/Kolkata,
    which added a spurious +5:30 on top of values that were already IST -- e.g. a
    candle that is really 09:15 IST got relabeled 14:45. Day-bucketing still
    landed on the correct calendar date (both ends of the trading session shift
    by the same amount and never cross midnight), but every wall-clock comparison
    that reads bar timestamps directly -- force-exit-before-close cutoffs,
    simulated "now" for the replay engine, late-session timing -- was silently
    off by 5.5 hours. Naive timestamps from this data source are IST already;
    just label them as such instead of re-deriving IST from a false UTC premise.
    """
    if h is None or h.empty:
        return {}
    h = normalize_history_frame(h)
    tz = ZoneInfo('Asia/Kolkata')
    if h.index.tz is None:
        h.index = h.index.tz_localize(tz)
    else:
        h.index = h.index.tz_convert(tz)
    return {d: g for d, g in h.groupby(h.index.date)}


def fetch_intraday_bars_for_backtest(ticker: str, start_date, end_date, interval: str) -> Dict[Any, Any]:
    """Fetch minute-bar history for one ticker across [start_date, end_date] and group
    it by IST trading day. Uses explicit start/end dates (like fetch_daily() above)
    rather than a relative period=f'{n}d' string -- market_data.py's period parser only
    recognizes a small fixed set of period strings ('1d','5d','15d','1mo',...); an
    arbitrary day-count like '43d' silently fell back to a 365-day window anchored at
    *today*, not at this backtest's own end_date. That mismatch was the root cause of
    intraday backtests coming back with zero candidates whenever end_date wasn't today:
    the minute-bar data fetched didn't even cover the calendar days being tested. A few
    extra days are padded past end_date so the trading day *after* the last signal date
    is available for next-day trade entry, same reasoning as fetch_daily()'s own padding."""
    try:
        h = yf.Ticker(ticker).history(
            start=start_date.isoformat(),
            end=(end_date + datetime.timedelta(days=4)).isoformat(),
            interval=interval, timeout=YF_TIMEOUT,
        )
        return group_intraday_frame_by_day(h)
    except Exception:
        return {}


def build_intraday_backtest_snapshot(ticker: str, day_df, upto_idx: int) -> Dict[str, Any]:
    """Reconstruct the same snapshot shape fetch_intraday_snapshot() returns live,
    but from historical minute bars up to (and including) upto_idx within one
    trading day -- so the backtest exit logic sees exactly what the live snapshot
    function would have seen at that point in the session."""
    window = day_df.iloc[:upto_idx + 1]
    if window.empty:
        return {'ok': False, 'ticker': ticker}
    close = window['Close'].dropna()
    high = window['High'].dropna() if 'High' in window else close
    low = window['Low'].dropna() if 'Low' in window else close
    vol = window['Volume'].dropna() if 'Volume' in window else None
    last = float(close.iloc[-1]) if not close.empty else None
    open_price = float(window['Open'].dropna().iloc[0]) if 'Open' in window and not window['Open'].dropna().empty else last
    session_high = float(high.max()) if not high.empty else last
    session_low = float(low.min()) if not low.empty else last
    recent_closes = [float(x) for x in close.tail(4).tolist()]
    recent_trend = 'flat'
    if len(recent_closes) >= 3:
        if recent_closes[-1] < recent_closes[-2] < recent_closes[-3]:
            recent_trend = 'falling'
        elif recent_closes[-1] > recent_closes[-2] > recent_closes[-3]:
            recent_trend = 'rising'
    completed_vol = vol.iloc[:-1] if vol is not None and len(vol) > 1 else vol
    avg_bar_volume = float(completed_vol.tail(20).mean()) if completed_vol is not None and not completed_vol.empty else None
    recent_window = vol.tail(3) if vol is not None else None
    last_bar_volume = float(recent_window.mean()) if recent_window is not None and not recent_window.empty else None
    vwap = None
    try:
        if vol is not None and not vol.empty and float(vol.sum()) > 0:
            typical = (window['High'] + window['Low'] + window['Close']) / 3
            vwap = float((typical * window['Volume']).sum() / window['Volume'].sum())
    except Exception:
        vwap = None
    return {
        'ok': True, 'ticker': ticker, 'last': last, 'open': open_price,
        'high': session_high, 'low': session_low, 'recent_closes': recent_closes,
        'recent_trend': recent_trend, 'vwap': vwap,
        'last_bar_volume': last_bar_volume, 'avg_bar_volume': avg_bar_volume,
        'bars': int(len(window)),
    }


def simulate_intraday_backtest_trade(ticker: str, day_df, entry_idx: int, candidate: Dict[str, Any],
                                      intraday_settings: Dict[str, Any], effective_settings: Dict[str, Any],
                                      market: str, signal_date) -> Optional[Dict[str, Any]]:
    """Replay one intraday trade against real minute bars using the SAME exit
    function the live/paper engine uses (evaluate_profit_protection_exit), so a
    backtest win/loss reflects the real exit logic instead of a separate
    approximation. Known gap: TIME_DECAY_EXIT and LATE_SESSION_WEAK_HOLD inside
    that function key off live wall-clock time, so they're effectively inactive
    when replaying historical timestamps -- every other exit path (target, stop,
    trailing profit-protect, momentum-fade, quick-profit-book, force-exit-before-close)
    runs exactly as it does live."""
    if entry_idx >= len(day_df):
        return None
    entry_snap = build_intraday_backtest_snapshot(ticker, day_df, entry_idx)
    if not entry_snap.get('ok') or not entry_snap.get('last'):
        return None
    candidate = dict(candidate)
    candidate['last'] = entry_snap['last']
    candidate['vwap'] = entry_snap.get('vwap')
    candidate['opening_low'] = entry_snap.get('low')
    candidate['opening_high'] = entry_snap.get('high')
    candidate = attach_intraday_trade_metrics(candidate, intraday_settings)
    entry_price = float(candidate.get('entry_price') or 0)
    stop_price = float(candidate.get('stop_price') or 0)
    target_price = float(candidate.get('target_price') or 0)
    if entry_price <= 0 or stop_price <= 0 or target_price <= 0:
        return None
    try:
        position_value = float(intraday_settings.get('min_position_value_inr') or 10000)
        qty = max(1, int(position_value / entry_price))
    except Exception:
        qty = 1
    pos = {
        'entry_price': entry_price, 'target_price': target_price, 'stop_price': stop_price,
        'quantity': qty, 'market': market, 'horizon': 'intraday', 'side': _candidate_side(candidate),
        'peak_price': entry_price, 'trough_price': entry_price, 'trailing_stop_price': stop_price,
        'opened_at': None, 'metadata_json': {'profit_book_pct': intraday_settings.get('profit_book_pct')},
    }
    force_exit_minutes = int(intraday_settings.get('force_exit_before_close_minutes') or 15)
    market_close_ts = day_df.index[-1]
    force_exit_cutoff = market_close_ts - datetime.timedelta(minutes=force_exit_minutes)
    exit_price, exit_reason, exit_idx = None, None, None
    for j in range(entry_idx, len(day_df)):
        snap = build_intraday_backtest_snapshot(ticker, day_df, j)
        if not snap.get('ok') or not snap.get('last'):
            continue
        if day_df.index[j] >= force_exit_cutoff:
            exit_price, exit_reason, exit_idx = snap['last'], 'INTRADAY_FORCE_EXIT_BEFORE_CLOSE', j
            break
        try:
            reason, meta = evaluate_profit_protection_exit(pos, effective_settings, snap)
        except Exception:
            # Defensive fallback: if the live exit function hits an edge case it
            # doesn't expect from a synthetic backtest pos/snap, fall back to a
            # plain target/stop check for this bar rather than aborting the trade.
            reason, meta = None, {'last': snap['last']}
            side = _candidate_side(candidate)
            if (side == 'LONG' and snap['last'] >= target_price) or (side == 'SHORT' and snap['last'] <= target_price):
                reason = 'TARGET_HIT'
            elif (side == 'LONG' and snap['last'] <= stop_price) or (side == 'SHORT' and snap['last'] >= stop_price):
                reason = 'STOP_LOSS_HIT'
        pos['peak_price'] = meta.get('peak', pos['peak_price'])
        pos['trough_price'] = meta.get('trough', pos['trough_price'])
        pos['trailing_stop_price'] = meta.get('trailing_stop_price', pos['trailing_stop_price'])
        if reason:
            exit_price = meta.get('last') or snap['last']
            exit_reason, exit_idx = reason, j
            break
    if exit_price is None:
        last_snap = build_intraday_backtest_snapshot(ticker, day_df, len(day_df) - 1)
        exit_price = last_snap.get('last') or entry_price
        exit_reason, exit_idx = 'END_OF_DAY_EXIT', len(day_df) - 1

    pnl = calculate_net_trade_pnl(entry_price, exit_price, qty, market, _candidate_side(candidate))
    raw_return_pct = v3_2_engine.gross_return_pct(entry_price, exit_price, _candidate_side(candidate)) if entry_price else 0
    net_return_pct = float(pnl.get('net_pnl_pct') if pnl.get('net_pnl_pct') is not None else raw_return_pct)
    outcome = 'target_hit' if exit_reason == 'TARGET_HIT' else (
        'stop_loss_hit' if exit_reason in ('STOP_LOSS_HIT', 'TRAILING_STOP_GAVE_BACK_PROFIT') else 'horizon_exit')
    return {
        'ticker': ticker, 'signal_date': str(signal_date), 'entry_date': str(day_df.index[entry_idx]),
        'exit_date': str(day_df.index[exit_idx]) if exit_idx is not None else str(day_df.index[-1]),
        'entry_price': round(entry_price, 2), 'exit_price': round(float(exit_price), 2),
        'target_price': round(target_price, 2), 'stop_price': round(stop_price, 2),
        'raw_return_pct': round(raw_return_pct, 3), 'net_return_pct': round(net_return_pct, 3),
        'outcome': outcome, 'failure_reason': exit_reason if net_return_pct <= 0 else None,
        'lesson_summary': f'Exit: {exit_reason}',
        'regime': (candidate.get('regime_info') or {}).get('regime') if isinstance(candidate.get('regime_info'), dict) else None,
        'score': candidate.get('final_pre_ai_score'), 'pattern_key': candidate.get('strategy_pattern_key'),
        'unprotected_exit_price': round(float(exit_price), 2), 'unprotected_net_return_pct': round(net_return_pct, 3), 'unprotected_outcome': outcome,
        'protected_exit_price': round(float(exit_price), 2), 'protected_net_return_pct': round(net_return_pct, 3), 'protected_outcome': outcome,
        'protected_action': exit_reason, 'protected_reason': f'Live evaluate_profit_protection_exit result: {exit_reason}',
        'avoided_loss_pct': 0, 'missed_profit_pct': 0,
        'entry_learning_return_pct': round(net_return_pct, 3), 'exit_learning_delta_pct': 0,
    }


def run_intraday_historical_backtest(market: str, start_date: Optional[str] = None, end_date: Optional[str] = None,
                                      universe_limit: Optional[int] = None, top_n: Optional[int] = None,
                                      commit_learning: bool = False, require_cap_filter: bool = True) -> Dict[str, Any]:
    """LEGACY ENGINE -- NOT THE PRIMARY BENCHMARK (report: "the legacy backtest is
    STILL in the application... otherwise you can end up comparing incompatible
    engines"). This predates the 10-strategy selector and does not have strategy
    selection, EV-before-selection, strategy-specific stop/target
    (compute_intraday_risk_plan), the risk-budget allocator, or exit calibration.
    Kept only for historical/legacy comparison -- use Intraday Replay Lab
    (start_intraday_replay) to evaluate the current system. See
    metrics['benchmark_warning'] in this function's return value, surfaced
    through the API/UI so this distinction isn't only a code comment.

    Real intraday backtest. Same-day hold, real intraday_settings target/stop
    math, and the actual evaluate_profit_protection_exit() function replayed
    against real minute bars -- not the swing-style 5-session/daily-bar path that
    horizon='intraday' used to silently fall into.

    require_cap_filter (default True): PARITY FIX -- this engine used to always
    scan load_market_universe(market) directly, unfiltered, while Live
    (get_intraday_scan_universe) and Replay Lab (require_cap_filter, default True)
    both restrict intraday trading to the Large/Mid-cap allowlist by default. That
    meant the Backtest Lab could report results for stocks Live/Replay would never
    have touched. Now it goes through the SAME get_intraday_scan_universe() Live
    uses, and -- matching Replay Lab's own default -- refuses to run rather than
    silently widening the universe if the allowlist genuinely isn't available.
    Pass require_cap_filter=False to explicitly run the full configured universe.

    Known simplifications (documented, not hidden):
    - Candidate/day selection reuses the existing daily-technical scoring (same
      scorer as the day/week backtest) as a watchlist filter, since a single day
      of minute bars alone can't compute multi-day RSI/MACD/trend context.
    - Minute-bar data comes from INDstocks (IndMoney), not yfinance -- see
      get_intraday_backtest_config(). The window is still clamped (59 days by
      default) as a conservative cap on API calls per run, not because the
      provider hard-stops at that depth.
    - TIME_DECAY_EXIT and LATE_SESSION_WEAK_HOLD inside the live exit function are
      wall-clock-dependent and are effectively inactive during replay.
    """
    if not BACKTEST_ENABLED:
        return {'ok': False, 'error': 'Backtesting is disabled by BACKTEST_ENABLED=false'}
    market, _ = validate_market_horizon(market, 'intraday')
    cfg = get_intraday_backtest_config()
    universe_limit = int(universe_limit or BACKTEST_UNIVERSE_LIMIT)
    top_n = int(top_n or BACKTEST_TOP_N)
    end_dt = datetime.date.fromisoformat(end_date) if end_date else datetime.date.today()
    requested_start_dt = datetime.date.fromisoformat(start_date) if start_date else end_dt - datetime.timedelta(days=cfg['max_lookback_days'])
    earliest_allowed = end_dt - datetime.timedelta(days=cfg['max_lookback_days'])
    start_dt = max(requested_start_dt, earliest_allowed)
    clamped = start_dt != requested_start_dt

    cap_filter_applied = False
    cap_filter_source = None
    if require_cap_filter:
        cap_meta = fetch_and_cache_large_mid_cap_allowlist()
        allowlist = cap_meta.get('symbols')
        base_market_universe = load_market_universe(market)
        filtered = apply_cap_allowlist(base_market_universe, allowlist)
        if filtered is None:
            no_overlap = bool(allowlist)
            return {'ok': False, 'error': (
                (f'Large/Mid-cap universe is required for this run (require_cap_filter=true, the default), and an '
                 f'allowlist of {len(allowlist)} symbols WAS loaded (source={cap_meta.get("source")}), but NONE of them '
                 'matched the configured universe even after stripping exchange suffixes -- ticker-format mismatch, not '
                 'a missing file.') if no_overlap else
                ('Large/Mid-cap universe is required for this run (require_cap_filter=true, the default) but no '
                 'allowlist is available right now -- data/large_mid_cap_universe.txt is empty and the '
                 'auto-download of the NIFTY LargeMidcap 250 constituent list failed. Populate the file '
                 'or set require_cap_filter=false to explicitly run unfiltered (matches Replay Lab\'s own default behavior).')
            )}
        base_universe = filtered
        cap_filter_applied = True
        cap_filter_source = cap_meta.get('source')
    else:
        base_universe = load_market_universe(market)
    universe = base_universe[:max(1, universe_limit)]
    intraday_settings = get_intraday_settings()
    trading_settings = get_trading_settings()
    effective_settings = get_intraday_effective_trading_settings(trading_settings, intraday_settings)

    daily_hist: Dict[str, Any] = {}

    # Batched 5-tickers-per-HTTP-call (same pattern fetch_intraday_candidates_batch()
    # already uses for the live scan) instead of one Ticker.history() call per ticker.
    # The old per-ticker loop here was issuing 5x more HTTP calls than necessary against
    # INDstocks' rate limit -- for a 25-ticker universe that's 25 individual daily calls
    # plus, worse, 25 x ~9 individual 5-minute-window calls below, which is exactly what
    # was producing the storms of 429 "Rate limit exceeded" failures seen in production.
    daily_chunks = [universe[i:i + 5] for i in range(0, len(universe), 5)]
    daily_workers = min(max(1, BACKTEST_MAX_WORKERS), max(1, len(daily_chunks)))
    with concurrent.futures.ThreadPoolExecutor(max_workers=daily_workers) as ex:
        futures = {
            ex.submit(yf.history_batch, chunk,
                      start=(start_dt - datetime.timedelta(days=220)).isoformat(),
                      end=(end_dt + datetime.timedelta(days=2)).isoformat(),
                      interval='1d', timeout=YF_TIMEOUT): chunk
            for chunk in daily_chunks
        }
        for fut in concurrent.futures.as_completed(futures):
            try:
                for ticker, h in fut.result().items():
                    if h is not None and not h.empty and len(h) >= BACKTEST_MIN_HISTORY_DAYS + 5:
                        daily_hist[ticker] = normalize_history_frame(h)
            except Exception:
                continue
    if not daily_hist:
        return {'ok': False, 'error': 'No daily history available for candidate scoring in selected universe.'}

    minute_universe = [t for t in universe if t in daily_hist]
    minute_chunks = [minute_universe[i:i + 5] for i in range(0, len(minute_universe), 5)]
    minute_workers = min(max(1, BACKTEST_MAX_WORKERS), max(1, len(minute_chunks)))
    intraday_hist: Dict[str, Dict[Any, Any]] = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=minute_workers) as ex:
        futures = {
            ex.submit(yf.history_batch, chunk,
                      start=start_dt.isoformat(),
                      end=(end_dt + datetime.timedelta(days=4)).isoformat(),
                      interval=cfg['interval'], timeout=YF_TIMEOUT): chunk
            for chunk in minute_chunks
        }
        for fut in concurrent.futures.as_completed(futures):
            try:
                for ticker, h in fut.result().items():
                    by_day = group_intraday_frame_by_day(h)
                    if by_day:
                        intraday_hist[ticker] = by_day
            except Exception:
                continue
    if not intraday_hist:
        return {'ok': False, 'error': 'No intraday minute-bar history available (provider may not serve intraday data for this universe/date range).'}

    # Union the trading-day calendar across every ticker we actually got daily
    # data for, instead of picking one arbitrary ticker's own date list.
    #
    # The old code walked daily_hist.values() (order isn't even deterministic --
    # it's whichever ticker's ThreadPoolExecutor future completed and got
    # inserted first) and only accepted the FIRST ticker whose own in-range day
    # count exceeded 10, discarding every other ticker's dates entirely. Two
    # consequences, both silent:
    #   1. Any requested window with 10 or fewer trading days (two calendar
    #      weeks or less) left `calendar` as [] -- the main loop below then
    #      ran zero iterations and the run reported "no trades" without ever
    #      checking a single day, indistinguishable from a window that WAS
    #      checked and genuinely had nothing.
    #   2. Even for longer windows, whichever ticker happened to win the race
    #      could have its own gaps (a listing gap, a data-provider hiccup for
    #      just that scrip) and those gaps silently became gaps in the whole
    #      run's calendar, even though other tickers had valid data for them.
    # A union has neither failure mode: any ticker's data can contribute a
    # trading day, and there's no arbitrary minimum-count gate at all.
    calendar_dates = set()
    for h in daily_hist.values():
        for idx in h.index:
            d = idx.date()
            if start_dt <= d <= end_dt:
                calendar_dates.add(d)
    calendar = sorted(calendar_dates)

    if not calendar:
        return {'ok': False,
                'error': (f'No trading days with daily price history fall between {start_dt.isoformat()} and '
                          f'{end_dt.isoformat()} for this market/universe, so no day was even attempted '
                          f'(0 trading days found -- double-check the date range covers actual market days).'),
                'diagnostics': {'trading_days_in_window': 0, 'universe_size_with_daily_data': len(daily_hist),
                                 'universe_size_with_minute_data': len(intraday_hist),
                                 'window_clamped_to_provider_limit': clamped}}

    trades = []
    started = utc_now_naive()
    deadline_ts = time.monotonic() + max(8, BACKTEST_MAX_RUNTIME_SECONDS)
    skipped_no_intraday_data = 0
    min_score_gate = float(intraday_settings.get('min_score') or 70)
    max_trades_per_day = int(intraday_settings.get('max_candidates') or top_n)

    # Rejection-reason counters -- purely diagnostic, so that "no trades" can
    # say WHICH gate actually zeroed things out instead of shrugging with an
    # "X or Y or Z" error that gives no way to tell which one happened.
    rejected_insufficient_history = 0
    rejected_no_snapshot_or_volume = 0
    rejected_low_liquidity = 0
    rejected_below_score_gate = 0
    best_score_seen = None
    days_checked = 0

    for signal_date in calendar:
        if time.monotonic() > deadline_ts:
            break
        days_checked += 1
        day_candidates = []
        for ticker, h in daily_hist.items():
            try:
                eligible_idx = [i for i, idx in enumerate(h.index) if idx.date() <= signal_date]
                if not eligible_idx:
                    continue
                idx = eligible_idx[-1]
                if idx < BACKTEST_MIN_HISTORY_DAYS or idx + 1 >= len(h):
                    rejected_insufficient_history += 1
                    continue
                snap = historical_snapshot_at(ticker, h, idx)
                if not snap:
                    rejected_no_snapshot_or_volume += 1
                    continue
                snap = score_historical_candidate(snap, market, 'intraday')
                if snap.get('avg_volume_20', 0) <= 0:
                    rejected_no_snapshot_or_volume += 1
                    continue
                score = float(snap.get('final_pre_ai_score') or 0)
                best_score_seen = score if best_score_seen is None else max(best_score_seen, score)
                liq_ok, _ = snapshot_passes_liquidity(snap, market)
                if not liq_ok:
                    rejected_low_liquidity += 1
                    continue
                if score < min_score_gate:
                    rejected_below_score_gate += 1
                    continue
                day_candidates.append((ticker, idx, snap))
            except BaseException:
                rejected_no_snapshot_or_volume += 1
                continue
        day_candidates.sort(key=lambda item: item[2].get('final_pre_ai_score', 0), reverse=True)

        entries_today = 0
        for ticker, idx, snap in day_candidates:
            if entries_today >= min(top_n, max_trades_per_day):
                break
            by_day = intraday_hist.get(ticker) or {}
            trade_day = next((d for d in sorted(by_day.keys()) if d > signal_date), None)
            day_bars = by_day.get(trade_day) if trade_day else None
            if day_bars is None or day_bars.empty:
                skipped_no_intraday_data += 1
                continue
            wait_minutes = int(intraday_settings.get('opening_wait_minutes') or 15)
            entry_cutoff = day_bars.index[0] + datetime.timedelta(minutes=wait_minutes)
            entry_candidates_idx = [i for i, ts in enumerate(day_bars.index) if ts >= entry_cutoff]
            if not entry_candidates_idx:
                continue
            trade = simulate_intraday_backtest_trade(ticker, day_bars, entry_candidates_idx[0], snap,
                                                       intraday_settings, effective_settings, market, signal_date)
            if trade:
                trade['market'] = market
                trade['horizon'] = 'intraday'
                trades.append(trade)
                entries_today += 1

    if not trades:
        deadline_hit = days_checked < len(calendar)
        gate_breakdown = (
            f'Checked {days_checked} of {len(calendar)} trading day(s) in range '
            f'({start_dt.isoformat()} to {end_dt.isoformat()})'
            + (' -- stopped early after hitting the run-time limit, so the rest of the window was never checked.'
               if deadline_hit else '.') +
            f' Across {len(daily_hist)} stock(s) with daily data and {len(intraday_hist)} with 5-minute data: '
            f'{rejected_insufficient_history} candidate-day(s) lacked enough price history, '
            f'{rejected_no_snapshot_or_volume} had no usable snapshot/volume data, '
            f'{rejected_low_liquidity} failed the liquidity filter, and '
            f'{rejected_below_score_gate} scored below the {min_score_gate:.0f}-point minimum'
            + (f' (best score seen: {best_score_seen:.1f})' if best_score_seen is not None else '') + '. '
            + (f'{skipped_no_intraday_data} candidate(s) that DID clear every gate had no matching next-day minute-bar data.'
               if skipped_no_intraday_data else 'None that cleared the gates were left to check for minute-bar data.')
        )
        return {'ok': False,
                'error': f'No intraday trades could be simulated in this window. {gate_breakdown}',
                'diagnostics': {
                    'trading_days_in_window': len(calendar), 'trading_days_checked': days_checked,
                    'run_time_limit_hit': deadline_hit,
                    'universe_size_with_daily_data': len(daily_hist), 'universe_size_with_minute_data': len(intraday_hist),
                    'window_clamped_to_provider_limit': clamped,
                    'effective_min_score_gate': min_score_gate, 'best_score_seen': best_score_seen,
                    'rejected_insufficient_history': rejected_insufficient_history,
                    'rejected_no_snapshot_or_volume': rejected_no_snapshot_or_volume,
                    'rejected_low_liquidity': rejected_low_liquidity,
                    'rejected_below_score_gate': rejected_below_score_gate,
                    'skipped_no_intraday_data': skipped_no_intraday_data,
                },
                'skipped_no_intraday_data': skipped_no_intraday_data}

    metrics = compute_backtest_metrics(trades)
    metrics.update({
        'start_date': start_dt.isoformat(), 'end_date': end_dt.isoformat(),
        'universe_size_requested': universe_limit, 'universe_size_with_data': len(intraday_hist),
        'top_n': top_n, 'data_interval': cfg['interval'],
        'window_clamped_to_provider_limit': clamped,
        'window_clamp_note': (f'Intraday runs are capped at {cfg["max_lookback_days"]} days per run (to limit API calls per ticker), so the window was clamped to {start_dt.isoformat()} - {end_dt.isoformat()}.' if clamped else None),
        'skipped_no_intraday_data': skipped_no_intraday_data,
        'exit_logic_note': 'Exits replay the live evaluate_profit_protection_exit() function against real minute bars, not a separate backtest-only approximation. TIME_DECAY_EXIT and LATE_SESSION_WEAK_HOLD are wall-clock-dependent live rules and are effectively inactive in this replay.',
        'learning_mode': 'raw',
        'cap_filter_applied': cap_filter_applied,
        'cap_filter_source': cap_filter_source,
    })
    fingerprint_payload = backtest_fingerprint_payload(market, 'intraday', start_dt, end_dt, universe_limit, top_n, 1, list(intraday_hist.keys()), learning_mode='raw')
    fingerprint_hash = backtest_fingerprint_hash(fingerprint_payload)
    run_id = persist_backtest_result(market, 'intraday', start_dt, end_dt, universe_limit, top_n, 1, trades, metrics, started,
                                      fingerprint_hash=fingerprint_hash, fingerprint_payload=fingerprint_payload, learning_applied=commit_learning)
    metrics['commit_learning'] = commit_learning
    metrics['commit_learning_note'] = (
        'This run WROTE its results into strategy_signal_stats and will influence future learned-mode runs.'
        if commit_learning else
        'This run did NOT write into strategy_signal_stats (research/comparison mode).'
    )
    # NOT THE PRIMARY BENCHMARK (report -- "the legacy backtest is STILL in the
    # application"). This engine does not go through the 10-strategy selector,
    # the EV-before-selection gate, strategy-specific stop/target, the risk-budget
    # allocator, or exit calibration -- it's a simpler single-scorer backtest kept
    # for historical comparison only. Use Intraday Replay Lab
    # (start_intraday_replay / _run_intraday_replay_worker) as the benchmark for
    # the current multi-strategy system; comparing this engine's numbers against
    # Replay Lab's compares two different, incompatible engines.
    metrics['benchmark_warning'] = (
        'This is the LEGACY single-scorer intraday backtest, not the current 10-strategy engine. It does not '
        'use strategy selection, EV-before-selection, strategy-specific stop/target, the risk-budget allocator, '
        'or exit calibration. Do NOT use this as the primary profitability benchmark for the current system -- '
        'use Intraday Replay Lab for that. This engine is kept only for historical/legacy comparison.'
    )
    metrics['run_id'] = run_id
    metrics['recent_trades'] = trades[-60:][::-1]
    metrics['ok'] = True
    return metrics


# =============================================================================
# INTRADAY REPLAY LAB
# =============================================================================
# A controllable historical replay of the *actual live intraday engine*, not a
# separate/approximate backtest strategy. It reuses, unmodified:
#   - load_market_universe()                    (same universe as Live/Paper)
#   - get_intraday_settings()                    (same strategy settings)
#   - fetch_intraday_candidate_snapshot()         (same scoring math, fed
#                                                  historical candles instead
#                                                  of a live quote)
#   - score_intraday_prescan_candidate()          (same pre-scan ranking)
#   - attach_intraday_trade_metrics()             (same entry/target/stop math)
#   - evaluate_profit_protection_exit()           (same exit rules, now
#                                                  clock-aware via sim_now)
#
# Known, documented simplifications (see item list this replaced):
#   - The universe is the same curated Large/Mid-cap NIFTY-500-style list
#     load_market_universe() already returns for Live/Paper -- there is no
#     point-in-time market-cap-on-that-date classification, so a stock that
#     has since been removed/renamed from the index is filtered by
#     KNOWN_TICKER_ALIASES only, not by point-in-time index membership.
#   - Candle-level SL/target conflicts: when both stop and target sit inside
#     the same 5-minute bar, the conservative adverse-outcome-first rule is
#     applied (see _resolve_intrabar_conflict below) BEFORE the live exit
#     function even runs, so replay results are never inflated by assuming
#     the favorable order.
INTRADAY_REPLAY_MAX_UNIVERSE = int(os.environ.get('INTRADAY_REPLAY_MAX_UNIVERSE', '0')) or None
# PRIORITY-2 FIX (Live vs Replay pre-scan pool size mismatch): Replay's
# pre-scan pool now defaults to the SAME authoritative constant Live uses
# (INTRADAY_PRE_SCAN_POOL_LIMIT, defined near the top of this file) instead
# of its own separately-configurable INTRADAY_REPLAY_MAX_UNIVERSE default.
# INTRADAY_REPLAY_MAX_UNIVERSE, if set, now only acts as an EXTRA hard
# ceiling on top of that (e.g. for Render memory safety -- see
# INTRADAY_REPLAY_MEMORY_SAFETY_MB below) -- if it ends up smaller than
# INTRADAY_PRE_SCAN_POOL_LIMIT, start_intraday_replay() surfaces a loud
# parity warning rather than silently running a smaller pool than Live.
INTRADAY_REPLAY_MAX_LOOKBACK_DAYS = int(os.environ.get('INTRADAY_REPLAY_MAX_LOOKBACK_DAYS', '59'))
INTRADAY_REPLAY_MAX_SELECTED_DAYS = int(os.environ.get('INTRADAY_REPLAY_MAX_SELECTED_DAYS', '15'))
INTRADAY_REPLAY_EVENT_LOG_LIMIT = int(os.environ.get('INTRADAY_REPLAY_EVENT_LOG_LIMIT', '4000'))
INTRADAY_REPLAY_WARMUP_DAYS = int(os.environ.get('INTRADAY_REPLAY_WARMUP_DAYS', '3'))
INTRADAY_REPLAY_CAP_ALLOWLIST_PATH = os.environ.get('INTRADAY_REPLAY_CAP_ALLOWLIST_PATH', os.path.join(os.path.dirname(__file__), 'data', 'large_mid_cap_universe.txt'))
# PRIORITY-2 FIX (Large/Mid universe was silently optional): if the manually
# maintained local file is empty, auto-download NSE's own published NIFTY
# LargeMidcap 250 constituent CSV (Large Cap = NIFTY 100 + Mid Cap = NIFTY
# Midcap 150) and cache it in the DB, refreshed periodically -- see
# fetch_and_cache_large_mid_cap_allowlist() below. Set to '' to disable
# auto-download entirely (falls back to file-only / no-filter behavior).
INTRADAY_REPLAY_CAP_ALLOWLIST_URL = os.environ.get(
    'INTRADAY_REPLAY_CAP_ALLOWLIST_URL',
    'https://www.niftyindices.com/IndexConstituent/ind_niftylargemidcap250list.csv',
)
INTRADAY_REPLAY_CAP_ALLOWLIST_CACHE_MAX_AGE_DAYS = int(os.environ.get('INTRADAY_REPLAY_CAP_ALLOWLIST_CACHE_MAX_AGE_DAYS', '7'))
# PRIORITY-1 FIX (review round 2, #3): explicit order-fill timing/realism.
# 'next_open' (default) is the conservative, non-lookahead-safe fill: a
# signal detected on bar T is filled at bar T+1's Open (plus slippage), not
# at bar T's own close/last price -- you cannot actually transact at the
# exact price that just triggered your own signal. 'signal_price' keeps the
# old (more optimistic) behavior of filling at the signal candle's own last
# price, for comparison only.
INTRADAY_REPLAY_FILL_MODE = os.environ.get('INTRADAY_REPLAY_FILL_MODE', 'next_open').strip().lower()
INTRADAY_REPLAY_ENTRY_SLIPPAGE_BPS = float(os.environ.get('INTRADAY_REPLAY_ENTRY_SLIPPAGE_BPS', '5'))
# PRIORITY-2 FIX (Render memory risk): rough pre-flight estimate of how much
# candle data a run would hold in memory (universe size x trading days x
# bars/day), to refuse (by default) a combination likely to exhaust a small
# Render instance instead of failing/getting OOM-killed mid-run. Override
# per-request with acknowledge_memory_risk=true.
INTRADAY_REPLAY_MEMORY_SAFETY_MB = float(os.environ.get('INTRADAY_REPLAY_MEMORY_SAFETY_MB', '250'))
INTRADAY_REPLAY_BYTES_PER_CANDLE_ESTIMATE = float(os.environ.get('INTRADAY_REPLAY_BYTES_PER_CANDLE_ESTIMATE', '400'))


def load_large_mid_cap_allowlist() -> Optional[List[str]]:
    """Optional explicit Large+Mid-cap ticker allowlist for the Replay Lab.

    Why this exists instead of classifying by live market-cap data: the
    market_data.py shim this app now uses (INDstocks-backed) only implements
    .history() -- there is no .info/fundamentals endpoint, so info.get('marketCap')
    (what enrich_candidate()/score_fundamentals() ask for) always returns None
    post-migration. There is currently no live/API way in this codebase to
    classify a stock as Large/Mid/Small cap. Rather than silently pretend
    load_market_universe()'s full list is already "Large+Mid" (it isn't
    explicitly filtered), this reads an OPTIONAL plain-text file -- one
    ticker per line, '#' comments allowed -- that you maintain yourself, e.g.
    from NSE Indices' own published constituent list for NIFTY 100 + NIFTY
    Midcap 150 (= the NIFTY LargeMidcap 250 index, which is exactly "Large +
    Mid Cap, no small/micro"): https://www.niftyindices.com/IndexConstituent/ind_niftylargemidcap250list.csv
    Save that CSV's Symbol column (or NIFTY's own list) into
    data/large_mid_cap_universe.txt and every Replay Lab run will
    automatically intersect the configured universe against it. Returns None
    (meaning "no filter available, use the full configured universe" --
    unchanged prior behavior) if the file doesn't exist or is empty."""
    meta = fetch_and_cache_large_mid_cap_allowlist()
    return meta.get('symbols') or None


def _read_local_cap_allowlist_file() -> Optional[List[str]]:
    try:
        if not os.path.exists(INTRADAY_REPLAY_CAP_ALLOWLIST_PATH):
            return None
        with open(INTRADAY_REPLAY_CAP_ALLOWLIST_PATH, 'r') as f:
            tickers = [line.strip().upper() for line in f if line.strip() and not line.strip().startswith('#')]
        return tickers or None
    except Exception as e:
        print(f"[WARN] could not read large/mid cap allowlist file: {e}")
        return None


def _parse_symbol_csv(text: str) -> List[str]:
    """Parse NSE Indices' published constituent CSV -- header includes a
    'Symbol' column; be tolerant of exact header spelling/case."""
    tickers: List[str] = []
    try:
        reader = csv.DictReader(io.StringIO(text))
        symbol_field = None
        for field in (reader.fieldnames or []):
            if str(field).strip().lower() == 'symbol':
                symbol_field = field
                break
        if not symbol_field:
            return []
        for row in reader:
            sym = str(row.get(symbol_field) or '').strip().upper()
            if sym:
                tickers.append(sym)
    except Exception as e:
        print(f"[WARN] could not parse large/mid cap allowlist CSV: {e}")
    return tickers


def _load_cached_cap_allowlist_row(cache_key: str) -> Optional[Dict[str, Any]]:
    conn = get_db_connection()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT symbols, source, fetched_at FROM market_universe_cache WHERE cache_key = %s", (cache_key,))
            row = cur.fetchone()
    except Exception as e:
        print(f"[WARN] market_universe_cache read failed: {e}")
        return None
    finally:
        conn.close()
    if not row:
        return None
    return {'symbols': row[0] or [], 'source': row[1], 'fetched_at': row[2]}


def _store_cached_cap_allowlist_row(cache_key: str, symbols: List[str], source: str) -> None:
    conn = get_db_connection()
    if conn is None:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO market_universe_cache (cache_key, symbols, source, fetched_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (cache_key) DO UPDATE SET symbols = EXCLUDED.symbols, source = EXCLUDED.source, fetched_at = NOW()
            """, (cache_key, json.dumps(symbols), source))
    except Exception as e:
        print(f"[WARN] market_universe_cache write failed: {e}")
    finally:
        conn.close()


LARGE_MID_CAP_CACHE_KEY = 'nifty_largemidcap_250'


def _cap_allowlist_symbol(sym: str) -> str:
    """Normalize a ticker for Large/Mid-cap allowlist matching.

    CRITICAL BUG FIX (found via Replay Run 6, Sep 2026): DEFAULT_UNIVERSES['IN']
    and universe_<mkt>.txt store tickers WITH the exchange suffix (e.g.
    'RELIANCE.NS'), but the allowlist -- both the downloaded/cached NSE
    Indices CSV (_parse_symbol_csv) and the local override file's documented
    format -- stores BARE symbols ('RELIANCE', no suffix). The old filter did
    `t.upper() in allowlist_set` with no suffix stripping, so the intersection
    was ALWAYS EMPTY whenever the allowlist came from the download/cache path.
    Every "fail closed" check below only looked at whether the allowlist
    itself was empty (`if not allowlist`), never at whether the intersection
    was empty -- so this silently fell through to the full unfiltered
    universe on every run, while cap_filter_applied was still reported
    accurately as False (that part worked) but nothing actually refused to
    run despite require_cap_filter=True being the default. This is why Run 6
    showed cap_filter_applied=false with universe_count=300 even though the
    "Large + Mid Cap only -- required" checkbox was ticked."""
    s = str(sym or '').strip().upper()
    for suf in ('.NS', '.BO', '.BSE', '.NSE'):
        if s.endswith(suf):
            return s[:-len(suf)]
    return s


def apply_cap_allowlist(universe: List[str], allowlist: Optional[List[str]]) -> Optional[List[str]]:
    """Filter `universe` down to the Large/Mid-cap allowlist, matching on
    normalized (suffix-stripped) symbols. Returns None if the allowlist is
    empty/unavailable OR if normalized matching still produces zero overlap
    -- callers MUST treat None as "cap filter cannot be honestly applied
    right now" and fail closed (refuse to run / return no candidates),
    exactly like the existing "allowlist unavailable" case. Never fall back
    to the unfiltered universe on a None return -- see the ticker-suffix
    bug explained in _cap_allowlist_symbol's docstring above; a silent
    fallback here is exactly what let every prior run and every Live cycle
    quietly trade the full configured universe instead of Large+Mid cap."""
    if not allowlist:
        return None
    allowlist_set = {_cap_allowlist_symbol(s) for s in allowlist}
    filtered = [t for t in universe if _cap_allowlist_symbol(t) in allowlist_set]
    return filtered if filtered else None


def fetch_and_cache_large_mid_cap_allowlist(force: bool = False) -> Dict[str, Any]:
    """Resolve the Large+Mid-cap (NIFTY LargeMidcap 250) allowlist so it is
    authoritative rather than depending on someone remembering to hand-edit
    data/large_mid_cap_universe.txt (which previously shipped empty and
    silently degraded every Replay Lab run to the FULL configured universe).

    Resolution order:
      1. The local file, IF it has been explicitly populated -- lets you
         override with your own curated/verified list.
      2. A fresh (< INTRADAY_REPLAY_CAP_ALLOWLIST_CACHE_MAX_AGE_DAYS old)
         DB-cached download of NSE Indices' own published CSV.
      3. A live download of that CSV (cached to DB for next time).
      4. A stale DB cache, if the live download fails.
      5. None -- meaning no authoritative Large/Mid list is available at
         all right now; callers MUST treat this as "cap filter unavailable"
         rather than silently pretending the full universe already is
         Large/Mid (see require_cap_filter in start_intraday_replay).

    Returns {'symbols': List[str] | None, 'source': str, 'fetched_at': datetime|None, 'stale': bool}.
    """
    local = _read_local_cap_allowlist_file()
    if local:
        return {'symbols': local, 'source': 'local_file', 'fetched_at': None, 'stale': False}

    cached = None if force else _load_cached_cap_allowlist_row(LARGE_MID_CAP_CACHE_KEY)
    if cached and cached.get('symbols'):
        age_days = (datetime.datetime.utcnow() - cached['fetched_at']).total_seconds() / 86400.0 if cached.get('fetched_at') else 999
        if age_days <= INTRADAY_REPLAY_CAP_ALLOWLIST_CACHE_MAX_AGE_DAYS:
            return {'symbols': cached['symbols'], 'source': f"{cached.get('source') or 'downloaded_csv'}_cached", 'fetched_at': cached.get('fetched_at'), 'stale': False}

    if INTRADAY_REPLAY_CAP_ALLOWLIST_URL:
        try:
            req = urllib.request.Request(INTRADAY_REPLAY_CAP_ALLOWLIST_URL, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req, timeout=15) as resp:
                text = resp.read().decode('utf-8', errors='replace')
            downloaded = _parse_symbol_csv(text)
            if downloaded:
                _store_cached_cap_allowlist_row(LARGE_MID_CAP_CACHE_KEY, downloaded, 'downloaded_csv')
                return {'symbols': downloaded, 'source': 'downloaded_csv', 'fetched_at': datetime.datetime.utcnow(), 'stale': False}
        except Exception as e:
            print(f"[WARN] large/mid cap allowlist download failed ({INTRADAY_REPLAY_CAP_ALLOWLIST_URL}): {e}")

    if cached and cached.get('symbols'):
        # Live download failed but we have an older cached copy -- better than
        # silently running unfiltered.
        return {'symbols': cached['symbols'], 'source': f"{cached.get('source') or 'downloaded_csv'}_stale_cache", 'fetched_at': cached.get('fetched_at'), 'stale': True}

    return {'symbols': None, 'source': 'none', 'fetched_at': None, 'stale': False}


# PRIORITY FIX (review round 3, #1): Live's own intraday scanner was still
# scanning the FULL configured universe while the Replay Lab required
# Large/Mid-cap by default -- meaning Replay was testing a different, smaller
# universe than Live actually trades. Both now go through this one function.
INTRADAY_LIVE_CAP_FILTER_ENABLED = os.environ.get('INTRADAY_LIVE_CAP_FILTER_ENABLED', 'true').strip().lower() not in ('0', 'false', 'no', '')


# PRIORITY FIX (parity/safety review): previously, if the Large/Mid-cap allowlist was
# unavailable, Live would silently WARN and fall back to scanning the FULL configured
# universe -- while Replay Lab refused to run at all in the same situation
# (require_cap_filter=True by default). That meant Live could temporarily trade stocks
# outside the intended Large/Mid universe at exactly the moment Replay would have refused
# to test it. INTRADAY_LIVE_CAP_FAIL_CLOSED (default true) makes Live match Replay's
# safer default: fail closed (scan nothing, surface a clear error) instead of silently
# broadening the universe. Set to false to restore the old fall-back-and-warn behavior.
INTRADAY_LIVE_CAP_FAIL_CLOSED = os.environ.get('INTRADAY_LIVE_CAP_FAIL_CLOSED', 'true').strip().lower() not in ('0', 'false', 'no', '')
# Per-market "cap allowlist unavailable" message, set by get_intraday_scan_universe()
# and surfaced by scan_intraday_candidates()/build_intraday_dynamic_shortlist()/the
# self-scan trading-automation path into their own `errors` list, so a fail-closed empty
# universe reads as "Large/Mid-cap list unavailable" in the UI instead of a bare "0
# candidates found" that looks identical to an ordinary quiet market.
INTRADAY_CAP_UNAVAILABLE_ERRORS: Dict[str, str] = {}


def get_intraday_scan_universe(market: str) -> List[str]:
    """Live intraday's own scan universe, with the SAME Large/Mid-cap
    restriction the Replay Lab requires by default -- so Live trades the
    same universe Replay tests, not a broader one. Set
    INTRADAY_LIVE_CAP_FILTER_ENABLED=false to opt back out.

    When the allowlist genuinely isn't available right now, behavior depends on
    INTRADAY_LIVE_CAP_FAIL_CLOSED (default true): fail closed and return an empty
    universe (with the reason recorded in INTRADAY_CAP_UNAVAILABLE_ERRORS for callers to
    surface), matching Replay Lab's default refusal -- rather than silently falling back
    to the full configured universe. Live itself never crashes either way; it just finds
    zero candidates this cycle until the allowlist is available again."""
    configured = load_market_universe(market)
    if not INTRADAY_LIVE_CAP_FILTER_ENABLED:
        INTRADAY_CAP_UNAVAILABLE_ERRORS.pop(market, None)
        return configured
    cap_meta = fetch_and_cache_large_mid_cap_allowlist()
    allowlist = cap_meta.get('symbols')
    filtered = apply_cap_allowlist(configured, allowlist)
    if filtered is None:
        reason = ('allowlist is unavailable' if not allowlist
                   else f'allowlist has {len(allowlist)} symbols but NONE matched the configured universe after suffix normalization -- check ticker formats')
        message = (f"Large/Mid-cap allowlist problem for {market} (source={cap_meta.get('source')}): {reason}. "
                    + ("Scanning nothing this cycle rather than trading outside the intended universe "
                       "(set INTRADAY_LIVE_CAP_FAIL_CLOSED=false to fall back to the full configured universe instead)."
                       if INTRADAY_LIVE_CAP_FAIL_CLOSED else
                       f"Scanning the full configured universe for {market} this cycle."))
        print(f"[{'ERROR' if INTRADAY_LIVE_CAP_FAIL_CLOSED else 'WARN'}] {message}")
        INTRADAY_CAP_UNAVAILABLE_ERRORS[market] = message
        return [] if INTRADAY_LIVE_CAP_FAIL_CLOSED else configured
    INTRADAY_CAP_UNAVAILABLE_ERRORS.pop(market, None)
    return filtered

# run_id -> live objects. Only meaningful within one Gunicorn worker process;
# see intraday_replay_status()/list/detail below, which read the persisted DB
# row so status/history/delete work regardless of which worker handled the
# request. If you run more than one web worker on Render, start/pause/stop
# must land on the same worker that is actually running the thread -- sticky
# sessions or a single-worker web process are required for full control.
INTRADAY_REPLAY_THREADS: Dict[int, threading.Thread] = {}
INTRADAY_REPLAY_STOP_EVENTS: Dict[int, threading.Event] = {}
INTRADAY_REPLAY_PAUSE_EVENTS: Dict[int, threading.Event] = {}
INTRADAY_REPLAY_LOCK = threading.Lock()


def get_intraday_replay_config() -> Dict[str, Any]:
    # Uses whatever interval Live/Paper is actually configured for
    # (INTRADAY_DATA_INTERVAL, e.g. '1m' or '5m') rather than a hardcoded
    # value -- Live and Replay must agree on candle resolution for the
    # replay to be a faithful reproduction of what Live actually does.
    return {'interval': str(INTRADAY_DATA_INTERVAL or '5m').strip().lower(), 'max_lookback_days': INTRADAY_REPLAY_MAX_LOOKBACK_DAYS}


def resolve_intraday_replay_dates(market: str, dates: Optional[List[str]], start_date: Optional[str],
                                   end_date: Optional[str]) -> List[datetime.date]:
    """Turn either an explicit list of dates or a start/end range into a sorted
    list of actual trading days, clamped to INTRADAY_REPLAY_MAX_LOOKBACK_DAYS
    back from today and INTRADAY_REPLAY_MAX_SELECTED_DAYS days total (a single
    HTTP request just kicks off the background thread, so this cap protects
    against an accidental 5-year selection, not against a Render timeout)."""
    picked, _dropped = resolve_intraday_replay_dates_with_drops(market, dates, start_date, end_date)
    return picked


def resolve_intraday_replay_dates_with_drops(market: str, dates: Optional[List[str]], start_date: Optional[str],
                                              end_date: Optional[str]) -> Tuple[List[datetime.date], List[Dict[str, str]]]:
    """Same resolution as resolve_intraday_replay_dates, but for an explicit `dates`
    list also reports WHY any requested date got dropped (holiday/weekend vs outside
    the allowed lookback window) -- so the run can say so upfront in its queued
    message instead of the user only finding out after a full replay finishes with
    0 trades that one of their selected days was e.g. Ganesh Chaturthi and never had
    any data to begin with."""
    earliest_allowed = datetime.date.today() - datetime.timedelta(days=INTRADAY_REPLAY_MAX_LOOKBACK_DAYS)
    picked: List[datetime.date] = []
    dropped: List[Dict[str, str]] = []
    if dates:
        for d in dates:
            try:
                day = datetime.date.fromisoformat(str(d).strip())
            except Exception:
                dropped.append({'date': str(d), 'reason': 'invalid_date'})
                continue
            if day > datetime.date.today():
                dropped.append({'date': day.isoformat(), 'reason': 'in_the_future'})
            elif day < earliest_allowed:
                dropped.append({'date': day.isoformat(), 'reason': 'outside_lookback_window'})
            elif not is_trading_day(market, day):
                reason = 'weekend' if day.weekday() >= 5 else 'market_holiday'
                dropped.append({'date': day.isoformat(), 'reason': reason})
            else:
                picked.append(day)
    elif start_date or end_date:
        end_dt = datetime.date.fromisoformat(end_date) if end_date else datetime.date.today()
        start_dt = datetime.date.fromisoformat(start_date) if start_date else end_dt - datetime.timedelta(days=7)
        start_dt = max(start_dt, earliest_allowed)
        cur = start_dt
        while cur <= end_dt:
            if is_trading_day(market, cur):
                picked.append(cur)
            cur += datetime.timedelta(days=1)
    picked = sorted(set(picked))[:INTRADAY_REPLAY_MAX_SELECTED_DAYS]
    return picked, dropped


def _cache_frame_to_records(df) -> List[List[Any]]:
    records = []
    for ts, row in df.iterrows():
        try:
            records.append([ts.isoformat(), float(row['Open']), float(row['High']), float(row['Low']), float(row['Close']), float(row.get('Volume') or 0)])
        except Exception:
            continue
    return records


def _cache_records_to_frame(records: List[List[Any]]):
    if not records:
        return pd.DataFrame(columns=["Open", "High", "Low", "Close", "Volume"])
    idx = [pd.Timestamp(r[0]) for r in records]
    return pd.DataFrame({
        'Open': [r[1] for r in records], 'High': [r[2] for r in records], 'Low': [r[3] for r in records],
        'Close': [r[4] for r in records], 'Volume': [r[5] for r in records],
    }, index=pd.DatetimeIndex(idx))


def _load_cached_replay_days(ticker: str, market: str, interval: str, trading_dates: List[datetime.date]) -> Dict[datetime.date, Any]:
    """Returns whichever of the requested trading_dates are already cached for
    this ticker+market+interval, as {date: day_dataframe}. Callers only need
    to hit the API for tickers/date-spans this DOESN'T fully cover."""
    if not trading_dates:
        return {}
    conn = get_db_connection()
    if conn is None:
        return {}
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT trading_date, candles FROM intraday_replay_candle_cache "
                "WHERE ticker = %s AND market = %s AND interval = %s AND trading_date = ANY(%s)",
                (ticker, market, interval, trading_dates),
            )
            rows = cur.fetchall()
    except Exception as e:
        print(f"[WARN] replay candle cache read failed for {ticker}: {e}")
        return {}
    finally:
        conn.close()
    return {r[0]: _cache_records_to_frame(r[1]) for r in rows}


def _store_cached_replay_day(ticker: str, market: str, interval: str, day: datetime.date, df) -> None:
    if df is None or df.empty:
        return
    conn = get_db_connection()
    if conn is None:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO intraday_replay_candle_cache (ticker, market, interval, trading_date, candles, fetched_at)
                VALUES (%s,%s,%s,%s,%s,NOW())
                ON CONFLICT (ticker, market, interval, trading_date) DO UPDATE SET candles = EXCLUDED.candles, fetched_at = NOW()
            """, (ticker, market, interval, day, json.dumps(_cache_frame_to_records(df))))
    except Exception as e:
        print(f"[WARN] replay candle cache write failed for {ticker}: {e}")
    finally:
        conn.close()


def download_replay_universe_history(tickers: List[str], start_date: datetime.date, end_date: datetime.date,
                                      interval: str, market: str = 'IN') -> Dict[str, Dict[Any, Any]]:
    """Download the whole universe's minute-bar history for [start_date, end_date]
    ONCE, up front, then group each ticker's frame by trading day -- instead of
    re-fetching per candle per stock (the old per-tick-per-ticker approach this
    replaces). Chunks the universe 5-at-a-time (INDstocks' own per-call scrip
    cap) across a small thread pool, mirroring fetch_intraday_candidates_batch's
    existing concurrency pattern so this doesn't open a new/unproven code path.

    Checks the persistent intraday_replay_candle_cache FIRST: a ticker whose
    every expected trading day in range is already cached skips the API call
    entirely. This matters because tuning strategy settings means re-running
    the exact same historical day(s) over and over -- only the very first run
    for a given day/ticker/interval combination should ever call INDstocks.

    Returns {ticker: {date: day_dataframe}}.

    PRIORITY-3 FIX (historical 1m/5m API windowing): indstocks_client.get_historical()
    already internally splits any single request into <= MAX_RANGE_DAYS-sized
    windows (7 days for 1m/5m), so a request never technically "fails" for
    being too long. But this function used to always request one continuous
    [start_date, end_date] span regardless of which days were actually
    selected -- if you pick a handful of scattered trading days across the
    full INTRADAY_REPLAY_MAX_LOOKBACK_DAYS window, that downloaded (and
    walked window-by-window through) every calendar day in between too,
    multiplying API calls and cache writes for data never used. This now
    groups the expected trading days into contiguous fetch windows first
    (merging runs that are within a few calendar days of each other, e.g. a
    normal weekend/holiday gap) and only fetches those windows -- fewer,
    smaller requests, each still safely under the provider's per-call range
    limit."""
    result: Dict[str, Dict[Any, Any]] = {}
    if not tickers:
        return result
    fetch_start_floor = start_date - datetime.timedelta(days=INTRADAY_REPLAY_WARMUP_DAYS)
    expected_days = []
    d = fetch_start_floor
    while d <= end_date:
        if is_trading_day(market, d):
            expected_days.append(d)
        d += datetime.timedelta(days=1)

    to_fetch: List[str] = []
    for ticker in tickers:
        cached = _load_cached_replay_days(ticker, market, interval, expected_days)
        if cached and all(day in cached and not cached[day].empty for day in expected_days):
            result[ticker] = cached
        else:
            to_fetch.append(ticker)

    if to_fetch:
        # Group expected trading days into contiguous fetch windows instead of
        # one span covering the whole selection -- a gap of more than a few
        # calendar days (typical max normal weekend/holiday run) starts a new
        # window, so sparsely-selected replay dates don't pull everything in
        # between them.
        fetch_windows: List[Tuple[datetime.date, datetime.date]] = []
        if expected_days:
            group_start = expected_days[0]
            prev = expected_days[0]
            for day in expected_days[1:]:
                if (day - prev).days > 4:
                    fetch_windows.append((group_start, prev))
                    group_start = day
                prev = day
            fetch_windows.append((group_start, prev))

        chunk_size = 5
        chunks = [to_fetch[i:i + chunk_size] for i in range(0, len(to_fetch), chunk_size)]
        workers = min(max(1, INTRADAY_MAX_WORKERS), max(1, len(chunks) * max(1, len(fetch_windows))))
        by_ticker_days: Dict[str, Dict[Any, Any]] = {t: {} for t in to_fetch}
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            future_map = {}
            for (win_start, win_end) in (fetch_windows or [(fetch_start_floor, end_date)]):
                win_fetch_start = win_start - datetime.timedelta(days=INTRADAY_REPLAY_WARMUP_DAYS)
                win_fetch_end = win_end + datetime.timedelta(days=1)
                for chunk in chunks:
                    future_map[executor.submit(
                        yf.history_batch, chunk, interval=interval,
                        start=win_fetch_start.isoformat(), end=win_fetch_end.isoformat(), timeout=YF_TIMEOUT,
                    )] = chunk
            for fut in concurrent.futures.as_completed(future_map):
                try:
                    hist_map = fut.result()
                except Exception:
                    continue
                for ticker, h in (hist_map or {}).items():
                    for day, day_df in group_intraday_frame_by_day(h).items():
                        by_ticker_days.setdefault(ticker, {})[day] = day_df
        for ticker, by_day in by_ticker_days.items():
            result[ticker] = by_day
            for day, day_df in by_day.items():
                if day in expected_days:
                    _store_cached_replay_day(ticker, market, interval, day, day_df)
    return result


def _resolve_intrabar_conflict(bar, target_price: float, stop_price: float) -> Tuple[Optional[str], Optional[str]]:
    """If a single 5-minute bar's High/Low straddle BOTH the target and the
    stop, we cannot know from OHLC alone which was actually touched first.
    Assume the adverse outcome (stop) first -- a conservative rule that
    prevents an inflated backtest.

    Returns (exit_reason, resolution_label):
      exit_reason: 'STOP_LOSS_HIT', 'TARGET_HIT', or None if neither was touched.
      resolution_label: 'STOP_ONLY', 'TARGET_ONLY', 'BOTH_TOUCHED_SAME_BAR', or None --
        logged onto the trade record (intrabar_resolution) so a loss can be told apart
        as "only the stop was ever touched this bar" (unambiguous) vs. "both target and
        stop were in range this bar and we conservatively assumed stop-first" (a real
        loss under this policy, but the bar's own data doesn't rule out an unlucky
        same-bar reversal -- worth knowing when judging whether the stop distance itself
        needs to change)."""
    try:
        high = float(bar.get('High'))
        low = float(bar.get('Low'))
    except Exception:
        return None, None
    hit_target = high >= target_price
    hit_stop = low <= stop_price
    if hit_target and hit_stop:
        return 'STOP_LOSS_HIT', 'BOTH_TOUCHED_SAME_BAR'
    if hit_stop:
        return 'STOP_LOSS_HIT', 'STOP_ONLY'
    if hit_target:
        return 'TARGET_HIT', 'TARGET_ONLY'
    return None, None


def build_replay_candidate_row(ticker: str, day_df, upto_idx: int, settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """The historical-replay equivalent of fetch_intraday_candidate_snapshot():
    same function, fed only the bars that existed up to (and including)
    upto_idx today -- so there is no look-ahead, and the resulting score/
    blocked_reasons/entry-target-stop math is identical to what the live
    engine would have produced at that exact moment."""
    window = day_df.iloc[:upto_idx + 1]
    if window is None or window.empty or len(window) < 3:
        return None
    row = fetch_intraday_candidate_snapshot(ticker, settings, hist=window)
    if not row.get('ok'):
        return None
    # fetch_intraday_candidate_snapshot's freshness check compares the last
    # candle's timestamp to the REAL current time (see
    # get_intraday_last_candle_meta), which is never "fresh" for a historical
    # candle. That staleness check exists to catch a broken/delayed live data
    # feed, not to judge a deliberate historical replay -- drop it here rather
    # than let every single replay candidate get blocked as "stale".
    row['blocked_reasons'] = [r for r in (row.get('blocked_reasons') or []) if not str(r).startswith('stale_or_delayed')]
    row['is_replay'] = True
    row['pre_scan_score'] = score_intraday_prescan_candidate(row, settings)
    return row


def replay_scan_universe(day_data: Dict[str, Any], universe: List[str], settings: Dict[str, Any],
                          market: str, market_context: Dict[str, Any], trade_memory: Dict[str, Any],
                          open_tickers: set, use_learning: bool = True,
                          sim_now: Optional[datetime.datetime] = None) -> Dict[str, Any]:
    """One scan cycle across the whole universe at the current simulated
    5-minute tick -- the historical-replay equivalent of scan_intraday_candidates().
    Returns eligible/watch candidates plus a rejection sample for the decision log.

    PRIORITY-1 FIX (dynamic-shortlist parity with Live): this now reproduces
    Live's exact two-stage pipeline (build_intraday_dynamic_shortlist() ->
    scan_intraday_candidates()) instead of running price-filter + strict-
    learning over the ENTIRE supplied universe every tick:

        pre-scan pool (this tick's `universe`, same size Live uses)
              -> pre_scan_score every symbol
              -> rank by pre_scan_score
              -> take top `shortlist_limit` (settings.universe_limit / INTRADAY_UNIVERSE_LIMIT)
              -> price/size focus filter + strict learning + score gate, ONLY on that shortlist
              -> final rank by `score` (not pre_scan_score)

    A stock outside Live's pre-scan shortlist at a given moment must not be
    considered as a replay entry either -- that was the main strategy-parity
    gap in the previous version. When INTRADAY_DYNAMIC_UNIVERSE_ENABLED is
    False, this instead mirrors Live's fixed-universe fallback path (every
    symbol in `universe` goes straight to price-filter/strict-learning, no
    pre-scan shortlist stage) -- exactly matching scan_intraday_candidates()'s
    own `dynamic_enabled` branch.

    use_learning=False runs the RAW/BASELINE mode: strict_learning_review (and
    therefore per-stock trade-history score adjustments/blocks) is skipped
    entirely, so the result reflects the strategy's own signals with no
    learned overlay -- useful for measuring the raw edge before asking
    whether the learning layer is helping or hurting on a given window."""
    # --- Stage 1: build the pre-scan pool (every symbol with data this tick) ---
    pool: List[Dict[str, Any]] = []
    for ticker in universe:
        entry = day_data.get(ticker)
        if not entry:
            continue
        # MULTI-STRATEGY parity: hand the strategy engine the SAME two inputs Live
        # gives it (regime context + measured strategy performance). scan-scoped, so
        # a replay tick sees exactly the shape of input a live tick would.
        scan_settings = settings
        if INTRADAY_MULTI_STRATEGY_ENABLED:
            scan_settings = dict(settings)
            scan_settings.setdefault('_market_context', market_context)
            scan_settings['_strategy_performance'] = settings.get('_strategy_performance') or {}
            # THIS TICK's simulated instant, so the time-of-day bucket the EV gate
            # conditions on is the historical one rather than the real wall clock
            # (the same class of bug already fixed for strict_learning_review).
            scan_settings['_sim_now'] = sim_now
            # Same-day ledger, so the selector's fast-adaptation layer sees losses
            # that closed earlier in THIS simulated session.
            scan_settings['_session_trades'] = settings.get('_session_trades') or []
            scan_settings['ev_gate_enabled'] = bool(settings.get('ev_gate_enabled', True)) and use_learning
            scan_settings['fast_adapt_enabled'] = bool(settings.get('fast_adapt_enabled', INTRADAY_FAST_ADAPT_ENABLED)) and use_learning
        row = build_replay_candidate_row(ticker, entry['df'], entry['idx'], scan_settings)
        if row:
            pool.append(row)

    # STRATEGY AUDIT TRAIL: aggregate, for every candidate the multi-strategy engine
    # actually looked at this tick (the whole pre-scan pool, not just the narrower
    # shortlist below), how many times each of the 10 strategies was evaluated,
    # came back eligible, and was the one actually selected. Without this there was
    # no way to answer "were all 10 strategies meaningfully tested" from a replay run
    # -- events.csv only ever recorded the ONE selected/rejected outcome per candidate,
    # never what the other 9 strategies concluded. Returned per-tick here and summed
    # across the whole run by the caller into run_summary.json's stats.strategy_audit.
    strategy_audit: Dict[str, Dict[str, int]] = {}
    for row in pool:
        for ev in (row.get('strategy_evaluations') or []):
            sid = ev.get('strategy_id')
            if not sid:
                continue
            bucket = strategy_audit.setdefault(sid, {'name': ev.get('name'), 'evaluated': 0, 'eligible': 0, 'selected': 0})
            bucket['evaluated'] += 1
            if ev.get('eligible'):
                bucket['eligible'] += 1
        selected_id = row.get('strategy_id')
        if selected_id and selected_id in strategy_audit:
            strategy_audit[selected_id]['selected'] += 1

    dynamic_enabled = bool(INTRADAY_DYNAMIC_UNIVERSE_ENABLED)
    if dynamic_enabled:
        # --- Stage 2: rank the pool by pre_scan_score, keep only the top shortlist ---
        # Mirrors build_intraday_dynamic_shortlist() exactly, including its sort key.
        shortlist_limit = max(1, int(settings.get('universe_limit') or INTRADAY_UNIVERSE_LIMIT))
        pool.sort(key=lambda r: (float(r.get('pre_scan_score') or 0), float(r.get('score') or 0), float(r.get('change_pct') or 0)), reverse=True)
        shortlist = pool[:shortlist_limit]
    else:
        # Fixed-universe fallback: no pre-scan shortlist stage, same as Live's
        # scan_intraday_candidates() when the dynamic shortlist is disabled.
        shortlist = pool

    # --- Stage 3: price/size filter + strict learning + score gate, ONLY on the shortlist ---
    candidates: List[Dict[str, Any]] = []
    rejections: List[Dict[str, Any]] = []
    # Fix 6 (eligibility funnel): tally EVERY rejection reason across the whole shortlist,
    # not just the top-10 sample kept for the decision log -- so a run's final stats can
    # report an accurate breakdown (e.g. "volume_spike_missing: 1922") instead of only
    # whatever happened to be in the first few logged samples per tick.
    reason_counts: Dict[str, int] = {}

    def _tally(reason: str) -> None:
        key = str(reason).split(';')[0].split(':')[0].strip() or 'unknown'
        reason_counts[key] = reason_counts.get(key, 0) + 1

    for row in shortlist:
        ticker = row['ticker']
        apply_intraday_price_focus_filter(row, settings)
        if row.get('blocked_reasons'):
            for r in row['blocked_reasons']:
                _tally(r)
            rejections.append({'ticker': ticker, 'score': row.get('score'), 'reason': '; '.join(row['blocked_reasons'][:2])})
            continue
        if use_learning:
            # BUGFIX: pass sim_now through so strict_learning_review's late-session/
            # square-off check uses THIS TICK's simulated time, not the real wall-clock
            # time (see strict_learning_review's now_utc docstring for the full story).
            review = strict_learning_review(row, market, 'intraday', engine='intraday', market_context=market_context, trade_memory=trade_memory, now_utc=sim_now)
            row['strict_learning'] = review
            if review.get('enabled') and not review.get('allowed'):
                reason = 'strict_learning_no_trade: ' + '; '.join((review.get('hard_blocks') or review.get('cautions') or [])[:2])
                row.setdefault('blocked_reasons', []).append(reason)
                _tally(reason)
                rejections.append({'ticker': ticker, 'score': row.get('score'), 'reason': reason})
                continue
            elif review.get('enabled') and review.get('score_adjustment'):
                row['score'] = round(max(0, min(100, float(row.get('score') or 0) + float(review.get('score_adjustment') or 0))), 1)
            # PRIORITY 1/2/3/7/8 (report-driven): evidence-based adjustments on TOP of
            # strict_learning_review -- same score, same clamp, "needs a minimum
            # sample" convention. PRIORITY 2/3 FIX: the expected-net-edge component is
            # now a HARD GATE (reject=True), not just a score nudge -- see
            # compute_evidence_based_score_adjustment's docstring. ev_gate_enabled comes
            # from settings so the Blind Replay Benchmark's baseline leg can turn it off
            # and get the pre-fix (soft-penalty-only) behavior for a genuine before/after.
            evidence = compute_evidence_based_score_adjustment(
                row, row.get('regime'), sim_now, settings.get('_strategy_performance'),
                float(settings.get('est_roundtrip_cost_pct') or INTRADAY_EST_ROUNDTRIP_COST_PCT),
                ev_gate_enabled=bool(settings.get('ev_gate_enabled', True)),
                session_trades=settings.get('_session_trades') or [])
            row['evidence_adjustment'] = evidence
            if evidence.get('reject'):
                row.setdefault('blocked_reasons', []).append(evidence['reject_reason'])
                _tally(evidence['reject_reason'])
                rejections.append({'ticker': ticker, 'score': row.get('score'), 'reason': evidence['reject_reason']})
                continue
            if evidence.get('adjustment'):
                row['score'] = round(max(0, min(100, float(row.get('score') or 0) + evidence['adjustment'])), 1)
        candidates.append(row)
    # Final ranking is by `score` (post strict-learning), matching Live's
    # scan_intraday_candidates() -- NOT by pre_scan_score, which is only used
    # to pick the shortlist in Stage 2 above.
    # Ranked by expected value first (proven EV ahead of unproven), then by score --
    # matching the live path. The risk budget spends against this order.
    candidates.sort(key=lambda r: (1 if r.get('expected_net_edge_pct') is not None else 0,
                                   float(r.get('expected_net_edge_pct') or 0.0),
                                   float(r.get('score') or 0), float(r.get('change_pct') or 0)), reverse=True)
    # PRIORITY 3 FIX (report-driven): the flat global min_score was overriding a
    # selected strategy's own, lower min_confidence at this OUTER eligibility gate --
    # candidate['min_score'] is already set to strategy_min_confidence when a
    # multi-strategy candidate was selected (see attach_intraday_strategy_engine),
    # and strict_learning_review already honors it internally, but this gate was
    # still checking the flat global settings['min_score'] instead, silently
    # re-imposing a uniform threshold the strategy engine was designed to avoid.
    # Each candidate's OWN effective threshold (strategy-specific if it has one,
    # global otherwise) is now what's authoritative here.
    min_score_gate = float(settings.get('min_score') or 0)
    eligible = [c for c in candidates
                if float(c.get('score') or 0) >= float(c.get('min_score') if c.get('min_score') is not None else min_score_gate)
                and c['ticker'] not in open_tickers]
    watch = [c for c in candidates if c not in eligible][:int(settings.get('max_candidates') or 8)]
    return {
        'eligible': eligible[:int(settings.get('max_candidates') or 8)],
        'watch': watch,
        'scanned_count': len(universe),
        'pre_scan_pool_count': len(pool),
        'shortlisted_count': len(shortlist),
        'selection_mode': 'dynamic_prescan' if dynamic_enabled else 'fixed_universe_limit',
        'rejections_sample': sorted(rejections, key=lambda r: float(r.get('score') or 0), reverse=True)[:10],
        'rejection_reason_counts': reason_counts,
        'strategy_audit': strategy_audit,
    }


def _replay_log_event(run_id: int, event_counter: List[int], trading_date, sim_time: str, ticker: Optional[str],
                       event_type: str, score: Optional[float], reason: Optional[str], detail: Optional[Dict[str, Any]] = None) -> None:
    """Decision/rejection log for one run, capped at INTRADAY_REPLAY_EVENT_LOG_LIMIT
    rows so a multi-day, 300-stock replay can't grow this table unbounded."""
    if event_counter[0] >= INTRADAY_REPLAY_EVENT_LOG_LIMIT:
        return
    conn = get_db_connection()
    if conn is None:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute(
                "INSERT INTO intraday_replay_events (run_id, trading_date, sim_time, ticker, event_type, score, reason, detail) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
                (run_id, trading_date, sim_time, ticker, event_type, score, reason, json.dumps(detail or {}, default=_json_safe)),
            )
        event_counter[0] += 1
    except Exception as e:
        print(f"[WARN] intraday replay event log failed: {e}")
    finally:
        conn.close()


def _replay_update_run_row(run_id: int, **fields) -> None:
    if not fields:
        return
    conn = get_db_connection()
    if conn is None:
        return
    try:
        set_clause = ", ".join(f"{k} = %s" for k in fields)
        with conn, conn.cursor() as cur:
            cur.execute(f"UPDATE intraday_replay_runs SET {set_clause} WHERE id = %s", (*fields.values(), run_id))
    except Exception as e:
        print(f"[WARN] intraday replay run update failed: {e}")
    finally:
        conn.close()


def _replay_insert_trade(run_id: int, market: str, trade: Dict[str, Any]) -> None:
    conn = get_db_connection()
    if conn is None:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""
                INSERT INTO intraday_replay_trades
                    (run_id, ticker, market, trading_date, entry_time, exit_time, entry_price, exit_price,
                     target_price, stop_price, quantity, net_return_pct, net_pnl, outcome, exit_reason, score, pattern_key,
                     gross_pnl, cost_amount, signal_price, mfe_pct, mae_pct, peak_price, trough_price,
                     intrabar_resolution, signal_fill_gap_pct,
                     strategy_id, strategy_name, strategy_confidence, regime,
                     failure_type, diagnosis, suggested_focus, strategy_why,
                     time_bucket, volatility_bucket, extension_bucket, relative_strength_bucket,
                     expected_net_edge_pct, calibrated_win_prob_pct, risk_amount, phase)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            """, (
                run_id, trade['ticker'], market, trade['trading_date'], trade['entry_time'], trade['exit_time'],
                trade['entry_price'], trade['exit_price'], trade['target_price'], trade['stop_price'],
                trade['quantity'], trade['net_return_pct'], trade['net_pnl'], trade['outcome'], trade['exit_reason'],
                trade.get('score'), trade.get('pattern_key'),
                trade.get('gross_pnl'), trade.get('cost_amount'), trade.get('signal_price'),
                trade.get('mfe_pct'), trade.get('mae_pct'), trade.get('peak_price'), trade.get('trough_price'),
                trade.get('intrabar_resolution'), trade.get('signal_fill_gap_pct'),
                trade.get('strategy_id'), trade.get('strategy_name'), trade.get('strategy_confidence'),
                trade.get('regime'), trade.get('failure_type'), trade.get('diagnosis'),
                trade.get('suggested_focus'),
                psycopg2.extras.Json(trade.get('strategy_why')) if trade.get('strategy_why') else None,
                trade.get('time_bucket'), trade.get('volatility_bucket'),
                trade.get('extension_bucket'), trade.get('relative_strength_bucket'),
                trade.get('expected_net_edge_pct'), trade.get('calibrated_win_prob_pct'),
                trade.get('risk_amount'), trade.get('phase'),
            ))
    except Exception as e:
        print(f"[WARN] intraday replay trade insert failed: {e}")
    finally:
        conn.close()


def estimate_replay_memory_mb(universe_size: int, trading_days_count: int, interval: str) -> Dict[str, Any]:
    """PRIORITY-2 FIX (Render memory risk): rough, deliberately conservative
    pre-flight estimate of the candle data a run would hold in memory at
    once (universe_size x trading_days x bars/day x per-candle overhead),
    used by start_intraday_replay() to refuse combinations likely to exhaust
    a small Render instance (previously this only surfaced AFTER the fact,
    as a worker crash/timeout).

    This only estimates the candle DataFrames themselves -- it does NOT
    account for the Python interpreter, Flask/Gunicorn, DB connections,
    the historical index-context data, replay bookkeeping structures, or
    event/trade logging, all of which also live in the same process. Treat
    INTRADAY_REPLAY_MEMORY_SAFETY_MB as a floor that must be well under your
    instance's actual RAM (default 250 MB, deliberately conservative on a
    512 MB Render instance), not as "this many MB is guaranteed safe."."""
    m = re.match(r'(\d+)', str(interval or '1').strip())
    minutes = max(1, int(m.group(1))) if m else 1
    session_minutes = 375  # NSE cash session, 9:15-15:30 IST
    bars_per_day = max(1, math.ceil(session_minutes / minutes))
    total_candles = max(0, int(universe_size)) * max(0, int(trading_days_count)) * bars_per_day
    estimated_mb = round((total_candles * INTRADAY_REPLAY_BYTES_PER_CANDLE_ESTIMATE) / (1024 * 1024), 1)
    return {
        'universe_size': universe_size, 'trading_days_count': trading_days_count, 'interval': interval,
        'bars_per_day_estimate': bars_per_day, 'total_candles_estimate': total_candles,
        'estimated_mb': estimated_mb, 'safety_limit_mb': INTRADAY_REPLAY_MEMORY_SAFETY_MB,
        'over_limit': estimated_mb > INTRADAY_REPLAY_MEMORY_SAFETY_MB,
    }


def start_intraday_replay(market: str, dates: Optional[List[str]] = None, start_date: Optional[str] = None,
                           end_date: Optional[str] = None, universe_limit: Optional[int] = None,
                           use_learning: bool = True, require_cap_filter: bool = True,
                           acknowledge_memory_risk: bool = False,
                           capital_override: Optional[float] = None,
                           require_vwap_override: Optional[bool] = None,
                           max_open_positions_override: Any = 'unlimited',
                           enforce_capital: bool = True,
                           exit_calibration_override: Optional[Dict[str, Any]] = None,
                           training_dates: Optional[List[str]] = None,
                           train_start_date: Optional[str] = None,
                           train_end_date: Optional[str] = None,
                           evidence_mode: str = 'frozen',
                           auto_apply_exit_calibration: bool = True,
                           exit_calibration_experimental_unvalidated: bool = False,
                           risk_budget_enabled: Optional[bool] = None,
                           daily_risk_budget_pct: Optional[float] = None,
                           max_concurrent_risk_pct: Optional[float] = None,
                           risk_budget_reserve_pct: Optional[float] = None) -> Dict[str, Any]:
    """Create the run row and launch its background replay thread. Returns
    immediately (this is the fix for the old /api/backtest/run's Render/Gunicorn
    90-second-timeout problem: the HTTP request no longer waits for the replay
    itself, only for it to be scheduled). Poll intraday_replay_status(run_id)
    for progress, and stop/pause it with the matching controls below.

    require_cap_filter: defaults to True (changed from False) -- this call
    REFUSES to start (returns ok=False) rather than silently falling back to
    the unfiltered configured universe when no Large/Mid-cap allowlist is
    available -- see fetch_and_cache_large_mid_cap_allowlist(). Pass
    explicitly False to allow an unfiltered run on purpose.

    acknowledge_memory_risk: the universe/day/interval combination is
    pre-flight-checked against INTRADAY_REPLAY_MEMORY_SAFETY_MB (see
    estimate_replay_memory_mb()); if it's over budget this call refuses to
    start unless this is True.

    capital_override / require_vwap_override: per-run overrides so a replay
    can be tested against a different simulation capital or VWAP-confirmation
    rule than what's currently saved in Live/Paper settings, without touching
    those saved settings. Leave as None to use the current Live/Paper value
    (the default, unchanged behavior). These are applied to the settings
    snapshot stored with the run, so a later Live/Paper settings change still
    never changes what this run says it used.

    max_open_positions_override: how many positions this replay may hold at
    once. Defaults to 'unlimited' -- research should measure every signal the
    strategy produced, not just the ones that happened to arrive while a slot
    was free (a cap biases results toward early-session signals and quietly
    discards the rest). Pass 'live' / 'match_live' to use the Intraday Engine's
    own Max intraday positions setting instead, or a positive integer to cap
    this run at a specific number. The resolved value is stored on the run's
    settings snapshot, so a finished run always reports the limit it actually
    enforced.

    training_dates / train_start_date / train_end_date: PROPER RESEARCH DESIGN
    (report issue #4 -- "the EV gate is still effectively a cold-start system").
    Supplying a training window replays those (earlier) days FIRST to build the
    evidence base -- strategy expectancy, context slices, exit calibration -- then
    FREEZES it and replays the requested test days against it. Training trades are
    excluded from the run's reported statistics, so the headline result describes
    unseen days only. Without this, day 1 of every run has zero recorded trades and
    the hard EV gate is inert on it, day 2 sees only day 1, and the early days of
    the window are scored while the system is still cold.

    A training window must end before the test window begins; overlapping or
    later-dated training days are rejected rather than silently reordered, because
    training on days that occur after the test days is leakage, not a configuration
    preference.

    evidence_mode: 'frozen' (default -- test days see ONLY the training evidence,
    a genuinely blind test of a model that does not move while being measured) or
    'expanding' (test days additionally see test trades closed on earlier test
    days -- still leak-free, and closer to live behaviour).

    auto_apply_exit_calibration: CRITICAL FIX (report issue #2 -- "exit calibration
    can be applied without the required validation"). This now applies ONLY an
    ALREADY-VALIDATED calibration -- one that previously cleared
    validate_exit_calibration_out_of_sample's required out-of-sample PF improvement
    bar (INTRADAY_EXIT_CALIBRATION_MIN_PF_GAIN) and was written by
    promote_exit_calibration -- loaded via load_active_exit_calibration() at the START of this run, so it's in force for
    both the training and test windows identically. Previously this flag instead
    derived a FRESH, unvalidated suggestion from THIS run's own training window and
    silently applied it to THIS run's own test window -- a training sample-size
    check ("15+ qualifying exits") standing in for the actual measure -> validate ->
    promote -> apply governance loop this file otherwise enforces everywhere else.
    That made every replay's "clean baseline" secretly a calibration experiment.
    Set to False to run with no exit calibration at all (the flat global default).

    exit_calibration_experimental_unvalidated: opt back into the OLD behavior above
    -- derive a calibration from this run's own training window and apply it to
    this run's own test window, with NO out-of-sample validation. Use this only to
    generate a candidate to test properly (pair with exit_calibration_override on a
    SEPARATE run plus validate_exit_calibration_out_of_sample), never to read this
    run's own test-window numbers as a profitability result: stats and the run log
    both mark this loudly (exit_calibration_is_experimental_unvalidated=True) so it
    can never be mistaken for the clean baseline above.

    risk_budget_enabled / daily_risk_budget_pct / max_concurrent_risk_pct /
    risk_budget_reserve_pct: per-run overrides for the risk-budget allocator that
    replaced the trade quota as the governing entry control.

    exit_calibration_override: PRIORITY 5 (report-driven) opt-in. Pass the
    'exit_calibration_suggestions' dict a PRIOR run's stats produced (see
    compute_exit_calibration_suggestions) to make THIS run's trailing-stop
    activation/giveback strategy-specific instead of using the one global
    default for all 10 strategies. Leave as None (the default) to reproduce
    exact previous behavior. Applying a calibration measured on one run to a
    DIFFERENT run's days is exactly the out-of-sample validation step the
    report's governance section calls for -- pair this with the Blind Replay
    Benchmark to see whether it actually helped before trusting it."""
    if not BACKTEST_ENABLED:
        return {'ok': False, 'error': 'Backtesting is disabled by BACKTEST_ENABLED=false'}
    market, _ = validate_market_horizon(market, 'intraday')
    trading_days, dropped_dates = resolve_intraday_replay_dates_with_drops(market, dates, start_date, end_date)
    if not trading_days:
        return {'ok': False, 'error': 'No valid trading days selected (check the dates are actual trading days within the lookback window).'}
    # --- Training window (report issue #4) ---------------------------------
    training_days: List[datetime.date] = []
    if training_dates or train_start_date or train_end_date:
        training_days, _train_dropped = resolve_intraday_replay_dates_with_drops(
            market, training_dates, train_start_date, train_end_date)
        if not training_days:
            return {'ok': False, 'error': ('A training window was requested but none of those dates are valid trading '
                                           'days within the lookback window.')}
        test_start = min(trading_days)
        leaking = [d for d in training_days if d >= test_start]
        if leaking:
            return {'ok': False,
                    'error': (f'{len(leaking)} training day(s) fall on or after the first test day '
                              f'({test_start.isoformat()}): {", ".join(d.isoformat() for d in leaking[:5])}. Training on '
                              f'days at or after the test window is look-ahead leakage -- the whole point of the '
                              f'training window is that the test days were unseen. Move the training window earlier.')}
        # Overlap is impossible after the check above, but de-duplicate defensively
        # so a day can never be replayed twice in one run.
        training_days = sorted(set(training_days) - set(trading_days))
        trading_days = training_days + trading_days
    evidence_mode = str(evidence_mode or 'frozen').lower()
    if evidence_mode not in ('frozen', 'expanding'):
        return {'ok': False, 'error': "evidence_mode must be 'frozen' or 'expanding'."}
    configured_universe = load_market_universe(market)
    cap_meta = fetch_and_cache_large_mid_cap_allowlist()
    cap_allowlist = cap_meta.get('symbols')
    cap_filter_applied = False
    filtered = apply_cap_allowlist(configured_universe, cap_allowlist)
    if filtered is not None:
        configured_universe = filtered
        cap_filter_applied = True
    elif require_cap_filter:
        no_overlap = bool(cap_allowlist)  # allowlist existed but normalized matching found nothing
        return {
            'ok': False,
            'error': (('Large/Mid-cap universe is required for this run (require_cap_filter=true, the default), and an '
                        f'allowlist of {len(cap_allowlist)} symbols WAS loaded (source={cap_meta.get("source")}), but NONE '
                        'of them matched the configured universe even after stripping exchange suffixes -- this points to a '
                        'ticker-format mismatch between the allowlist and universe_IN.txt/DEFAULT_UNIVERSES, not a missing '
                        'file. Check the symbol formats on both sides.') if no_overlap else
                       ('Large/Mid-cap universe is required for this run (require_cap_filter=true, the default) but no '
                        'allowlist is available right now -- data/large_mid_cap_universe.txt is empty and the '
                        'auto-download of the NIFTY LargeMidcap 250 constituent list failed. Populate the file '
                        'manually, check network access to INTRADAY_REPLAY_CAP_ALLOWLIST_URL, or pass '
                        'require_cap_filter=false to explicitly run unfiltered.')),
        }

    # PRIORITY-2 FIX (Live vs Replay universe-size mismatch): the pre-scan
    # pool size now defaults to the SAME constant Live uses
    # (INTRADAY_PRE_SCAN_POOL_LIMIT) rather than a separately configured
    # replay-only default, so a run started with no explicit universe_limit
    # is automatically parity-correct with whatever Live is currently
    # configured for. INTRADAY_REPLAY_MAX_UNIVERSE, if set, is an ADDITIONAL
    # ceiling (e.g. for memory safety) -- if that ceiling forces the pool
    # smaller than Live's, we say so loudly instead of staying silent.
    requested_limit = int(universe_limit) if universe_limit else INTRADAY_PRE_SCAN_POOL_LIMIT
    effective_limit = max(1, min(requested_limit, len(configured_universe)))
    if INTRADAY_REPLAY_MAX_UNIVERSE:
        effective_limit = min(effective_limit, INTRADAY_REPLAY_MAX_UNIVERSE)
    universe = configured_universe[:effective_limit]
    parity_warning = None
    if len(universe) < min(INTRADAY_PRE_SCAN_POOL_LIMIT, len(configured_universe)):
        parity_warning = (
            f"Replay pre-scan pool is {len(universe)} stock(s), smaller than Live's configured "
            f"INTRADAY_PRE_SCAN_POOL_LIMIT={INTRADAY_PRE_SCAN_POOL_LIMIT}. A stock Live would have pre-scanned may "
            f"never be considered here -- results are not guaranteed to be identical to Live's stock selection."
        )

    cfg = get_intraday_replay_config()
    mem_estimate = estimate_replay_memory_mb(len(universe), len(trading_days), cfg['interval'])
    if mem_estimate['over_limit'] and not acknowledge_memory_risk:
        return {
            'ok': False,
            'error': (f"Estimated memory for this run (~{mem_estimate['estimated_mb']} MB for "
                       f"{len(universe)} stocks x {len(trading_days)} day(s) x {cfg['interval']} candles) exceeds the "
                       f"safety limit ({INTRADAY_REPLAY_MEMORY_SAFETY_MB} MB) for a small Render instance. Reduce the "
                       f"universe size or number of days, switch to a coarser interval (e.g. 5m), or pass "
                       f"acknowledge_memory_risk=true to run it anyway."),
            'memory_estimate': mem_estimate,
        }

    # This IS the same settings object Live/Paper reads (get_intraday_settings());
    # there is no separate "backtest strategy" to fall out of sync. A snapshot is
    # stored on the run row so a later settings change never changes what this
    # historical run says it used.
    settings = get_intraday_settings()
    settings['market'] = market
    if capital_override is not None:
        clamped_capital = min(100000000.0, max(100.0, float(capital_override)))
        settings['simulation_capital_inr'] = clamped_capital
        settings['capital_inr'] = clamped_capital
    if require_vwap_override is not None:
        settings['require_vwap'] = bool(require_vwap_override)
    # Resolve the run's position limit ONCE, here, and stamp it on the settings
    # snapshot the worker reads -- so the limit is decided at start time and
    # recorded with the run, rather than re-read from live settings mid-run.
    if isinstance(max_open_positions_override, str) and max_open_positions_override.strip().lower() in ('live', 'match_live', 'match-live', 'engine', 'settings'):
        replay_position_limit = resolve_position_limit(settings.get('max_open_positions'), INTRADAY_MAX_OPEN_POSITIONS)
        position_limit_source = 'intraday engine setting'
    elif max_open_positions_override is None:
        replay_position_limit = resolve_position_limit(INTRADAY_REPLAY_MAX_OPEN_POSITIONS, None)
        position_limit_source = 'replay default'
    else:
        replay_position_limit = resolve_position_limit(max_open_positions_override, None)
        position_limit_source = 'this run'
    settings['replay_max_open_positions'] = replay_position_limit if replay_position_limit is not None else 0
    settings['replay_max_open_positions_label'] = position_limit_label(replay_position_limit)
    # With positions unlimited, cash is what makes the run realistic -- see the
    # capital-guard comment in _run_intraday_replay_worker().
    settings['replay_enforce_capital'] = bool(enforce_capital)
    settings['_training_days'] = training_days
    settings['evidence_mode'] = evidence_mode
    settings['auto_apply_exit_calibration'] = bool(auto_apply_exit_calibration)
    settings['exit_calibration_experimental_unvalidated'] = bool(exit_calibration_experimental_unvalidated)
    settings['risk_budget_enabled'] = (INTRADAY_RISK_BUDGET_ENABLED if risk_budget_enabled is None
                                       else bool(risk_budget_enabled))
    if daily_risk_budget_pct is not None:
        settings['daily_risk_budget_pct'] = max(0.05, min(20.0, float(daily_risk_budget_pct)))
    if max_concurrent_risk_pct is not None:
        settings['max_concurrent_risk_pct'] = max(0.05, min(20.0, float(max_concurrent_risk_pct)))
    if risk_budget_reserve_pct is not None:
        settings['risk_budget_reserve_pct'] = max(0.0, min(100.0, float(risk_budget_reserve_pct)))
    trading_settings = get_trading_settings()
    if exit_calibration_override:
        # Stored on BOTH settings dicts: `settings` (intraday) is what's persisted in
        # the run's settings_snapshot for display, `trading_settings` is what
        # evaluate_profit_protection_exit() actually reads during the replay -- same
        # "never silently apply, always show what was used" convention as
        # capital_override/require_vwap_override just above.
        clean_calibration = {
            sid: v for sid, v in exit_calibration_override.items()
            if isinstance(v, dict) and v.get('proven') and v.get('suggested_activation_pct') and v.get('suggested_giveback_pct')
        }
        settings['_strategy_exit_calibration'] = clean_calibration
        trading_settings = dict(trading_settings)
        trading_settings['_strategy_exit_calibration'] = clean_calibration
    elif auto_apply_exit_calibration:
        # CRITICAL FIX (report issue #2): apply only an ALREADY-VALIDATED calibration
        # here, at run start, so it's in force identically for training and test --
        # never a fresh, unvalidated suggestion derived from this same run's own
        # training window (see _run_intraday_replay_worker's training-window-close
        # handling, which now requires exit_calibration_experimental_unvalidated to
        # do that, and labels it loudly when it does).
        try:
            _validated_calib = load_active_exit_calibration()
        except Exception:
            _validated_calib = {}
        if _validated_calib:
            settings['_strategy_exit_calibration'] = _validated_calib
            trading_settings = dict(trading_settings)
            trading_settings['_strategy_exit_calibration'] = _validated_calib
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set; Intraday Replay Lab needs the database for run state.'}
    try:
        with conn, conn.cursor() as cur:
            cap_source_label = {
                'local_file': 'local file override',
                'downloaded_csv': 'auto-downloaded NIFTY LargeMidcap 250 list',
                'downloaded_csv_cached': 'cached NIFTY LargeMidcap 250 list',
                'downloaded_csv_stale_cache': 'STALE cached NIFTY LargeMidcap 250 list (fresh download failed)',
                'none': 'unavailable',
            }.get(cap_meta.get('source'), cap_meta.get('source') or 'unavailable')
            message = (
                f'Queued: {len(trading_days)} day(s), {len(universe)} stock(s)'
                + (f' (Large+Mid cap filter applied: {cap_source_label})' if cap_filter_applied
                   else f' (NO cap filter -- {cap_source_label}; results include the full configured universe, not just Large+Mid cap)')
            )
            if dropped_dates:
                # Tell the user up front which of their requested dates won't be replayed
                # and why (market holiday/weekend/out of range), instead of them only
                # discovering it later from a lower-than-expected day count or a "no
                # historical data available" skip message once the run finishes.
                by_reason: Dict[str, List[str]] = {}
                for item in dropped_dates:
                    by_reason.setdefault(item['reason'], []).append(item['date'])
                reason_labels = {
                    'market_holiday': 'market holiday', 'weekend': 'weekend',
                    'outside_lookback_window': 'outside lookback window',
                    'in_the_future': 'in the future', 'invalid_date': 'invalid date',
                }
                dropped_note = '; '.join(
                    f"{reason_labels.get(reason, reason)}: {', '.join(ds)}" for reason, ds in by_reason.items()
                )
                message += f' | {len(dropped_dates)} requested date(s) skipped before queueing ({dropped_note})'
            if training_days:
                message += (f' | Research design: {len(training_days)} TRAINING day(s) '
                            f'({training_days[0].isoformat()}..{training_days[-1].isoformat()}) build the evidence base, '
                            f'then it is FROZEN and the remaining {len(trading_days) - len(training_days)} day(s) are '
                            f'replayed blind (evidence_mode={evidence_mode}). Training trades are excluded from the '
                            f'reported result.')
            else:
                message += (' | No training window: day 1 starts with zero recorded trades, so the EV gate is inert on '
                            'it and the early days are traded while the system is still cold. Pass train_start_date/'
                            'train_end_date for a proper out-of-sample result.')
            message += (f' | Max open positions for this run: {position_limit_label(replay_position_limit)} ({position_limit_source})'
                         f' | Capital guard: {"ON — total deployed capital capped at the run capital" if enforce_capital else "OFF — deployed capital may exceed the run capital"}')
            if capital_override is not None:
                message += f' | Capital overridden for this run: ₹{settings["simulation_capital_inr"]:.0f}'
            if require_vwap_override is not None:
                message += f' | VWAP requirement overridden for this run: {"required" if settings["require_vwap"] else "not required"}'
            if parity_warning:
                message += f' | WARNING: {parity_warning}'
            cur.execute("""
                INSERT INTO intraday_replay_runs
                    (market, status, selected_dates, settings_snapshot, universe_snapshot, universe_count, cap_filter_applied, use_learning, message)
                VALUES (%s,'pending',%s,%s,%s,%s,%s,%s,%s) RETURNING id
            """, (
                market, json.dumps([d.isoformat() for d in trading_days]),
                json.dumps({'intraday_settings': settings, 'trading_settings': trading_settings, 'use_learning': use_learning,
                            'cap_filter_applied': cap_filter_applied, 'cap_filter_source': cap_meta.get('source'),
                            'cap_filter_stale': cap_meta.get('stale', False),
                            'pre_scan_pool_limit_live': INTRADAY_PRE_SCAN_POOL_LIMIT, 'pre_scan_pool_limit_replay': len(universe),
                            'universe_parity_warning': parity_warning,
                            'fill_mode': INTRADAY_REPLAY_FILL_MODE, 'entry_slippage_bps': INTRADAY_REPLAY_ENTRY_SLIPPAGE_BPS,
                            'memory_estimate': mem_estimate,
                            'capital_overridden': capital_override is not None,
                            'require_vwap_overridden': require_vwap_override is not None,
                            'max_open_positions': position_limit_label(replay_position_limit),
                            'max_open_positions_source': position_limit_source,
                            'enforce_capital': bool(enforce_capital),
                            'training_days': [d.isoformat() for d in training_days],
                            'test_days': [d.isoformat() for d in trading_days if d not in set(training_days)],
                            'evidence_mode': evidence_mode,
                            'auto_apply_exit_calibration': bool(auto_apply_exit_calibration),
                            'risk_budget': {
                                'enabled': settings.get('risk_budget_enabled'),
                                'daily_risk_budget_pct': settings.get('daily_risk_budget_pct', INTRADAY_DAILY_RISK_BUDGET_PCT),
                                'max_concurrent_risk_pct': settings.get('max_concurrent_risk_pct', INTRADAY_MAX_CONCURRENT_RISK_PCT),
                                'reserve_pct': settings.get('risk_budget_reserve_pct', INTRADAY_RISK_BUDGET_RESERVE_PCT)}},
                           default=_json_safe),
                json.dumps(universe), len(universe), cap_filter_applied, use_learning, message,
            ))
            run_id = cur.fetchone()[0]
    finally:
        conn.close()
    stop_event = threading.Event()
    pause_event = threading.Event()
    with INTRADAY_REPLAY_LOCK:
        INTRADAY_REPLAY_STOP_EVENTS[run_id] = stop_event
        INTRADAY_REPLAY_PAUSE_EVENTS[run_id] = pause_event
        thread = threading.Thread(
            target=_run_intraday_replay_worker,
            args=(run_id, market, trading_days, universe, settings, trading_settings, stop_event, pause_event, use_learning),
            daemon=True, name=f'intraday-replay-{run_id}',
        )
        INTRADAY_REPLAY_THREADS[run_id] = thread
        thread.start()
    result = {'ok': True, 'run_id': run_id, 'selected_dates': [d.isoformat() for d in trading_days], 'universe_count': len(universe),
               'training_days': [d.isoformat() for d in training_days],
               'test_days': [d.isoformat() for d in trading_days if d not in set(training_days)],
               'evidence_mode': evidence_mode,
               'message': 'Replay started in the background -- poll /api/intraday-replay/<run_id>/status for progress.',
               'max_open_positions': position_limit_label(replay_position_limit),
               'max_open_positions_source': position_limit_source,
               'enforce_capital': bool(enforce_capital),
               'starting_capital': round(float(settings.get('simulation_capital_inr') or TRADING_DEFAULT_CAPITAL_INR), 2),
               'memory_estimate': mem_estimate}
    if parity_warning:
        result['warnings'] = [parity_warning]
    return result


def _count_by(rows: List[Dict[str, Any]], key: str) -> Dict[str, int]:
    """Tally non-null values of `key` across rows (used for strategy/regime/failure mix)."""
    counts: Dict[str, int] = {}
    for r in rows:
        v = r.get(key)
        if v:
            counts[str(v)] = counts.get(str(v), 0) + 1
    return counts


def classify_strategy_health(group: List[Dict[str, Any]]) -> Dict[str, Any]:
    """PRIORITY-6 / LAYER-6 (report-driven): a single evidence-gated health state per
    strategy -- PROVEN / UNDER_REVIEW / WEAKENING / DISABLED / UNPROVEN -- instead of
    leaving a reader to eyeball win rate and profit factor and guess what they imply.

    Mirrors the SAME thresholds strategies._is_auto_disabled/_historical_edge already
    use (MIN_TRADES_FOR_EDGE_DISPLAY, AUTO_DISABLE_MIN_TRADES, AUTO_DISABLE_PROFIT_FACTOR)
    so this label can never disagree with what the selector itself is doing -- it is a
    read-only description of the same evidence, not a second, competing opinion.

    WEAKENING is the one genuinely new state: split the group's trades in half by exit
    time and compare profit factor across the two halves. A strategy whose second half
    is meaningfully worse than its first is flagged even before it crosses the hard
    auto-disable line -- exactly the case AUTO_DISABLE alone would miss until it's
    already lost a lot of money finding out.
    """
    n = len(group)
    if n < MIN_TRADES_FOR_EDGE_DISPLAY:
        return {'state': 'UNPROVEN', 'reason': f'only {n} trade(s) recorded -- need {MIN_TRADES_FOR_EDGE_DISPLAY}+ before a health state means anything.'}

    def _pf(rows: List[Dict[str, Any]]) -> Optional[float]:
        gw = sum(float(r.get('net_pnl') or 0) for r in rows if float(r.get('net_return_pct') or 0) > 0)
        gl = abs(sum(float(r.get('net_pnl') or 0) for r in rows if float(r.get('net_return_pct') or 0) <= 0))
        return round(gw / gl, 2) if gl > 0 else None

    pf = _pf(group)
    AUTO_DISABLE_MIN_TRADES = 40
    AUTO_DISABLE_PROFIT_FACTOR = 0.85
    if n >= AUTO_DISABLE_MIN_TRADES and pf is not None and pf < AUTO_DISABLE_PROFIT_FACTOR:
        return {'state': 'DISABLED', 'reason': f'{n} trades, profit factor {pf} -- below the auto-disable floor ({AUTO_DISABLE_PROFIT_FACTOR}). Auto-benched by the selector.'}

    ordered = sorted(group, key=lambda t: t.get('exit_time') or datetime.datetime.min)
    mid = len(ordered) // 2
    first_half, second_half = ordered[:mid], ordered[mid:]
    weakening = False
    trend_note = ''
    if len(first_half) >= 10 and len(second_half) >= 10:
        pf1, pf2 = _pf(first_half), _pf(second_half)
        if pf1 is not None and pf2 is not None and pf2 < pf1 * 0.7 and pf2 < 1.1:
            weakening = True
            trend_note = f' First half profit factor {pf1} -> second half {pf2} -- meaningfully worse recently.'

    if weakening:
        return {'state': 'WEAKENING', 'reason': f'{n} trades, overall profit factor {pf}.{trend_note} Not yet auto-disabled, but trending the wrong way -- worth reviewing before it gets worse.'}
    if pf is None or pf < 1.1:
        return {'state': 'UNDER_REVIEW', 'reason': f'{n} trades, profit factor {pf} -- thin or unclear edge, not yet a confident PROVEN.'}
    return {'state': 'PROVEN', 'reason': f'{n} trades, profit factor {pf} -- consistent positive edge on a meaningful sample.'}


def _slice_trades(group: List[Dict[str, Any]], key_fn) -> Dict[str, Dict[str, Any]]:
    """Break one strategy's trades into buckets on a single context dimension, and
    record enough per bucket to compute a CONDITIONAL expectancy from it -- not just
    a count and a net P&L.

    Specifically: wins/trades (so a conditional win probability can be estimated with
    its own sample size, which is what shrinkage needs), and the average winner and
    average loser IN THAT BUCKET (so payoff asymmetry is conditional too -- the same
    strategy can win just as often in a high-volatility bucket while its losers are
    twice the size, and a win-rate-only slice hides exactly that).

    All returns here are already NET of round-trip costs, because net_return_pct is
    (see calculate_net_trade_pnl). Nothing downstream should subtract costs again.
    """
    out: Dict[str, Dict[str, Any]] = {}
    for t in group:
        try:
            k = key_fn(t)
        except Exception:
            k = None
        if not k:
            continue
        b = out.setdefault(str(k), {'trades': 0, 'wins': 0, 'net_pnl': 0.0,
                                    '_win_sum': 0.0, '_loss_sum': 0.0})
        r = float(t.get('net_return_pct') or 0)
        b['trades'] += 1
        b['net_pnl'] += float(t.get('net_pnl') or 0)
        if r > 0:
            b['wins'] += 1
            b['_win_sum'] += r
        else:
            b['_loss_sum'] += abs(r)
    for k, b in out.items():
        n, w = b['trades'], b['wins']
        losses = n - w
        b['losses'] = losses
        b['net_pnl'] = round(b['net_pnl'], 2)
        b['win_rate_pct'] = round((w / n) * 100, 1) if n else None
        b['avg_winner_pct'] = round(b['_win_sum'] / w, 3) if w else None
        b['avg_loser_pct'] = round(b['_loss_sum'] / losses, 3) if losses else None
        b['expectancy_pct_per_trade'] = round((b['_win_sum'] - b['_loss_sum']) / n, 3) if n else None
        del b['_win_sum'], b['_loss_sum']
    return out


def compute_strategy_performance(trades: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    """Per-strategy track record, computed from recorded trades only.

    This is the evidence base the selector uses (via _historical_edge) and the
    Strategy Dashboard displays. Nothing here is assumed or hard-coded -- a strategy
    that has never traded gets no entry, and one below MIN_TRADES_FOR_EDGE is still
    reported but explicitly marked unproven so a lucky 4-trade streak can't masquerade
    as an edge.

    Reports profit factor and expectancy alongside win rate on purpose: a 70% win rate
    with oversized losers is worse than 55% with controlled ones, and win-rate-only
    reporting hides exactly that.
    """
    by_id: Dict[str, List[Dict[str, Any]]] = {}
    for t in trades:
        sid = t.get('strategy_id')
        if not sid:
            continue
        by_id.setdefault(sid, []).append(t)

    out: Dict[str, Dict[str, Any]] = {}
    for sid, group in by_id.items():
        n = len(group)
        rets = [float(t.get('net_return_pct') or 0) for t in group]
        pnls = [float(t.get('net_pnl') or 0) for t in group]
        wins = [r for r in rets if r > 0]
        losses = [r for r in rets if r <= 0]
        gross_win = sum(r for r in rets if r > 0)
        gross_loss = abs(sum(r for r in rets if r < 0))
        # Failure-type breakdown: which way does THIS strategy tend to fail?
        failure_counts: Dict[str, int] = {}
        for t in group:
            ft = t.get('failure_type')
            if ft:
                failure_counts[ft] = failure_counts.get(ft, 0) + 1
        mfes = [float(t['mfe_pct']) for t in group if t.get('mfe_pct') is not None]
        maes = [float(t['mae_pct']) for t in group if t.get('mae_pct') is not None]
        spec = STRATEGY_BY_ID.get(sid, {})
        health = classify_strategy_health(group)
        # PRIORITY-6/7/8 (report-driven): regime and time-of-day breakdown WITHIN this
        # strategy -- a strategy judged "fine" overall can still be losing money in one
        # regime or one 30-minute window; this is the evidence compute_evidence_based_score_adjustment
        # (below) reads before applying any soft penalty, and what a human reviews before
        # deciding whether to restrict a strategy to certain regimes/times.
        by_regime = _slice_trades(group, lambda t: t.get('regime'))
        by_time_bucket = _slice_trades(group, _entry_time_bucket)
        # CONTEXT-CONDITIONED SLICES (report issues #2/#3). Expectancy is not a
        # property of a strategy -- it is a property of a strategy IN A SITUATION.
        # EMA Trend at +0.15%/trade overall can still be badly negative at 09:15-10:00
        # in a downtrend on a stock already up 1.5%, and a strategy-level EV gate
        # cannot see that. Each dimension is sliced separately (not as one combined
        # key) so every slice stays large enough to mean something; the hierarchical
        # blend in estimate_calibrated_win_probability() is what recombines them.
        by_volatility = _slice_trades(group, lambda t: t.get('volatility_bucket'))
        by_extension = _slice_trades(group, lambda t: t.get('extension_bucket'))
        by_relative_strength = _slice_trades(group, lambda t: t.get('relative_strength_bucket'))
        # The one genuinely joint slice kept: regime x time bucket. These two
        # interact strongly (a downtrend at the open is a different animal from a
        # downtrend at 14:00) and it is the pairing the report calls out by name.
        by_regime_time = _slice_trades(
            group, lambda t: (f"{t.get('regime')}|{_entry_time_bucket(t)}"
                              if t.get('regime') and _entry_time_bucket(t) else None))
        out[sid] = {
            'strategy_id': sid,
            'name': spec.get('name', sid),
            'description': spec.get('description'),
            'total_trades': n,
            'wins': len(wins), 'losses': len(losses),
            'win_rate_pct': round((len(wins) / n) * 100, 1) if n else 0.0,
            'profit_factor': round(gross_win / gross_loss, 2) if gross_loss > 0 else None,
            'expectancy_pct_per_trade': round(sum(rets) / n, 3) if n else 0.0,
            'net_pnl': round(sum(pnls), 2),
            'avg_winner_pct': round(sum(wins) / len(wins), 3) if wins else None,
            'avg_loser_pct': round(sum(losses) / len(losses), 3) if losses else None,
            'largest_loss_pct': round(min(rets), 3) if rets else None,
            'avg_mfe_pct': round(sum(mfes) / len(mfes), 3) if mfes else None,
            'avg_mae_pct': round(sum(maes) / len(maes), 3) if maes else None,
            'failure_breakdown': failure_counts,
            'health_state': health['state'], 'health_reason': health['reason'],
            'by_regime': by_regime, 'by_time_bucket': by_time_bucket,
            'by_volatility': by_volatility, 'by_extension': by_extension,
            'by_relative_strength': by_relative_strength, 'by_regime_time': by_regime_time,
            # Explicitly flag whether this record is big enough to mean anything.
            'proven': n >= MIN_TRADES_FOR_EDGE_DISPLAY,
            'evidence_note': (f'{n} trades — statistically meaningful' if n >= MIN_TRADES_FOR_EDGE_DISPLAY
                               else f'only {n} trades — NOT yet enough evidence to judge this strategy'),
        }
    return out


# ---------------------------------------------------------------------------
# GRADUATED COLD-START EVIDENCE + EV-PROPORTIONAL RISK SIZING (report #2/#3/#10)
# ---------------------------------------------------------------------------
# Report issue: a strategy below MIN_TRADES_FOR_EDGE_DISPLAY (30) was treated as
# flatly "unproven" and could still compete on setup quality with the SAME
# authority as a 60+ trade strategy, and every qualifying setup -- strong edge
# or barely-qualifying edge -- got approximately the same position size. This
# gives risk sizing (and, via strategies._historical_edge, ranking) a graduated
# evidence ladder instead of one hard cutoff, and scales risk with the strength
# of the validated edge instead of treating "cleared the gate" as a single tier.
#
# Trade-count tiers exactly as specified in the report:
#   0-9 trades   -> tiny risk / research only
#   10-29        -> reduced risk
#   30-59        -> normal selection but conservative
#   60+          -> full evidence weighting
EVIDENCE_TIERS = (
    (10, 'research_only', 0.15),
    (30, 'reduced_risk', 0.50),
    (60, 'normal_conservative', 0.85),
    (float('inf'), 'full_evidence', 1.00),
)


def evidence_tier_for_trade_count(trades: int) -> Dict[str, Any]:
    """Which cold-start evidence tier a strategy's trade count falls into, and the
    risk multiplier that tier earns. Mirrors strategies.evidence_tier() -- kept as
    its own copy (not a shared import) because strategies.py is deliberately kept
    free of any dependency on app.py (see that module's design rules)."""
    trades = int(trades or 0)
    lower = 0
    for upper, tier_name, mult in EVIDENCE_TIERS:
        if trades < upper:
            return {'tier': tier_name, 'trade_range': (f'{lower}-{upper - 1}' if upper != float('inf') else f'{lower}+'),
                    'trades': trades, 'risk_multiplier': mult}
        lower = int(upper)
    return {'tier': 'full_evidence', 'trade_range': '60+', 'trades': trades, 'risk_multiplier': 1.00}


# EV-proportional risk anchor points exactly as specified in the report:
#   EV 0.05% -> 0.25x normal risk, 0.15% -> 0.50x, 0.30% -> 1.00x, 0.50%+ capped at 1.25x
_EV_RISK_ANCHORS = ((0.0, 0.10), (0.05, 0.25), (0.15, 0.50), (0.30, 1.00), (0.50, 1.25))


def ev_proportional_risk_multiplier(ev_pct: Optional[float]) -> float:
    """Scale risk with the STRENGTH of the validated expected value (report #10):
    better evidence gets more capital instead of every qualifying setup getting
    approximately the same risk. Piecewise-linear between the report's anchor
    points; flat below 0 and capped at 1.25x beyond 0.50%/trade."""
    if ev_pct is None:
        return 1.0
    ev = max(0.0, float(ev_pct))
    pts = _EV_RISK_ANCHORS
    if ev <= pts[0][0]:
        return pts[0][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if ev <= x1:
            frac = (ev - x0) / (x1 - x0) if x1 > x0 else 0.0
            return round(y0 + frac * (y1 - y0), 3)
    return pts[-1][1]


def compute_candidate_risk_scale(ev_pct: Optional[float], ev_proven: bool, evidence_trades: int) -> Dict[str, Any]:
    """Single source of truth for how much of normal risk-per-trade a candidate
    earns, combining the cold-start evidence tier (#3) with EV-proportional
    sizing (#10). Computed ONCE per candidate at selection time (see
    attach_intraday_strategy_engine) and threaded through compute_integer_position_size
    so Live, Paper and Replay all size the same candidate identically -- the same
    single-choke-point principle the report's other fixes rely on.

    ev_proven=False means there is no real EV number to scale by (unproven
    strategy, neutral prior) -- only the cold-start tier governs in that case,
    so a brand-new strategy isn't ALSO punished or rewarded for a made-up EV.
    """
    tier = evidence_tier_for_trade_count(evidence_trades)
    ev_mult = ev_proportional_risk_multiplier(ev_pct) if ev_proven else 1.0
    combined = round(max(0.05, min(1.25, tier['risk_multiplier'] * ev_mult)), 3)
    return {
        'risk_scale': combined,
        'evidence_tier': tier['tier'],
        'evidence_trade_range': tier['trade_range'],
        'evidence_trades': tier['trades'],
        'evidence_risk_multiplier': tier['risk_multiplier'],
        'ev_risk_multiplier': round(ev_mult, 3),
        'note': (f"{tier['tier']} tier ({tier['trades']} trades, {tier['trade_range']}) x "
                 f"EV multiplier {round(ev_mult, 2)} = {combined}x normal risk"),
    }


# Mirrors strategies.MIN_TRADES_FOR_EDGE; kept as its own name so the display
# threshold can diverge from the selection threshold later without silently
# changing selection behaviour.
MIN_TRADES_FOR_EDGE_DISPLAY = 30


def compute_replay_statistics(completed_trades: List[Dict[str, Any]]) -> Dict[str, Any]:
    """PRIORITY-5 FIX: proper replay performance statistics -- previously the
    run row only tracked win/loss counts and a raw sum of %returns. Computes
    win rate, gross/net/cost-adjusted P&L, profit factor, expectancy,
    average winner/loser, largest win/loss, max drawdown (on the cumulative
    net-P&L curve in exit order), average holding time, and win rate broken
    down by score bucket (so a 70-point score gate can actually be checked
    against the data instead of assumed)."""
    n = len(completed_trades)
    if n == 0:
        return {'total_trades': 0}
    wins = [t for t in completed_trades if float(t.get('net_return_pct') or 0) > 0]
    losses = [t for t in completed_trades if float(t.get('net_return_pct') or 0) <= 0]
    gross_pnl = sum(float(t.get('gross_pnl') or 0) for t in completed_trades)
    cost_total = sum(float(t.get('cost_amount') or 0) for t in completed_trades)
    net_pnl = sum(float(t.get('net_pnl') or 0) for t in completed_trades)
    gross_win = sum(float(t.get('net_pnl') or 0) for t in wins)
    gross_loss = abs(sum(float(t.get('net_pnl') or 0) for t in losses))
    avg_winner_pct = round(sum(float(t.get('net_return_pct') or 0) for t in wins) / len(wins), 3) if wins else None
    avg_loser_pct = round(sum(float(t.get('net_return_pct') or 0) for t in losses) / len(losses), 3) if losses else None
    largest_win = max((float(t.get('net_pnl') or 0) for t in wins), default=None)
    largest_loss = min((float(t.get('net_pnl') or 0) for t in losses), default=None)

    # Max drawdown on the cumulative net-P&L curve, trades ordered by exit time.
    ordered = sorted(completed_trades, key=lambda t: t.get('exit_time') or datetime.datetime.min)
    cum = 0.0
    peak = 0.0
    max_dd = 0.0
    holding_minutes = []
    for t in ordered:
        cum += float(t.get('net_pnl') or 0)
        peak = max(peak, cum)
        max_dd = min(max_dd, cum - peak)
        entry_time, exit_time = t.get('entry_time'), t.get('exit_time')
        if entry_time and exit_time:
            try:
                holding_minutes.append((exit_time - entry_time).total_seconds() / 60.0)
            except Exception:
                pass

    # Win rate by score bucket, so the current min-score gate is checked
    # against actual outcomes rather than assumed to be well-calibrated.
    buckets = [(70, 75), (75, 80), (80, 85), (85, 90), (90, 101)]
    score_buckets = {}
    for lo, hi in buckets:
        label = f'{lo}-{hi - 1}' if hi <= 100 else f'{lo}+'
        in_bucket = [t for t in completed_trades if t.get('score') is not None and lo <= float(t['score']) < hi]
        if in_bucket:
            b_wins = sum(1 for t in in_bucket if float(t.get('net_return_pct') or 0) > 0)
            score_buckets[label] = {
                'trades': len(in_bucket), 'wins': b_wins,
                'win_rate_pct': round((b_wins / len(in_bucket)) * 100, 1),
                'avg_return_pct': round(sum(float(t.get('net_return_pct') or 0) for t in in_bucket) / len(in_bucket), 3),
            }

    # MAE/MFE roll-up (Priority 4): classify losing trades as "bad entry"
    # (never really moved in our favor -- MFE stayed small before the loss)
    # vs. "bad management" (moved nicely in our favor at some point, THEN
    # reversed into a loss -- the signal was fine, the exit/protection logic
    # gave the profit back). Threshold: MFE >= 50% of the eventual adverse
    # move counts as "had a real favorable excursion" -- a rough but useful
    # split, meant to guide where engineering effort goes next, not as a
    # precise clinical measure.
    mfe_losses = [t for t in losses if t.get('mfe_pct') is not None]
    bad_entry_losses = 0
    bad_management_losses = 0
    for t in mfe_losses:
        mfe = float(t.get('mfe_pct') or 0)
        loss_size = abs(float(t.get('net_return_pct') or 0))
        if loss_size > 0 and mfe >= 0.5 * loss_size:
            bad_management_losses += 1
        else:
            bad_entry_losses += 1
    avg_mfe_pct = round(sum(float(t.get('mfe_pct') or 0) for t in completed_trades if t.get('mfe_pct') is not None) / n, 3) if n else None
    avg_mae_pct = round(sum(float(t.get('mae_pct') or 0) for t in completed_trades if t.get('mae_pct') is not None) / n, 3) if n else None
    avg_signal_fill_gap_pct = None
    gap_vals = [float(t.get('signal_fill_gap_pct')) for t in completed_trades if t.get('signal_fill_gap_pct') is not None]
    if gap_vals:
        avg_signal_fill_gap_pct = round(sum(gap_vals) / len(gap_vals), 3)
    intrabar_conflict_count = sum(1 for t in completed_trades if t.get('intrabar_resolution') == 'BOTH_TOUCHED_SAME_BAR')

    return {
        'total_trades': n, 'wins': len(wins), 'losses': len(losses),
        'win_rate_pct': round((len(wins) / n) * 100, 1),
        'gross_pnl': round(gross_pnl, 2), 'total_costs': round(cost_total, 2), 'net_pnl': round(net_pnl, 2),
        'avg_winner_pct': avg_winner_pct, 'avg_loser_pct': avg_loser_pct,
        'largest_win': round(largest_win, 2) if largest_win is not None else None,
        'largest_loss': round(largest_loss, 2) if largest_loss is not None else None,
        'profit_factor': round(gross_win / gross_loss, 2) if gross_loss > 0 else None,
        'expectancy_pct_per_trade': round(sum(float(t.get('net_return_pct') or 0) for t in completed_trades) / n, 3),
        'max_drawdown': round(max_dd, 2),
        'avg_holding_minutes': round(sum(holding_minutes) / len(holding_minutes), 1) if holding_minutes else None,
        'score_buckets': score_buckets,
        'avg_mfe_pct': avg_mfe_pct, 'avg_mae_pct': avg_mae_pct,
        'avg_signal_fill_gap_pct': avg_signal_fill_gap_pct,
        'intrabar_both_touched_count': intrabar_conflict_count,
        'losses_bad_entry_count': bad_entry_losses,
        'losses_bad_management_count': bad_management_losses,
        # MULTI-STRATEGY reporting: which strategy actually made each decision, how each
        # one performed, and which failure modes are RECURRING (>=4 occurrences) rather
        # than one-offs. The recurrence bar matters: acting on a single loss is how a
        # system tunes itself into nonsense.
        'strategy_performance': compute_strategy_performance(completed_trades),
        'failure_patterns': summarize_failure_patterns(completed_trades),
        'strategy_trade_counts': _count_by(completed_trades, 'strategy_id'),
        'regime_trade_counts': _count_by(completed_trades, 'regime'),
        'failure_type_counts': _count_by(completed_trades, 'failure_type'),
        'losses_diagnostic_note': ('Rough split of losing trades: "bad entry" = the trade barely moved in our '
                                    'favor before losing (MFE small relative to the loss) -- fixing this needs a '
                                    'stronger/later entry signal, not a wider stop. "bad management" = the trade '
                                    'moved meaningfully in our favor at some point then reversed into a loss -- '
                                    'fixing this needs better profit protection/trailing logic, not a different '
                                    'entry signal. Only trades with mfe_pct recorded (new replay runs) are counted.'),
    }



def compute_replay_deep_analysis(completed_trades: List[Dict[str, Any]], stats: Dict[str, Any],
                                  max_trades_per_day: Optional[int], trading_days_count: int) -> Dict[str, Any]:
    """AUTO-GENERATED 'point 1' style deep report for a replay run, surfaced in the UI
    instead of living only in an ad-hoc chat analysis. Everything here is derived
    purely from this run's completed_trades plus the stats dict compute_replay_statistics
    already produced -- no new data collection, just the diagnostic layer that was
    previously done by hand: exit-reason P&L attribution, the break-even win rate the
    current avg winner/loser actually requires, an overtrading check against the
    configured daily cap, a time-of-day expectancy breakdown, a score-calibration
    monotonicity check, and a traffic-light verdict summarizing all of it.
    """
    n = len(completed_trades)
    if n == 0:
        return {'has_data': False}

    wins = [t for t in completed_trades if float(t.get('net_return_pct') or 0) > 0]
    losses = [t for t in completed_trades if float(t.get('net_return_pct') or 0) <= 0]

    # --- 1. Exit-reason P&L attribution: where the money was actually made/lost,
    # not just how many trades exited each way (failure counts alone hide whether
    # a "give-back" exit type is net negative or just less profitable than a clean
    # target hit).
    by_exit: Dict[str, Dict[str, Any]] = {}
    for t in completed_trades:
        reason = t.get('exit_reason') or 'UNKNOWN'
        b = by_exit.setdefault(reason, {'exit_reason': reason, 'trades': 0, 'wins': 0,
                                          'gross_pnl': 0.0, 'costs': 0.0, 'net_pnl': 0.0})
        b['trades'] += 1
        b['wins'] += 1 if float(t.get('net_return_pct') or 0) > 0 else 0
        b['gross_pnl'] += float(t.get('gross_pnl') or 0)
        b['costs'] += float(t.get('cost_amount') or 0)
        b['net_pnl'] += float(t.get('net_pnl') or 0)
    exit_reason_breakdown = sorted(
        [{**b, 'gross_pnl': round(b['gross_pnl'], 2), 'costs': round(b['costs'], 2), 'net_pnl': round(b['net_pnl'], 2),
          'win_rate_pct': round((b['wins'] / b['trades']) * 100, 1) if b['trades'] else None,
          'avg_net_per_trade': round(b['net_pnl'] / b['trades'], 2) if b['trades'] else None}
         for b in by_exit.values()], key=lambda x: x['net_pnl'])
    giveback_reasons = [r for r in exit_reason_breakdown if 'GAVE_BACK' in r['exit_reason'] or 'TRAILING' in r['exit_reason']]
    giveback_net_pnl = round(sum(r['net_pnl'] for r in giveback_reasons), 2) if giveback_reasons else None

    # --- 2. Break-even win rate the CURRENT avg winner/loser actually requires,
    # so a score/threshold gate can be checked against the real payoff ratio
    # instead of an assumed one. Reported both pre-cost (pct-return basis, matches
    # what most people mean by "win rate needed") and against the realized win rate.
    avg_win_pct = round(sum(float(t.get('net_return_pct') or 0) for t in wins) / len(wins), 3) if wins else None
    avg_loss_pct = round(abs(sum(float(t.get('net_return_pct') or 0) for t in losses) / len(losses)), 3) if losses else None
    breakeven_win_rate_pct = None
    if avg_win_pct and avg_loss_pct and (avg_win_pct + avg_loss_pct) > 0:
        breakeven_win_rate_pct = round((avg_loss_pct / (avg_win_pct + avg_loss_pct)) * 100, 1)
    actual_win_rate_pct = round((len(wins) / n) * 100, 1)
    win_rate_gap_pct = round(actual_win_rate_pct - breakeven_win_rate_pct, 1) if breakeven_win_rate_pct is not None else None

    # --- 3. Overtrading check: how many days actually hit the configured daily cap,
    # which turns "we took every eligible signal" into "we filled the quota and
    # stopped selecting" -- the two look identical in a trade count alone.
    daily_counts: Dict[str, int] = {}
    for t in completed_trades:
        d = t.get('trading_date')
        key = d.isoformat() if hasattr(d, 'isoformat') else str(d)
        daily_counts[key] = daily_counts.get(key, 0) + 1
    days_at_cap = sorted([d for d, c in daily_counts.items() if max_trades_per_day and c >= max_trades_per_day])
    overtrading_flag = bool(max_trades_per_day and trading_days_count and len(days_at_cap) >= max(1, trading_days_count // 2))

    # --- 4. Time-of-day expectancy, 30-minute buckets, entry-time based. A strategy
    # can look fine in aggregate while systematically losing in one window (e.g. the
    # opening 30-60 minutes) -- this is the check that catches it without having to
    # eyeball the trade log by hand.
    def _bucket_label(dt) -> Optional[str]:
        if not dt:
            return None
        try:
            h, m = dt.hour, dt.minute
        except Exception:
            return None
        bm = 0 if m < 30 else 30
        return f'{h:02d}:{bm:02d}'

    tod: Dict[str, Dict[str, Any]] = {}
    for t in completed_trades:
        lbl = _bucket_label(t.get('entry_time'))
        if not lbl:
            continue
        b = tod.setdefault(lbl, {'bucket': lbl, 'trades': 0, 'wins': 0, 'net_pnl': 0.0, 'return_sum': 0.0})
        b['trades'] += 1
        b['wins'] += 1 if float(t.get('net_return_pct') or 0) > 0 else 0
        b['net_pnl'] += float(t.get('net_pnl') or 0)
        b['return_sum'] += float(t.get('net_return_pct') or 0)
    time_of_day = sorted(
        [{**b, 'net_pnl': round(b['net_pnl'], 2),
          'win_rate_pct': round((b['wins'] / b['trades']) * 100, 1) if b['trades'] else None,
          'avg_return_pct': round(b['return_sum'] / b['trades'], 3) if b['trades'] else None}
         for b in tod.values()], key=lambda x: x['bucket'])
    # A bucket needs a real sample before its negative expectancy means anything --
    # 8 trades is a low bar on purpose (matches the MIN_TRADES_FOR_EDGE_DISPLAY spirit
    # but scoped to a 30-min slice, where a full-run threshold would almost never fire).
    weak_time_buckets = [b for b in time_of_day if b['trades'] >= 8 and b['net_pnl'] < 0]

    # --- 5. Score calibration: is win rate actually increasing with score, the way a
    # confidence score implies it should? Flags the exact failure mode from the chat
    # report ("a 90 score isn't behaving remotely like a 90% probability").
    score_buckets = stats.get('score_buckets') or {}
    ordered_buckets = [score_buckets[k] for k in ('70-74', '75-79', '80-84', '85-89', '90+') if k in score_buckets]
    calibrated = None
    calibration_note = None
    if len(ordered_buckets) >= 3:
        win_rates = [b['win_rate_pct'] for b in ordered_buckets]
        # "Calibrated" here just means no lower-score bucket beats a higher-score
        # bucket's win rate by a wide margin -- a loose check, not a statistical test.
        violations = sum(1 for i in range(len(win_rates) - 1) if win_rates[i] > win_rates[i + 1] + 10)
        calibrated = violations == 0
        calibration_note = ('Higher score buckets are not reliably winning more often than lower ones -- '
                             'the confidence score is not behaving like a calibrated probability.' if not calibrated else
                             'Win rate rises reasonably consistently with score across buckets with enough trades.')

    # --- 6. Cost drag vs the underlying (pre-cost) edge.
    gross_pnl = float(stats.get('gross_pnl') or 0)
    net_pnl = float(stats.get('net_pnl') or 0)
    total_costs = float(stats.get('total_costs') or 0)
    pre_cost_negative = gross_pnl <= 0

    # --- Traffic-light verdict, one rating per area, each with the number behind it
    # so the light is never just an unexplained color.
    def _light(cond_red, cond_green, red_reason, green_reason, yellow_reason):
        if cond_red:
            return {'level': 'red', 'reason': red_reason}
        if cond_green:
            return {'level': 'green', 'reason': green_reason}
        return {'level': 'yellow', 'reason': yellow_reason}

    profit_factor = stats.get('profit_factor')
    verdict = {
        'signal_quality': _light(
            pre_cost_negative,
            (not pre_cost_negative) and profit_factor is not None and profit_factor >= 1.3,
            f'Gross P&L before costs is already negative (₹{gross_pnl:,.2f}) -- the entry signals themselves are not selecting winning setups.',
            f'Positive edge before AND after costs (profit factor {profit_factor}).',
            f'Gross P&L before costs is positive (₹{gross_pnl:,.2f}) but the edge is thin or costs erase it (net ₹{net_pnl:,.2f}).'),
        'exit_management': _light(
            giveback_net_pnl is not None and giveback_net_pnl < 0 and abs(giveback_net_pnl) > 0.1 * abs(net_pnl or 1),
            giveback_net_pnl is not None and giveback_net_pnl >= 0,
            f'Trailing-stop/give-back exits are net negative (₹{giveback_net_pnl:,.2f} across {sum(r["trades"] for r in giveback_reasons)} trade(s)) -- '
            'the exit/protection logic is giving back favorable moves instead of locking them in.' if giveback_net_pnl is not None else 'No give-back exits recorded.',
            'Trailing-stop/give-back exits are net neutral or positive -- exit management is not the leak.',
            'Not enough give-back exits in this sample to judge exit management specifically.'),
        'overtrading': _light(
            overtrading_flag and net_pnl < 0,
            not overtrading_flag,
            f'Hit the daily trade cap ({max_trades_per_day}/day) on {len(days_at_cap)} of {trading_days_count} day(s) while net P&L is negative -- '
            'this looks like "fill the quota" rather than "select the best setups".',
            'Trade volume stayed comfortably under the daily cap.',
            f'Hit the daily trade cap on {len(days_at_cap)} of {trading_days_count} day(s); net P&L is not negative enough to call this the primary problem yet.'),
        'capital_allocation': _light(
            (stats.get('capital', {}).get('peak_capital_utilisation_pct') or 0) >= 90 and net_pnl < 0,
            (stats.get('capital', {}).get('peak_capital_utilisation_pct') or 0) >= 60 and net_pnl >= 0,
            f'Peak capital utilisation was {stats.get("capital", {}).get("peak_capital_utilisation_pct")}% while net P&L is negative -- '
            'near-full capital was deployed into a strategy that has not shown a positive edge yet.',
            'High utilisation paired with a positive net result.',
            'Capital utilisation is not both high and loss-making enough to flag on its own.'),
        'score_calibration': (
            {'level': 'red', 'reason': calibration_note} if calibrated is False else
            {'level': 'green', 'reason': calibration_note} if calibrated is True else
            {'level': 'yellow', 'reason': 'Not enough trades across score buckets yet to judge calibration.'}),
    }
    red_count = sum(1 for v in verdict.values() if v['level'] == 'red')
    green_count = sum(1 for v in verdict.values() if v['level'] == 'green')
    if red_count >= 3:
        headline = f'Not profitable in this sample and multiple areas need work ({red_count} red, {green_count} green). See verdict below.'
    elif pre_cost_negative:
        headline = f'Losing before costs are even applied (gross ₹{gross_pnl:,.2f}) -- costs (₹{total_costs:,.2f}) make it worse, but the entry logic is the root cause.'
    elif net_pnl < 0:
        headline = f'Positive gross edge (₹{gross_pnl:,.2f}) but costs (₹{total_costs:,.2f}) turn it net-negative (₹{net_pnl:,.2f}) -- this is a cost/frequency problem, not a signal problem.'
    else:
        headline = f'Net profitable in this sample (₹{net_pnl:,.2f}) with {green_count} area(s) green and {red_count} red.'

    return {
        'has_data': True,
        'headline': headline,
        'verdict': verdict,
        'exit_reason_breakdown': exit_reason_breakdown,
        'breakeven_win_rate_pct': breakeven_win_rate_pct,
        'actual_win_rate_pct': actual_win_rate_pct,
        'win_rate_gap_pct': win_rate_gap_pct,
        'avg_winner_pct': avg_win_pct,
        'avg_loser_pct': avg_loss_pct,
        'breakeven_note': (f'With an average winner of +{avg_win_pct}% and average loser of -{avg_loss_pct}%, this strategy '
                            f'needs roughly a {breakeven_win_rate_pct}% win rate just to break even before costs; it actually '
                            f'achieved {actual_win_rate_pct}% ({"+" if (win_rate_gap_pct or 0) >= 0 else ""}{win_rate_gap_pct} pts vs break-even).'
                            if breakeven_win_rate_pct is not None else None),
        'overtrading': {
            'flag': overtrading_flag, 'max_trades_per_day': max_trades_per_day,
            'trading_days_count': trading_days_count, 'days_at_cap': days_at_cap,
            'daily_trade_counts': daily_counts,
        },
        'time_of_day': time_of_day,
        'weak_time_buckets': weak_time_buckets,
        'score_calibrated': calibrated,
        'score_calibration_note': calibration_note,
        'cost_drag': {
            'gross_pnl': round(gross_pnl, 2), 'total_costs': round(total_costs, 2), 'net_pnl': round(net_pnl, 2),
            'pre_cost_negative': pre_cost_negative,
        },
    }


# ---------------------------------------------------------------------------
# PRIORITY 1/2/3/7/8 (report-driven): evidence-based soft adjustments.
#
# All of these follow the SAME design rule the rest of this file already
# enforces (see strict_learning_review / strategy_memory_adjustment): a single
# piece of evidence is a SCORE ADJUSTMENT, never a hard block on its own, and
# every adjustment requires a minimum sample size before it's allowed to speak
# at all. Nothing here changes any behaviour unless use_learning=True AND the
# specific strategy/context combination it's judging has enough recorded
# trades to mean something -- exactly the same evidence bar _historical_edge
# and _is_auto_disabled already apply to the strategy selector itself.
# ---------------------------------------------------------------------------

# Flat round-trip cost estimate used ONLY for the pre-trade expected-value gate
# below (Priority 3), expressed as a % of position value. Derived from Replay 13
# (~₹40/trade against ~₹27k average position ≈ 0.15%); deliberately a rough,
# documented constant rather than a precise per-trade forecast -- the EV gate
# only needs to be right about the SIGN of the edge after costs, not the last
# paisa. Overridable via settings['est_roundtrip_cost_pct'] if a better number
# becomes available (e.g. computed from this run's own trades so far).
INTRADAY_EST_ROUNDTRIP_COST_PCT = 0.15

# A context slice (one strategy in one regime, or one strategy in one 30-min
# window) needs at least this many recorded trades before its measured
# expectancy is allowed to penalize a new candidate. Deliberately smaller than
# MIN_TRADES_FOR_EDGE_DISPLAY (30) -- these are much narrower slices of the
# same data and would almost never reach 30 within one run -- but still a real
# bar, not "any 2 losses in a row".
MIN_TRADES_FOR_CONTEXT_EVIDENCE = 12


# ---------------------------------------------------------------------------
# CALIBRATED, CONTEXT-CONDITIONED PROBABILITY AND EXPECTED VALUE
# ---------------------------------------------------------------------------
# Report issues #2 and #3, together, because they are the same missing piece:
#
#   #2  "your calibrated probability is NOT actually a calibrated probability"
#       -- a Wilson lower bound on a strategy's overall win rate is a
#       conservative estimate of an UNCONDITIONAL rate. It answers "how often
#       does this strategy win, ever", not "what is P(win) for THIS setup".
#
#   #3  "EV is still too broad" -- the same problem one layer up: expectancy
#       built from a strategy's entire history, so a strategy that is positive
#       overall passes the gate even in the specific regime/time/volatility
#       slice where it reliably loses.
#
# WHAT THIS IMPLEMENTS -- a hierarchical (partial-pooling / empirical-Bayes)
# estimate. Each context dimension contributes its own conditional win rate,
# shrunk toward the strategy-level rate in proportion to how thin that slice is:
#
#       p_slice_shrunk = (wins + k * p_parent) / (trades + k)
#
# with k = SHRINKAGE_PSEUDO_TRADES. A slice with 3 trades barely moves the
# estimate; a slice with 60 trades substantially overrides it. This is the honest
# middle between "trust every slice" (confidently quoting probabilities derived
# from four trades) and "trust no slice" (the old global-average behaviour), and
# it degrades gracefully to exactly the old strategy-level number when no context
# evidence exists at all.
#
# The dimension estimates are then combined in LOG-ODDS space, where independent
# evidence adds, and the result is finally passed through a Wilson lower bound
# computed on the EFFECTIVE sample size backing it -- so conservatism is still
# applied, but to a conditional estimate rather than instead of one.
#
# Payoff (avg winner / avg loser) is conditioned the same way, because payoff
# asymmetry is context-dependent too: the same strategy can keep its win rate in
# a high-volatility tape while its losers quietly double in size.

SHRINKAGE_PSEUDO_TRADES = float(os.environ.get('INTRADAY_CALIBRATION_SHRINKAGE', '12'))
# How hard to discount each ADDITIONAL context dimension, because the dimensions
# are correlated rather than independent (see the damping comment below). 0 would
# mean "treat all five as independent evidence" -- which is exactly the mistake.
CONTEXT_CORRELATION_DAMPING = float(os.environ.get('INTRADAY_CONTEXT_CORRELATION_DAMPING', '0.6'))
# Maximum total log-odds shift context may apply. 1.1 is roughly a 3x odds ratio:
# enough to move a 50% strategy to ~25% or ~75% in a genuinely bad/good context,
# not enough to manufacture a near-certainty from a few dozen sliced trades.
MAX_CONTEXT_LOG_ODDS_SHIFT = float(os.environ.get('INTRADAY_MAX_CONTEXT_LOG_ODDS_SHIFT', '1.1'))
# A context slice needs at least this many trades before it is allowed to
# contribute anything at all. Below it, even shrunk, it is noise with a label.
MIN_SLICE_TRADES_FOR_CALIBRATION = int(os.environ.get('INTRADAY_MIN_SLICE_TRADES', '6'))


def _wilson_lower_bound(wins: float, n: float, z: float = 1.96) -> float:
    """Lower bound of the Wilson score interval. Small samples are pulled down
    hard, large ones barely at all -- 6/10 is treated with far more suspicion
    than 180/300 despite both being 60%."""
    if n <= 0:
        return 0.0
    p = max(0.0, min(1.0, wins / n))
    denom = 1 + z * z / n
    center = p + z * z / (2 * n)
    margin = z * ((p * (1 - p) / n + z * z / (4 * n * n)) ** 0.5)
    return max(0.0, min(1.0, (center - margin) / denom))


def _logit(p: float) -> float:
    p = min(0.999, max(0.001, p))
    return math.log(p / (1 - p))


def _inv_logit(x: float) -> float:
    return 1.0 / (1.0 + math.exp(-x))


def estimate_calibrated_win_probability(strategy_id: Optional[str], performance: Optional[Dict[str, Any]],
                                         context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """P(win | this strategy, this regime, this time bucket, this volatility,
    this extension, this relative strength) -- with an honest account of how much
    evidence actually stands behind it.

    Returns:
        proven                  -- enough evidence for the number to mean anything
        win_prob_pct            -- the point estimate (context-conditioned)
        calibrated_win_prob_pct -- the conservative (Wilson-bounded) figure the EV
                                   gate actually uses
        effective_trades        -- sample size backing the conditional estimate
        contributions           -- per-dimension detail, so the number is explainable
    """
    perf = _performance_for_strategy_side(strategy_id, performance)
    if not perf or int(perf.get('total_trades') or 0) <= 0:
        return {'proven': False, 'win_prob_pct': None, 'calibrated_win_prob_pct': None,
                'effective_trades': 0, 'contributions': [],
                'note': 'no recorded trades for this strategy yet -- judged on setup quality alone'}

    n_parent = int(perf.get('total_trades') or 0)
    wins_parent = int(perf.get('wins') or 0)
    p_parent = wins_parent / n_parent if n_parent else 0.0

    ctx = context or {}
    dimensions = [
        ('regime_time', 'by_regime_time',
         (f"{ctx.get('regime')}|{ctx.get('time_bucket')}" if ctx.get('regime') and ctx.get('time_bucket') else None)),
        ('regime', 'by_regime', ctx.get('regime')),
        ('time_bucket', 'by_time_bucket', ctx.get('time_bucket')),
        ('volatility', 'by_volatility', ctx.get('volatility_bucket')),
        ('extension', 'by_extension', ctx.get('extension_bucket')),
        ('relative_strength', 'by_relative_strength', ctx.get('relative_strength_bucket')),
    ]

    logit_parent = _logit(p_parent)
    contributions: List[Dict[str, Any]] = []
    deltas: List[float] = []
    effective_trades = float(n_parent)
    used_joint = False

    for label, perf_key, bucket in dimensions:
        if not bucket:
            continue
        # regime and time_bucket are already inside regime_time; counting them a
        # second time would double-weight the same trades as if they were
        # independent evidence, which is how a hierarchical model talks itself
        # into a 90% probability off one modest slice.
        if used_joint and label in ('regime', 'time_bucket'):
            continue
        sl = (perf.get(perf_key) or {}).get(str(bucket))
        if not sl or int(sl.get('trades') or 0) < MIN_SLICE_TRADES_FOR_CALIBRATION:
            continue
        n_s = float(sl['trades'])
        w_s = float(sl.get('wins') or 0)
        p_shrunk = (w_s + SHRINKAGE_PSEUDO_TRADES * p_parent) / (n_s + SHRINKAGE_PSEUDO_TRADES)
        delta = _logit(p_shrunk) - logit_parent
        deltas.append(delta)
        # The slice's contribution to effective sample size is discounted by how
        # much of it was pseudo-data rather than real trades.
        effective_trades += n_s * (n_s / (n_s + SHRINKAGE_PSEUDO_TRADES))
        if label == 'regime_time':
            used_joint = True
        contributions.append({
            'dimension': label, 'bucket': str(bucket), 'trades': int(n_s),
            'raw_win_rate_pct': sl.get('win_rate_pct'),
            'shrunk_win_rate_pct': round(p_shrunk * 100, 1),
            'log_odds_delta': round(delta, 3),
            'net_pnl': sl.get('net_pnl'),
        })

    # CORRELATION DAMPING. Adding log-odds across dimensions is only valid if the
    # dimensions carry INDEPENDENT evidence, and these plainly do not: a downtrend
    # at the open on a stretched stock in a high-volatility tape is largely one
    # phenomenon described five ways, and the same losing trades populate all five
    # buckets. Summing undamped, that produced conditional probabilities like 1.8%
    # and 81.3% off a strategy whose true rate is 50% -- trading one kind of
    # overconfidence (a global average pretending to be a probability) for a worse
    # one (a confident number derived from the same evidence counted five times).
    #
    # Each additional dimension is therefore discounted: the first contributes
    # fully, later ones progressively less. The total movement is then capped
    # outright, because no amount of context slicing should be able to turn a 50%
    # strategy into a 2% or a 95% one on sample sizes this small.
    k = len(deltas)
    if k:
        damping = 1.0 / (1.0 + CONTEXT_CORRELATION_DAMPING * (k - 1))
        total_delta = sum(deltas) * damping
        total_delta = max(-MAX_CONTEXT_LOG_ODDS_SHIFT, min(MAX_CONTEXT_LOG_ODDS_SHIFT, total_delta))
    else:
        total_delta = 0.0
    p_context = _inv_logit(logit_parent + total_delta)
    # Hard sanity bounds. A conditional estimate outside this range is claiming a
    # near-certainty that intraday evidence at these sample sizes cannot support.
    p_context = max(0.05, min(0.90, p_context))
    # Conservatism applied to the CONDITIONAL estimate: express it as an implied
    # win count on the effective sample, then take the Wilson lower bound of that.
    calibrated = _wilson_lower_bound(p_context * effective_trades, effective_trades)
    proven = n_parent >= MIN_TRADES_FOR_EDGE_DISPLAY

    if contributions:
        note = (f'P(win) conditioned on {len(contributions)} context dimension(s) '
                f'(correlation-damped x{round(1.0 / (1.0 + CONTEXT_CORRELATION_DAMPING * (k - 1)), 2)}): '
                f'{round(p_parent * 100, 1)}% unconditional -> {round(p_context * 100, 1)}% for this setup '
                f'-> {round(calibrated * 100, 1)}% after Wilson bound on ~{round(effective_trades)} effective trades. '
                + '; '.join(f"{c['dimension']}={c['bucket']} ({c['trades']} trades, {c['shrunk_win_rate_pct']}%)"
                            for c in contributions))
    else:
        note = (f'No context slice has {MIN_SLICE_TRADES_FOR_CALIBRATION}+ recorded trades yet, so this falls back to '
                f'the strategy-level rate: {round(p_parent * 100, 1)}% raw -> {round(calibrated * 100, 1)}% calibrated '
                f'on {n_parent} trades. NOT yet conditioned on regime/time/volatility.')

    return {'proven': proven, 'win_prob_pct': round(p_context * 100, 1),
            'calibrated_win_prob_pct': round(calibrated * 100, 1),
            'unconditional_win_prob_pct': round(p_parent * 100, 1),
            'effective_trades': round(effective_trades, 1),
            'context_conditioned': bool(contributions),
            'contributions': contributions, 'note': note}


def _conditional_payoff(perf: Dict[str, Any], context: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Average winner / average loser for this context, shrunk toward the
    strategy-level averages by the same rule the win probability uses.

    Payoff has to be conditioned too. A strategy whose win rate holds up in a
    high-volatility tape but whose losers double in size there has a genuinely
    negative EV in that slice, and a conditional probability paired with an
    unconditional payoff would report it as fine.
    """
    base_win = abs(float(perf.get('avg_winner_pct') or 0) or 0.0)
    base_loss = abs(float(perf.get('avg_loser_pct') or 0) or 0.0)
    ctx = context or {}
    candidates = [
        ('by_regime_time', (f"{ctx.get('regime')}|{ctx.get('time_bucket')}"
                            if ctx.get('regime') and ctx.get('time_bucket') else None)),
        ('by_volatility', ctx.get('volatility_bucket')),
        ('by_regime', ctx.get('regime')),
        ('by_time_bucket', ctx.get('time_bucket')),
    ]
    win, loss, used = base_win, base_loss, None
    for perf_key, bucket in candidates:
        if not bucket:
            continue
        sl = (perf.get(perf_key) or {}).get(str(bucket))
        if not sl or int(sl.get('trades') or 0) < MIN_SLICE_TRADES_FOR_CALIBRATION:
            continue
        n_s = float(sl['trades'])
        weight = n_s / (n_s + SHRINKAGE_PSEUDO_TRADES)
        sw = sl.get('avg_winner_pct')
        sll = sl.get('avg_loser_pct')
        if sw is not None:
            win = (1 - weight) * base_win + weight * abs(float(sw))
        if sll is not None:
            loss = (1 - weight) * base_loss + weight * abs(float(sll))
        used = f'{perf_key}:{bucket}'
        break  # most specific available slice wins; blending several would double-count
    return {'avg_winner_pct': round(win, 3), 'avg_loser_pct': round(loss, 3),
            'payoff_slice': used, 'base_avg_winner_pct': round(base_win, 3),
            'base_avg_loser_pct': round(base_loss, 3)}


def _performance_for_strategy_side(strategy_id: Optional[str], performance: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Return performance evidence without applying LONG statistics to SHORT trades."""
    if not strategy_id:
        return None
    perf = performance or {}
    sid = str(strategy_id)
    is_short = sid.lower().endswith('_short')
    base = sid[:-6] if is_short else sid
    if is_short:
        return perf.get(f'{base}:short'.lower()) or perf.get(f'{base}:SHORT') or None
    return perf.get(f'{base}:long'.lower()) or perf.get(base) or perf.get(sid)


def estimate_context_adjusted_ev(strategy_id: Optional[str], performance: Optional[Dict[str, Any]],
                                  context: Optional[Dict[str, Any]] = None,
                                  cost_pct_est: float = 0.0) -> Dict[str, Any]:
    """The number the EV gate actually decides on:

        expected_net_edge_pct = P(win | context) * avg_winner(context)
                              - P(loss | context) * avg_loser(context)

    Both terms conditional, both already net of round-trip costs (net_return_pct
    is net -- see calculate_net_trade_pnl -- which is why cost_pct_est defaults to
    0 here and is only used when a caller has a forward-looking reason to expect
    materially different costs than this strategy's own history, e.g. a much
    larger position).

    This REPLACES estimate_expected_net_edge_pct() as the gate's input. That
    function is kept intact below and still reports the strategy-level number,
    because "this strategy overall" remains the right thing to show on a
    dashboard -- it is just the wrong thing to make a per-trade decision on.
    """
    perf = _performance_for_strategy_side(strategy_id, performance)
    if not perf or int(perf.get('total_trades') or 0) < MIN_TRADES_FOR_EDGE_DISPLAY:
        n = int((perf or {}).get('total_trades') or 0)
        return {'proven': False, 'expected_net_edge_pct': None, 'calibrated_win_prob_pct': None,
                'context_conditioned': False,
                'note': (f'only {n} recorded trade(s) for this strategy (need {MIN_TRADES_FOR_EDGE_DISPLAY}) '
                         f'-- no EV opinion; judged on setup quality alone')}

    prob = estimate_calibrated_win_probability(strategy_id, performance, context)
    payoff = _conditional_payoff(perf, context)
    p_cal = float(prob['calibrated_win_prob_pct']) / 100.0
    p_raw = float(prob['win_prob_pct']) / 100.0
    avg_win = payoff['avg_winner_pct']
    avg_loss = payoff['avg_loser_pct']
    extra_cost = max(0.0, float(cost_pct_est or 0.0))
    ev_calibrated = p_cal * avg_win - (1 - p_cal) * avg_loss - extra_cost
    ev_point = p_raw * avg_win - (1 - p_raw) * avg_loss - extra_cost

    ctx = context or {}
    ctx_label = ', '.join(f'{k}={v}' for k, v in (
        ('regime', ctx.get('regime')), ('time', ctx.get('time_bucket')),
        ('vol', ctx.get('volatility_bucket')), ('ext', ctx.get('extension_bucket')),
        ('rs', ctx.get('relative_strength_bucket'))) if v) or 'no context available'

    return {
        'proven': True,
        'expected_net_edge_pct': round(ev_calibrated, 4),
        'expected_net_edge_pct_point': round(ev_point, 4),
        'calibrated_win_prob_pct': prob['calibrated_win_prob_pct'],
        'win_prob_pct': prob['win_prob_pct'],
        'unconditional_win_prob_pct': prob['unconditional_win_prob_pct'],
        'effective_trades': prob['effective_trades'],
        'context_conditioned': prob['context_conditioned'],
        'context': ctx_label,
        'payoff': payoff,
        'probability_contributions': prob['contributions'],
        'note': (f'[{ctx_label}] {prob["note"]} Conditional payoff: avg win +{avg_win}%, avg loss -{avg_loss}% '
                 f'(slice: {payoff["payoff_slice"] or "strategy-level"}) -> expected net edge '
                 f'{round(ev_calibrated, 3)}%/trade calibrated ({round(ev_point, 3)}% at the point estimate).'),
    }


def estimate_expected_net_edge_pct(strategy_id: Optional[str], performance: Optional[Dict[str, Any]],
                                    cost_pct_est: float = INTRADAY_EST_ROUNDTRIP_COST_PCT) -> Dict[str, Any]:
    """PRIORITY 2/3 (report-driven): replace 'confidence score' with an actual
    expected-value estimate for THIS strategy, using ONLY this run's own recorded,
    point-in-time trade history (never future data -- performance is always the
    trades_closed_before_day snapshot, same as the selector's own historical-edge
    term).

    BUGFIX (double-counted cost): avg_winner_pct/avg_loser_pct in `performance`
    come from compute_strategy_performance(), which builds them from each trade's
    net_return_pct -- already AFTER round-trip costs (see calculate_net_trade_pnl).
    An earlier version of this function then subtracted cost_pct_est a SECOND
    time, silently making every strategy's measured edge look worse than it
    actually was and skewing which strategies got penalized. Costs are now
    subtracted exactly once, inside the historical average itself; the formula
    below is a clean expected NET return per trade, nothing more.

        expected_net_edge_pct = P(win) * avg_winner_pct(net) - P(loss) * avg_loser_pct(net)

    cost_pct_est is kept as a parameter (currently unused in the formula) so a
    caller can still pass a forward-looking cost adjustment if round-trip costs
    are expected to differ materially from this strategy's own trading history
    (e.g. a much larger position size) -- but it is deliberately NOT subtracted
    by default, since doing so unconditionally is exactly the bug being fixed.

    Uses a Wilson-score LOWER BOUND on win rate (95% confidence), not the raw
    observed win rate, so a small or borderline-sized sample is judged
    conservatively -- this is the 'calibrated probability' the report asked
    for: proof it's actually that good, not just a point estimate that happens
    to look good on this many trades.

    Returns proven=False (no opinion) below MIN_TRADES_FOR_EDGE_DISPLAY, exactly
    like _historical_edge -- an unproven strategy competes on setup quality alone,
    it is never penalized for lacking a track record yet.
    """
    perf = _performance_for_strategy_side(strategy_id, performance)
    if not perf or int(perf.get('total_trades') or 0) < MIN_TRADES_FOR_EDGE_DISPLAY:
        return {'proven': False, 'expected_net_edge_pct': None, 'calibrated_win_prob_pct': None,
                'note': 'not enough recorded trades yet for this strategy -- judged on setup quality alone'}
    n = int(perf['total_trades'])
    wins = int(perf.get('wins') or 0)
    raw_win_rate = wins / n if n else 0.0
    # Wilson score interval lower bound, z=1.96 (95% confidence) -- a strategy with
    # 6/10 wins (60%) gets pulled down much harder than one with 180/300 wins (also
    # 60%), because the smaller sample genuinely deserves less trust. This is what
    # feeds the EV gate below, not the raw win rate.
    z = 1.96
    denom = 1 + z * z / n
    center = raw_win_rate + z * z / (2 * n)
    margin = z * ((raw_win_rate * (1 - raw_win_rate) / n + z * z / (4 * n * n)) ** 0.5)
    calibrated_win_rate = max(0.0, (center - margin) / denom)
    avg_win = float(perf.get('avg_winner_pct') or 0) or 0.0
    avg_loss = abs(float(perf.get('avg_loser_pct') or 0) or 0.0)
    ev_raw = raw_win_rate * avg_win - (1 - raw_win_rate) * avg_loss
    ev_calibrated = calibrated_win_rate * avg_win - (1 - calibrated_win_rate) * avg_loss
    return {'proven': True, 'expected_net_edge_pct': round(ev_calibrated, 4), 'expected_net_edge_pct_raw': round(ev_raw, 4),
            'calibrated_win_prob_pct': round(calibrated_win_rate * 100, 1), 'raw_win_prob_pct': round(raw_win_rate * 100, 1),
            'note': (f'Raw P(win)={round(raw_win_rate * 100, 1)}% on {n} trades -> Wilson-calibrated (conservative) '
                     f'P(win)={round(calibrated_win_rate * 100, 1)}%. avg win (net) +{avg_win}%, avg loss (net) -{avg_loss}% '
                     f'-> expected net edge {round(ev_calibrated, 3)}%/trade (calibrated), {round(ev_raw, 3)}%/trade (raw).')}


def estimate_context_penalty(strategy_id: Optional[str], regime: Optional[str], time_bucket: Optional[str],
                              performance: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """PRIORITY 7/8 (report-driven): 'a strategy shouldn't be judged globally' --
    checks THIS strategy's own recorded performance in THIS regime and THIS
    30-minute window (both already computed by compute_strategy_performance as
    by_regime/by_time_bucket) and returns a soft penalty only when a slice has
    enough trades (MIN_TRADES_FOR_CONTEXT_EVIDENCE) and negative net P&L.
    Positive slices never earn a boost here, by the same convention the rest of
    this codebase already uses for soft signals (downgrades only, never
    auto-boosts on a positive that might just be a lucky run).
    """
    perf = (performance or {}).get(strategy_id) if strategy_id else None
    if not perf:
        return {'penalty': 0.0, 'notes': []}
    notes: List[str] = []
    penalty = 0.0
    regime_slice = (perf.get('by_regime') or {}).get(regime) if regime else None
    if regime_slice and regime_slice.get('trades', 0) >= MIN_TRADES_FOR_CONTEXT_EVIDENCE and regime_slice.get('net_pnl', 0) < 0:
        penalty -= 6.0
        notes.append(f'This strategy has a negative net P&L (₹{regime_slice["net_pnl"]}) in the "{regime}" regime '
                      f'over {regime_slice["trades"]} recorded trade(s) so far this run.')
    time_slice = (perf.get('by_time_bucket') or {}).get(time_bucket) if time_bucket else None
    if time_slice and time_slice.get('trades', 0) >= MIN_TRADES_FOR_CONTEXT_EVIDENCE and time_slice.get('net_pnl', 0) < 0:
        penalty -= 6.0
        notes.append(f'This strategy has a negative net P&L (₹{time_slice["net_pnl"]}) in the {time_bucket} window '
                      f'over {time_slice["trades"]} recorded trade(s) so far this run.')
    return {'penalty': round(penalty, 1), 'notes': notes}


def estimate_extension_penalty(features: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """PRIORITY 1, first pass (report-driven): 'the move is already extended /
    resistance is nearby' -- a human trader's contextual read that the current
    engine has no equivalent of. Approximated cheaply from features every
    candidate already carries (extract_intraday_strategy_features): a stock
    sitting almost exactly at today's session high (pullback_from_high_pct
    near zero -- no room left before the nearest visible resistance) AND
    already up a large % on the day (change_pct) has less room to run and a
    higher reversal risk than the same setup earlier in a move.

    Deliberately narrow and conservative -- a single soft caution, not a
    block, and only fires when BOTH conditions hold together, so a genuine
    strong trend continuation (still climbing, still making new highs) is not
    penalized just for being at its high; it's the COMBINATION of "already a
    big move" and "no pullback room left" that this flags.

    UPDATED (report #7 -- real support/resistance): "sitting at the session
    high" is not the same thing as "sitting at real resistance" -- a stock can
    be near its own session high with a prior swing/day high still 2%+ away
    (genuine room to run), or be a modest 0.7% up but sitting right under a
    real prior-day/swing resistance level. When distance_to_resistance_pct is
    available (Live and Replay both -- see _attach_support_resistance_features), it
    overrides the session-high-only heuristic below; when it isn't (an
    unmapped/unfetchable ticker, or missing daily history), this falls back to
    the original session-high proxy exactly as before, so nothing regresses
    when the extra data simply isn't there.
    """
    f = features or {}
    change_pct = f.get('change_pct')
    pullback = f.get('pullback_from_high_pct')
    dist_resistance = f.get('distance_to_resistance_pct')
    dist_support = f.get('distance_to_support_pct')
    penalty = 0.0
    notes: List[str] = []
    if change_pct is not None and pullback is not None:
        try:
            change_pct_f = float(change_pct)
            pullback_f = float(pullback)
            if change_pct_f >= 2.5 and pullback_f <= 0.15:
                if dist_resistance is not None and float(dist_resistance) > 2.0:
                    notes.append(f"Near session high, but the nearest real resistance ({f.get('resistance_source')}) "
                                 f"is still {round(float(dist_resistance), 2)}% away -- not treating this as an extended, out-of-room move.")
                else:
                    penalty -= 4.0
                    notes.append(f'Already up {round(change_pct_f, 2)}% today and sitting within '
                                 f'{round(pullback_f, 2)}% of the session high -- little room left before the move needs to pause.')
        except Exception:
            pass
    if dist_resistance is not None:
        try:
            dist_resistance_f = float(dist_resistance)
            if dist_resistance_f <= 0.3:
                penalty -= 3.0
                notes.append(f"Within {round(dist_resistance_f, 2)}% of {f.get('resistance_source') or 'a prior swing/session high'} "
                             f"({f.get('resistance_level')}) -- real overhead supply, not just a round-number level.")
        except Exception:
            pass
    if dist_support is not None:
        try:
            dist_support_f = float(dist_support)
            change_pct_f2 = float(change_pct) if change_pct is not None else 0.0
            if dist_support_f <= 0.3 and change_pct_f2 <= 0.3:
                notes.append(f"Sitting right on {f.get('support_source') or 'a nearby support level'} "
                             f"({f.get('support_level')}, {round(dist_support_f, 2)}% above it) -- a defined base to enter from.")
        except Exception:
            pass
    return {'penalty': round(penalty, 2), 'notes': notes}


def build_candidate_ev_evaluator(performance: Optional[Dict[str, Any]], context: Optional[Dict[str, Any]],
                                  cost_pct_est: float = 0.0, session_trades: Optional[List[Dict[str, Any]]] = None,
                                  sim_now: Optional[datetime.datetime] = None,
                                  fast_adapt_enabled: bool = True) -> Any:
    """Build the callable strategies.select_strategy() uses to judge EACH of the 10
    strategies BEFORE it picks one -- the core of the report's #1 architectural fix.

    The selector calls this per strategy id and gets back that strategy's own
    context-adjusted expected net edge plus any same-day suspension, so negative-EV
    strategies are removed from the candidate pool instead of being allowed to win
    the ranking and then kill the whole stock at a post-selection gate.

    Also folds in the FAST same-day adaptation layer (report issue #5), because a
    strategy that has already lost twice this morning should stop being selectable
    immediately -- not tomorrow, when the daily evidence snapshot next refreshes.
    """
    session_trades = session_trades or []

    def _evaluate(strategy_id: str) -> Dict[str, Any]:
        ev = estimate_context_adjusted_ev(strategy_id, performance, context, cost_pct_est)
        out: Dict[str, Any] = {
            'proven': ev.get('proven'),
            'expected_net_edge_pct': ev.get('expected_net_edge_pct'),
            'calibrated_win_prob_pct': ev.get('calibrated_win_prob_pct'),
            'note': ev.get('note'),
            'context_conditioned': ev.get('context_conditioned'),
            'score_penalty': 0.0,
        }
        if fast_adapt_enabled and session_trades:
            fast = assess_session_adaptation(
                session_trades, strategy_id, now=sim_now,
                config={'loss_streak': INTRADAY_FAST_ADAPT_LOSS_STREAK,
                        'timeout_minutes': INTRADAY_FAST_ADAPT_TIMEOUT_MINUTES,
                        'max_losses_per_day': INTRADAY_FAST_ADAPT_MAX_LOSSES_PER_DAY})
            out['score_penalty'] = float(fast.get('score_penalty') or 0.0)
            out['risk_multiplier'] = float(fast.get('risk_multiplier') or 1.0)
            out['session_notes'] = fast.get('notes')
            if fast.get('block'):
                out['block'] = True
                out['block_reason'] = fast.get('block_reason')
        return out

    return _evaluate


def compute_evidence_based_score_adjustment(cand: Dict[str, Any], regime: Optional[str], entry_dt: Optional[datetime.datetime],
                                             performance: Optional[Dict[str, Any]],
                                             cost_pct_est: float = INTRADAY_EST_ROUNDTRIP_COST_PCT,
                                             ev_gate_enabled: bool = True,
                                             session_trades: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
    """Final, candidate-level evidence check applied AFTER the selector has already
    eliminated negative-EV strategies from the pool.

    WHAT CHANGED (report issues #1/#3): this used to be the ONLY place the EV gate
    lived, which is exactly why a rejected candidate died here instead of falling
    through to the next strategy. The gate now runs inside select_strategy() via
    build_candidate_ev_evaluator() above, so by the time execution reaches this
    function the selected strategy has already been judged positive-EV in context.
    This remains as a defence-in-depth backstop -- it re-checks the SELECTED
    strategy's context-adjusted EV using the candidate's final context (which can
    differ slightly from selection time once entry/target/stop are attached), and
    still hard-rejects on proven negative expectancy. It is no longer the thing
    standing between a good stock and a trade, because the fallthrough happened
    upstream.

    The EV it checks is context-adjusted (this strategy, this regime, this time
    bucket, this volatility, this extension, this relative strength), not the
    strategy's overall historical average -- that was report issue #3.

    ev_gate_enabled=False reproduces the old soft-penalty-only behaviour, used by
    the Blind Replay Benchmark's baseline leg.
    """
    strategy_id = cand.get('strategy_id')
    notes: List[str] = []
    adjustment = 0.0
    reject = False
    reject_reason = None

    time_bucket = _entry_time_bucket({'entry_time': entry_dt}) if entry_dt else None
    context = cand.get('setup_context') or build_setup_context(cand.get('strategy_features'), regime, entry_dt)
    if time_bucket and not context.get('time_bucket'):
        context = dict(context)
        context['time_bucket'] = time_bucket

    ev = estimate_context_adjusted_ev(strategy_id, performance, context, 0.0)
    if ev.get('proven') and ev.get('expected_net_edge_pct') is not None:
        min_ev = float(INTRADAY_MIN_EV_PCT_TO_TRADE)
        if ev_gate_enabled and ev['expected_net_edge_pct'] <= min_ev:
            reject = True
            reject_reason = f'negative_expected_net_edge: {ev["note"]}'
            notes.append(reject_reason)
        elif ev['expected_net_edge_pct'] < 0:
            # ev_gate_enabled=False path only (baseline leg of a blind benchmark) --
            # falls back to the old proportional caution instead of a hard block.
            ev_penalty = max(-20.0, ev['expected_net_edge_pct'] * 10.0)
            adjustment += ev_penalty
            notes.append(f'expected_net_edge: {ev["note"]} ({round(ev_penalty, 1)} pts, gate disabled)')
        else:
            notes.append(f'expected_net_edge: {ev["note"]} (passes EV gate)')

    ctx_pen = estimate_context_penalty(strategy_id, regime, time_bucket, performance)
    if ctx_pen['penalty']:
        adjustment += ctx_pen['penalty']
        notes.extend(ctx_pen['notes'])

    ext = estimate_extension_penalty(cand.get('strategy_features'))
    if ext['penalty']:
        adjustment += ext['penalty']
        notes.extend(ext['notes'])

    # FAST ADAPTATION (report issue #5), candidate level. The selector already
    # refuses to SELECT a suspended strategy; this catches a candidate that was
    # selected on an earlier tick's state and re-checks it against what has closed
    # since, so the reaction time to an intraday losing streak is one tick, not one
    # trading day.
    risk_multiplier = 1.0
    if INTRADAY_FAST_ADAPT_ENABLED and session_trades and strategy_id:
        fast = assess_session_adaptation(
            session_trades, strategy_id, now=entry_dt,
            config={'loss_streak': INTRADAY_FAST_ADAPT_LOSS_STREAK,
                    'timeout_minutes': INTRADAY_FAST_ADAPT_TIMEOUT_MINUTES,
                    'max_losses_per_day': INTRADAY_FAST_ADAPT_MAX_LOSSES_PER_DAY})
        risk_multiplier = float(fast.get('risk_multiplier') or 1.0)
        if fast.get('block') and ev_gate_enabled:
            reject = True
            reject_reason = f'fast_adaptation_suspended: {fast.get("block_reason")}'
            notes.append(reject_reason)
        elif fast.get('score_penalty'):
            adjustment += float(fast['score_penalty'])
            notes.extend(fast.get('notes') or [])

    return {'adjustment': round(max(-30.0, adjustment), 1), 'notes': notes, 'reject': reject, 'reject_reason': reject_reason,
            'expected_net_edge_pct': ev.get('expected_net_edge_pct'), 'calibrated_win_prob_pct': ev.get('calibrated_win_prob_pct'),
            'context_conditioned': ev.get('context_conditioned'), 'context': ev.get('context'),
            'risk_multiplier': risk_multiplier, 'ev_detail': ev}


# ---------------------------------------------------------------------------
# RISK BUDGET ALLOCATION (report: the risk-management issue)
# ---------------------------------------------------------------------------
# "The system should not have a philosophy of 'you may take 50 trades'. It should
# have 'you have a limited risk budget; spend it only on the best positive-EV
# opportunities.' That's much more important than merely lowering the number from
# 50 to 10."
#
# A trade quota treats every trade as costing the same thing, which is false: a
# trade risking 0.15% of capital and one risking 0.9% both consume exactly one
# unit of a count limit. What a trade actually costs the account is
# (entry - stop) * quantity. This class makes that the governing constraint.
#
# Three mechanisms, in order of importance:
#   1. DAILY BUDGET   -- a fixed pot of risk per session. When it is gone the day
#      is over, whether that took two trades or eight.
#   2. CONCURRENT CAP -- how much of that pot may be live simultaneously, so the
#      whole day cannot be lost in one correlated cluster.
#   3. SELECTIVITY    -- and this is the part that distinguishes a budget from a
#      quota. Once RESERVE_PCT of the budget is spent, the rest is released only
#      to candidates whose expected edge is materially better than what has
#      already been bought. Without it, a budget is still first-come-first-served
#      and the best setup of the day arrives to an empty account -- the same
#      failure as a trade cap, just denominated differently.

class IntradayRiskBudget:
    """Per-session risk ledger. Deliberately explicit about WHY a trade was
    refused, so a day that took two trades can prove it was selective rather than
    simply broken."""

    def __init__(self, capital: float, daily_budget_pct: float = None, concurrent_pct: float = None,
                 reserve_pct: float = None, enabled: bool = True):
        self.capital = float(capital or 0)
        self.enabled = bool(enabled) and self.capital > 0
        self.daily_budget_pct = float(daily_budget_pct if daily_budget_pct is not None else INTRADAY_DAILY_RISK_BUDGET_PCT)
        self.concurrent_pct = float(concurrent_pct if concurrent_pct is not None else INTRADAY_MAX_CONCURRENT_RISK_PCT)
        self.reserve_pct = float(reserve_pct if reserve_pct is not None else INTRADAY_RISK_BUDGET_RESERVE_PCT)
        self.daily_budget = self.capital * self.daily_budget_pct / 100.0
        self.concurrent_cap = self.capital * self.concurrent_pct / 100.0
        self.reset_day()

    def reset_day(self) -> None:
        """Intraday is flat overnight, so the budget resets with the session."""
        self.spent = 0.0            # risk committed today, including closed trades
        self.open_risk = 0.0        # risk currently live
        self.taken_ev: List[float] = []
        self.refused_budget = 0     # refused: daily budget exhausted
        self.refused_concurrent = 0 # refused: too much already at risk right now
        self.refused_selectivity = 0  # refused: not good enough for the reserve tranche
        self.trades_taken = 0
        self.risk_multiplier = 1.0  # set by the session de-risk layer

    @property
    def remaining(self) -> float:
        return max(0.0, self.daily_budget - self.spent)

    @property
    def spent_fraction(self) -> float:
        return (self.spent / self.daily_budget) if self.daily_budget > 0 else 0.0

    def _selectivity_bar(self) -> Optional[float]:
        """The expected-edge a late-in-the-day candidate must beat. None until the
        reserve tranche is reached, and None if nothing taken so far had a proven
        EV to compare against (there is no evidence to be selective WITH)."""
        if self.spent_fraction * 100.0 < self.reserve_pct:
            return None
        proven = [e for e in self.taken_ev if e is not None]
        if not proven:
            return None
        avg = sum(proven) / len(proven)
        if avg <= 0:
            return 0.0
        # 25% better than the average edge already bought today. Not arbitrary in
        # spirit: the reserve exists to be spent on something clearly superior, and
        # "clearly" has to mean a margin big enough not to be sampling noise.
        return round(avg * 1.25, 4)

    def check(self, risk_amount: float, expected_edge_pct: Optional[float] = None) -> Dict[str, Any]:
        """May this trade have this much risk? Returns ok plus a human-readable
        reason, which is what gets written to the decision log."""
        if not self.enabled:
            return {'ok': True, 'reason': None, 'risk_amount': risk_amount}
        risk_amount = max(0.0, float(risk_amount or 0))
        if risk_amount <= 0:
            return {'ok': True, 'reason': None, 'risk_amount': risk_amount}
        if self.risk_multiplier <= 0:
            return {'ok': False, 'reason': 'session_risk_halted: the session de-risk layer has stopped further entries today.',
                    'risk_amount': risk_amount}
        if risk_amount > self.remaining + 0.005:
            self.refused_budget += 1
            return {'ok': False,
                    'reason': (f'daily_risk_budget_exhausted: this trade risks Rs{risk_amount:,.0f} but only '
                               f'Rs{self.remaining:,.0f} of the Rs{self.daily_budget:,.0f} daily risk budget '
                               f'({self.daily_budget_pct}% of capital) is left after {self.trades_taken} trade(s).'),
                    'risk_amount': risk_amount}
        if self.open_risk + risk_amount > self.concurrent_cap + 0.005:
            self.refused_concurrent += 1
            return {'ok': False,
                    'reason': (f'concurrent_risk_cap: Rs{self.open_risk:,.0f} already at risk in open positions; '
                               f'adding Rs{risk_amount:,.0f} would exceed the Rs{self.concurrent_cap:,.0f} '
                               f'simultaneous-risk cap ({self.concurrent_pct}% of capital).'),
                    'risk_amount': risk_amount}
        bar = self._selectivity_bar()
        if bar is not None and bar > 0:
            if expected_edge_pct is None or float(expected_edge_pct) < bar:
                self.refused_selectivity += 1
                have = 'unproven' if expected_edge_pct is None else f'{round(float(expected_edge_pct), 4)}%'
                return {'ok': False,
                        'reason': (f'risk_budget_reserve: {round(self.spent_fraction * 100)}% of today\'s risk budget is '
                                   f'already committed, so the remainder is reserved for setups with an expected edge '
                                   f'above {bar}%/trade. This one is {have}.'),
                        'risk_amount': risk_amount}
        return {'ok': True, 'reason': None, 'risk_amount': risk_amount}

    def commit(self, risk_amount: float, expected_edge_pct: Optional[float] = None) -> None:
        if not self.enabled:
            return
        self.spent += max(0.0, float(risk_amount or 0))
        self.open_risk += max(0.0, float(risk_amount or 0))
        self.taken_ev.append(float(expected_edge_pct) if expected_edge_pct is not None else None)
        self.trades_taken += 1

    def release(self, risk_amount: float) -> None:
        """A closed position stops consuming CONCURRENT risk, but the risk it
        already took remains spent for the day -- you do not get the bullet back
        just because it missed."""
        if not self.enabled:
            return
        self.open_risk = max(0.0, self.open_risk - max(0.0, float(risk_amount or 0)))

    def summary(self) -> Dict[str, Any]:
        return {
            'enabled': self.enabled,
            'capital': round(self.capital, 2),
            'daily_budget_pct': self.daily_budget_pct,
            'daily_budget_amount': round(self.daily_budget, 2),
            'concurrent_cap_pct': self.concurrent_pct,
            'concurrent_cap_amount': round(self.concurrent_cap, 2),
            'reserve_pct': self.reserve_pct,
            'spent': round(self.spent, 2),
            'spent_pct_of_budget': round(self.spent_fraction * 100, 1),
            'open_risk': round(self.open_risk, 2),
            'trades_taken': self.trades_taken,
            'refused_daily_budget': self.refused_budget,
            'refused_concurrent_cap': self.refused_concurrent,
            'refused_selectivity': self.refused_selectivity,
        }


def compute_trade_risk_amount(entry_price: Any, stop_price: Any, quantity: Any) -> float:
    """What this specific trade can actually lose if the stop does its job. This is
    the unit the budget is denominated in -- not 'one trade'."""
    try:
        entry, stop, qty = float(entry_price or 0), float(stop_price or 0), int(quantity or 0)
    except (TypeError, ValueError):
        return 0.0
    if entry <= 0 or stop <= 0 or qty <= 0 or stop >= entry:
        return 0.0
    return round((entry - stop) * qty, 2)


def load_today_session_trades(market: Optional[str] = None, mode: Optional[str] = None) -> List[Dict[str, Any]]:
    """Trades that have already CLOSED today, for the fast same-day adaptation
    layer in Live/Paper (report issue #5).

    Replay keeps this ledger in memory as the simulated day runs; Live has no such
    loop, so it reloads from the database on every scan. That is what makes the
    live reaction time one scan tick rather than one trading day -- the same
    property the in-memory ledger gives replay.
    """
    conn = get_db_connection()
    if conn is None:
        return []
    try:
        day_start, day_end = get_intraday_today_bounds(market or 'IN')
        filters = ["status='CLOSED'", "horizon='intraday'", "COALESCE(closed_at, opened_at) >= %s",
                   "COALESCE(closed_at, opened_at) <= %s"]
        params: List[Any] = [day_start, day_end]
        if market and market != 'all':
            filters.append('market=%s')
            params.append(market)
        if mode:
            filters.append('mode=%s')
            params.append(mode)
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"""
                SELECT ticker, market, quantity, entry_price, exit_price, exit_reason,
                       net_pnl_amount, pnl_amount, pnl_pct, closed_at, opened_at, metadata_json
                FROM trade_positions
                WHERE {' AND '.join(filters)}
                ORDER BY COALESCE(closed_at, opened_at) ASC
                LIMIT 500
            """, params)
            raw = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"[WARN] session trade load failed: {e}")
        return []
    finally:
        conn.close()

    out: List[Dict[str, Any]] = []
    for r in raw:
        sid, sname = _strategy_from_metadata(r.get('metadata_json'))
        net = _safe_float(r.get('net_pnl_amount'))
        if net is None:
            net = _safe_float(r.get('pnl_amount'), 0) or 0.0
        out.append({
            'strategy_id': sid, 'strategy_name': sname,
            'net_pnl': float(net), 'net_return_pct': _safe_float(r.get('pnl_pct'), 0) or 0.0,
            'exit_time': r.get('closed_at') or r.get('opened_at'),
            'ticker': r.get('ticker'), 'exit_reason': r.get('exit_reason'),
        })
    return out


def compute_exit_calibration_suggestions(trades: List[Dict[str, Any]]) -> Dict[str, Any]:
    """PRIORITY 5 (report-driven): MFE/MAE-based trailing-stop calibration, per
    strategy -- measurement + suggestion ONLY. This does NOT change how any trade
    in this run was exited; it looks back at trades this run already closed and
    proposes strategy-specific trailing_stop_activation_pct/giveback_pct values a
    LATER run could opt into (via start_intraday_replay's exit_calibration_override),
    so the change can be validated on unseen days (ideally via the Blind Replay
    Benchmark) before anyone trusts it -- 'test the change, don't apply it live'
    is the existing convention this file already uses everywhere else
    (see strategies._recommendation_for), applied here too.

    Approximation, clearly labeled as such: true MFE/MAE-based calibration needs
    the full intrabar price path per trade (see report section 15); this only has
    each trade's peak_price/trough_price/entry/target, so it estimates
    - activation: how far (as % of the entry-to-target distance) a trade that
      DID trigger a trailing/giveback exit had typically already run before that
      exit -- i.e. where trailing protection should realistically start arming.
    - giveback: for those same trades, what fraction of their peak favorable
      move (relative to entry-to-target distance) was given back by the time
      they exited -- i.e. how tight the trail needs to be to have captured more
      of it.
    """
    by_strategy: Dict[str, List[Dict[str, Any]]] = {}
    for t in trades:
        sid = t.get('strategy_id')
        if sid:
            by_strategy.setdefault(sid, []).append(t)

    def _pctl(vals: List[float], p: float) -> Optional[float]:
        if not vals:
            return None
        s = sorted(vals)
        idx = min(len(s) - 1, max(0, int(round((p / 100.0) * (len(s) - 1)))))
        return s[idx]

    suggestions: Dict[str, Any] = {}
    GIVEBACK_EXIT_REASONS = {'TRAILING_STOP_GAVE_BACK_PROFIT', 'TRAILING_PROFIT_PROTECT'}
    for sid, group in by_strategy.items():
        giveback_trades = [t for t in group if t.get('exit_reason') in GIVEBACK_EXIT_REASONS
                            and t.get('peak_price') is not None and t.get('entry_price') and t.get('target_price')]
        if len(giveback_trades) < 15:
            suggestions[sid] = {'proven': False, 'trades_considered': len(giveback_trades),
                                 'note': f'only {len(giveback_trades)} trailing/giveback exit(s) recorded -- need 15+ before suggesting a calibration.'}
            continue
        activation_progress: List[float] = []
        giveback_fraction: List[float] = []
        for t in giveback_trades:
            entry, target, peak = float(t['entry_price']), float(t['target_price']), float(t['peak_price'])
            target_distance = target - entry
            if target_distance <= 0:
                continue
            peak_progress_pct = ((peak - entry) / target_distance) * 100
            activation_progress.append(peak_progress_pct)
            peak_move = peak - entry
            # final_move: price-equivalent of the trade's actual net % outcome, on the
            # same price scale as peak_move, so the two are directly comparable.
            final_move = (float(t.get('net_return_pct') or 0) / 100.0) * entry
            if peak_move > 0:
                giveback_fraction.append(max(0.0, min(1.0, (peak_move - final_move) / peak_move)) * 100)
        if not activation_progress or not giveback_fraction:
            suggestions[sid] = {'proven': False, 'trades_considered': len(giveback_trades),
                                 'note': 'insufficient price data on these trades to calibrate.'}
            continue
        suggested_activation = round(max(20.0, min(90.0, _pctl(activation_progress, 40) or 60.0)), 1)
        suggested_giveback = round(max(15.0, min(70.0, _pctl(giveback_fraction, 50) or 35.0)), 1)
        suggestions[sid] = {
            'proven': True, 'trades_considered': len(giveback_trades),
            'suggested_activation_pct': suggested_activation,
            'suggested_giveback_pct': suggested_giveback,
            'note': (f'From {len(giveback_trades)} trailing/giveback exit(s): trades that reversed typically had already '
                     f'reached ~{suggested_activation}% of the entry-to-target distance, and gave back a median '
                     f'~{suggested_giveback}% of their peak favorable move by exit. NOT applied automatically -- '
                     f'pass these as exit_calibration_override on a LATER, different replay run (ideally via the Blind '
                     f'Replay Benchmark) to validate before trusting them.'),
        }
    return suggestions


# ---------------------------------------------------------------------------
# EXIT CALIBRATION: MEASURE -> VALIDATE -> PROMOTE -> APPLY (report issue #7)
# ---------------------------------------------------------------------------
# compute_exit_calibration_suggestions() above measures and suggests, and that is
# where it stopped: "measurement + suggestion only". So the 142 give-back exits
# were diagnosed and then nothing about the exit rules changed. Diagnosis without
# deployment is not a fix.
#
# The missing pipeline, now implemented end to end:
#
#     historical MFE/MAE  (compute_exit_calibration_suggestions)
#            v
#     candidate trailing rules
#            v
#     blind / out-of-sample replay      (validate_exit_calibration_out_of_sample)
#            v
#     validated winner                  (promote_exit_calibration)
#            v
#     APPLIED                           (load_active_exit_calibration ->
#                                        evaluate_profit_protection_exit)
#
# The safety property is preserved: a calibration still never takes effect
# because it looked good on the run that produced it. It takes effect because it
# was measured on one set of days and then beat the baseline on DIFFERENT days by
# at least INTRADAY_EXIT_CALIBRATION_MIN_PF_GAIN. What changed is that clearing
# that bar now actually promotes it instead of printing a suggestion.

def load_active_exit_calibration() -> Dict[str, Any]:
    """Promoted, validated per-strategy trailing rules -- the ones allowed to
    change real exits. Returns {} when nothing has been validated yet, which
    means every strategy keeps the global default, exactly as before."""
    if not INTRADAY_EXIT_CALIBRATION_AUTO_APPLY:
        return {}
    conn = get_db_connection()
    if conn is None:
        return {}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT strategy_id, activation_pct, giveback_pct, trades_considered,
                       baseline_profit_factor, validated_profit_factor, evidence_note, promoted_at
                FROM strategy_exit_calibration WHERE status = 'validated'
            """)
            rows = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"[WARN] exit calibration load failed: {e}")
        return {}
    finally:
        conn.close()
    out: Dict[str, Any] = {}
    for r in rows:
        out[r['strategy_id']] = {
            'proven': True,
            'suggested_activation_pct': float(r['activation_pct']),
            'suggested_giveback_pct': float(r['giveback_pct']),
            'trades_considered': r.get('trades_considered'),
            'validated': True,
            'baseline_profit_factor': _safe_float(r.get('baseline_profit_factor')),
            'validated_profit_factor': _safe_float(r.get('validated_profit_factor')),
            'note': r.get('evidence_note'),
            'promoted_at': r.get('promoted_at'),
        }
    return out


def promote_exit_calibration(calibration: Dict[str, Any], baseline_run_id: Optional[int] = None,
                             validation_run_id: Optional[int] = None,
                             baseline_pf: Optional[float] = None, validated_pf: Optional[float] = None,
                             note: Optional[str] = None) -> Dict[str, Any]:
    """Write a validated calibration into the table the exit engine reads.

    Called only by validate_exit_calibration_out_of_sample() below, or explicitly
    by an operator via the API. Never called from the run that measured the
    calibration -- that would be exactly the in-sample self-approval this whole
    structure exists to prevent.
    """
    clean = {sid: v for sid, v in (calibration or {}).items()
             if isinstance(v, dict) and v.get('suggested_activation_pct') and v.get('suggested_giveback_pct')}
    if not clean:
        return {'ok': False, 'error': 'No usable calibration entries to promote.'}
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    promoted: List[str] = []
    try:
        with conn, conn.cursor() as cur:
            for sid, v in clean.items():
                cur.execute("""
                    INSERT INTO strategy_exit_calibration
                        (strategy_id, activation_pct, giveback_pct, status, trades_considered,
                         baseline_run_id, validation_run_id, baseline_profit_factor,
                         validated_profit_factor, evidence_note, promoted_at)
                    VALUES (%s,%s,%s,'validated',%s,%s,%s,%s,%s,%s,NOW())
                    ON CONFLICT (strategy_id) DO UPDATE SET
                        activation_pct = EXCLUDED.activation_pct,
                        giveback_pct = EXCLUDED.giveback_pct,
                        status = 'validated',
                        trades_considered = EXCLUDED.trades_considered,
                        baseline_run_id = EXCLUDED.baseline_run_id,
                        validation_run_id = EXCLUDED.validation_run_id,
                        baseline_profit_factor = EXCLUDED.baseline_profit_factor,
                        validated_profit_factor = EXCLUDED.validated_profit_factor,
                        evidence_note = EXCLUDED.evidence_note,
                        promoted_at = NOW()
                """, (sid, float(v['suggested_activation_pct']), float(v['suggested_giveback_pct']),
                      v.get('trades_considered'), baseline_run_id, validation_run_id,
                      baseline_pf, validated_pf,
                      note or v.get('note')))
                promoted.append(sid)
    except Exception as e:
        return {'ok': False, 'error': f'Promotion failed: {e}'}
    finally:
        conn.close()
    return {'ok': True, 'promoted': promoted,
            'message': (f'{len(promoted)} strategy exit calibration(s) promoted and now APPLIED to live/paper/replay '
                        f'exits: {", ".join(promoted)}.')}


def validate_exit_calibration_out_of_sample(baseline_run_id: int, validation_run_id: int,
                                            auto_promote: bool = True) -> Dict[str, Any]:
    """Compare a run that used a candidate calibration against a baseline run on
    the SAME unseen days, and promote the calibration only if it actually won.

    baseline_run_id: a completed run on the test days WITHOUT the calibration.
    validation_run_id: a completed run on the SAME days WITH it applied (started
        via start_intraday_replay(exit_calibration_override=...)).

    Refuses to promote when the two runs did not cover the same days, because a
    calibration that "won" on different days has not been validated against
    anything.
    """
    baseline = intraday_replay_status(baseline_run_id)
    validation = intraday_replay_status(validation_run_id)
    if not baseline.get('ok'):
        return {'ok': False, 'error': f'baseline_run_id {baseline_run_id}: {baseline.get("error")}'}
    if not validation.get('ok'):
        return {'ok': False, 'error': f'validation_run_id {validation_run_id}: {validation.get("error")}'}
    if baseline.get('status') not in ('completed', 'stopped') or validation.get('status') not in ('completed', 'stopped'):
        return {'ok': False, 'error': 'Both runs must have finished before a calibration can be validated.'}

    b_dates = set(baseline.get('selected_dates') or [])
    v_dates = set(validation.get('selected_dates') or [])
    if not b_dates or b_dates != v_dates:
        return {'ok': False, 'error': ('The two runs did not cover the same trading days, so this is not an '
                                       'out-of-sample comparison of the calibration -- it is a comparison of two '
                                       'different windows. Re-run both legs on identical dates.')}

    calibration = ((validation.get('settings_snapshot') or {}).get('intraday_settings') or {}).get('_strategy_exit_calibration')
    if not calibration:
        calibration = (validation.get('stats') or {}).get('exit_calibration_used')
    if not calibration:
        return {'ok': False, 'error': ('The validation run did not actually use an exit calibration override, so there '
                                       'is nothing to validate. Start it with exit_calibration_override set.')}

    b_stats, v_stats = baseline.get('stats') or {}, validation.get('stats') or {}
    b_pf, v_pf = _safe_float(b_stats.get('profit_factor')), _safe_float(v_stats.get('profit_factor'))
    b_net, v_net = _safe_float(b_stats.get('net_pnl')), _safe_float(v_stats.get('net_pnl'))
    min_gain = float(INTRADAY_EXIT_CALIBRATION_MIN_PF_GAIN)

    if b_pf is None or v_pf is None:
        return {'ok': True, 'validated': False, 'promoted': False,
                'verdict': 'insufficient_data',
                'reason': 'One or both runs produced no profit factor (too few trades) -- cannot validate.',
                'baseline_profit_factor': b_pf, 'validated_profit_factor': v_pf}

    gain = round(v_pf - b_pf, 4)
    validated = gain >= min_gain and (v_net is None or b_net is None or v_net >= b_net)
    result = {
        'ok': True, 'validated': validated, 'promoted': False,
        'baseline_run_id': baseline_run_id, 'validation_run_id': validation_run_id,
        'days_tested': sorted(v_dates),
        'baseline_profit_factor': b_pf, 'validated_profit_factor': v_pf,
        'profit_factor_gain': gain, 'min_gain_required': min_gain,
        'baseline_net_pnl': b_net, 'validated_net_pnl': v_net,
        'calibration': calibration,
    }
    if not validated:
        result['verdict'] = 'rejected'
        result['reason'] = (f'Profit factor moved {b_pf} -> {v_pf} ({gain:+}), which does not clear the required '
                            f'+{min_gain} improvement on unseen days. Calibration NOT applied -- the existing global '
                            f'trailing rule stays in force.')
        return result
    result['verdict'] = 'validated'
    note = (f'Validated out-of-sample on {len(v_dates)} unseen day(s): profit factor {b_pf} -> {v_pf} ({gain:+}), '
            f'net P&L {b_net} -> {v_net}. Baseline run #{baseline_run_id}, validation run #{validation_run_id}.')
    result['reason'] = note
    if auto_promote:
        promo = promote_exit_calibration(calibration, baseline_run_id, validation_run_id, b_pf, v_pf, note)
        result['promoted'] = bool(promo.get('ok'))
        result['promotion'] = promo
    return result


def _run_intraday_replay_worker(run_id: int, market: str, trading_days: List[datetime.date], universe: List[str],
                                 settings: Dict[str, Any], trading_settings: Dict[str, Any],
                                 stop_event: threading.Event, pause_event: threading.Event,
                                 use_learning: bool = True) -> None:
    """The actual replay loop, run on a background thread. Structured as two
    concerns per tick, matching the live architecture on purpose (item: entry
    scanner vs position guard must stay separate so the scanner never
    interferes with an open position's own exit management):
        1. POSITION GUARD -- every open position is checked against this
           tick's bar first (intrabar SL/target conflict, then the live exit
           function with sim_now set to this tick).
        2. ENTRY SCANNER -- only after the guard runs, the universe is
           rescanned and new entries are opened into any free slots.

    use_learning=False runs the RAW/BASELINE mode (strict_learning_review and
    per-stock trade-history adjustments switched off entirely) instead of the
    default POINT-IN-TIME LEARNED mode, which only counts trades that had
    actually closed before the simulated day being replayed.
    """
    cfg = get_intraday_replay_config()
    interval = cfg['interval']
    event_counter = [0]
    # RESEARCH MODE POSITION LIMIT.
    # Replay defaults to UNLIMITED concurrent positions (max_positions is None)
    # because a portfolio cap during research throws away signals the strategy
    # genuinely produced, and does it with a time bias: whatever was found first
    # in the day fills the slots, so every later signal -- including the better
    # ones -- is discarded before it can be measured. The run's resolved limit is
    # carried on the settings snapshot ('replay_max_open_positions', already
    # resolved by start_intraday_replay), so what a past run enforced is recorded
    # on the run row itself and never re-derived from current settings.
    max_positions = settings.get('replay_max_open_positions')
    if isinstance(max_positions, str) or max_positions == 0:
        max_positions = resolve_position_limit(max_positions, None)
    max_positions = max_positions if isinstance(max_positions, int) and max_positions > 0 else None
    positions_label = position_limit_label(max_positions)
    max_trades_per_day = int(settings.get('max_trades_per_day') or INTRADAY_MAX_TRADES_PER_DAY)
    # CAPITAL GUARD.
    # Unlimited positions only makes sense as research if MONEY is still finite --
    # otherwise the simulation quietly assumes infinite funds, every signal gets
    # sized off the full capital, and "amount invested" becomes a number you could
    # never actually have deployed. With the guard on, positions are unlimited in
    # COUNT but the sum of their entry values can never exceed the run's capital,
    # so the P&L breakdown answers the real question: "starting with this much on
    # that day, what happened?"
    replay_capital = float(settings.get('simulation_capital_inr') or TRADING_DEFAULT_CAPITAL_INR)
    capital_guard_enabled = bool(settings.get('replay_enforce_capital', True))
    capital_deployed = 0.0          # value of currently-open positions, at entry price
    peak_capital_deployed = 0.0     # high-water mark across the whole run
    capital_blocked_signals = 0     # signals refused purely because cash was fully deployed
    cooldown_minutes = float(INTRADAY_TICKER_COOLDOWN_MINUTES)
    # Explicit resolved-config logging (report of updates, Priority 1): print AND persist
    # the actual limit this run is using so "what limit did this run actually enforce" is
    # never a guessing game between UI/DB/engine -- this print line and the run message
    # below are the single source of truth for this specific run.
    print(f"[INTRADAY REPLAY CONFIG] run_id={run_id} max_trades_per_day={max_trades_per_day} "
           f"max_open_positions={positions_label} capital={replay_capital:.0f} capital_guard={'on' if capital_guard_enabled else 'off'}")
    try:
        _replay_update_run_row(run_id, status='running',
                                message=f'Downloading historical data for the selected universe/days... (resolved config: max_trades_per_day={max_trades_per_day}, max_open_positions={positions_label})')
        start_date, end_date = trading_days[0], trading_days[-1]
        history = download_replay_universe_history(universe, start_date, end_date, interval, market=market)
        index_history = download_replay_index_history(market, start_date, end_date, interval)
        # REPLAY PARITY FIX: sector-relative-strength and support/resistance context,
        # downloaded once here (never per-tick, never live) so Replay evaluates the
        # same intelligence Live does -- see download_replay_sector_index_history /
        # download_replay_universe_daily_history docstrings for why these are
        # separate, small downloads rather than reusing the intraday history above.
        settings['_replay_sector_index_history'] = download_replay_sector_index_history(market, start_date, end_date, interval)
        settings['_replay_daily_history'] = download_replay_universe_daily_history(universe, start_date, market=market)

        open_positions: Dict[str, Dict[str, Any]] = {}
        last_closed_at: Dict[str, Tuple[datetime.datetime, float]] = {}  # ticker -> (sim_time, net_return_pct)
        completed_trades: List[Dict[str, Any]] = []
        # Training/test split (report issue #4). training_days are replayed first,
        # build evidence, and are then EXCLUDED from the reported result -- their
        # trades live in training_trades, not completed_trades, so a run's headline
        # statistics describe unseen days only.
        training_day_set = set(settings.get('_training_days') or [])
        evidence_mode = str(settings.get('evidence_mode') or 'frozen').lower()
        training_trades: List[Dict[str, Any]] = []
        frozen_evidence: Dict[str, Any] = {}
        evidence_frozen_at: Optional[str] = None
        session_trades: List[Dict[str, Any]] = []
        # RISK BUDGET (replaces the trade quota as the governing entry control).
        risk_budget = IntradayRiskBudget(
            capital=float(settings.get('simulation_capital_inr') or TRADING_DEFAULT_CAPITAL_INR),
            daily_budget_pct=settings.get('daily_risk_budget_pct'),
            concurrent_pct=settings.get('max_concurrent_risk_pct'),
            reserve_pct=settings.get('risk_budget_reserve_pct'),
            enabled=bool(settings.get('risk_budget_enabled', INTRADAY_RISK_BUDGET_ENABLED)) and use_learning)
        risk_budget_refusals = 0
        # Rough total tick count across all days, for the progress bar.
        any_ticker_days = next((history[t] for t in universe if history.get(t)), {})
        ticks_per_day_guess = max(1, len(next(iter(any_ticker_days.values()), [])) if any_ticker_days else 75)
        total_ticks_all_days = max(1, ticks_per_day_guess * len(trading_days))
        ticks_done = 0
        # Fix 3 (selected-day completeness): a day the user selected can end up with no
        # usable bars for the whole universe (market holiday, delisting gap, provider
        # outage, etc.) and previously was silently skipped -- the run still finished with
        # status 'completed' as if every selected day had actually been replayed. Track
        # which days were skipped so the final message/stats say so honestly.
        days_with_data: List[str] = []
        days_skipped_no_data: List[str] = []
        days_skipped_holiday: List[str] = []
        # Fix 6 (eligibility funnel): rejection reasons aggregated across the ENTIRE run.
        run_rejection_reason_counts: Dict[str, int] = {}
        # Run-level accumulation of the per-tick strategy_audit dicts returned by
        # replay_scan_universe -- see the audit-trail comment there for why this exists.
        run_strategy_audit: Dict[str, Dict[str, Any]] = {}
        total_scan_cycles = 0

        for day in trading_days:
            if stop_event.is_set():
                break
            tz = ZoneInfo('Asia/Kolkata')
            # Build the day's combined timestamp axis from whichever ticker has the
            # most bars today (bars can differ slightly ticker-to-ticker on data gaps).
            day_frames = {t: history[t][day] for t in universe if history.get(t, {}).get(day) is not None and not history[t][day].empty}
            if not day_frames:
                # Distinguish a genuine data outage from a day the exchange simply wasn't
                # open (weekend, or a known holiday from get_market_holidays -- e.g. Sep 14,
                # 2026 was Ganesh Chaturthi). Previously both cases were reported identically
                # as "no historical data available", which reads as a provider/outage problem
                # even when the market was correctly closed that day.
                if not is_trading_day(market, day):
                    days_skipped_holiday.append(day.isoformat())
                else:
                    days_skipped_no_data.append(day.isoformat())
                continue
            days_with_data.append(day.isoformat())
            axis_ticker = max(day_frames, key=lambda t: len(day_frames[t]))
            timestamps = list(day_frames[axis_ticker].index)
            trades_opened_today = 0
            # Intraday is flat overnight, so deployed capital is re-derived from whatever
            # is actually open at the start of each day rather than carried forward. This
            # keeps the running figure exact even if a day ended through an unusual path
            # (stop event mid-day, a ticker whose frame vanished), instead of letting a
            # small drift accumulate across a multi-day run.
            capital_deployed = sum(float(p.get('position_value') or 0) for p in open_positions.values())
            # Market/sector context and learning memory are point-in-time: recomputed
            # fresh for EACH simulated day using only data available before that day
            # (see build_historical_market_context_for_day and the before_ts filter
            # on get_closed_trade_history_strength) -- a run covering 02/05/08 Sep
            # must not let 08 Sep's outcomes leak into the 02 Sep decision.
            market_context = build_historical_market_context_for_day(index_history, day)
            index_day_df = (index_history.get('trend_intraday_by_day') or {}).get(day)
            trade_memory = {}
            day_start_utc = datetime.datetime.combine(day, datetime.time(0, 0))
            if use_learning:
                trade_memory = get_closed_trade_history_strength(market, 'intraday', engine='intraday', before_ts=day_start_utc)
            # BUGFIX (dead historical-edge signal in Replay): settings['_strategy_performance']
            # was NEVER set anywhere in this worker -- Live's scan_intraday_candidates() sets
            # it fresh from the DB every scan, but Replay has no equivalent call, so the
            # selector's 20%-weighted historical-edge term was silently NEUTRAL_PRIOR_EDGE
            # (50, "unproven") on every single tick of every run, regardless of how many
            # trades the replay itself had already accumulated. This was not lookahead
            # leakage (nothing from the future was used) -- it was simply dead, so a
            # multi-day/multi-week replay never got to demonstrate a strategy earning (or
            # losing) real selector weight from its own track record.
            # Point-in-time fix, same pattern as trade_memory above: recomputed once per
            # simulated day, from only THIS RUN's own trades that had actually closed
            # before this simulated day started -- never the DB's real historical trades
            # (which belong to Live/Paper, not this replay) and never a later day's outcome
            # inside the same run.
            # ---------------------------------------------------------------
            # TRAINING WINDOW -> FROZEN EVIDENCE -> BLIND TEST (report issue #4)
            # ---------------------------------------------------------------
            # The cold-start problem: with point-in-time evidence and no prior
            # window, day 1 of a run has ZERO recorded trades, so the hard EV gate
            # does nothing at all on it, day 2 sees only day 1, and so on. The run
            # spends its early days learning what it should have known before it
            # started, and those days still count in the reported result.
            #
            # The research structure the report asks for:
            #     historical training period -> freeze evidence -> blind test period
            # is now what a run does when training days are supplied. Training days
            # build evidence and are EXCLUDED from the reported statistics; test
            # days are scored against that evidence.
            #
            # evidence_mode:
            #   'frozen'    (default) -- test days see the training evidence ONLY.
            #               A genuinely blind test: the model does not move while
            #               it is being measured, so the result is attributable to
            #               the frozen model rather than to mid-test adaptation.
            #   'expanding' -- test days see training evidence PLUS test trades
            #               that closed on earlier test days. Still leak-free, and
            #               closer to how the thing would actually run live.
            phase = 'training' if day in training_day_set else 'test'
            if phase == 'test' and training_day_set and not evidence_frozen_at:
                # THE FREEZE. Everything the training window learned is snapshotted
                # here, once, and the test window is then measured against it.
                frozen_evidence = compute_strategy_performance(training_trades)
                evidence_frozen_at = day.isoformat()
                _replay_log_event(run_id, event_counter, day, '00:00', None, 'evidence_frozen', None,
                                   f'Training window closed: {len(training_trades)} trade(s) over '
                                   f'{len(training_day_set)} day(s) frozen as the evidence base for the blind test '
                                   f'window (mode={evidence_mode}).')
                # EXIT CALIBRATION EXPERIMENT (report critical issue #2 fix). This
                # derives a FRESH suggestion from THIS run's own training window and
                # applies it to THIS run's own test window -- which has NOT cleared
                # validate_exit_calibration_out_of_sample's independent out-of-sample
                # PF bar (that requires a SEPARATE baseline run on the same days; a
                # training-window sample-size check is not that). Previously this ran
                # whenever auto_apply_exit_calibration was left at its True default --
                # i.e. on every ordinary replay -- silently turning every "clean
                # baseline" run into an unvalidated calibration experiment. It now
                # requires the operator to explicitly opt into
                # exit_calibration_experimental_unvalidated, and marks the run/stats
                # unmistakably as an experiment when it fires (see below and the
                # 'exit_calibration_used' stats block near this run's completion).
                # The clean default (auto_apply_exit_calibration=True) instead applies
                # an already-validated calibration loaded once at run start -- see
                # start_intraday_replay.
                if bool(settings.get('exit_calibration_experimental_unvalidated', False)) and training_trades:
                    try:
                        suggestions = compute_exit_calibration_suggestions(training_trades)
                        proven_calib = {sid: v for sid, v in suggestions.items()
                                        if isinstance(v, dict) and v.get('proven')}
                        if proven_calib:
                            settings['_strategy_exit_calibration'] = proven_calib
                            settings['_exit_calibration_is_experimental'] = True
                            trading_settings = dict(trading_settings)
                            trading_settings['_strategy_exit_calibration'] = proven_calib
                            _replay_log_event(run_id, event_counter, day, '00:00', None, 'exit_calibration_applied', None,
                                               f'EXPERIMENTAL / UNVALIDATED: trailing-stop calibration derived from '
                                               f"THIS run's own training window, applied to THIS run's own test window "
                                               f'for {len(proven_calib)} strategy(ies). This has NOT cleared the '
                                               f'independent out-of-sample validation bar -- do not read this run as a '
                                               f'clean profitability baseline: '
                                               + '; '.join(f'{sid} activation {v["suggested_activation_pct"]}% / giveback '
                                                           f'{v["suggested_giveback_pct"]}%' for sid, v in proven_calib.items()))
                    except Exception as _cal_err:
                        print(f'[WARN] training-window exit calibration experiment failed: {_cal_err}')
            if phase == 'training' or evidence_mode == 'expanding':
                trades_closed_before_day = [t for t in completed_trades if t.get('exit_time') and t['exit_time'] < day_start_utc]
                settings['_strategy_performance'] = compute_strategy_performance(trades_closed_before_day)
            else:
                # Frozen: evidence is exactly what the training window produced and
                # does not move for the duration of the test window.
                settings['_strategy_performance'] = frozen_evidence or {}
            settings['_phase'] = phase
            # FAST ADAPTATION LEDGER (report issue #5). Recomputed continuously as
            # the simulated day runs -- NOT once per day like the evidence snapshot
            # above. This is the layer that reacts to 09:30/09:35/09:40 losses
            # inside the same session instead of waiting for tomorrow's snapshot.
            # Intraday is flat overnight, so it resets with the session.
            session_trades: List[Dict[str, Any]] = []
            settings['_session_trades'] = session_trades
            settings['fast_adapt_enabled'] = INTRADAY_FAST_ADAPT_ENABLED
            risk_budget.reset_day()
            for tick_idx, ts in enumerate(timestamps):
                if stop_event.is_set():
                    break
                while pause_event.is_set() and not stop_event.is_set():
                    _replay_update_run_row(run_id, status='paused', sim_date=day.isoformat(), current_sim_time=ts.strftime('%H:%M'))
                    time.sleep(1)
                ticks_done += 1
                sim_now = ts if ts.tzinfo else ts.tz_localize(tz)
                if index_day_df is not None:
                    idx_pos = index_day_df.index.get_indexer([ts], method='pad')
                    if len(idx_pos) and idx_pos[0] >= 0:
                        market_context['intraday_index'] = build_historical_intraday_index_context(index_history.get('trend_ticker'), index_day_df, idx_pos[0])
                # REPLAY PARITY FIX: sector-relative-strength context, computed ONCE
                # per tick for every sector (not per ticker) -- exactly the same
                # point-in-time pattern as the NIFTY index just above. Consumed by
                # _attach_sector_context via market_context['sector_contexts'].
                sector_index_history = settings.get('_replay_sector_index_history')
                if sector_index_history:
                    sector_ctxs: Dict[str, Any] = {}
                    for _sector, _entry in sector_index_history.items():
                        _sector_day_df = (_entry.get('intraday_by_day') or {}).get(day)
                        if _sector_day_df is None or _sector_day_df.empty:
                            continue
                        _idx_pos = _sector_day_df.index.get_indexer([ts], method='pad')
                        if len(_idx_pos) and _idx_pos[0] >= 0:
                            sector_ctxs[_sector] = build_historical_sector_context(sector_index_history, _sector, day, _idx_pos[0])
                    market_context['sector_contexts'] = sector_ctxs

                # --- 1. POSITION GUARD -------------------------------------------------
                for ticker in list(open_positions.keys()):
                    pos = open_positions[ticker]
                    df = day_frames.get(ticker)
                    if df is None or ts not in df.index:
                        continue
                    bar_pos = df.index.get_loc(ts)
                    bar = df.iloc[bar_pos]
                    conflict_reason, intrabar_resolution = _resolve_intrabar_conflict(bar, pos['target_price'], pos['stop_price'])
                    exit_reason = None
                    exit_price = None
                    # MAE/MFE FIX: previously, when the conflict-resolution branch fired (this
                    # bar's high/low crossed the stop and/or target), peak_price/trough_price
                    # were left exactly where the PREVIOUS tick's evaluate_profit_protection_exit
                    # call last set them -- so the exit bar's own extremes (often the most
                    # extreme prices of the whole trade, since that's what triggered the exit)
                    # never made it into the MFE/MAE numbers. Update them from this bar's actual
                    # High/Low here too, unconditionally, before either exit path below.
                    try:
                        bar_high, bar_low = float(bar.get('High')), float(bar.get('Low'))
                        pos['peak_price'] = max(float(pos.get('peak_price') or pos['entry_price']), bar_high)
                        pos['trough_price'] = min(float(pos.get('trough_price') or pos['entry_price']), bar_low)
                    except Exception:
                        pass
                    if conflict_reason:
                        exit_reason = conflict_reason
                        exit_price = pos['target_price'] if conflict_reason == 'TARGET_HIT' else pos['stop_price']
                    else:
                        snap = build_intraday_backtest_snapshot(ticker, df, bar_pos)
                        if snap.get('ok') and snap.get('last'):
                            try:
                                reason, meta = evaluate_profit_protection_exit(pos, trading_settings, snap, sim_now=sim_now)
                            except Exception:
                                reason, meta = None, {'last': snap['last']}
                            pos['peak_price'] = max(float(pos.get('peak_price') or pos['entry_price']), float(meta.get('peak', pos['peak_price'])))
                            pos['trough_price'] = min(float(pos.get('trough_price') or pos['entry_price']), float(meta.get('trough', pos['trough_price'])))
                            pos['trailing_stop_price'] = meta.get('trailing_stop_price', pos['trailing_stop_price'])
                            if reason:
                                exit_reason = reason
                                exit_price = meta.get('last') or snap['last']
                        # Belt-and-suspenders: evaluate_profit_protection_exit's own
                        # INTRADAY_FORCE_EXIT_BEFORE_CLOSE check (now clock-aware via
                        # sim_now) already covers the close window using the real
                        # session schedule. This only catches the literal final bar
                        # of the day in case that check somehow didn't fire (e.g. a
                        # short/partial data day whose last bar is earlier than the
                        # configured cutoff).
                        if not exit_reason and bar_pos == len(df) - 1:
                            exit_reason = 'INTRADAY_FORCE_EXIT_BEFORE_CLOSE'
                            exit_price = float(bar['Close'])
                    if exit_reason:
                        pnl = calculate_net_trade_pnl(pos['entry_price'], exit_price, pos['quantity'], market, _position_side(pos))
                        net_return_pct = float(pnl.get('net_pnl_pct') or 0)
                        entry_px = float(pos['entry_price'])
                        peak_px = float(pos.get('peak_price') or entry_px)
                        trough_px = float(pos.get('trough_price') or entry_px)
                        # MAE/MFE FIX (Priority 4 from the ChatGPT diagnostic report): the
                        # single most important missing diagnostic. mfe_pct = best this trade
                        # ever moved in our favor before exit; mae_pct = worst it ever moved
                        # against us before exit. High MFE + losing exit = signal was fine,
                        # management gave the profit back. MFE ~ 0 + MAE ~ the final loss =
                        # the entry itself was already fighting the tape -- no amount of exit
                        # tuning fixes that, the entry signal needs to change.
                        position_side = _position_side(pos)
                        favor_px = peak_px if position_side == 'LONG' else trough_px
                        adverse_px = trough_px if position_side == 'LONG' else peak_px
                        mfe_pct = round(v3_2_engine.gross_return_pct(entry_px, favor_px, position_side), 3) if entry_px else None
                        mae_pct = round(-v3_2_engine.gross_return_pct(entry_px, adverse_px, position_side), 3) if entry_px else None
                        trade = {
                            'ticker': ticker, 'trading_date': day, 'entry_time': pos['opened_at'], 'exit_time': ts.to_pydatetime().replace(tzinfo=None),
                            'entry_price': round(pos['entry_price'], 2), 'exit_price': round(float(exit_price), 2),
                            'target_price': round(pos['target_price'], 2), 'stop_price': round(pos['stop_price'], 2),
                            'quantity': pos['quantity'], 'side': _position_side(pos), 'net_return_pct': round(net_return_pct, 3),
                            'net_pnl': round(float(pnl.get('net_pnl') or 0), 2),
                            'gross_pnl': round(float(pnl.get('gross_pnl') or 0), 2),
                            'cost_amount': round(float(pnl.get('cost_amount') or 0), 2),
                            'signal_price': pos.get('signal_price'),
                            'outcome': 'target_hit' if exit_reason == 'TARGET_HIT' else ('stop_loss_hit' if exit_reason in ('STOP_LOSS_HIT', 'TRAILING_STOP_GAVE_BACK_PROFIT') else 'horizon_exit'),
                            'exit_reason': exit_reason, 'score': pos.get('score'), 'pattern_key': pos.get('pattern_key'),
                            'mfe_pct': mfe_pct, 'mae_pct': mae_pct,
                            'peak_price': round(peak_px, 2), 'trough_price': round(trough_px, 2),
                            'intrabar_resolution': intrabar_resolution,
                            'signal_fill_gap_pct': pos.get('signal_fill_gap_pct'),
                            'strategy_id': pos.get('strategy_id'),
                            'strategy_name': pos.get('strategy_name'),
                            'strategy_confidence': pos.get('strategy_confidence'),
                            'regime': pos.get('regime'),
                            'strategy_why': pos.get('strategy_why'),
                            # CONTEXT AT ENTRY (report issues #2/#3). Recorded on the
                            # trade so future evidence can be sliced the same way a
                            # live candidate is described -- without this, a
                            # conditional P(win) has nothing to condition on.
                            'time_bucket': (pos.get('setup_context') or {}).get('time_bucket'),
                            'volatility_bucket': (pos.get('setup_context') or {}).get('volatility_bucket'),
                            'extension_bucket': (pos.get('setup_context') or {}).get('extension_bucket'),
                            'relative_strength_bucket': (pos.get('setup_context') or {}).get('relative_strength_bucket'),
                            'expected_net_edge_pct': pos.get('expected_net_edge_pct'),
                            'calibrated_win_prob_pct': pos.get('calibrated_win_prob_pct'),
                            'risk_amount': pos.get('risk_amount'),
                            'phase': phase,
                        }
                        # LAYER 3 POST-TRADE ANALYSIS: classify WHY this trade ended up
                        # where it did, deterministically, from MAE/MFE + fill gap + exit
                        # reason. This is what turns "trade lost" into "false breakout" or
                        # "gave back profit" -- the difference between knowing a strategy
                        # is weak and knowing which layer of it to fix.
                        try:
                            entry_dt, exit_dt = pos['opened_at'], ts.to_pydatetime().replace(tzinfo=None)
                            trade['holding_minutes'] = round((exit_dt - entry_dt).total_seconds() / 60, 1) if entry_dt else None
                            cls = classify_trade_outcome(trade)
                            trade['failure_type'] = cls.get('failure_type')
                            trade['diagnosis'] = cls.get('diagnosis')
                            trade['suggested_focus'] = cls.get('suggested_focus')
                            trade['classification'] = cls
                        except Exception:
                            pass
                        # SLOW layer: only test-window trades count toward the
                        # reported result; training trades build evidence and are
                        # reported separately (report issue #4).
                        if phase == 'training':
                            training_trades.append(trade)
                        else:
                            completed_trades.append(trade)
                        # FAST layer (report issue #5): the same-day ledger updates
                        # the instant a trade closes, so the very next tick's
                        # selector already knows about this loss. This is the
                        # difference between adapting in 5 minutes and adapting
                        # tomorrow.
                        session_trades.append({
                            'strategy_id': trade.get('strategy_id'), 'net_pnl': trade.get('net_pnl'),
                            'net_return_pct': trade.get('net_return_pct'),
                            'exit_time': ts.to_pydatetime().replace(tzinfo=None),
                            'ticker': ticker, 'failure_type': trade.get('failure_type'),
                        })
                        settings['_session_trades'] = session_trades
                        risk_budget.release(pos.get('risk_amount'))
                        _replay_insert_trade(run_id, market, trade)
                        _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'exit', pos.get('score'), exit_reason, trade)
                        last_closed_at[ticker] = (ts, net_return_pct)
                        # Closing frees the capital this position was holding, so a later
                        # signal the same day can reuse it -- exactly how a real account
                        # recycles money through the session.
                        capital_deployed = max(0.0, capital_deployed - float(pos.get('position_value') or 0))
                        del open_positions[ticker]

                # --- 2. ENTRY SCANNER ---------------------------------------------------
                # Always scans -- even with zero free slots or max_trades_per_day already
                # hit -- so the decision log still records what was eligible-but-missed
                # ("what opportunities did we miss because the portfolio was full").
                # Only the actual ENTRY action below is gated on slots/day-limit.
                day_data_for_scan = {}
                for t, df in day_frames.items():
                    if ts in df.index:
                        day_data_for_scan[t] = {'df': df, 'idx': df.index.get_loc(ts)}
                slots = available_position_slots(max_positions, len(open_positions))
                trades_left_today = max_trades_per_day - trades_opened_today
                if day_data_for_scan:
                    # BUGFIX: sim_now=sim_now threads THIS TICK's simulated timestamp down
                    # into strict_learning_review's late-session/square-off check, instead
                    # of leaving it to fall back to the real wall-clock time.
                    scan = replay_scan_universe(day_data_for_scan, list(day_data_for_scan.keys()), settings, market,
                                                 market_context, trade_memory, set(open_positions.keys()), use_learning=use_learning,
                                                 sim_now=sim_now)
                    total_scan_cycles += 1
                    for _reason, _count in (scan.get('rejection_reason_counts') or {}).items():
                        run_rejection_reason_counts[_reason] = run_rejection_reason_counts.get(_reason, 0) + _count
                    for _sid, _sbucket in (scan.get('strategy_audit') or {}).items():
                        _run_bucket = run_strategy_audit.setdefault(_sid, {'name': _sbucket.get('name'), 'evaluated': 0, 'eligible': 0, 'selected': 0})
                        _run_bucket['evaluated'] += _sbucket.get('evaluated', 0)
                        _run_bucket['eligible'] += _sbucket.get('eligible', 0)
                        _run_bucket['selected'] += _sbucket.get('selected', 0)
                    for rej in scan['rejections_sample'][:3]:
                        _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), rej['ticker'], 'scan_reject', rej.get('score'), rej.get('reason'))
                    # SESSION-LEVEL DE-RISK / HALT (report issue #5, portfolio layer).
                    # A session can bleed out across ten different strategies without
                    # any single one crossing its own limit, and the account has only
                    # one balance.
                    session_risk = assess_session_risk_state(
                        session_trades, risk_budget.capital,
                        derisk_pct=INTRADAY_SESSION_DERISK_DRAWDOWN_PCT,
                        stop_pct=INTRADAY_SESSION_STOP_DRAWDOWN_PCT) if (use_learning and INTRADAY_FAST_ADAPT_ENABLED) else {}
                    risk_budget.risk_multiplier = float(session_risk.get('risk_multiplier', 1.0))
                    if session_risk.get('stop_entries'):
                        if scan['eligible']:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), None, 'scan_reject', None,
                                               f'session_risk_halt: {session_risk.get("note")}')
                        scan['eligible'] = []
                    # RANK BY EXPECTED VALUE before spending any of the risk budget.
                    # "Rank candidates -> risk-budget allocation": the budget must be
                    # spent on the best expected edge available at this tick, not on
                    # whichever ticker happens to come first in score order.
                    scan['eligible'] = sorted(
                        scan['eligible'],
                        key=lambda c: (1 if c.get('expected_net_edge_pct') is not None else 0,
                                       float(c.get('expected_net_edge_pct') or 0.0),
                                       float(c.get('score') or 0)),
                        reverse=True)
                    for cand in scan['eligible']:
                        if slots <= 0:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), cand['ticker'], 'scan_reject', cand.get('score'), f'max_open_positions_reached ({positions_label})')
                            continue
                        if trades_left_today <= 0:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), cand['ticker'], 'scan_reject', cand.get('score'), f'max_trades_per_day_reached ({max_trades_per_day})')
                            continue
                        # PRIORITY 4 (report-driven): "closer to: find as many qualifying
                        # setups as possible until the trade quota is exhausted" -- instead
                        # of accepting every candidate that merely clears min_score right up
                        # to the daily cap, require a progressively HIGHER bar as the day's
                        # trade budget depletes, so the system spends its last few slots on
                        # its best remaining signals rather than whatever arrives next.
                        # Tapers from 0 extra points (<=60% of the daily budget used) up to
                        # +20 points at 100% used; only engages with use_learning on (raw/
                        # baseline runs are meant to show the strategy's unmodified signal).
                        if use_learning and max_trades_per_day > 0:
                            quota_used_frac = trades_opened_today / max_trades_per_day
                            if quota_used_frac > 0.6:
                                taper_bonus_needed = round(min(20.0, (quota_used_frac - 0.6) / 0.4 * 20.0), 1)
                                min_score_gate_val = float(cand.get('min_score') if cand.get('min_score') is not None else (settings.get('min_score') or 0))
                                if float(cand.get('score') or 0) < min_score_gate_val + taper_bonus_needed:
                                    _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), cand['ticker'], 'scan_reject', cand.get('score'),
                                                       f'daily_quota_taper: {trades_opened_today}/{max_trades_per_day} trades used today, '
                                                       f'needs {round(min_score_gate_val + taper_bonus_needed, 1)}+ now (was {min_score_gate_val})')
                                    continue
                        ticker = cand['ticker']
                        if ticker in open_positions:
                            continue
                        last_close = last_closed_at.get(ticker)
                        if last_close and (ts - last_close[0]).total_seconds() / 60 < cooldown_minutes and last_close[1] < 0:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'), f'same_ticker_cooldown_after_loss ({cooldown_minutes} min)')
                            continue
                        # PRIORITY FIX (review round 3, #2): Live's REAL entry path
                        # doesn't stop at the scan's proxy entry/target/stop -- it
                        # builds the authoritative final trade plan via
                        # build_intraday_plan(), which reruns position sizing AND
                        # applies apply_intraday_size_efficiency_gate() +
                        # intraday_cost_gate() (min position value, min expected net
                        # profit, min gross-profit-to-cost ratio). Replay used to skip
                        # straight to compute_integer_position_size() and open the
                        # position regardless -- meaning it could take trades Live's
                        # own gates would have rejected. Build the same plan here, at
                        # the same point in the pipeline (signal time, before fill).
                        plan = build_intraday_plan(cand, trading_settings, settings)
                        if not plan:
                            reason = cand.get('blocked_reason') or explain_intraday_plan_skip(cand, trading_settings, settings)
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'), f'trade_plan_rejected: {reason}')
                            continue
                        signal_price = float(plan['limit_price'])
                        target_price = float(plan['target_price'])
                        stop_price = float(plan['stop_price'])
                        if signal_price <= 0 or target_price <= 0 or stop_price <= 0:
                            continue
                        # PRIORITY-1 FIX (review round 2, #3 -- order-fill timing):
                        # a signal detected on THIS bar cannot actually be filled at
                        # this bar's own price -- by the time you'd see the signal,
                        # this candle has already printed. Default policy
                        # ('next_open') fills at the NEXT candle's Open plus
                        # slippage, and re-anchors target/stop to that fill price
                        # while preserving the strategy's intended risk/reward
                        # distances. 'signal_price' keeps the old, more optimistic
                        # same-candle fill for side-by-side comparison only.
                        entry_price = signal_price
                        fill_ts = ts
                        fill_gap_pct_final = 0.0
                        ticker_df = day_frames.get(ticker)
                        if INTRADAY_REPLAY_FILL_MODE == 'next_open':
                            if ticker_df is None or ts not in ticker_df.index:
                                continue
                            bar_pos = ticker_df.index.get_loc(ts)
                            if bar_pos + 1 >= len(ticker_df):
                                # No next candle today to fill on -- skip rather than
                                # pretend we could enter and exit within the same bar.
                                _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'), 'no_next_candle_for_fill')
                                continue
                            next_bar = ticker_df.iloc[bar_pos + 1]
                            next_open = float(next_bar['Open'])
                            if next_open <= 0:
                                continue
                            fill_ts = ticker_df.index[bar_pos + 1]
                            entry_price = round(next_open * (1 + INTRADAY_REPLAY_ENTRY_SLIPPAGE_BPS / 10000.0), 2)
                            # PRIORITY FIX (review round 3, #3): re-check the actual
                            # fill against Live's own max-chase guard. The scan-time
                            # chase check (score_intraday_prescan_candidate /
                            # fetch_intraday_candidate_snapshot) only looked at
                            # change-from-session-open as of the SIGNAL bar; it can't
                            # know about a gap between the signal bar and the next
                            # bar's open. If that gap alone already pushes the fill
                            # beyond max_chase_pct away from the signal price, Live's
                            # chase guard would reject this setup by the time an order
                            # could actually go in -- so replay must too.
                            max_chase_pct = float(settings.get('max_chase_pct') or INTRADAY_MAX_CHASE_PCT)
                            fill_gap_pct = ((entry_price - signal_price) / signal_price) * 100 if signal_price else 0
                            if fill_gap_pct > max_chase_pct:
                                _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                                   f'gap_exceeds_max_chase_after_fill: fill {round(fill_gap_pct, 2)}% above signal, limit {max_chase_pct}%')
                                continue
                            # PRIORITY-7 FIX (ChatGPT diagnostic report): a SEPARATE, deliberately
                            # tighter gate than max_chase_pct above -- see INTRADAY_MAX_SIGNAL_FILL_GAP_PCT's
                            # module docstring. max_chase_pct (default 3%) was letting trades through that
                            # already start meaningfully underwater versus the signal price alone, before
                            # the stop/target math even begins -- e.g. the KRBL trade in Run 6 entered
                            # ~0.29% above its signal price against only a ~0.6% stop. This check runs in
                            # addition to (not instead of) the max_chase_pct check above.
                            max_signal_fill_gap_pct = float(settings.get('max_signal_fill_gap_pct') or INTRADAY_MAX_SIGNAL_FILL_GAP_PCT)
                            if fill_gap_pct > max_signal_fill_gap_pct:
                                _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                                   f'signal_fill_gap_exceeded: fill {round(fill_gap_pct, 3)}% above signal, limit {max_signal_fill_gap_pct}% -- entry already disadvantaged before target/stop math')
                                continue
                            # Preserve the strategy's intended target/stop distance
                            # (as a % of the signal price) but re-anchor it to the
                            # actual fill price, rather than keeping the stale
                            # absolute levels computed off the signal candle.
                            target_pct = (target_price / signal_price) - 1
                            stop_pct = (stop_price / signal_price) - 1
                            target_price = round(entry_price * (1 + target_pct), 2)
                            stop_price = round(entry_price * (1 + stop_pct), 2)
                            fill_gap_pct_final = round(fill_gap_pct, 3)
                        # Re-size for the actual fill price/stop (same position-sizing
                        # math Live/Paper uses -- capital, max position %, risk-per-trade
                        # %, stop distance) so replay P&L scales the same way a real
                        # position would once the fill price is known. The size-
                        # efficiency and cost gates were already checked above, at the
                        # same signal-time point Live checks them.
                        # risk_scale (report #3/#10): computed once at strategy selection
                        # time (attach_intraday_strategy_engine) and carried on `cand`, so
                        # replay sizes this candidate exactly the same way Live/Paper would.
                        sizing = compute_integer_position_size(entry_price, stop_price, trading_settings, market, risk_scale=cand.get('risk_scale', 1.0))
                        qty = int(sizing.get('quantity') or 0)
                        if qty <= 0:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'), sizing.get('skip_reason') or 'position_size_zero')
                            continue
                        # POST-FILL FIX: the size-efficiency and cost gates above only ran
                        # against the SIGNAL price/target/stop, before the actual next-open
                        # fill (plus slippage) re-anchored entry/target/stop and this
                        # re-sizing recomputed quantity. A signal that cleared both gates
                        # can fail them again after a real fill -- e.g. a gap-up fill raises
                        # the position value/qty math, or a re-anchored target shrinks the
                        # gross-profit-to-cost ratio below the minimum. Live would refuse to
                        # actually place such an order, so replay must re-check here too,
                        # using the ACTUAL fill entry/target/stop/quantity, before opening
                        # the simulated position -- not just trust the signal-time checks.
                        post_fill_candidate = {**cand, 'last': entry_price, 'market': market}
                        post_fill_size_reasons = apply_intraday_size_efficiency_gate(post_fill_candidate, sizing, settings)
                        if post_fill_size_reasons:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                               'post_fill_size_filter_no_edge: ' + '; '.join(post_fill_size_reasons))
                            continue
                        post_fill_cost_gate = intraday_cost_gate(entry_price, target_price, qty, market, settings)
                        if not post_fill_cost_gate.get('ok'):
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                               'post_fill_cost_filter_no_edge: ' + '; '.join(post_fill_cost_gate.get('reasons') or []))
                            continue
                        # ---------------------------------------------------------
                        # RISK BUDGET ALLOCATION (report: the risk-management issue)
                        # ---------------------------------------------------------
                        # What this trade actually costs the account is
                        # (entry - stop) * qty, not "one trade". The budget is checked
                        # here, at the point the real numbers finally exist (post-fill,
                        # post-sizing), and it is the governing control -- the daily
                        # trade count is now only a backstop above it.
                        risk_amount = compute_trade_risk_amount(entry_price, stop_price, qty)
                        cand_ev = cand.get('expected_net_edge_pct')
                        # Fast-adaptation risk step-down: a strategy already bleeding
                        # today gets a smaller position, not just a score handicap.
                        size_multiplier = 1.0
                        if use_learning and INTRADAY_FAST_ADAPT_ENABLED:
                            _fast = assess_session_adaptation(
                                session_trades, cand.get('strategy_id'), now=sim_now,
                                config={'loss_streak': INTRADAY_FAST_ADAPT_LOSS_STREAK,
                                        'timeout_minutes': INTRADAY_FAST_ADAPT_TIMEOUT_MINUTES,
                                        'max_losses_per_day': INTRADAY_FAST_ADAPT_MAX_LOSSES_PER_DAY})
                            if _fast.get('block'):
                                _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                                   f'fast_adaptation_suspended: {_fast.get("block_reason")}')
                                continue
                            size_multiplier = min(size_multiplier, float(_fast.get('risk_multiplier') or 1.0))
                        size_multiplier = min(size_multiplier, float(risk_budget.risk_multiplier or 1.0))
                        if size_multiplier <= 0:
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                               'session_risk_halt: further entries stopped for today by the de-risk layer')
                            continue
                        if size_multiplier < 1.0 and qty > 1:
                            scaled_qty = max(1, int(qty * size_multiplier))
                            if scaled_qty != qty:
                                qty = scaled_qty
                                risk_amount = compute_trade_risk_amount(entry_price, stop_price, qty)
                        budget_check = risk_budget.check(risk_amount, cand_ev)
                        if not budget_check['ok']:
                            risk_budget_refusals += 1
                            _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                               budget_check['reason'])
                            continue
                        position_value = round(float(entry_price) * int(qty), 2)
                        if capital_guard_enabled and (capital_deployed + position_value) > replay_capital + 0.005:
                            capital_blocked_signals += 1
                            _replay_log_event(
                                run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'scan_reject', cand.get('score'),
                                f'capital_fully_deployed: needs ₹{position_value:,.0f}, only '
                                f'₹{max(0.0, replay_capital - capital_deployed):,.0f} of ₹{replay_capital:,.0f} free '
                                f'({len(open_positions)} position(s) already holding ₹{capital_deployed:,.0f})')
                            continue
                        open_positions[ticker] = {
                            'position_value': position_value,
                            'entry_price': entry_price, 'signal_price': round(signal_price, 2),
                            'target_price': target_price, 'stop_price': stop_price,
                            'quantity': qty, 'market': market, 'horizon': 'intraday', 'side': _candidate_side(cand),
                            'peak_price': entry_price, 'trough_price': entry_price, 'trailing_stop_price': stop_price,
                            'opened_at': fill_ts.to_pydatetime().replace(tzinfo=None),
                            'metadata_json': {
                                'profit_book_pct': settings.get('profit_book_pct'),
                                'force_exit_before_close_minutes': settings.get('force_exit_before_close_minutes'),
                            },
                            'score': cand.get('score'), 'pattern_key': cand.get('strategy_pattern_key'),
                            'signal_fill_gap_pct': fill_gap_pct_final,
                            # Strategy attribution travels with the position from entry to
                            # exit -- the selector's decision is made at entry, so it has to
                            # be captured here rather than re-derived (differently) at exit.
                            'strategy_id': cand.get('strategy_id'),
                            'strategy_name': cand.get('strategy_name'),
                            'strategy_confidence': cand.get('strategy_confidence'),
                            'regime': cand.get('regime'),
                            'strategy_why': cand.get('strategy_why'),
                            'setup_context': cand.get('setup_context'),
                            'expected_net_edge_pct': cand.get('expected_net_edge_pct'),
                            'calibrated_win_prob_pct': cand.get('calibrated_win_prob_pct'),
                            'risk_amount': risk_amount,
                        }
                        risk_budget.commit(risk_amount, cand_ev)
                        capital_deployed += position_value
                        peak_capital_deployed = max(peak_capital_deployed, capital_deployed)
                        slots -= 1
                        trades_left_today -= 1
                        trades_opened_today += 1
                        _replay_log_event(run_id, event_counter, day, ts.strftime('%H:%M'), ticker, 'entry', cand.get('score'), 'entered', {
                            'signal_price': signal_price, 'entry_price': entry_price, 'target_price': target_price, 'stop_price': stop_price, 'quantity': qty,
                            'fill_mode': INTRADAY_REPLAY_FILL_MODE,
                            'position_value': round(position_value, 2),
                            # capital_deployed already includes this position (incremented
                            # just above), so it must NOT be added a second time here.
                            'capital_deployed_after_entry': round(capital_deployed, 2),
                            'capital_free_after_entry': round(max(0.0, replay_capital - capital_deployed), 2),
                            'risk_amount': risk_amount,
                            'expected_net_edge_pct': cand_ev,
                            'calibrated_win_prob_pct': cand.get('calibrated_win_prob_pct'),
                            'risk_budget': risk_budget.summary(),
                            'size_multiplier': round(size_multiplier, 2),
                            'phase': phase,
                        })

                if tick_idx % 3 == 0 or tick_idx == len(timestamps) - 1:
                    wins = sum(1 for t in completed_trades if t['net_return_pct'] > 0)
                    losses = sum(1 for t in completed_trades if t['net_return_pct'] <= 0)
                    _replay_update_run_row(
                        run_id, status='running', sim_date=day.isoformat(), current_sim_time=ts.strftime('%H:%M'),
                        progress_pct=round(min(100.0, (ticks_done / total_ticks_all_days) * 100), 1),
                        scan_cycles=ticks_done, open_positions_count=len(open_positions),
                        completed_trades_count=len(completed_trades), win_count=wins, loss_count=losses,
                    )

            # Forced EOD flatten for anything still open when the day's bars run out.
            if not stop_event.is_set():
                for ticker in list(open_positions.keys()):
                    pos = open_positions[ticker]
                    df = day_frames.get(ticker)
                    if df is None or df.empty:
                        capital_deployed = max(0.0, capital_deployed - float(pos.get('position_value') or 0))
                        del open_positions[ticker]
                        continue
                    last_bar = df.iloc[-1]
                    exit_price = float(last_bar['Close'])
                    pnl = calculate_net_trade_pnl(pos['entry_price'], exit_price, pos['quantity'], market, _position_side(pos))
                    net_return_pct = float(pnl.get('net_pnl_pct') or 0)
                    trade = {
                        'ticker': ticker, 'trading_date': day, 'entry_time': pos['opened_at'], 'exit_time': df.index[-1].to_pydatetime().replace(tzinfo=None),
                        'entry_price': round(pos['entry_price'], 2), 'exit_price': round(exit_price, 2),
                        'target_price': round(pos['target_price'], 2), 'stop_price': round(pos['stop_price'], 2),
                        'quantity': pos['quantity'], 'side': _position_side(pos), 'net_return_pct': round(net_return_pct, 3),
                        'net_pnl': round(float(pnl.get('net_pnl') or 0), 2),
                        'gross_pnl': round(float(pnl.get('gross_pnl') or 0), 2),
                        'cost_amount': round(float(pnl.get('cost_amount') or 0), 2),
                        'signal_price': pos.get('signal_price'),
                        'outcome': 'horizon_exit',
                        'exit_reason': 'INTRADAY_FORCE_EXIT_BEFORE_CLOSE', 'score': pos.get('score'), 'pattern_key': pos.get('pattern_key'),
                    }
                    trade['phase'] = phase
                    trade['risk_amount'] = pos.get('risk_amount')
                    trade['strategy_id'] = pos.get('strategy_id')
                    trade['strategy_name'] = pos.get('strategy_name')
                    trade['strategy_confidence'] = pos.get('strategy_confidence')
                    trade['regime'] = pos.get('regime')
                    for _ck in ('time_bucket', 'volatility_bucket', 'extension_bucket', 'relative_strength_bucket'):
                        trade[_ck] = (pos.get('setup_context') or {}).get(_ck)
                    trade['expected_net_edge_pct'] = pos.get('expected_net_edge_pct')
                    trade['calibrated_win_prob_pct'] = pos.get('calibrated_win_prob_pct')
                    if phase == 'training':
                        training_trades.append(trade)
                    else:
                        completed_trades.append(trade)
                    risk_budget.release(pos.get('risk_amount'))
                    _replay_insert_trade(run_id, market, trade)
                    _replay_log_event(run_id, event_counter, day, 'EOD', ticker, 'exit', pos.get('score'), 'INTRADAY_FORCE_EXIT_BEFORE_CLOSE', trade)
                    capital_deployed = max(0.0, capital_deployed - float(pos.get('position_value') or 0))
                    del open_positions[ticker]

        wins = sum(1 for t in completed_trades if t['net_return_pct'] > 0)
        losses = sum(1 for t in completed_trades if t['net_return_pct'] <= 0)
        net_return_pct = round(sum(t['net_return_pct'] for t in completed_trades), 3) if completed_trades else None
        final_status = 'stopped' if stop_event.is_set() else 'completed'
        # PRIORITY-5 FIX: full performance statistics (profit factor,
        # expectancy, drawdown, cost-adjusted P&L, score-bucket win rates),
        # not just win/loss counts and a raw sum of %returns.
        stats = compute_replay_statistics(completed_trades)
        # AUTO DEEP ANALYSIS: the "point 1" style report (exit-reason P&L attribution,
        # break-even win rate, overtrading vs the daily cap, time-of-day expectancy,
        # score calibration, traffic-light verdict) computed automatically for every
        # run and surfaced in the UI, instead of being redone by hand in chat each time.
        try:
            stats['deep_analysis'] = compute_replay_deep_analysis(completed_trades, stats, max_trades_per_day, len(days_with_data))
        except Exception as _da_err:
            stats['deep_analysis'] = {'has_data': False, 'error': str(_da_err)[:300]}
        # PRIORITY 5 (report-driven): measurement + suggestion only, never applied to
        # THIS run (it already finished). See compute_exit_calibration_suggestions and
        # start_intraday_replay's exit_calibration_override for how to opt a LATER run
        # into using these.
        # TRAINING/TEST REPORTING (report issue #4). The headline statistics above
        # describe the TEST window only -- training trades never entered
        # completed_trades. The training window is reported alongside so the two are
        # comparable and so a large train/test gap (the classic overfit signature)
        # is visible rather than buried.
        if training_day_set:
            training_stats = compute_replay_statistics(training_trades)
            stats['research_design'] = {
                'structure': 'training window -> frozen evidence -> blind test window',
                'evidence_mode': evidence_mode,
                'training_days': sorted(d.isoformat() for d in training_day_set),
                'training_day_count': len(training_day_set),
                'test_days': [d for d in days_with_data if d not in {x.isoformat() for x in training_day_set}],
                'evidence_frozen_at': evidence_frozen_at,
                'training_trades': len(training_trades),
                'test_trades': len(completed_trades),
                'training_stats': training_stats,
                'note': ('Headline statistics on this run describe the TEST window only. The training window built '
                         'the evidence base (strategy expectancy, context slices, exit calibration) and its trades '
                         'are excluded from the result, so the test days were genuinely unseen when they were '
                         'traded. A test profit factor far below the training one is the signature of a model '
                         'fitted to its own training data rather than a real edge.'),
            }
            if training_stats.get('profit_factor') and stats.get('profit_factor'):
                gap = round(float(training_stats['profit_factor']) - float(stats['profit_factor']), 2)
                stats['research_design']['train_test_profit_factor_gap'] = gap
                stats['research_design']['overfit_warning'] = bool(gap >= 0.5)
        stats['risk_budget'] = risk_budget.summary()
        stats['risk_budget']['signals_refused'] = risk_budget_refusals
        try:
            stats['exit_calibration_suggestions'] = compute_exit_calibration_suggestions(completed_trades)
        except Exception as _ec_err:
            stats['exit_calibration_suggestions'] = {'error': str(_ec_err)[:300]}
        if settings.get('_strategy_exit_calibration'):
            stats['exit_calibration_used'] = settings['_strategy_exit_calibration']
            # Report critical issue #2: make an unvalidated in-run calibration
            # unmistakable in the run's own results, never just in a log line.
            stats['exit_calibration_is_experimental_unvalidated'] = bool(settings.get('_exit_calibration_is_experimental'))
            if stats['exit_calibration_is_experimental_unvalidated']:
                stats['exit_calibration_warning'] = (
                    "This run's test window used an UNVALIDATED, in-run training-window-derived exit "
                    "calibration (exit_calibration_experimental_unvalidated=True). Treat this run as a "
                    "calibration EXPERIMENT, not a clean profitability baseline, until the calibration clears "
                    "validate_exit_calibration_out_of_sample against an independent baseline run on the same days.")
        # Fix 3: report which selected days actually replayed vs were skipped for lack of
        # data, instead of letting a run silently call itself "completed" when one or more
        # selected days never produced a single tick.
        stats['days_selected'] = [d.isoformat() for d in trading_days]
        stats['days_replayed'] = days_with_data
        stats['days_skipped_no_data'] = days_skipped_no_data
        stats['days_skipped_holiday'] = days_skipped_holiday
        # Fix 6: full rejection-reason breakdown across the whole run (every rejection, not
        # just the samples kept for the tick-by-tick decision log), so a "0 trades" run
        # comes with an honest answer to "was it 0 opportunities, or were good candidates
        # getting filtered out downstream".
        stats['rejection_reason_counts'] = run_rejection_reason_counts
        # STRATEGY AUDIT TRAIL: per-strategy evaluated/eligible/selected counts across the
        # whole run's entire pre-scan pool, every tick -- this is the missing evidence a
        # replay report needs to actually answer "were all 10 strategies meaningfully
        # tested", instead of only ever showing the one selected/rejected outcome per
        # candidate. A strategy with evaluated=0 here genuinely never saw a single
        # candidate all run; a strategy with evaluated>0 but eligible=0 was evaluated but
        # its own conditions never once matched; eligible>0 but selected=0 means it kept
        # losing the selector's confidence/regime-fit/historical-edge ranking to another
        # strategy on every candidate it did qualify for.
        stats['strategy_audit'] = run_strategy_audit
        stats['scan_cycles_with_data'] = total_scan_cycles
        # CAPITAL VIEW of the run: what the money actually did, not just what the
        # percentages did. peak_capital_deployed is the highest amount held in open
        # positions at any one moment, which is the number that answers "did this
        # strategy actually fit inside the capital I had?".
        _cap_used_pct = round((peak_capital_deployed / replay_capital) * 100, 1) if replay_capital else None
        stats['capital'] = {
            'starting_capital': round(replay_capital, 2),
            'capital_guard_enabled': capital_guard_enabled,
            'max_open_positions': positions_label,
            'peak_capital_deployed': round(peak_capital_deployed, 2),
            'peak_capital_utilisation_pct': _cap_used_pct,
            'signals_blocked_by_capital': capital_blocked_signals,
            'net_pnl': stats.get('net_pnl'),
            'gross_pnl': stats.get('gross_pnl'),
            'total_costs': stats.get('total_costs'),
            'ending_capital': round(replay_capital + float(stats.get('net_pnl') or 0), 2),
            'return_on_starting_capital_pct': round((float(stats.get('net_pnl') or 0) / replay_capital) * 100, 3) if replay_capital else None,
            'note': ('Positions were unlimited in count but capped by available cash: '
                      f'{capital_blocked_signals} signal(s) were refused because the capital was fully deployed at that moment.'
                      if capital_guard_enabled else
                      'Capital guard was OFF for this run: positions were sized off full capital independently, so peak '
                      'deployed capital can exceed the starting capital and "amount invested" is notional, not fundable.'),
        }
        incomplete_note = ''
        if days_skipped_holiday:
            incomplete_note += f' (skipped {", ".join(days_skipped_holiday)} — exchange holiday, not a data problem)'
        if days_skipped_no_data:
            incomplete_note += f' ({len(days_with_data)}/{len(trading_days)} selected days actually replayed; skipped {", ".join(days_skipped_no_data)} — no historical data available)'
        _replay_update_run_row(
            run_id, status=final_status, finished_at=datetime.datetime.utcnow(),
            progress_pct=100.0 if final_status == 'completed' else round(min(100.0, (ticks_done / total_ticks_all_days) * 100), 1),
            completed_trades_count=len(completed_trades), win_count=wins, loss_count=losses,
            open_positions_count=len(open_positions), net_return_pct=net_return_pct,
            stats=json.dumps(stats, default=_json_safe),
            message=f'{"Stopped by user" if final_status == "stopped" else "Completed"}: {len(completed_trades)} trade(s), {wins} win / {losses} loss.{incomplete_note}',
        )
    except Exception as e:
        import traceback
        traceback.print_exc()
        _replay_update_run_row(run_id, status='error', finished_at=datetime.datetime.utcnow(), error=str(e)[:500], message=f'Replay failed: {e}')
    finally:
        with INTRADAY_REPLAY_LOCK:
            INTRADAY_REPLAY_STOP_EVENTS.pop(run_id, None)
            INTRADAY_REPLAY_PAUSE_EVENTS.pop(run_id, None)
            INTRADAY_REPLAY_THREADS.pop(run_id, None)


def pause_intraday_replay(run_id: int) -> Dict[str, Any]:
    with INTRADAY_REPLAY_LOCK:
        ev = INTRADAY_REPLAY_PAUSE_EVENTS.get(run_id)
    if ev is None:
        return {'ok': False, 'error': 'Run not found or already finished.'}
    ev.set()
    _replay_update_run_row(run_id, status='paused', message='Paused by user.')
    return {'ok': True, 'message': 'Pause requested.'}


def resume_intraday_replay(run_id: int) -> Dict[str, Any]:
    with INTRADAY_REPLAY_LOCK:
        ev = INTRADAY_REPLAY_PAUSE_EVENTS.get(run_id)
    if ev is None:
        return {'ok': False, 'error': 'Run not found or already finished.'}
    ev.clear()
    _replay_update_run_row(run_id, status='running', message='Resumed by user.')
    return {'ok': True, 'message': 'Resumed.'}


def stop_intraday_replay(run_id: int) -> Dict[str, Any]:
    with INTRADAY_REPLAY_LOCK:
        stop_ev = INTRADAY_REPLAY_STOP_EVENTS.get(run_id)
        pause_ev = INTRADAY_REPLAY_PAUSE_EVENTS.get(run_id)
    if stop_ev is None:
        # Not running in this worker process (already finished, or a different
        # worker owns the thread) -- still mark it stopped in the DB so the UI
        # reflects intent even though we can't interrupt a live thread here.
        _replay_update_run_row(run_id, status='stopped', finished_at=datetime.datetime.utcnow(), message='Stop requested (run was not active in this process).')
        return {'ok': True, 'message': 'Stop requested.'}
    stop_ev.set()
    if pause_ev is not None:
        pause_ev.clear()  # don't leave it stuck paused; let the loop see stop_event and exit
    _replay_update_run_row(run_id, status='stopped', message='Stop requested by user; finishing the current tick safely...')
    return {'ok': True, 'message': 'Stop requested. The current tick finishes safely and completed trades so far are kept.'}


def _replay_run_config_summary(row: Dict[str, Any]) -> Dict[str, Any]:
    """The few settings a reader needs to interpret a run's numbers, lifted out of
    the stored snapshot: the position limit it enforced, whether cash was capped,
    and the capital it was sized against. Without these, two runs with very
    different constraints look identical in the runs table.
    """
    snap = row.get('settings_snapshot')
    if isinstance(snap, str):
        try:
            snap = json.loads(snap)
        except Exception:
            snap = None
    if not isinstance(snap, dict):
        return {}
    intra = snap.get('intraday_settings') if isinstance(snap.get('intraday_settings'), dict) else {}
    limit_raw = intra.get('replay_max_open_positions')
    return {
        'max_open_positions': snap.get('max_open_positions') or intra.get('replay_max_open_positions_label')
                               or ('unlimited' if limit_raw in (0, None) else str(limit_raw)),
        'max_open_positions_source': snap.get('max_open_positions_source'),
        'enforce_capital': snap.get('enforce_capital', intra.get('replay_enforce_capital', True)),
        'starting_capital': float(intra.get('simulation_capital_inr') or 0) or None,
        'max_trades_per_day': intra.get('max_trades_per_day'),
        'min_score': intra.get('min_score'),
        'require_vwap': intra.get('require_vwap'),
    }


def _replay_run_row_to_dict(row: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'config': _replay_run_config_summary(row),
        'run_id': row['id'], 'created_at': row['created_at'].isoformat() if row.get('created_at') else None,
        'finished_at': row['finished_at'].isoformat() if row.get('finished_at') else None,
        'market': row['market'], 'status': row['status'],
        'selected_dates': row.get('selected_dates') or [],
        'universe_count': row.get('universe_count'),
        'cap_filter_applied': bool(row.get('cap_filter_applied')),
        'use_learning': bool(row.get('use_learning')) if row.get('use_learning') is not None else True,
        'current_date': row['sim_date'].isoformat() if row.get('sim_date') else None,
        'current_sim_time': row.get('current_sim_time'),
        'progress_pct': float(row['progress_pct']) if row.get('progress_pct') is not None else 0,
        'scan_cycles': row.get('scan_cycles') or 0,
        'open_positions_count': row.get('open_positions_count') or 0,
        'completed_trades_count': row.get('completed_trades_count') or 0,
        'win_count': row.get('win_count') or 0, 'loss_count': row.get('loss_count') or 0,
        'win_rate_pct': round((row['win_count'] / row['completed_trades_count']) * 100, 1) if row.get('completed_trades_count') else None,
        'net_return_pct': float(row['net_return_pct']) if row.get('net_return_pct') is not None else None,
        'stats': row.get('stats'),
        'error': row.get('error'), 'message': row.get('message'),
    }


def intraday_replay_status(run_id: int) -> Dict[str, Any]:
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("SELECT * FROM intraday_replay_runs WHERE id = %s", (run_id,))
            row = cur.fetchone()
            if not row:
                return {'ok': False, 'error': 'Replay run not found.'}
            cur.execute("""
                SELECT ticker, trading_date, entry_time, exit_time, entry_price, exit_price, target_price, stop_price,
                       quantity, net_return_pct, net_pnl, outcome, exit_reason, score, pattern_key, gross_pnl, cost_amount, signal_price,
                       mfe_pct, mae_pct, peak_price, trough_price, intrabar_resolution, signal_fill_gap_pct,
                       strategy_id, strategy_name, strategy_confidence, regime, failure_type, diagnosis, suggested_focus
                FROM intraday_replay_trades WHERE run_id = %s ORDER BY entry_time DESC LIMIT 60
            """, (run_id,))
            trades = cur.fetchall()
            cur.execute("""
                SELECT ts, trading_date, sim_time, ticker, event_type, score, reason
                FROM intraday_replay_events WHERE run_id = %s ORDER BY id DESC LIMIT 40
            """, (run_id,))
            events = cur.fetchall()
    finally:
        conn.close()
    result = _replay_run_row_to_dict(row)
    result['ok'] = True
    result['recent_trades'] = [{
        'ticker': t['ticker'], 'trading_date': t['trading_date'].isoformat() if t['trading_date'] else None,
        'entry_time': t['entry_time'].isoformat() if t['entry_time'] else None,
        'exit_time': t['exit_time'].isoformat() if t['exit_time'] else None,
        'entry_price': float(t['entry_price']) if t['entry_price'] is not None else None,
        'exit_price': float(t['exit_price']) if t['exit_price'] is not None else None,
        'target_price': float(t['target_price']) if t['target_price'] is not None else None,
        'stop_price': float(t['stop_price']) if t['stop_price'] is not None else None,
        'net_return_pct': float(t['net_return_pct']) if t['net_return_pct'] is not None else None,
        'net_pnl': float(t['net_pnl']) if t['net_pnl'] is not None else None,
        'gross_pnl': float(t['gross_pnl']) if t.get('gross_pnl') is not None else None,
        'cost_amount': float(t['cost_amount']) if t.get('cost_amount') is not None else None,
        'signal_price': float(t['signal_price']) if t.get('signal_price') is not None else None,
        'outcome': t['outcome'], 'exit_reason': t['exit_reason'], 'score': float(t['score']) if t['score'] is not None else None,
        'mfe_pct': float(t['mfe_pct']) if t.get('mfe_pct') is not None else None,
        'mae_pct': float(t['mae_pct']) if t.get('mae_pct') is not None else None,
        'peak_price': float(t['peak_price']) if t.get('peak_price') is not None else None,
        'trough_price': float(t['trough_price']) if t.get('trough_price') is not None else None,
        'intrabar_resolution': t.get('intrabar_resolution'),
        'signal_fill_gap_pct': float(t['signal_fill_gap_pct']) if t.get('signal_fill_gap_pct') is not None else None,
        'strategy_id': t.get('strategy_id'), 'strategy_name': t.get('strategy_name'),
        'strategy_confidence': float(t['strategy_confidence']) if t.get('strategy_confidence') is not None else None,
        'regime': t.get('regime'), 'failure_type': t.get('failure_type'),
        'diagnosis': t.get('diagnosis'), 'suggested_focus': t.get('suggested_focus'),
    } for t in trades]
    result['recent_events'] = [{
        'ts': e['ts'].isoformat() if e['ts'] else None,
        'trading_date': e['trading_date'].isoformat() if e['trading_date'] else None,
        'sim_time': e['sim_time'], 'ticker': e['ticker'], 'event_type': e['event_type'],
        'score': float(e['score']) if e['score'] is not None else None, 'reason': e['reason'],
    } for e in events]
    return result


def build_intraday_replay_download(run_id: int) -> Dict[str, Any]:
    """Full (uncapped) trades + events for a single Replay Lab run, for the
    'Download replay data' button. Unlike intraday_replay_status() -- which
    is deliberately capped to the most recent 60 trades / 40 events for the
    live-polling UI -- a download should contain every trade and every
    decision-log event the run produced."""
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("SELECT * FROM intraday_replay_runs WHERE id = %s", (run_id,))
            row = cur.fetchone()
            if not row:
                return {'ok': False, 'error': 'Replay run not found.'}
            cur.execute("""
                SELECT * FROM intraday_replay_trades WHERE run_id = %s ORDER BY entry_time ASC
            """, (run_id,))
            trades = _dict_rows(cur.fetchall())
            cur.execute("""
                SELECT ts, trading_date, sim_time, ticker, event_type, score, reason
                FROM intraday_replay_events WHERE run_id = %s ORDER BY id ASC
            """, (run_id,))
            events = _dict_rows(cur.fetchall())
    finally:
        conn.close()
    return {'ok': True, 'run': _replay_run_row_to_dict(row), 'trades': trades, 'events': events}


def list_intraday_replay_runs(limit: int = 30) -> Dict[str, Any]:
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.', 'runs': []}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("SELECT * FROM intraday_replay_runs ORDER BY created_at DESC LIMIT %s", (limit,))
            rows = cur.fetchall()
    finally:
        conn.close()
    return {'ok': True, 'runs': [_replay_run_row_to_dict(r) for r in rows]}


def delete_intraday_replay_run(run_id: int) -> Dict[str, Any]:
    with INTRADAY_REPLAY_LOCK:
        if run_id in INTRADAY_REPLAY_THREADS:
            return {'ok': False, 'error': 'This run is still active -- stop it first before deleting.'}
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    try:
        with conn, conn.cursor() as cur:
            cur.execute("DELETE FROM intraday_replay_runs WHERE id = %s", (run_id,))
            deleted = cur.rowcount
    finally:
        conn.close()
    if not deleted:
        return {'ok': False, 'error': 'Replay run not found.'}
    return {'ok': True, 'message': f'Deleted replay run {run_id} and its trades/events.'}


def delete_all_intraday_replay_runs() -> Dict[str, Any]:
    with INTRADAY_REPLAY_LOCK:
        active = list(INTRADAY_REPLAY_THREADS.keys())
    if active:
        return {'ok': False, 'error': f'Run(s) {active} are still active -- stop them first before deleting all replay data.'}
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'error': 'DATABASE_URL not set.'}
    try:
        with conn, conn.cursor() as cur:
            cur.execute("DELETE FROM intraday_replay_runs")
            deleted = cur.rowcount
    finally:
        conn.close()
    return {'ok': True, 'message': f'Deleted all {deleted} replay run(s), their trades, and their decision logs.'}


def run_historical_backtest(market: str, horizon: str, start_date: Optional[str] = None, end_date: Optional[str] = None,
                            universe_limit: Optional[int] = None, top_n: Optional[int] = None,
                            rebalance_step_days: Optional[int] = None, learning_mode: str = 'raw',
                            commit_learning: bool = False, require_cap_filter: bool = True) -> Dict[str, Any]:
    """commit_learning controls whether this run is allowed to WRITE into
    strategy_signal_stats (the shared pattern/regime memory that 'learned' mode
    reads from). Defaults to False: research/comparison/replication runs must
    opt in explicitly with commit_learning=True. This prevents a run from
    contaminating the evidence base that a sibling or subsequent run reads,
    which was previously making 'learned' mode a moving target between
    otherwise-identical reruns.

    require_cap_filter only applies to horizon='intraday' (see
    run_intraday_historical_backtest's own docstring for why) -- swing/positional
    backtests are unaffected and keep scanning the full configured universe."""
    if not BACKTEST_ENABLED:
        return {'ok': False, 'error': 'Backtesting is disabled by BACKTEST_ENABLED=false'}
    market, horizon = validate_market_horizon(market, horizon)
    if horizon == 'intraday':
        # Intraday needs same-day minute-bar replay against the live exit engine,
        # which is structurally different from the day/week swing simulation below
        # (which uses daily bars and a multi-session hold). See
        # run_intraday_historical_backtest() docstring for what it replays and its
        # documented simplifications/limits.
        return run_intraday_historical_backtest(market, start_date, end_date, universe_limit, top_n, commit_learning, require_cap_filter=require_cap_filter)
    learning_mode = 'learned' if str(learning_mode or 'raw').lower() == 'learned' else 'raw'
    universe_limit = int(universe_limit or BACKTEST_UNIVERSE_LIMIT)
    top_n = int(top_n or BACKTEST_TOP_N)
    step = int(rebalance_step_days or BACKTEST_REBALANCE_STEP_DAYS)
    end_dt = datetime.date.fromisoformat(end_date) if end_date else datetime.date.today()
    start_dt = datetime.date.fromisoformat(start_date) if start_date else end_dt - datetime.timedelta(days=365 * BACKTEST_DEFAULT_LOOKBACK_YEARS)
    universe = load_market_universe(market)[:max(1, universe_limit)]
    fingerprint_payload = backtest_fingerprint_payload(market, horizon, start_dt, end_dt, universe_limit, top_n, step, universe, learning_mode=learning_mode)
    fingerprint_hash = backtest_fingerprint_hash(fingerprint_payload)

    if BACKTEST_DUPLICATE_PROTECTION and not BACKTEST_ALLOW_DUPLICATE_LEARNING:
        duplicate = find_duplicate_backtest_run(fingerprint_hash)
        if duplicate:
            payload = load_backtest_run_payload(int(duplicate['id']))
            if payload.get('ok'):
                run = payload.get('run') or {}
                metrics = dict(payload.get('metrics') or {})
                metrics.setdefault('total_trades', run.get('total_trades') or 0)
                metrics.setdefault('win_rate_pct', run.get('win_rate_pct'))
                metrics.setdefault('expectancy_pct', run.get('expectancy_pct'))
                metrics.setdefault('max_drawdown_pct', run.get('max_drawdown_pct'))
                metrics['ok'] = True
                metrics['run_id'] = run.get('id')
                metrics['duplicate_cached'] = True
                metrics['duplicate_of_run_id'] = run.get('id')
                metrics['learning_applied'] = False
                metrics['recent_trades'] = (payload.get('trades') or [])[:60]
                metrics['stock_stats'] = payload.get('per_stock') or []
                metrics['duplicate_protection'] = {
                    'enabled': True,
                    'duplicate_found': True,
                    'existing_run_id': run.get('id'),
                    'existing_created_at': run.get('created_at'),
                    'fingerprint_hash': fingerprint_hash,
                    'learning_applied': False,
                    'plain_summary': 'This exact backtest was already learned from, so the app showed the existing result and did not double-count the same evidence.'
                }
                return metrics

    all_hist: Dict[str, Any] = {}
    started = utc_now_naive()
    source_info = get_market_data_source_info(market, 'historical_backtest')
    source_info['price_mode'] = get_backtest_price_mode_info()
    source_info['data_integrity_guard'] = data_integrity_thresholds()
    deadline_ts = time.monotonic() + max(8, BACKTEST_MAX_RUNTIME_SECONDS)
    skipped_errors = []
    skipped_symbols = []
    skipped_quality = []
    quality_passed = []

    def fetch_hist(ticker):
        try:
            price_mode_info = get_backtest_price_mode_info()
            h = yf.Ticker(ticker).history(
                start=(start_dt - datetime.timedelta(days=220)).isoformat(),
                end=(end_dt + datetime.timedelta(days=10)).isoformat(),
                interval='1d',
                auto_adjust=bool(price_mode_info.get('yfinance_auto_adjust')),
                actions=True,
                timeout=YF_TIMEOUT,
            )
            if h is not None and not h.empty:
                h = normalize_history_frame(h)
                close_series = history_series(h, 'Close')
                if close_series is None or close_series.empty:
                    return ticker, None, 'No usable close-price history from data provider.'
                h = h.loc[close_series.index]
                split_dates = detect_split_dates(h)
                integrity = analyze_backtest_data_integrity(ticker, h, market, split_dates=split_dates)
                if not integrity.get('ok'):
                    return ticker, None, 'Data integrity guard blocked learning: ' + '; '.join((integrity.get('warnings') or [])[:2]), {'data_integrity': integrity}
                quality = analyze_historical_stock_quality(ticker, h, market)
                if not quality.get('ok'):
                    quality['data_integrity'] = integrity
                    return ticker, None, quality.get('reason') or 'Failed active/liquid quality filter.', quality
                quality['data_integrity'] = integrity
                quality['split_dates'] = split_dates
                return ticker, h, None, quality
            return ticker, None, 'No historical data from Yahoo/yfinance. Symbol may be changed, delisted, or unavailable.', None
        except BaseException as e:
            return ticker, None, str(e)[:180] or 'Data provider error.', None

    all_split_dates: Dict[str, set] = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, min(BACKTEST_MAX_WORKERS, 4))) as ex:
        for ticker, h, skip_reason, quality in ex.map(fetch_hist, universe):
            if h is not None and not h.empty and len(h) >= BACKTEST_MIN_HISTORY_DAYS + 5:
                all_hist[ticker] = h
                all_split_dates[ticker] = (quality or {}).get('split_dates') or set()
                if quality and len(quality_passed) < 80:
                    quality_passed.append({'ticker': ticker, 'metrics': quality.get('metrics'), 'reason': quality.get('reason')})
            else:
                item = {
                    'ticker': ticker,
                    'reason': skip_reason or f'Not enough clean history. Minimum required: {BACKTEST_MIN_HISTORY_DAYS} daily bars.'
                }
                if quality:
                    item['quality'] = quality
                    if len(skipped_quality) < 80:
                        skipped_quality.append(item)
                if len(skipped_symbols) < 80:
                    skipped_symbols.append(item)
    if not all_hist:
        return {'ok': False, 'error': 'No historical bars available for selected universe/date range.'}
    calendar = []
    for h in all_hist.values():
        calendar = [idx for idx in h.index if idx.date().isoformat() >= start_dt.isoformat() and idx.date().isoformat() <= end_dt.isoformat()]
        if len(calendar) > 10:
            break
    trades = []
    strict_rejections: List[Dict[str, Any]] = []
    strict_rejection_counts: Dict[str, int] = {}
    strict_empty_test_days = 0
    strict_watch_only_tested = 0
    skipped_for_corporate_action = 0
    # 'learned' mode applies everything the system has learned so far (pattern-memory
    # score adjustments + per-stock historical strength) before ranking/filtering each
    # test day. 'raw' mode never applies these, so it always replays the base strategy
    # untouched by any accumulated learning -- this is the control group.
    stock_memory_for_learning = get_stock_backtest_strength(market, horizon, list(all_hist.keys())) if learning_mode == 'learned' else {}
    for cal_pos in range(0, len(calendar), max(step, 1)):
        if time.monotonic() > deadline_ts:
            break
        signal_ts = calendar[cal_pos]
        day_candidates = []
        for ticker, h in all_hist.items():
            try:
                eligible_idx = [i for i, idx in enumerate(h.index) if idx <= signal_ts]
                if not eligible_idx:
                    continue
                idx = eligible_idx[-1]
                if idx < BACKTEST_MIN_HISTORY_DAYS or idx + 1 >= len(h):
                    continue
                snap = historical_snapshot_at(ticker, h, idx)
                if not snap:
                    continue
                snap = score_historical_candidate(snap, market, horizon)
                if snap.get('avg_volume_20', 0) <= 0:
                    continue
                liq_ok, liq_reason = snapshot_passes_liquidity(snap, market)
                if not liq_ok:
                    bump_count(strict_rejection_counts, 'quality/liquidity gate')
                    if len(strict_rejections) < 80:
                        strict_rejections.append({'ticker': ticker, 'date': str(signal_ts.date()), 'reason': 'Quality/liquidity gate: ' + liq_reason, 'score': snap.get('final_pre_ai_score')})
                    continue
                snap['quality_gate'] = {'passed': True, 'reason': liq_reason}
                day_candidates.append((ticker, idx, snap))
            except BaseException as e:
                if len(skipped_errors) < 20:
                    skipped_errors.append({'ticker': ticker, 'date': str(signal_ts), 'error': str(e)[:160]})
                continue
        if learning_mode == 'learned' and day_candidates:
            regime_for_memory = None
            if day_candidates:
                regime_for_memory = (day_candidates[0][2].get('regime_info') or {}).get('regime')
            memory = get_strategy_memory(market, horizon, regime=regime_for_memory)
            for ticker, idx, snap in day_candidates:
                adj = strategy_memory_adjustment(snap, memory, regime=regime_for_memory)
                snap['strategy_memory_adjustment'] = adj
                snap['strategy_pattern_key'] = backtest_pattern_key(snap)
                if adj:
                    snap['final_pre_ai_score'] = round(float(snap.get('final_pre_ai_score', 0)) + adj, 2)
        # Strict Learning Mode makes the past simulation match the future policy:
        # do not force low-score/low-volume/weak-RR setups just to fill Top N.
        day_candidates.sort(key=lambda item: item[2].get('final_pre_ai_score', 0), reverse=True)
        if STRICT_LEARNING_ENABLED:
            strict_day_candidates = []
            for ticker, idx, snap in day_candidates:
                stock_mem_for_ticker = stock_memory_for_learning if learning_mode == 'learned' else None
                review = strict_learning_review(snap, market, horizon, engine='backtest', market_context=snap.get('regime_info'),
                                                stock_memory=stock_mem_for_ticker)
                snap['strict_learning'] = review
                snap['strict_learning_verdict'] = review.get('verdict')
                # For historical research we block true no-trade setups, but by default
                # still test watch-only setups so the system has enough examples to learn from.
                # Live/paper automation remains stricter and can block these entries.
                verdict = review.get('verdict')
                if verdict == 'no_trade' or (verdict == 'watch_only' and not STRICT_BACKTEST_ALLOW_WATCH_ONLY):
                    label = strict_rejection_label_from_review(review)
                    bump_count(strict_rejection_counts, label)
                    if len(strict_rejections) < 80:
                        strict_rejections.append({'ticker': ticker, 'date': str(signal_ts.date()), 'reason': '; '.join((review.get('hard_blocks') or review.get('cautions') or [])[:2]), 'score': review.get('score_before'), 'label': label})
                    continue
                if verdict == 'watch_only':
                    strict_watch_only_tested += 1
                    snap['strict_learning_warning'] = '; '.join((review.get('cautions') or [])[:2])
                snap['strict_score_after'] = review.get('score_after')
                strict_day_candidates.append((ticker, idx, snap))
            if day_candidates and not strict_day_candidates:
                strict_empty_test_days += 1
            strict_day_candidates.sort(key=lambda item: item[2].get('strict_score_after', item[2].get('final_pre_ai_score', 0)), reverse=True)
            day_candidates = strict_day_candidates
        for ticker, idx, snap in day_candidates[:top_n]:
            ticker_hist = all_hist[ticker]
            hold_sessions = 1 if horizon == 'day' else 5
            exit_limit_idx = min(idx + 1 + hold_sessions, len(ticker_hist) - 1)
            ticker_splits = all_split_dates.get(ticker) or set()
            if ticker_splits:
                window_dates = {
                    ticker_hist.index[j].date() if hasattr(ticker_hist.index[j], 'date') else ticker_hist.index[j]
                    for j in range(idx + 1, min(exit_limit_idx + 1, len(ticker_hist)))
                }
                if window_dates & ticker_splits:
                    skipped_for_corporate_action += 1
                    continue
            trade = simulate_backtest_trade(ticker, ticker_hist, idx, snap, horizon)
            if trade:
                trade['market'] = market
                trade['horizon'] = horizon
                trade['strict_learning_verdict'] = snap.get('strict_learning_verdict')
                trade['strict_learning_warning'] = snap.get('strict_learning_warning')
                if snap.get('strict_learning_warning'):
                    trade['failure_reason'] = trade.get('failure_reason') or 'strict_warning_setup'
                    trade['lesson_summary'] = (trade.get('lesson_summary') or '') + (' Strict note: ' + str(snap.get('strict_learning_warning'))[:220])
                trades.append(trade)
    metrics = compute_backtest_metrics(trades)
    metrics.update(compute_split_and_benchmark_metrics(trades, all_hist, start_dt, end_dt))
    metrics.update({'start_date': start_dt.isoformat(), 'end_date': end_dt.isoformat(), 'universe_size_requested': universe_limit, 'universe_size_with_data': len(all_hist), 'top_n': top_n, 'rebalance_step_days': step, 'source': source_info, 'lookahead_policy': 'No future bars used for signal creation; entry is next session open; free historical mode excludes non-point-in-time fundamentals/news. Current macro/news risk is used only for forward scans/trading, not old-date backtests.', 'partial': time.monotonic() > deadline_ts, 'runtime_limit_seconds': BACKTEST_MAX_RUNTIME_SECONDS, 'skipped_errors': skipped_errors, 'skipped_symbols': skipped_symbols, 'skipped_quality': skipped_quality, 'skipped_for_corporate_action': skipped_for_corporate_action, 'quality_passed_sample': quality_passed, 'quality_filter': {'enabled': QUALITY_STOCK_FILTER_ENABLED, 'thresholds': quality_thresholds_for_market(market), 'policy': 'Backtests include only active, liquid, tradeable symbols with usable price and volume history.'}, 'data_integrity_guard': {'enabled': BACKTEST_DATA_INTEGRITY_ENABLED, 'price_mode': get_backtest_price_mode_info(), 'thresholds': data_integrity_thresholds(), 'policy': 'Backtests store the selected raw/adjusted price mode and block suspicious candle data before learning from it. Confirmed stock splits/bonus issues are detected via yfinance corporate-action data and excluded both from the integrity penalty and from any trade whose holding window would straddle the split, so a real split cannot masquerade as a fake stop-loss/target hit.'}, 'exit_aware_learning_policy': backtest_exit_learning_policy(), 'duplicate_protection': {'enabled': BACKTEST_DUPLICATE_PROTECTION, 'duplicate_found': False, 'fingerprint_hash': fingerprint_hash, 'learning_applied': True, 'plain_summary': 'Exact repeated backtests are protected from double-counting. Same market, dates, universe, filters, and settings will reuse the old result instead of inflating learning.'}, 'stock_selection_policy': {'quality_universe_step': 'First choose the requested market universe, then keep only active/liquid stocks with enough clean price and volume history.', 'daily_pick_step': 'On each old test date, every quality stock is scored using trend, RSI, MACD, volume, risk/reward, market type, pattern memory, and stock-specific history. The top ranked setups are tested only if strict filters allow them.', 'not_random': True}, 'known_symbol_aliases': KNOWN_TICKER_ALIASES, 'strict_learning': {'enabled': STRICT_LEARNING_ENABLED, 'mode': STRICT_BACKTEST_RELAXED_LABEL, 'policy': 'balanced research mode: block true no-trade setups, but still test watch-only setups so the system has enough history to learn from; live automation stays stricter', 'rejected_setups_sample': strict_rejections, 'rejection_counts': strict_rejection_counts, 'empty_test_days': strict_empty_test_days, 'watch_only_setups_tested': strict_watch_only_tested, 'allow_watch_only_in_backtest': STRICT_BACKTEST_ALLOW_WATCH_ONLY, 'architecture': strict_learning_architecture()}})
    metrics['learning_mode'] = learning_mode
    metrics['learning_mode_note'] = (
        'Raw mode replays the base strategy exactly as originally coded, ignoring any pattern/regime memory learned since.'
        if learning_mode == 'raw' else
        'Learned mode applies the pattern-memory score adjustments and per-stock historical strength learned from past backtests before ranking/filtering each test day.'
    )
    run_id = persist_backtest_result(market, horizon, start_dt, end_dt, universe_limit, top_n, step, trades, metrics, started, fingerprint_hash=fingerprint_hash, fingerprint_payload=fingerprint_payload, learning_applied=commit_learning)
    metrics['commit_learning'] = commit_learning
    metrics['commit_learning_note'] = (
        'This run WROTE its results into strategy_signal_stats and will influence future learned-mode runs.'
        if commit_learning else
        'This run did NOT write into strategy_signal_stats (research/comparison mode). It reflects the memory state as of when it started, and it will not change what any other run sees.'
    )
    metrics['run_id'] = run_id
    metrics['recent_trades'] = trades[-60:][::-1]
    metrics['ok'] = True
    return metrics


def aggregate_stock_backtest_rows(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    buckets: Dict[str, List[Dict[str, Any]]] = {}
    for r in rows:
        buckets.setdefault(r.get('ticker') or 'UNKNOWN', []).append(dict(r))
    stats = []
    for ticker, trades in buckets.items():
        rets = [float(t.get('net_return_pct') or 0) for t in trades]
        wins = [r for r in rets if r > 0]
        losses = [r for r in rets if r <= 0]
        outcomes, reasons, regimes = {}, {}, {}
        for t in trades:
            outcomes[t.get('outcome') or 'unknown'] = outcomes.get(t.get('outcome') or 'unknown', 0) + 1
            if t.get('failure_reason'):
                reasons[t.get('failure_reason')] = reasons.get(t.get('failure_reason'), 0) + 1
            regimes[t.get('regime') or 'unknown'] = regimes.get(t.get('regime') or 'unknown', 0) + 1
        top_reason = max(reasons.items(), key=lambda kv: kv[1])[0] if reasons else None
        stats.append({
            'ticker': ticker,
            'trades': len(rets),
            'win_rate_pct': round((len(wins) / len(rets)) * 100, 1) if rets else None,
            'expectancy_pct': round(float(np.mean(rets)), 3) if rets else None,
            'avg_win_pct': round(float(np.mean(wins)), 3) if wins else None,
            'avg_loss_pct': round(float(np.mean(losses)), 3) if losses else None,
            'best_trade_pct': round(max(rets), 3) if rets else None,
            'worst_trade_pct': round(min(rets), 3) if rets else None,
            'target_hits': outcomes.get('target_hit', 0),
            'stop_hits': outcomes.get('stop_loss_hit', 0),
            'horizon_exits': outcomes.get('horizon_exit', 0),
            'top_failure_reason': top_reason,
            'dominant_regime': max(regimes.items(), key=lambda kv: kv[1])[0] if regimes else None,
            'last_signal_date': max([str(t.get('signal_date')) for t in trades if t.get('signal_date')] or ['']),
            'lesson': (f"Avoid or require stronger confirmation when {top_reason.replace('_', ' ')} repeats." if top_reason else 'No repeated failure pattern yet.'),
        })
    stats.sort(key=lambda x: ((x.get('trades') or 0), (x.get('expectancy_pct') or -999)), reverse=True)
    return stats[:BACKTEST_STOCK_STATS_LIMIT]


def _backtest_config_key(run: Dict[str, Any]) -> Optional[tuple]:
    """Identity of 'the same test, run again' -- same market/horizon/window/universe/
    top_n/rebalance/learning_mode. Deliberately ignores fingerprint_hash (which for
    'learned' mode changes every time memory changes) so a genuine rerun of the same
    experiment is still recognized as a rerun even though its hash differs."""
    cfg = run.get('config_json')
    if isinstance(cfg, str):
        try:
            cfg = json.loads(cfg)
        except Exception:
            cfg = {}
    fp = (cfg or {}).get('fingerprint_payload') or {}
    learning_mode = fp.get('learning_mode') or ('learned' if run.get('learning_mode') == 'learned' else 'raw')
    try:
        return (
            run.get('market'), run.get('horizon'),
            str(run.get('start_date')), str(run.get('end_date')),
            int(run.get('universe_limit') or 0), int(run.get('top_n') or 0),
            int(run.get('rebalance_step_days') or 0), str(learning_mode),
        )
    except Exception:
        return None


def _rerun_delta(prev: Dict[str, Any], cur: Dict[str, Any]) -> Dict[str, Any]:
    def d(key, decimals=3):
        a, b = prev.get(key), cur.get(key)
        if a is None or b is None:
            return None
        return round(float(b) - float(a), decimals)
    delta_pf = d('profit_factor', 3)
    delta_exp = d('expectancy_pct', 3)
    delta_win = d('win_rate_pct', 1)
    if delta_pf is None and delta_exp is None:
        verdict = 'incomplete_data'
    elif (delta_pf or 0) > 0.001 and (delta_exp or 0) >= 0:
        verdict = 'improved'
    elif (delta_pf or 0) < -0.001 and (delta_exp or 0) <= 0:
        verdict = 'worse'
    elif delta_pf == 0 and delta_exp == 0:
        verdict = 'no_change'
    else:
        verdict = 'mixed'
    return {
        'is_rerun': True,
        'previous_run_id': prev.get('id'),
        'delta_profit_factor': delta_pf,
        'delta_expectancy_pct': delta_exp,
        'delta_win_rate_pct': delta_win,
        'delta_sharpe': d('sharpe', 2),
        'delta_max_drawdown_pct': d('max_drawdown_pct', 2),
        'verdict': verdict,
    }


def attach_rerun_info(runs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Mutates and returns `runs`, tagging each one with `rerun_info` describing
    whether it's a fresh test or a rerun of an earlier identical config, and if so
    the stat deltas vs that earlier run. Also assigns a stable `display_number`
    (position in chronological/id order) so the UI can show a real, consistent
    backtest number instead of just a timestamp."""
    by_id_asc = sorted(runs, key=lambda r: int(r.get('id') or 0))
    last_seen_for_key: Dict[tuple, Dict[str, Any]] = {}
    number_for_id: Dict[int, int] = {}
    for i, r in enumerate(by_id_asc):
        number_for_id[int(r.get('id') or 0)] = i + 1
        key = _backtest_config_key(r)
        if key is not None and key in last_seen_for_key:
            r['rerun_info'] = _rerun_delta(last_seen_for_key[key], r)
        else:
            r['rerun_info'] = {'is_rerun': False}
        if key is not None:
            last_seen_for_key[key] = r
    for r in runs:
        r['display_number'] = number_for_id.get(int(r.get('id') or 0), r.get('id'))
    return runs


def find_previous_same_config_run(cur, run: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Find the most recent earlier backtest_runs row that matches `run`'s exact
    config (same identity used by attach_rerun_info), used to diff per-stock stats
    between an original run and its rerun."""
    key = _backtest_config_key(run)
    if key is None:
        return None
    cur.execute("""
        SELECT id, created_at, market, horizon, start_date, end_date, universe_limit, top_n,
               rebalance_step_days, total_trades, win_rate_pct, expectancy_pct, profit_factor,
               sharpe, sortino, max_drawdown_pct, config_json
        FROM backtest_runs
        WHERE market=%s AND horizon=%s AND start_date=%s AND end_date=%s
              AND universe_limit=%s AND top_n=%s AND rebalance_step_days=%s AND id < %s
        ORDER BY id DESC LIMIT 5
    """, (run.get('market'), run.get('horizon'), run.get('start_date'), run.get('end_date'),
          run.get('universe_limit'), run.get('top_n'), run.get('rebalance_step_days'), run.get('id')))
    for candidate in cur.fetchall():
        cand = dict(candidate)
        if _backtest_config_key(cand) == key:
            return cand
    return None


def get_research_dashboard(limit: int = 20) -> Dict[str, Any]:
    conn = get_db_connection()
    if conn is None:
        return {'error': 'DATABASE_URL not set; research history disabled.', 'latest': [], 'strategy_memory': [], 'per_stock': [], 'recent_lessons': []}
    runs, memory, trade_rows, lessons = [], [], [], []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            # Pull a larger pool than `limit` so rerun-chain detection (attach_rerun_info)
            # can find an earlier run even if it has scrolled past the displayed page;
            # only the first `limit` rows are actually shown.
            rerun_pool_limit = max(int(limit), 200)
            cur.execute("""
                SELECT id, created_at, market, horizon, start_date, end_date, universe_limit, top_n,
                       rebalance_step_days, total_trades, win_rate_pct, expectancy_pct, avg_trade_pct, profit_factor,
                       sharpe, sortino, max_drawdown_pct, best_regime, worst_regime, status, error, metrics_json,
                       config_json, fingerprint_hash, duplicate_of_run_id, learning_applied
                FROM backtest_runs
                ORDER BY created_at DESC
                LIMIT %s
            """, (rerun_pool_limit,))
            runs = cur.fetchall()
            latest_run_id = runs[0]['id'] if runs else None
            if latest_run_id:
                cur.execute("""
                    SELECT ticker, market, horizon, signal_date, entry_date, exit_date, net_return_pct, outcome,
                           regime, score, failure_reason, lesson_summary, pattern_key, pattern_verdict
                    FROM backtest_trades
                    WHERE run_id=%s
                    ORDER BY signal_date DESC
                    LIMIT 5000
                """, (latest_run_id,))
                trade_rows = cur.fetchall()
            cur.execute("""
                SELECT market, horizon, regime, pattern_key, trades, win_rate_pct, expectancy_pct, confidence_adjustment, notes, updated_at
                FROM strategy_signal_stats
                ORDER BY updated_at DESC, trades DESC
                LIMIT 60
            """)
            memory = cur.fetchall()
            cur.execute("""
                SELECT created_at, market, horizon, ticker, signal, outcome_label, outcome_status,
                       failure_reason, lesson_summary, actual_gain_pct
                FROM prediction_lessons
                ORDER BY created_at DESC
                LIMIT 40
            """)
            lessons = cur.fetchall()
    finally:
        conn.close()
    per_stock = aggregate_stock_backtest_rows([dict(r) for r in trade_rows])
    all_runs = attach_rerun_info([dict(r) for r in runs])
    return {
        'latest': all_runs[:limit],
        'strategy_memory': [dict(r) for r in memory],
        'per_stock': per_stock,
        'recent_lessons': [dict(r) for r in lessons],
        'config': {
            'backtest_enabled': BACKTEST_ENABLED,
            'default_lookback_years': BACKTEST_DEFAULT_LOOKBACK_YEARS,
            'default_universe_limit': BACKTEST_UNIVERSE_LIMIT,
            'default_top_n': BACKTEST_TOP_N,
            'rebalance_step_days': BACKTEST_REBALANCE_STEP_DAYS,
            'stock_stats_limit': BACKTEST_STOCK_STATS_LIMIT,
            'execution_costs_bps': EXECUTION_SLIPPAGE_BPS + EXECUTION_SPREAD_BPS + EXECUTION_FEE_BPS,
            'uses_claude': False,
            'quality_stock_filter': {'enabled': QUALITY_STOCK_FILTER_ENABLED, 'thresholds': quality_thresholds_for_market('IN'), 'plain_summary': 'Backtests skip inactive, illiquid, unavailable, renamed, or low-turnover stocks so the system learns only from tradeable quality symbols.'},
            'duplicate_learning_protection': {'enabled': BACKTEST_DUPLICATE_PROTECTION, 'allow_duplicate_learning': BACKTEST_ALLOW_DUPLICATE_LEARNING, 'plain_summary': 'If the exact same backtest was already learned from, the app shows the existing result and does not count the same trades again.'},
            'stock_selection_policy': {'plain_summary': 'Quality stocks are chosen by tradeability first: clean data, active symbol, enough volume, enough turnover, and enough history. Best picks per test day are then ranked by bullish setup, volume confirmation, risk/reward, market type, past pattern behavior, and stock-specific behavior.'},
            'macro_risk_layer': {'enabled': MACRO_RISK_ENABLED, 'plain_summary': 'Forward scans/trading watch war, trade deals, tariffs, rates, oil shocks, regulation and other macro/news risks. Historical backtests do not use today’s news.'},
            'data_integrity_guard': {'enabled': BACKTEST_DATA_INTEGRITY_ENABLED, 'price_mode': get_backtest_price_mode_info(), 'thresholds': data_integrity_thresholds(), 'plain_summary': 'Backtests record whether prices are raw or adjusted and block suspicious candle data before it can teach the learning engine.'},
            'exit_aware_learning_policy': backtest_exit_learning_policy(),
            'learning_policy': 'failed predictions and failed backtest patterns are converted into pattern memory; future scans penalize repeated weak setups and reward historically durable setups',
            'strict_learning_mode': strict_learning_architecture(),
            'lookahead_policy': 'uses bars available before each simulated signal date; free historical mode excludes non-point-in-time fundamentals/news to avoid lookahead bias'
        }
    }

def ai_rank_candidates(candidates: List[Dict[str, Any]], market: str, horizon: str, market_context: Optional[Dict[str, Any]], learning_context: Optional[Dict[str, Any]] = None) -> Tuple[List[Dict[str, Any]], str]:
    api_key = os.environ.get('ANTHROPIC_API_KEY')
    if not api_key:
        return deterministic_rank_candidates(candidates, market, horizon), 'deterministic-fallback-no-api-key'

    estimated_input_tokens = SCAN_ESTIMATED_INPUT_TOKENS_BASE + min(len(candidates), DEEP_ANALYSIS_LIMIT) * SCAN_ESTIMATED_INPUT_TOKENS_PER_CANDIDATE
    estimated_cost = calculate_claude_cost(estimated_input_tokens, SCAN_ESTIMATED_OUTPUT_TOKENS)
    budget = get_ai_budget_status(estimated_cost.get('cost_inr', 0))
    if not budget.get('allowed'):
        print(f"[AI-BUDGET] Claude ranking skipped for {market}/{horizon}: {budget.get('reasons')}. Using deterministic ranker.")
        ranked = deterministic_rank_candidates(candidates, market, horizon)
        for item in ranked:
            item['ai_budget_blocked'] = True
            item['ai_budget_reasons'] = budget.get('reasons')
        return ranked, 'deterministic-fallback-ai-budget-guard'

    horizon_label = 'next 1 trading day' if horizon == 'day' else 'next 5 trading days (1 week)'
    today = datetime.date.today().strftime('%A, %B %d, %Y')
    compact_candidates = candidates[:DEEP_ANALYSIS_LIMIT]

    prompt = f"""You are ranking public stock opportunities for an educational market-scanning app. Today is {today}.

Use transparent, publicly documented analysis methods only. Do not claim to follow, copy, reverse-engineer, or replicate any specific certified financial adviser's proprietary methodology. Do not present the output as financial advice.

Market: {market}
Horizon: {horizon_label}
Market volatility context: {json.dumps(market_context or {}, default=_json_safe)}
Learning context from prior verified predictions: {json.dumps(learning_context or {}, default=_json_safe)}

The app has already applied a multi-stage funnel: liquidity, momentum, technical screening, fundamentals, and news sentiment. Rank the best opportunities from these deep-analysis candidates.

Framework to apply:
- Technicals: RSI, MACD, MA20/MA50/MA200 alignment, Bollinger Band position, volume confirmation, 20-day support/resistance, 52-week context.
- Fundamentals: revenue growth, EPS/earnings growth, ROE, debt-to-equity, operating/free cash flow, profit margin, valuation where available.
- News: headline sentiment and risk catalysts. Negative legal/regulatory/guidance headlines must reduce confidence.
- Risk management: set entry near current price, stop-loss around support/volatility, target near resistance or risk/reward extension.
- Learning loop: if prior verified predictions show repeated failure patterns, reduce confidence for similar setups and mention the adjustment briefly.

Return ONLY a valid JSON array of exactly {FINAL_PICK_LIMIT} items. No markdown. Each item must have:
rank, ticker, company, sector, current_price, signal, predicted_gain, gain_number, entry_price, target_exit_pct, stop_loss_pct, target_price, stop_price, risk_reward, confidence, rsi_reading, macd_reading, volume_reading, fundamental_reading, news_reading, horizon_tags, reasoning.

Rules:
- signal must be BUY, WATCH, or AVOID. Use WATCH instead of HOLD because users may not own the stock yet.
- confidence is an integer 0-100.
- risk_reward must look like "2.1:1".
- reasoning must cite actual numbers from the provided data and be 2-3 concise sentences.
- Do not invent backtest win rates or non-provided facts.

CANDIDATES_JSON:
{json.dumps(compact_candidates, separators=(',', ':'), default=_json_safe)}
"""
    try:
        client = anthropic.Anthropic(api_key=api_key)
        model_name = os.environ.get('ANTHROPIC_MODEL', 'claude-sonnet-5')
        response = client.messages.create(
            model=model_name,
            max_tokens=5000,
            messages=[{'role': 'user', 'content': prompt}],
        )
        usage = getattr(response, 'usage', None)
        if usage:
            log_api_cost(
                'anthropic_ai_ranking', market, horizon, model_name,
                int(getattr(usage, 'input_tokens', 0) or 0),
                int(getattr(usage, 'output_tokens', 0) or 0),
                notes='Final AI ranking for locked market scan',
                metadata={'candidate_count': len(compact_candidates)}
            )
        text_blocks = [b.text for b in response.content if getattr(b, 'type', None) == 'text']
        if not text_blocks:
            raise RuntimeError(f'Claude returned no text content (stop_reason={response.stop_reason}).')
        text = re.sub(r'```json|```', '', text_blocks[0].strip()).strip()
        try:
            picks = json.loads(text)
        except json.JSONDecodeError:
            match = re.search(r'\[[\s\S]*\]', text)
            if not match:
                raise
            picks = json.loads(match.group())
        return validate_ranked_picks(picks, candidates, horizon), model_name
    except Exception as e:
        print(f"[WARN] AI ranking failed; using deterministic fallback: {e}")
        return deterministic_rank_candidates(candidates, market, horizon), 'deterministic-fallback-ai-error'


def normalize_picks(picks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for i, p in enumerate((picks or [])[:FINAL_PICK_LIMIT], start=1):
        try:
            p['rank'] = int(p.get('rank') or i)
        except Exception:
            p['rank'] = i
        p['signal'] = 'WATCH' if p.get('signal') == 'HOLD' else (p.get('signal') if p.get('signal') in ['BUY', 'WATCH', 'AVOID'] else 'WATCH')
        try:
            p['confidence'] = int(float(p.get('confidence', 50)))
        except Exception:
            p['confidence'] = 50
        p['confidence'] = max(min(p['confidence'], 100), 0)
        for k in ['current_price', 'entry_price', 'target_price', 'stop_price', 'gain_number']:
            if p.get(k) is not None:
                try:
                    p[k] = round(float(p[k]), 2)
                except Exception:
                    pass
        if not p.get('entry_price') and p.get('current_price'):
            p['entry_price'] = p['current_price']
        normalized.append(p)
    return normalized


def _risk_reward_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).replace('x', '').strip()
    try:
        return float(text.split(':')[0])
    except Exception:
        return None


def validate_ranked_picks(picks: List[Dict[str, Any]], candidates: List[Dict[str, Any]], horizon: str) -> List[Dict[str, Any]]:
    """Keep AI output grounded in the candidate data and risk controls.

    The AI can format/rank, but the app keeps prices, stop/target sanity, and
    BUY/WATCH/AVOID gates deterministic. This makes the final predictions more
    rigorous and prevents hallucinated tickers or unrealistic risk/reward.
    """
    candidate_map = {str(c.get('ticker', '')).upper(): c for c in candidates}
    normalized = normalize_picks(picks)
    cleaned: List[Dict[str, Any]] = []
    seen = set()

    for p in normalized:
        ticker = str(p.get('ticker', '')).upper()
        c = candidate_map.get(ticker)
        if not ticker or not c or ticker in seen:
            continue
        seen.add(ticker)
        current = float(c.get('current_price') or p.get('current_price') or 0)
        if current <= 0:
            continue

        p['ticker'] = ticker
        p['company'] = p.get('company') or c.get('company') or ticker
        p['sector'] = p.get('sector') or c.get('sector') or 'N/A'
        p['current_price'] = round(current, 2)
        currency = get_currency_info('IN' if ticker.endswith('.NS') else '', ticker)
        p['currency'] = currency['currency']
        p['currency_symbol'] = currency['symbol']

        # Entry must stay close to the current scan price. If the AI drifts too
        # far, use the observed market price from the scan.
        try:
            entry = float(p.get('entry_price') or current)
        except Exception:
            entry = current
        if abs(entry - current) / current > 0.03:
            entry = current
        p['entry_price'] = round(entry, 2)

        support = float(c.get('support_20') or current * 0.97)
        resistance = float(c.get('resistance_20') or current * 1.04)
        try:
            stop_price = float(p.get('stop_price') or support)
        except Exception:
            stop_price = support
        if stop_price >= entry or (entry - stop_price) / entry > 0.10:
            stop_price = min(support, entry * 0.97)
        stop_price = round(max(stop_price, 0.01), 2)
        p['stop_price'] = stop_price

        try:
            target_price = float(p.get('target_price') or resistance)
        except Exception:
            target_price = resistance
        if target_price <= entry:
            target_price = max(resistance, entry * (1.025 if horizon == 'day' else 1.05))
        target_price = round(target_price, 2)
        p['target_price'] = target_price

        risk_pct = max(((entry - stop_price) / entry) * 100, 0.01)
        reward_pct = max(((target_price - entry) / entry) * 100, 0.0)
        rr = round(reward_pct / risk_pct, 2) if risk_pct else 0.0
        p['risk_reward'] = f"{rr}:1"
        p['gain_number'] = round(reward_pct, 2)
        p['predicted_gain'] = f"+{round(reward_pct, 1)}%"
        p['target_exit_pct'] = f"+{round(reward_pct, 1)}%"
        p['stop_loss_pct'] = f"-{round(risk_pct, 1)}%"

        confidence = int(max(min(p.get('confidence', 50), 100), 0))
        # Guardrail: a BUY needs minimum confidence and risk/reward. Otherwise
        # the setup remains visible but becomes WATCH/AVOID.
        if p.get('signal') == 'BUY' and (confidence < MIN_BUY_CONFIDENCE or rr < MIN_BUY_RISK_REWARD):
            p['signal'] = 'WATCH'
        if c.get('news_score', 0) <= -16 and confidence < 72:
            p['signal'] = 'AVOID'
            p['confidence'] = min(confidence, 60)
        else:
            p['confidence'] = confidence

        p['features_json'] = {
            'rsi_14': c.get('rsi_14'),
            'macd_histogram': c.get('macd_histogram'),
            'volume_ratio_vs_20d_avg': c.get('volume_ratio_vs_20d_avg'),
            'price_vs_ma20_pct': c.get('price_vs_ma20_pct'),
            'support_20': c.get('support_20'),
            'resistance_20': c.get('resistance_20'),
            'news_score': c.get('news_score'),
            'learning_penalty': c.get('learning_penalty', 0),
            'learning_patterns_considered': c.get('learning_patterns_considered', {}),
        }
        p['analysis_quality_flags'] = {
            'candidate_verified': True,
            'price_grounded_to_scan': True,
            'risk_reward_recomputed': True,
            'buy_requires_min_confidence': MIN_BUY_CONFIDENCE,
            'buy_requires_min_risk_reward': MIN_BUY_RISK_REWARD,
        }
        cleaned.append(p)

    # If AI output dropped items during validation, fill remaining slots using the
    # deterministic ranker so the UI still has enough grounded picks.
    if len(cleaned) < FINAL_PICK_LIMIT:
        fallback = deterministic_rank_candidates(candidates, '', horizon)
        for p in fallback:
            ticker = str(p.get('ticker', '')).upper()
            if ticker and ticker not in seen:
                seen.add(ticker)
                p['analysis_quality_flags'] = {'candidate_verified': True, 'source': 'deterministic_fill'}
                cleaned.append(p)
            if len(cleaned) >= FINAL_PICK_LIMIT:
                break

    for i, p in enumerate(cleaned[:FINAL_PICK_LIMIT], start=1):
        p['rank'] = i
    return cleaned[:FINAL_PICK_LIMIT]


def get_methodology(funnel_counts: Dict[str, int]) -> Dict[str, Any]:
    return {
        'engine': 'precomputed_background_scan',
        'cache_ttl_minutes': CACHE_TTL_MINUTES,
        'prediction_lock_enabled': PREDICTION_LOCK_ENABLED,
        'lock_policy': 'Daily predictions lock to one result per calendar day; weekly predictions lock to one result per ISO week unless an explicit force scan is run.',
        'accuracy_policy': 'On user scan requests, due unchecked predictions are scored once and then marked checked so they are not scored repeatedly.',
        'funnel_counts': funnel_counts,
        'stages': [
            {'stage': 'Liquidity', 'method': 'Keep active/liquid symbols using 20-day average share volume and 20-day average traded value.'},
            {'stage': 'Momentum', 'method': 'Score 1-week, 1-month and 3-month price change, price vs moving averages, MACD histogram, RSI zone and volume expansion.'},
            {'stage': 'Technical screening', 'method': 'Use RSI, MACD, MA20/MA50/MA200 alignment, Bollinger Band position, support/resistance, volume confirmation and 52-week context.'},
            {'stage': 'Fundamentals', 'method': 'Evaluate revenue growth, EPS/earnings growth, ROE, debt-to-equity, cash flow, margins and valuation where available.'},
            {'stage': 'News sentiment', 'method': 'Apply transparent headline keyword sentiment and downgrade legal/regulatory/guidance risk.'},
            {'stage': 'AI ranking', 'method': 'Only the narrowed 50-100 candidate set is sent to the AI ranker for final reasoning, confidence and risk/reward formatting.'},
            {'stage': 'Post-AI validation', 'method': 'The app rejects hallucinated tickers, grounds prices to the scan, recomputes risk/reward, and downgrades weak BUY signals to WATCH/AVOID.'},
            {'stage': 'Strict Learning Mode', 'method': 'Apply minimum score, reward/risk, volume, regime, pattern-memory and stock-history filters. If edge is weak, show WATCH/AVOID/no-trade instead of forcing a BUY.'},
        ],
        'proprietary_methodology_notice': 'This app uses public, documented technical/fundamental/news frameworks and does not claim to copy any certified financial adviser methodology.',
    }


def get_check_date(market: str, horizon: str, created_at_utc: Optional[datetime.datetime] = None):
    return get_prediction_check_datetime(market, horizon, created_at_utc)


def save_predictions(picks, market, horizon, check_date, prediction_date=None):
    conn = get_db_connection()
    if conn is None:
        return
    prediction_date = prediction_date or datetime.date.today()
    try:
        with conn:
            with conn.cursor() as cur:
                for p in picks:
                    try:
                        cur.execute("""
                            INSERT INTO predictions
                                (prediction_date, market, horizon, ticker, company, rank, signal,
                                 entry_price, predicted_gain_pct, target_price, stop_price,
                                 confidence, reasoning, check_date, features_json)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                            ON CONFLICT (market, horizon, ticker, prediction_date) DO NOTHING
                        """, (
                            prediction_date, market, horizon, p.get('ticker'), p.get('company'), p.get('rank'),
                            'WATCH' if p.get('signal') == 'HOLD' else p.get('signal'),
                            p.get('entry_price') or p.get('current_price'), p.get('gain_number'),
                            p.get('target_price'), p.get('stop_price'), p.get('confidence'),
                            p.get('reasoning'), check_date, json.dumps(p.get('features_json') or {}, default=_json_safe)
                        ))
                    except Exception as e:
                        print(f"[WARN] Could not save prediction for {p.get('ticker')}: {e}")
    except Exception as e:
        print(f"[WARN] save_predictions failed: {e}")
    finally:
        conn.close()

def upsert_scan_cache(market: str, horizon: str, payload: Dict[str, Any], status: str = 'complete', error: Optional[str] = None):
    conn = get_db_connection()
    if conn is None:
        return
    counts = payload.get('funnel_counts', {})
    now = datetime.datetime.now()
    expires_at = now + datetime.timedelta(minutes=CACHE_TTL_MINUTES)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO stock_scan_cache
                        (market, horizon, status, started_at, completed_at, expires_at,
                         total_universe, total_liquid, total_momentum, total_technical, total_deep_candidates,
                         model, prediction_lock_key, locked, results_json, methodology_json, error, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s,%s)
                    ON CONFLICT (market, horizon) DO UPDATE SET
                        status=EXCLUDED.status,
                        started_at=EXCLUDED.started_at,
                        completed_at=EXCLUDED.completed_at,
                        expires_at=EXCLUDED.expires_at,
                        total_universe=EXCLUDED.total_universe,
                        total_liquid=EXCLUDED.total_liquid,
                        total_momentum=EXCLUDED.total_momentum,
                        total_technical=EXCLUDED.total_technical,
                        total_deep_candidates=EXCLUDED.total_deep_candidates,
                        model=EXCLUDED.model,
                        prediction_lock_key=EXCLUDED.prediction_lock_key,
                        locked=EXCLUDED.locked,
                        results_json=EXCLUDED.results_json,
                        methodology_json=EXCLUDED.methodology_json,
                        error=EXCLUDED.error,
                        updated_at=EXCLUDED.updated_at
                """, (
                    market, horizon, status, payload.get('started_at'), payload.get('completed_at'), expires_at,
                    counts.get('total_universe', 0), counts.get('liquidity_pass', 0), counts.get('momentum_pass', 0),
                    counts.get('technical_pass', 0), counts.get('deep_analysis', 0), payload.get('model'),
                    payload.get('prediction_lock_key'), bool(payload.get('locked', True)),
                    json.dumps(payload, default=_json_safe), json.dumps(payload.get('methodology', {}), default=_json_safe), error, now
                ))
    finally:
        conn.close()


def insert_scan_run(market: str, horizon: str, status: str, started_at, completed_at=None, counts=None, error=None):
    conn = get_db_connection()
    if conn is None:
        return
    counts = counts or {}
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO stock_scan_runs
                        (market, horizon, started_at, completed_at, status, total_universe, total_liquid,
                         total_momentum, total_technical, total_deep_candidates, error)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """, (
                    market, horizon, started_at, completed_at, status,
                    counts.get('total_universe', 0), counts.get('liquidity_pass', 0), counts.get('momentum_pass', 0),
                    counts.get('technical_pass', 0), counts.get('deep_analysis', 0), error
                ))
    finally:
        conn.close()


def get_locked_cached_scan(market: str, horizon: str) -> Optional[Dict[str, Any]]:
    if not PREDICTION_LOCK_ENABLED:
        return None
    cached = get_cached_scan(market, horizon)
    if cached and payload_matches_current_lock(cached, horizon):
        cached['locked'] = True
        cached['lock_reused'] = True
        cached['prediction_lock_key'] = cached.get('prediction_lock_key') or get_prediction_lock_key(horizon)
        cached['lock_message'] = 'Prediction is already locked for the current period, so no new paid scan was run.'
        return cached
    return None


def run_market_scan(market: str, horizon: str, force: bool = False) -> Dict[str, Any]:
    started_at = utc_now_naive()
    if not force:
        locked = get_locked_cached_scan(market, horizon)
        if locked:
            print(f"[SCAN] Reusing locked prediction for market={market}, horizon={horizon}, lock={locked.get('prediction_lock_key')}")
            return locked
    if ACCURACY_CHECK_ON_SCAN:
        run_accuracy_check(market=market, horizon=horizon, triggered_by='background-scan')
    print(f"[SCAN] Starting background scan for market={market}, horizon={horizon}, force={force}")
    universe = load_market_universe(market)
    snapshots = download_universe_snapshots(universe)
    liquid = liquidity_filter(snapshots, market)
    momentum = apply_momentum_stage(liquid)
    technical = apply_technical_stage(momentum)
    deep = enrich_deep_candidates(technical)
    learning_context = get_learning_context(market, horizon)
    deep = apply_learning_adjustments(deep, learning_context)
    market_context = get_market_context(market)
    deep = apply_strategy_memory_adjustments(deep, market, horizon, market_context)
    strategy_memory = get_strategy_memory(market, horizon, (market_context or {}).get('regime') if isinstance(market_context, dict) else None)
    combined_learning_context = dict(learning_context or {})
    combined_learning_context['strategy_memory'] = strategy_memory
    picks, model = ai_rank_candidates(deep, market, horizon, market_context, combined_learning_context)
    strict_result = apply_strict_learning_to_picks(picks, deep, market, horizon, market_context)
    picks = strict_result.get('picks', picks)

    check_date = get_check_date(market, horizon, started_at)
    currency = get_currency_info(market)
    # Show the exchange-local verification/exit date to users. The stored check_date is UTC.
    sched = get_market_schedule(market)
    check_local = check_date.replace(tzinfo=datetime.timezone.utc).astimezone(ZoneInfo(sched['tz']))
    exit_date_label = check_local.strftime('%a, %b %d, %I:%M %p')
    for p in picks:
        p['exit_date'] = check_date.isoformat()
        p['exit_date_label'] = exit_date_label
        p['currency'] = p.get('currency') or currency['currency']
        p['currency_symbol'] = p.get('currency_symbol') or currency['symbol']

    counts = {
        'total_universe': len(universe),
        'price_snapshots': len(snapshots),
        'liquidity_pass': len(liquid),
        'momentum_pass': len(momentum),
        'technical_pass': len(technical),
        'deep_analysis': len(deep),
        'final_picks': len(picks),
    }
    methodology = get_methodology(counts)
    methodology['learning_context'] = {'patterns': learning_context.get('patterns', {}), 'lessons_considered': len(learning_context.get('lessons', []))}
    methodology['strategy_memory'] = {'patterns_considered': len(strategy_memory.get('patterns', [])), 'regime': (market_context or {}).get('regime') if isinstance(market_context, dict) else None}
    methodology['execution_policy'] = get_execution_policy()
    methodology['strict_learning_mode'] = strict_result.get('summary')
    methodology['learning_architecture'] = strict_learning_architecture()
    completed_at = utc_now_naive()
    payload = {
        'picks': picks,
        'total_scanned': len(universe),
        'market': market,
        'horizon': horizon,
        'prediction_date': completed_at.date().isoformat(),
        'prediction_lock_key': get_prediction_lock_key(horizon, completed_at),
        'locked': True,
        'lock_policy': 'one prediction per market/horizon lock period unless force scan is explicitly used',
        'timestamp': completed_at.isoformat(),
        'cached': True,
        'stale': False,
        'cache_ttl_minutes': CACHE_TTL_MINUTES,
        'funnel_counts': counts,
        'market_context': market_context,
        'methodology': methodology,
        'model': model,
        'learning_context': methodology.get('learning_context'),
        'strict_learning_mode': strict_result.get('summary'),
        'no_trade_recommendation': bool((strict_result.get('summary') or {}).get('no_trade_recommendation')),
        'execution_policy': get_execution_policy(),
        'ai_budget': get_ai_budget_status(),
        'cost_estimate_next_scan': estimate_next_scan_cost(market, horizon),
        'started_at': started_at.isoformat(),
        'completed_at': completed_at.isoformat(),
    }

    upsert_scan_cache(market, horizon, payload)
    insert_scan_run(market, horizon, 'complete', started_at, completed_at, counts)
    save_predictions(picks, market, horizon, check_date, completed_at.date())
    print(f"[SCAN] Completed {market}/{horizon}: {counts}")
    return payload


def get_cached_scan(market: str, horizon: str) -> Optional[Dict[str, Any]]:
    conn = get_db_connection()
    if conn is None:
        return None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT results_json, updated_at, expires_at, status, error, prediction_lock_key, locked
                FROM stock_scan_cache
                WHERE market=%s AND horizon=%s
                LIMIT 1
            """, (market, horizon))
            row = cur.fetchone()
            if not row or not row.get('results_json'):
                return None
            payload = row['results_json']
            if isinstance(payload, str):
                payload = json.loads(payload)
            now = datetime.datetime.now(row['expires_at'].tzinfo) if row.get('expires_at') and row['expires_at'].tzinfo else datetime.datetime.now()
            expires_at = row.get('expires_at')
            stale = bool(expires_at and expires_at < now)
            updated_at = row.get('updated_at')
            payload['cached'] = True
            payload['stale'] = stale
            payload['cache_updated_at'] = updated_at.isoformat() if updated_at else payload.get('timestamp')
            if updated_at:
                delta = datetime.datetime.now(updated_at.tzinfo) - updated_at if updated_at.tzinfo else datetime.datetime.now() - updated_at
                payload['cache_age_minutes'] = round(delta.total_seconds() / 60, 1)
            payload['cache_status'] = row.get('status')
            if row.get('prediction_lock_key'):
                payload['prediction_lock_key'] = row.get('prediction_lock_key')
            payload['locked'] = bool(row.get('locked', True))
            if payload_matches_current_lock(payload, horizon):
                payload['lock_status'] = 'current_period_locked'
            else:
                payload['lock_status'] = 'previous_period_cache'
            if row.get('error'):
                payload['cache_error'] = row['error']
            return payload
    finally:
        conn.close()



def validate_market_horizon(market: str, horizon: str) -> Tuple[str, str]:
    market = market if market in DEFAULT_UNIVERSES else 'IN'
    horizon = horizon if horizon in HORIZON_DAYS else 'day'
    return market, horizon


def get_scan_cache_status(market: str, horizon: str) -> Dict[str, Any]:
    """Return lightweight cache/job status without requiring a completed payload."""
    conn = get_db_connection()
    if conn is None:
        return {'status': 'disabled', 'error': 'DATABASE_URL not set'}
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT status, started_at, completed_at, updated_at, error, prediction_lock_key, locked, results_json
                FROM stock_scan_cache
                WHERE market=%s AND horizon=%s
                LIMIT 1
            """, (market, horizon))
            row = cur.fetchone()
            if not row:
                return {'status': 'empty', 'market': market, 'horizon': horizon}
            payload = row.get('results_json')
            if isinstance(payload, str):
                try:
                    payload = json.loads(payload)
                except Exception:
                    payload = None
            has_current_lock = bool(payload_matches_current_lock(payload, horizon))
            now = datetime.datetime.now(row['updated_at'].tzinfo) if row.get('updated_at') and row['updated_at'].tzinfo else datetime.datetime.now()
            updated_at = row.get('updated_at')
            age_minutes = None
            if updated_at:
                age = now - updated_at if not updated_at.tzinfo else datetime.datetime.now(updated_at.tzinfo) - updated_at
                age_minutes = round(age.total_seconds() / 60, 1)
            return {
                'status': row.get('status') or 'empty',
                'market': market,
                'horizon': horizon,
                'started_at': row['started_at'].isoformat() if row.get('started_at') else None,
                'completed_at': row['completed_at'].isoformat() if row.get('completed_at') else None,
                'updated_at': row['updated_at'].isoformat() if row.get('updated_at') else None,
                'age_minutes': age_minutes,
                'error': row.get('error'),
                'prediction_lock_key': row.get('prediction_lock_key'),
                'locked': bool(row.get('locked', True)),
                'has_payload': payload is not None,
                'has_current_lock': has_current_lock,
                'running_is_stale': bool(row.get('status') == 'running' and age_minutes is not None and age_minutes > FIRST_SCAN_RUNNING_TIMEOUT_MINUTES),
            }
    finally:
        conn.close()


def mark_first_scan_running(market: str, horizon: str) -> Tuple[bool, str, Dict[str, Any]]:
    """Atomically mark a user-started scan as running when no current lock exists.

    Returns (can_start, reason, status). This prevents repeated paid scans from
    multiple user clicks while still allowing the very first/current-period scan.
    """
    conn = get_db_connection()
    if conn is None:
        return False, 'database_disabled', {'error': 'DATABASE_URL not set'}

    now = datetime.datetime.now()
    lock_key = get_prediction_lock_key(horizon, now)
    try:
        with conn:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute("""
                    SELECT status, updated_at, results_json, prediction_lock_key, error
                    FROM stock_scan_cache
                    WHERE market=%s AND horizon=%s
                    FOR UPDATE
                """, (market, horizon))
                row = cur.fetchone()
                if row:
                    payload = row.get('results_json')
                    if isinstance(payload, str):
                        try:
                            payload = json.loads(payload)
                        except Exception:
                            payload = None
                    if payload_matches_current_lock(payload, horizon):
                        return False, 'already_locked', {'status': 'complete', 'prediction_lock_key': payload.get('prediction_lock_key') if payload else lock_key}
                    updated_at = row.get('updated_at')
                    age_minutes = None
                    if updated_at:
                        ref_now = datetime.datetime.now(updated_at.tzinfo) if updated_at.tzinfo else datetime.datetime.now()
                        age_minutes = (ref_now - updated_at).total_seconds() / 60
                    if row.get('status') == 'running' and (age_minutes is None or age_minutes <= FIRST_SCAN_RUNNING_TIMEOUT_MINUTES):
                        return False, 'already_running', {'status': 'running', 'started_at': row.get('updated_at').isoformat() if row.get('updated_at') else None}

                cur.execute("""
                    INSERT INTO stock_scan_cache
                        (market, horizon, status, started_at, completed_at, expires_at,
                         prediction_lock_key, locked, results_json, methodology_json, error, updated_at)
                    VALUES (%s,%s,'running',%s,NULL,NULL,%s,TRUE,NULL,NULL,NULL,%s)
                    ON CONFLICT (market, horizon) DO UPDATE SET
                        status='running',
                        started_at=EXCLUDED.started_at,
                        completed_at=NULL,
                        error=NULL,
                        prediction_lock_key=EXCLUDED.prediction_lock_key,
                        locked=TRUE,
                        updated_at=EXCLUDED.updated_at
                """, (market, horizon, now, lock_key, now))
        return True, 'started', {'status': 'running', 'prediction_lock_key': lock_key, 'started_at': now.isoformat()}
    finally:
        conn.close()


def mark_first_scan_failed(market: str, horizon: str, error: str):
    conn = get_db_connection()
    if conn is None:
        return
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    UPDATE stock_scan_cache
                    SET status='failed', error=%s, completed_at=NOW(), updated_at=NOW()
                    WHERE market=%s AND horizon=%s AND status='running'
                """, (error[:1000], market, horizon))
    finally:
        conn.close()


def _first_scan_worker(market: str, horizon: str):
    key = f"{market}:{horizon}"
    try:
        print(f"[FIRST-SCAN] User-started first/current-period scan running for {key}")
        run_market_scan(market, horizon, force=False)
    except Exception as e:
        import traceback
        traceback.print_exc()
        mark_first_scan_failed(market, horizon, str(e))
    finally:
        with FIRST_SCAN_THREADS_LOCK:
            FIRST_SCAN_THREADS.pop(key, None)


def start_first_scan_thread(market: str, horizon: str):
    key = f"{market}:{horizon}"
    with FIRST_SCAN_THREADS_LOCK:
        thread = FIRST_SCAN_THREADS.get(key)
        if thread and thread.is_alive():
            return False
        thread = threading.Thread(target=_first_scan_worker, args=(market, horizon), daemon=True)
        FIRST_SCAN_THREADS[key] = thread
        thread.start()
    return True

def score_outcome(signal, actual_gain_pct):
    # Backward-compatible fallback. Detailed scoring is handled by score_prediction_outcome.
    signal = 'WATCH' if signal == 'HOLD' else signal
    if signal == 'BUY':
        return actual_gain_pct > 0
    if signal == 'AVOID':
        return actual_gain_pct <= 0
    if signal == 'WATCH':
        return None
    return None


def fetch_prediction_price_window(ticker: str, market: str, scan_timestamp: datetime.datetime, check_date: datetime.datetime) -> Optional[Dict[str, float]]:
    """Fetch OHLC data for the prediction window.

    Accuracy uses high/low/close, not just the last visible price. yfinance is a
    free market-data fetch here; it does not call Claude and does not create a new
    prediction.
    """
    try:
        # Longer period gives a buffer for holidays and delayed EOD updates.
        hist = yf.Ticker(ticker).history(period='15d', timeout=YF_TIMEOUT)
        if hist is None or hist.empty:
            return None
        hist = hist.dropna(subset=['Close'])
        if hist.empty:
            return None

        # Prefer rows that fall inside the predicted horizon date window. Daily
        # yfinance bars are exchange-local dates, so date filtering is safer than
        # relying on exact intraday timestamps.
        sched = get_market_schedule(market)
        tz = ZoneInfo(sched['tz'])
        start_date = scan_timestamp.replace(tzinfo=datetime.timezone.utc).astimezone(tz).date() if scan_timestamp.tzinfo is None else scan_timestamp.astimezone(tz).date()
        end_date = check_date.replace(tzinfo=datetime.timezone.utc).astimezone(tz).date() if check_date.tzinfo is None else check_date.astimezone(tz).date()

        rows = hist
        try:
            idx_dates = []
            for idx in hist.index:
                if hasattr(idx, 'to_pydatetime'):
                    dt = idx.to_pydatetime()
                else:
                    dt = idx
                if getattr(dt, 'tzinfo', None):
                    idx_dates.append(dt.astimezone(tz).date())
                else:
                    idx_dates.append(dt.date())
            mask = [(d >= start_date and d <= end_date) for d in idx_dates]
            filtered = hist.loc[mask]
            if not filtered.empty:
                rows = filtered
        except Exception:
            rows = hist.tail(1)

        close_price = float(rows['Close'].dropna().iloc[-1])
        high_price = float(rows['High'].dropna().max()) if 'High' in rows else close_price
        low_price = float(rows['Low'].dropna().min()) if 'Low' in rows else close_price
        return {'close': round(close_price, 4), 'high': round(high_price, 4), 'low': round(low_price, 4)}
    except Exception as e:
        print(f"[WARN] Could not fetch prediction price window for {ticker}: {e}")
        return None


def score_prediction_outcome(row: Dict[str, Any], prices: Dict[str, float]) -> Dict[str, Any]:
    signal = 'WATCH' if row.get('signal') == 'HOLD' else row.get('signal')
    entry = float(row['entry_price']) if row.get('entry_price') is not None else None
    target = float(row['target_price']) if row.get('target_price') is not None else None
    stop = float(row['stop_price']) if row.get('stop_price') is not None else None
    close = float(prices['close'])
    high = float(prices.get('high', close))
    low = float(prices.get('low', close))
    actual_gain_pct = round(((close - entry) / entry) * 100, 2) if entry else None
    target_hit = bool(target and high >= target)
    stop_hit = bool(stop and low <= stop)

    if signal == 'BUY':
        if target_hit:
            label, status, correct, reason = 'Target Hit', 'success', True, None
        elif stop_hit:
            label, status, correct, reason = 'Stop Loss Hit', 'failed', False, 'stop_loss_hit'
        elif actual_gain_pct is not None and actual_gain_pct > 0:
            label, status, correct, reason = 'Partial Success', 'partial_success', True, None
        else:
            label, status, correct, reason = 'Closed Below Entry', 'failed', False, infer_failure_reason(row, actual_gain_pct, target_hit, stop_hit)
    elif signal == 'AVOID':
        if actual_gain_pct is not None and actual_gain_pct <= 0:
            label, status, correct, reason = 'Correct Avoid', 'success', True, None
        elif target_hit or (actual_gain_pct is not None and actual_gain_pct >= 2):
            label, status, correct, reason = 'Avoid Missed Rally', 'failed', False, 'missed_positive_move'
        else:
            label, status, correct, reason = 'Neutral Avoid', 'neutral', None, None
    else:  # WATCH
        if stop_hit or (actual_gain_pct is not None and actual_gain_pct <= -1.5):
            label, status, correct, reason = 'Correct Watch', 'success', True, None
        elif target_hit or (actual_gain_pct is not None and actual_gain_pct >= 2):
            label, status, correct, reason = 'Missed Opportunity', 'missed_opportunity', False, 'watch_rallied_without_buy'
        else:
            label, status, correct, reason = 'Neutral Watch', 'neutral', None, None

    lesson_summary = build_lesson_summary(row, label, status, reason, actual_gain_pct)
    return {
        'actual_price': close,
        'actual_high': high,
        'actual_low': low,
        'actual_gain_pct': actual_gain_pct,
        'outcome_correct': correct,
        'outcome_label': label,
        'outcome_status': status,
        'failure_reason': reason,
        'lesson_summary': lesson_summary,
    }


def infer_failure_reason(row: Dict[str, Any], actual_gain_pct: Optional[float], target_hit: bool, stop_hit: bool) -> str:
    features = row.get('features_json') or {}
    if isinstance(features, str):
        try:
            features = json.loads(features)
        except Exception:
            features = {}
    try:
        rr = None
        entry = float(row['entry_price']) if row.get('entry_price') is not None else None
        target = float(row['target_price']) if row.get('target_price') is not None else None
        stop = float(row['stop_price']) if row.get('stop_price') is not None else None
        if entry and target and stop and entry > stop:
            rr = (target - entry) / (entry - stop)
    except Exception:
        rr = None

    if stop_hit:
        return 'stop_loss_hit'
    if features.get('volume_ratio_vs_20d_avg') is not None and float(features.get('volume_ratio_vs_20d_avg') or 0) < 0.8:
        return 'low_volume_confirmation'
    if features.get('rsi_14') is not None and float(features.get('rsi_14') or 0) > 68:
        return 'overextended_or_chasing'
    if rr is not None and rr < MIN_BUY_RISK_REWARD:
        return 'weak_risk_reward'
    if features.get('news_score') is not None and float(features.get('news_score') or 0) < 0:
        return 'negative_news_or_event_risk'
    if features.get('news_score') is not None and float(features.get('news_score') or 0) == 0:
        return 'no_news_catalyst'
    return 'setup_did_not_follow_through'


def build_lesson_summary(row: Dict[str, Any], label: str, status: str, reason: Optional[str], actual_gain_pct: Optional[float]) -> str:
    signal = 'WATCH' if row.get('signal') == 'HOLD' else row.get('signal')
    ticker = row.get('ticker')
    if status == 'success':
        return f"{ticker} {signal} outcome worked as expected ({label}); keep similar confirmations when ranking future setups."
    if status == 'neutral':
        return f"{ticker} {signal} stayed neutral; do not count it as a strong win or loss when adjusting the model."
    reason_text = (reason or 'unknown').replace('_', ' ')
    return f"{ticker} {signal} failed/underperformed because of {reason_text}; reduce confidence for similar future setups unless stronger confirmation appears."


def save_prediction_lesson(row: Dict[str, Any], scored: Dict[str, Any]):
    conn = get_db_connection()
    if conn is None:
        return
    features = row.get('features_json') or {}
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO prediction_lessons
                        (prediction_id, market, horizon, ticker, signal, outcome_label, outcome_status,
                         failure_reason, lesson_summary, actual_gain_pct, features_json)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                    ON CONFLICT (prediction_id) WHERE (prediction_id IS NOT NULL) DO NOTHING
                """, (
                    row.get('id'), row.get('market'), row.get('horizon'), row.get('ticker'),
                    'WATCH' if row.get('signal') == 'HOLD' else row.get('signal'),
                    scored.get('outcome_label'), scored.get('outcome_status'), scored.get('failure_reason'),
                    scored.get('lesson_summary'), scored.get('actual_gain_pct'),
                    json.dumps(features, default=_json_safe)
                ))
    except Exception as e:
        print(f"[WARN] Could not save prediction lesson: {e}")
    finally:
        conn.close()


