def parse_rr(value: Any) -> float:
    if value is None:
        return 0.0
    if isinstance(value, (int, float, np.generic)):
        return float(value)
    m = re.search(r"([0-9.]+)", str(value))
    return float(m.group(1)) if m else 0.0


def get_open_positions(market: Optional[str] = None, mode: Optional[str] = None) -> List[Dict[str, Any]]:
    conn = get_db_connection()
    if conn is None:
        return []
    filters = ["status='OPEN'"]
    params: List[Any] = []
    if market:
        filters.append("market=%s")
        params.append(market)
    if mode:
        filters.append("mode=%s")
        params.append(mode)
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"SELECT * FROM trade_positions WHERE {' AND '.join(filters)} ORDER BY opened_at DESC", params)
            return list(cur.fetchall())
    finally:
        conn.close()


def fetch_last_price(ticker: str) -> Optional[float]:
    try:
        hist = yf.Ticker(ticker).history(period='2d', interval='1d', timeout=YF_TIMEOUT)
        if hist is not None and not hist.empty:
            return float(hist['Close'].dropna().iloc[-1])
    except Exception:
        return None
    return None


def get_market_session_state(market: str, wait_minutes: Optional[int] = None, now_utc: Optional[datetime.datetime] = None) -> Dict[str, Any]:
    # Return exchange-session state for deterministic entry gating. No paid AI call.
    wait = OPENING_CONFIRMATION_WAIT_MINUTES if wait_minutes is None else int(wait_minutes)
    sched = get_market_schedule(market)
    tz = ZoneInfo(sched['tz'])
    now_utc = now_utc or utc_now_naive()
    if now_utc.tzinfo is None:
        aware = now_utc.replace(tzinfo=datetime.timezone.utc)
    else:
        aware = now_utc.astimezone(datetime.timezone.utc)
    local_now = aware.astimezone(tz)
    day = local_now.date()
    open_dt = datetime.datetime.combine(day, sched['open'], tzinfo=tz)
    close_dt = datetime.datetime.combine(day, sched['close'], tzinfo=tz)
    ready_dt = open_dt + datetime.timedelta(minutes=max(wait, 0))
    if not is_trading_day(market, day):
        state = 'closed_non_trading_day'
    elif local_now < open_dt:
        state = 'before_open'
    elif local_now < ready_dt:
        state = 'opening_wait'
    elif local_now <= close_dt:
        state = 'open_ready'
    else:
        state = 'after_close'
    minutes_since_open = round((local_now - open_dt).total_seconds() / 60, 1)
    return {
        'state': state,
        'market': market,
        'timezone': sched['tz'],
        'local_now': local_now.isoformat(),
        'open_time': open_dt.isoformat(),
        'ready_time': ready_dt.isoformat(),
        'close_time': close_dt.isoformat(),
        'wait_minutes': wait,
        'minutes_since_open': minutes_since_open,
        'can_enter': state == 'open_ready',
    }



def get_intraday_session_phase(market: str, now_utc: Optional[datetime.datetime] = None) -> Dict[str, Any]:
    """Graduated late-session classification, instead of one arbitrary "close everything at
    X o'clock" rule.

    normal    -> more than 60 min to close: ordinary entry/exit rules.
    late      -> 30-60 min to close: new entries become increasingly selective.
    critical  -> 15-30 min to close: existing positions get a hold-score check instead of
                 waiting for the clock; no brand-new entries.
    square_off-> inside the existing INTRADAY_FORCE_EXIT_BEFORE_CLOSE_MINUTES hard cutoff:
                 no debate, everything closes (unchanged, handled elsewhere).
    """
    sched = get_market_schedule(market)
    tz = ZoneInfo(sched['tz'])
    now_utc = now_utc or utc_now_naive()
    aware = now_utc.replace(tzinfo=datetime.timezone.utc) if now_utc.tzinfo is None else now_utc.astimezone(datetime.timezone.utc)
    local_now = aware.astimezone(tz)
    close_dt = datetime.datetime.combine(local_now.date(), sched['close'], tzinfo=tz)
    minutes_to_close = (close_dt - local_now).total_seconds() / 60
    if minutes_to_close <= INTRADAY_FORCE_EXIT_BEFORE_CLOSE_MINUTES:
        phase = 'square_off'
    elif minutes_to_close <= 30:
        phase = 'critical'
    elif minutes_to_close <= 60:
        phase = 'late'
    else:
        phase = 'normal'
    return {'phase': phase, 'minutes_to_close': round(minutes_to_close, 1)}


def assess_intraday_momentum(snap: Dict[str, Any]) -> Dict[str, Any]:
    """Momentum QUALITY, not just magnitude: is the move accelerating, steady, decelerating,
    or already exhausted? Built entirely from fields fetch_intraday_snapshot already
    returns, so this costs no extra API calls.
    """
    closes = [float(c) for c in (snap.get('recent_closes') or []) if c is not None]
    state = 'steady'
    detail_bits = []
    if len(closes) >= 3:
        diffs = [closes[i + 1] - closes[i] for i in range(len(closes) - 1)]
        if all(d > 0 for d in diffs):
            if abs(diffs[-1]) > abs(diffs[0]) * 1.1:
                state = 'accelerating'
            elif abs(diffs[-1]) < abs(diffs[0]) * 0.6:
                state = 'decelerating'
            detail_bits.append(f'rising closes ({state})')
        elif all(d < 0 for d in diffs):
            state = 'decelerating'
            detail_bits.append('falling closes')
        else:
            detail_bits.append('choppy closes')
    last_bar_vol = snap.get('last_bar_volume')
    avg_bar_vol = snap.get('avg_bar_volume')
    vwap = snap.get('vwap')
    last = snap.get('last')
    if last_bar_vol is not None and avg_bar_vol and last is not None and vwap:
        vwap_distance_pct = ((last - vwap) / vwap) * 100 if vwap else 0
        volume_fading = last_bar_vol < avg_bar_vol * 0.7
        if vwap_distance_pct > 1.5 and volume_fading:
            state = 'exhausted'
            detail_bits.append(f'{round(vwap_distance_pct, 2)}% above VWAP on fading volume ({round(last_bar_vol, 0)} vs avg {round(avg_bar_vol, 0)})')
    return {'state': state, 'detail': '; '.join(detail_bits) or 'insufficient data'}



def get_intraday_interval_minutes() -> int:
    """Return the candle interval in minutes for wait-window and freshness math."""
    interval = str(INTRADAY_DATA_INTERVAL or '1m').strip().lower()
    m = re.match(r'^(\d+)(m|h|d)$', interval)
    if not m:
        return 1
    value = max(1, int(m.group(1)))
    unit = m.group(2)
    if unit == 'h':
        return value * 60
    if unit == 'd':
        return value * 1440
    return value


def get_intraday_last_candle_meta(hist: Any, market: str) -> Dict[str, Any]:
    """Measure provider freshness so stale/delayed candles are visible and blocked if needed."""
    meta = {'last_candle_at': None, 'data_age_minutes': None, 'is_stale': False, 'freshness_note': 'freshness_unknown'}
    try:
        if hist is None or hist.empty or len(hist.index) == 0:
            return meta
        ts = hist.index[-1]
        if hasattr(ts, 'to_pydatetime'):
            dt = ts.to_pydatetime()
        elif isinstance(ts, datetime.datetime):
            dt = ts
        else:
            return meta
        if dt.tzinfo is None:
            sched = get_market_schedule(market)
            dt = dt.replace(tzinfo=ZoneInfo(sched.get('tz') or 'UTC'))
        now = datetime.datetime.now(datetime.timezone.utc)
        dt_utc = dt.astimezone(datetime.timezone.utc)
        age = max(0.0, (now - dt_utc).total_seconds() / 60.0)
        max_age = max(1, int(INTRADAY_MAX_DATA_AGE_MINUTES))
        meta.update({
            'last_candle_at': dt_utc.isoformat(),
            'data_age_minutes': round(age, 1),
            'is_stale': age > max_age,
            'freshness_note': 'fresh' if age <= max_age else f'stale_or_delayed: last candle {round(age,1)} min old; max allowed {max_age} min',
        })
    except Exception as e:
        meta['freshness_note'] = f'freshness_check_failed: {str(e)[:80]}'
    return meta


def extract_intraday_strategy_features(row: Dict[str, Any], hist: Any) -> Dict[str, Any]:
    """Build the feature dict the multi-strategy engine consumes.

    Deliberately computed in ONE place from the candidate row + its bar history, so
    Live, Paper and Replay all feed the strategy engine identical inputs. The row is
    already produced by the same fetch_intraday_candidate_snapshot() in every engine,
    so anything derived from it here is automatically consistent across all three --
    which is the whole point of the shared-engine requirement.

    Adds the indicators the old single-strategy scorer never computed intraday
    (EMA9/EMA21, RSI, MACD histogram) plus setup-shape measures (pullback depth,
    consolidation tightness, VWAP reclaim, relative strength) that individual
    strategies need to tell their setups apart from each other.
    """
    f: Dict[str, Any] = {
        'ticker': row.get('ticker'),
        'last': row.get('last'), 'open': row.get('open'),
        'session_high': row.get('high'), 'session_low': row.get('low'),
        'opening_high': row.get('opening_high'), 'opening_low': row.get('opening_low'),
        'vwap': row.get('vwap'), 'above_vwap': row.get('above_vwap'),
        'change_pct': row.get('change_pct'), 'volume_multiplier': row.get('volume_multiplier'),
        'recent_trend': row.get('recent_trend'), 'breakout': row.get('breakout'),
        'failed_breakout': row.get('failed_breakout'), 'momentum_state': row.get('momentum_state'),
        'breakout_down': row.get('breakout_down'), 'failed_breakdown': row.get('failed_breakdown'),
        'bars': row.get('bars'),
    }
    try:
        last = float(row.get('last') or 0)
        open_price = float(row.get('open') or 0)
        session_high = float(row.get('high') or 0)
        session_low = float(row.get('low') or 0)
        vwap = float(row.get('vwap')) if row.get('vwap') else None
        f['pullback_from_low_pct'] = round(((last - session_low) / session_low) * 100, 3) if session_low and last else None

        f['vwap_distance_pct'] = round(((last - vwap) / vwap) * 100, 3) if vwap and last else None
        f['pullback_from_high_pct'] = round(((session_high - last) / session_high) * 100, 3) if session_high and last else None
        f['session_range_pct'] = round(((session_high - session_low) / open_price) * 100, 3) if open_price and session_high and session_low else None

        closes = None
        if hist is not None and not hist.empty and 'Close' in hist:
            closes = [float(x) for x in hist['Close'].dropna().tolist()]

        # Each intraday bar is INTRADAY_DATA_INTERVAL minutes, so bar count converts
        # directly to session age -- used by strategies that are only valid in a
        # particular part of the session (opening-range vs. post-opening coil).
        try:
            interval_minutes = int(''.join(ch for ch in str(INTRADAY_DATA_INTERVAL) if ch.isdigit()) or 5)
        except Exception:
            interval_minutes = 5
        f['minutes_since_open'] = (max(0, len(closes) - 1) * interval_minutes) if closes else None

        if closes and len(closes) >= 10:
            f['ema9'] = round(compute_ema(closes[-40:] if len(closes) > 40 else closes, 9), 3)
            if len(closes) >= 21:
                f['ema21'] = round(compute_ema(closes, 21), 3)
        if closes and len(closes) >= 15:
            f['rsi'] = compute_rsi(closes)
        if closes and len(closes) >= 35:
            try:
                _macd, _sig, _hist = compute_macd(closes)
                f['macd'] = _macd
                f['macd_hist'] = _hist
            except Exception:
                pass

        # VWAP reclaim must compare each historical close with its historical VWAP,
        # not every historical close against the CURRENT VWAP.  The old implementation
        # could manufacture a reclaim after the VWAP itself moved.
        f['vwap_reclaimed'] = False
        if closes and len(closes) >= 4 and last and hist is not None and not hist.empty and 'Volume' in hist:
            try:
                h = hist.copy().dropna(subset=['Close'])
                vol = pd.to_numeric(h.get('Volume'), errors='coerce').fillna(0.0)
                typ = (pd.to_numeric(h['High'], errors='coerce') + pd.to_numeric(h['Low'], errors='coerce') + pd.to_numeric(h['Close'], errors='coerce')) / 3.0
                denom = vol.cumsum().replace(0, np.nan)
                vwap_series = (typ * vol).cumsum() / denom
                close_series = pd.to_numeric(h['Close'], errors='coerce')
                valid = (close_series.notna() & vwap_series.notna()).to_numpy()
                cvals = close_series.to_numpy()[valid]
                vvals = vwap_series.to_numpy()[valid]
                if len(cvals) >= 4 and vvals[-1] > 0:
                    f['vwap_reclaimed'] = bool(cvals[-1] > vvals[-1] and np.any(cvals[:-1] < vvals[:-1]))
            except Exception:
                f['vwap_reclaimed'] = False

        # Consolidation tightness over the recent window -- the "coil" a range break
        # needs. Measured on the last ~8 bars, excluding the breakout bar itself.
        if closes and len(closes) >= 9:
            coil = closes[-9:-1]
            coil_hi, coil_lo = max(coil), min(coil)
            f['consolidation_range_pct'] = round(((coil_hi - coil_lo) / coil_lo) * 100, 3) if coil_lo else None
    except Exception as e:
        f['feature_error'] = str(e)[:120]
    return f


def _attach_relative_strength_feature(features: Dict[str, Any], market_context: Optional[Dict[str, Any]]) -> None:
    """Compute 'relative_strength_pct' (stock's change_pct minus the index's
    point-in-time change_pct so far today) directly on the feature dict.

    BUGFIX: the Relative Strength strategy (strategies.py) reads
    f.get('relative_strength_pct'), but nothing ever calculated it -- so that
    strategy always blocked with "no index benchmark available", regardless of
    settings. The index's own move is already computed once per tick as
    market_context['intraday_index']['change_pct'] (point-in-time in Replay,
    current-session in Live/Paper) specifically so this kind of stock-vs-index
    comparison can be built from it without a second index fetch.
    """
    ctx = market_context or {}
    intraday_index = ctx.get('intraday_index') if isinstance(ctx.get('intraday_index'), dict) else {}
    index_change = intraday_index.get('change_pct')
    stock_change = features.get('change_pct')
    try:
        if index_change is not None and stock_change is not None:
            features['relative_strength_pct'] = round(float(stock_change) - float(index_change), 3)
    except (TypeError, ValueError):
        pass


# Cache keyed by ticker (not sector): previous-session/swing levels are fixed for
# the whole trading session, unlike price, so a long TTL is correct here -- this
# is NOT the same cache as _SECTOR_CONTEXT_CACHE above.
_SR_LEVELS_CACHE: Dict[str, Tuple[float, Dict[str, Any]]] = {}
_SR_LEVELS_CACHE_TTL_SECONDS = 1800.0


def compute_support_resistance_levels(ticker: str, market: str = 'IN') -> Dict[str, Any]:
    """Report fix #7 -- real support/resistance context: previous session's
    high/low plus a 20-session swing high/low, fetched once per ticker per
    session and cached (unlike today's price, these levels don't move
    intraday). Returns ok=False (never raises) on any failure -- an unmapped
    or unfetchable ticker can only ever fail to add a signal, never block a
    scan or corrupt an existing one.

    Deliberately excludes the CURRENT day's own (still-forming) daily candle --
    using today's own high as 'resistance' would be circular, exactly the
    'session high isn't real resistance' gap the report calls out.
    """
    now = time.time()
    cached = _SR_LEVELS_CACHE.get(ticker)
    if cached and (now - cached[0]) < _SR_LEVELS_CACHE_TTL_SECONDS:
        return cached[1]
    try:
        hist = yf.Ticker(ticker).history(period='35d', interval='1d', timeout=YF_TIMEOUT)
        if hist is None or hist.empty or len(hist) < 3:
            result = {'ok': False, 'note': 'not_enough_daily_history'}
        else:
            today = datetime.datetime.now().date()
            try:
                prior = hist[hist.index.date < today]
            except Exception:
                prior = hist.iloc[:-1] if len(hist) > 1 else hist
            if prior.empty:
                prior = hist.iloc[:-1] if len(hist) > 1 else hist
            if prior is None or prior.empty:
                result = {'ok': False, 'note': 'no_prior_session_data'}
            else:
                prev_bar = prior.iloc[-1]
                prev_close = float(prev_bar['Close'])
                prev_day_high = float(prev_bar['High'])
                prev_day_low = float(prev_bar['Low'])
                swing_window = prior.tail(20)
                swing_high = float(swing_window['High'].max())
                swing_low = float(swing_window['Low'].min())
                result = {
                    'ok': True, 'prev_close': round(prev_close, 2),
                    'prev_day_high': round(prev_day_high, 2), 'prev_day_low': round(prev_day_low, 2),
                    'swing_high_20d': round(swing_high, 2), 'swing_low_20d': round(swing_low, 2),
                }
    except Exception as e:
        result = {'ok': False, 'note': str(e)[:160]}
    _SR_LEVELS_CACHE[ticker] = (now, result)
    return result


def _attach_support_resistance_features(features: Dict[str, Any], row: Dict[str, Any], settings: Dict[str, Any]) -> None:
    """Attaches prev_day_high/low, swing_high/low_20d, gap_pct, and (when current
    price is known) distance_to_resistance_pct / distance_to_support_pct + which
    level they came from -- consumed by estimate_extension_penalty (report #7).

    LIVE vs REPLAY (parity fix): uses settings.get('_sim_now') -- not
    row.get('is_replay') -- to tell the two apart. row['is_replay'] is only set
    by build_replay_candidate_row AFTER fetch_intraday_candidate_snapshot (and
    therefore this function, called from inside it) has already returned, so it
    reads as absent/False here even during an actual replay tick; _sim_now is
    the same signal the entry_dt line just above in attach_intraday_strategy_engine
    already relies on for this exact live/replay distinction, and is reliably set
    only during replay (see replay_scan_universe / build_replay_candidate_row).

    Replay uses the point-in-time daily history downloaded once for the whole
    run (download_replay_universe_daily_history), truncated to bars strictly
    before the simulated day -- never a live call, and never a look-ahead. Live
    uses a live daily-history fetch, cached per ticker for the process.
    Returns silently (features unchanged) if no levels are available in either
    case -- estimate_extension_penalty already handles that gracefully.
    """
    ticker = row.get('ticker')
    if not ticker:
        return
    sim_now = settings.get('_sim_now')
    if sim_now is not None:
        day = sim_now.date() if hasattr(sim_now, 'date') else None
        daily_hist_map = settings.get('_replay_daily_history') or {}
        if day is None or ticker not in daily_hist_map:
            return
        levels = compute_historical_support_resistance_levels(daily_hist_map.get(ticker), day)
    else:
        market = row.get('market') or settings.get('market') or 'IN'
        levels = compute_support_resistance_levels(ticker, market)
    if not levels.get('ok'):
        return
    current_price = _num(features.get('last'), None)
    open_price = _num(features.get('open'), None)
    features['prev_close'] = levels.get('prev_close')
    features['prev_day_high'] = levels.get('prev_day_high')
    features['prev_day_low'] = levels.get('prev_day_low')
    features['swing_high_20d'] = levels.get('swing_high_20d')
    features['swing_low_20d'] = levels.get('swing_low_20d')
    if open_price and levels.get('prev_close'):
        try:
            features['gap_pct'] = round(((open_price - levels['prev_close']) / levels['prev_close']) * 100, 3)
        except Exception:
            pass
    if current_price and current_price > 0:
        resistance_candidates = [(name, lvl) for name, lvl in
                                  (('prev_day_high', levels.get('prev_day_high')), ('swing_high_20d', levels.get('swing_high_20d')))
                                  if lvl and lvl > current_price]
        support_candidates = [(name, lvl) for name, lvl in
                               (('prev_day_low', levels.get('prev_day_low')), ('swing_low_20d', levels.get('swing_low_20d')))
                               if lvl and lvl < current_price]
        if resistance_candidates:
            r_name, r_lvl = min(resistance_candidates, key=lambda x: x[1])
            features['distance_to_resistance_pct'] = round(((r_lvl - current_price) / current_price) * 100, 3)
            features['resistance_source'] = r_name
            features['resistance_level'] = r_lvl
        if support_candidates:
            s_name, s_lvl = max(support_candidates, key=lambda x: x[1])
            features['distance_to_support_pct'] = round(((current_price - s_lvl) / current_price) * 100, 3)
            features['support_source'] = s_name
            features['support_level'] = s_lvl


def _attach_sector_context(row: Dict[str, Any], settings: Dict[str, Any], market_context: Optional[Dict[str, Any]]) -> None:
    """Attaches row['sector_context'] = {'sector', 'change_pct', ...} for
    strict_learning_review's sector-confirmation rule (report #8), used
    identically by Live and Replay -- see this function's live/replay branch
    for why _sim_now (not row['is_replay']) is the correct signal here, same
    reasoning as _attach_support_resistance_features just above.

    Replay: looks up the point-in-time value the per-tick loop already computed
    ONCE for every sector this tick (see the sector_contexts block next to
    build_historical_intraday_index_context's own call in the replay worker) --
    cheap, no re-fetch per ticker. Live: calls get_intraday_sector_context
    directly (its own short-TTL cache already avoids refetching per ticker).
    """
    sector = sector_data.get_sector(row.get('ticker'))
    if not sector:
        row['sector_context'] = {'sector': None, 'change_pct': None, 'note': 'ticker not in the sector map'}
        return
    if settings.get('_sim_now') is not None:
        sector_ctxs = (market_context or {}).get('sector_contexts') or {}
        row['sector_context'] = sector_ctxs.get(sector) or {
            'sector': sector, 'change_pct': None, 'note': 'no point-in-time sector index data for this tick'}
    else:
        market = row.get('market') or settings.get('market') or 'IN'
        row['sector_context'] = get_intraday_sector_context(sector, market)


def attach_intraday_strategy_engine(row: Dict[str, Any], settings: Dict[str, Any], hist: Any = None,
                                     market_context: Optional[Dict[str, Any]] = None,
                                     performance: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """LAYER 1 + LAYER 2 entry point, called from the single shared candidate builder.

    Attaches: the feature dict, all 10 strategy evaluations, the detected regime, and
    the selector's decision (including why every other strategy was passed over).

    IMPORTANT -- what this does NOT do: it does not decide position size, trade count,
    or affordability. Those stay in the risk/execution layer, unchanged. A stock with
    no valid strategy gets `no_strategy_matched` added to blocked_reasons, which is how
    the multi-strategy gate replaces the old "one global score >= 70" gate.
    """
    try:
        features = extract_intraday_strategy_features(row, hist)
        _attach_relative_strength_feature(features, market_context)
        _attach_support_resistance_features(features, row, settings)
        _attach_sector_context(row, settings, market_context)
        row['strategy_features'] = features
        regime_info = detect_market_regime(features, market_context)
        row['regime'] = regime_info.get('regime')
        row['regime_info'] = regime_info
        evaluations = evaluate_all_strategies(features, settings)
        row['strategy_evaluations'] = evaluations
        disabled = [s.strip() for s in str(settings.get('disabled_strategies') or '').split(',') if s.strip()]
        # CONTEXT (report issues #2/#3): describe this candidate in exactly the same
        # bucket vocabulary recorded trades are stored in, so the selector can ask
        # "what does this strategy actually pay in THIS situation" rather than
        # "what does this strategy pay on average across every situation".
        # sim_now is the replay's simulated clock; in Live it is absent and the
        # real clock is used, which is correct for each engine respectively.
        entry_dt = settings.get('_sim_now') or (None if row.get('is_replay') else utc_now_naive())
        setup_context = build_setup_context(features, regime_info.get('regime'), entry_dt)
        row['setup_context'] = setup_context
        # THE #1 ARCHITECTURAL FIX. The EV gate is handed to the selector as a
        # per-strategy evaluator so it runs BEFORE selection, on all 10 strategies
        # at once. A strategy with proven negative expectancy in this context is
        # removed from the candidate pool; the selector then picks the strongest
        # positive-EV survivor instead of picking a winner first and discovering
        # afterwards that it was un-tradeable -- which used to discard the stock
        # entirely even when a viable alternative strategy was ranked just below.
        ev_fn = None
        if bool(settings.get('ev_gate_enabled', True)):
            ev_fn = build_candidate_ev_evaluator(
                performance or {}, setup_context,
                cost_pct_est=0.0,
                session_trades=settings.get('_session_trades') or [],
                sim_now=entry_dt,
                fast_adapt_enabled=bool(settings.get('fast_adapt_enabled', INTRADAY_FAST_ADAPT_ENABLED)))
        selection = select_strategy(evaluations, regime_info.get('regime') or 'choppy',
                                    performance=performance or {}, disabled_ids=disabled,
                                    ev_fn=ev_fn,
                                    min_expected_edge_pct=float(settings.get('min_ev_pct_to_trade', INTRADAY_MIN_EV_PCT_TO_TRADE)))
        row['strategy_selection'] = selection
        selected = selection.get('selected')
        if selection.get('ev_rejected_strategies'):
            # Kept on the row (not just inside the selection dict) so the replay
            # event log and the live dashboard can both show the fallthrough without
            # digging: "A was dropped on negative EV, B was taken instead".
            row['ev_rejected_strategies'] = selection['ev_rejected_strategies']
        if selection.get('fallback_used'):
            row['ev_fallback_used'] = True
            row['ev_fallback_note'] = selection.get('fallback_note')
        if selected:
            row['strategy_id'] = selected['strategy_id']
            row['base_strategy_id'] = selected.get('base_strategy_id') or selected['strategy_id']
            row['side'] = selected.get('side') or ('SHORT' if str(selected['strategy_id']).endswith('_short') else 'LONG')
            row['strategy_name'] = selected['name']
            row['strategy_confidence'] = selected['confidence']
            row['strategy_target_pct'] = selected.get('target_pct')
            row['strategy_stop_pct'] = selected.get('stop_pct')
            row['strategy_min_confidence'] = selected.get('min_confidence')
            row['strategy_why'] = selection.get('why_selected')
            row['expected_net_edge_pct'] = selection.get('expected_net_edge_pct')
            row['calibrated_win_prob_pct'] = selection.get('calibrated_win_prob_pct')
            row['ev_note'] = selection.get('ev_note')
            # GRADUATED COLD-START RISK + EV-PROPORTIONAL SIZING (report #3/#10).
            # Computed once, here, at the single point Live/Paper/Replay all share for
            # strategy selection -- see compute_candidate_risk_scale's docstring for why
            # this must not be recomputed separately per engine.
            _base_sid = selected.get('base_strategy_id') or selected.get('strategy_id')
            _side_key = f"{_base_sid}:{selected.get('side') or 'LONG'}".lower()
            _evidence_perf = (performance or {}).get(_side_key) or ((performance or {}).get(_base_sid) if str(selected.get('side') or 'LONG').upper() == 'LONG' else None) or (performance or {}).get(selected['strategy_id']) or {}
            _evidence_trades = int(_evidence_perf.get('total_trades') or 0)
            _risk_scale_info = compute_candidate_risk_scale(
                ev_pct=selection.get('expected_net_edge_pct'),
                ev_proven=bool(selection.get('ev_proven')),
                evidence_trades=_evidence_trades)
            row['strategy_evidence_trades'] = _evidence_trades
            row['risk_scale'] = _risk_scale_info['risk_scale']
            row['risk_scale_detail'] = _risk_scale_info
            # The strategy's own confidence becomes the candidate's score. This is the
            # core behavioural change: ranking is now "how good is this specific setup
            # for the strategy that claimed it", not one global score built from a
            # fixed bundle of conditions applied to every stock alike.
            row['legacy_score'] = row.get('score')
            row['score'] = round(float(selected['confidence']), 1)
            row['strategy_rank_score'] = selected.get('final_rank_score')
        else:
            row['strategy_id'] = None
            row['strategy_name'] = None
            row.setdefault('blocked_reasons', []).append('no_strategy_matched')
            row['strategy_why_not'] = selection.get('why_not_any')
    except Exception as e:
        row['strategy_engine_error'] = str(e)[:160]
    return row


def _candidate_side(candidate: Dict[str, Any]) -> str:
    side = candidate.get('side') or candidate.get('direction')
    if side:
        return v3_2_engine.canonical_side(side)
    sid = str(candidate.get('strategy_id') or '').lower()
    return 'SHORT' if sid.endswith('_short') else 'LONG'


def _position_side(pos: Dict[str, Any]) -> str:
    """Canonical position direction; persisted side is authoritative when present."""
    raw = pos.get('direction') or pos.get('side')
    if raw:
        return v3_2_engine.canonical_side(raw)
    meta = pos.get('metadata_json') or {}
    if isinstance(meta, str):
        meta = parse_jsonish(meta)
    raw = meta.get('direction') or meta.get('side') or meta.get('order_side')
    return v3_2_engine.canonical_side(raw or 'LONG')


def compute_intraday_risk_plan(candidate: Dict[str, Any], settings: Dict[str, Any]) -> Dict[str, Any]:
    """Canonical side-aware entry/stop/target plan shared by preview and execution."""
    entry = float(candidate.get('last') or candidate.get('entry_price') or 0)
    if entry <= 0:
        return {'ok': False, 'reason': 'no_valid_entry_price', 'entry': entry}
    side = _candidate_side(candidate)
    max_stop_pct = float(settings.get('max_stop_loss_pct') or INTRADAY_MAX_STOP_LOSS_PCT)
    min_rr = float(settings.get('min_risk_reward') or INTRADAY_MIN_RISK_REWARD)
    quick_target_pct = float(settings.get('quick_target_pct') or INTRADAY_QUICK_TARGET_PCT)
    min_stop_pct = min(max_stop_pct, max(0.0, float(INTRADAY_MIN_STOP_LOSS_PCT or 0)))
    used_strategy_profile = candidate.get('strategy_target_pct') is not None or candidate.get('strategy_stop_pct') is not None
    if candidate.get('strategy_target_pct') is not None:
        quick_target_pct = float(candidate['strategy_target_pct'])
    if candidate.get('strategy_stop_pct') is not None:
        max_stop_pct = float(candidate['strategy_stop_pct'])

    opening_low_raw = candidate.get('opening_low')
    opening_high_raw = candidate.get('opening_high')
    if opening_low_raw is not None and opening_high_raw is not None:
        opening_range_pct = max(0.0, (float(opening_high_raw) - float(opening_low_raw)) / entry * 100.0)
        atr_based_stop_pct = max(max_stop_pct, min(opening_range_pct * 0.6, max_stop_pct * 2.5))
    else:
        atr_based_stop_pct = max_stop_pct

    side_c = v3_2_engine.canonical_side(side)
    if side_c == 'LONG':
        stop_by_pct = entry * (1.0 - atr_based_stop_pct / 100.0)
        structural_stop = None
        base_sid = str(candidate.get('base_strategy_id') or candidate.get('strategy_id') or '')
        if base_sid.endswith('_short'):
            base_sid = base_sid[:-6]
        if base_sid in ('opening_breakout', 'range_breakout', 'intraday_range_break') and opening_low_raw is not None:
            structural_stop = float(opening_low_raw) * 0.998
        elif base_sid in ('vwap_momentum', 'vwap_reclaim') and candidate.get('vwap'):
            structural_stop = float(candidate['vwap']) * 0.998
        elif candidate.get('strategy_id') is None and opening_low_raw is not None and candidate.get('vwap'):
            structural_stop = min(float(candidate['vwap']) * 0.998, float(opening_low_raw) * 0.998)
        stop = max(stop_by_pct, structural_stop) if structural_stop is not None else stop_by_pct
        if min_stop_pct > 0:
            stop = min(stop, entry * (1.0 - min_stop_pct / 100.0))
        if stop >= entry:
            stop = stop_by_pct
        risk_per_share = max(entry - stop, 0.01)
        quick_target = entry * (1.0 + quick_target_pct / 100.0)
        rr_target = entry + risk_per_share * min_rr
        target = max(quick_target, rr_target)
    else:
        stop_by_pct = entry * (1.0 + atr_based_stop_pct / 100.0)
        structural_stop = None
        base_sid = str(candidate.get('base_strategy_id') or candidate.get('strategy_id') or '')
        if base_sid.endswith('_short'):
            base_sid = base_sid[:-6]
        if base_sid in ('opening_breakout', 'range_breakout', 'intraday_range_break') and opening_high_raw is not None:
            structural_stop = float(opening_high_raw) * 1.002
        elif base_sid in ('vwap_momentum', 'vwap_reclaim') and candidate.get('vwap'):
            structural_stop = float(candidate['vwap']) * 1.002
        elif candidate.get('strategy_id') is None and opening_low_raw is not None and candidate.get('vwap'):
            structural_stop = max(float(candidate['vwap']) * 1.002, float(opening_high_raw or entry) * 1.002)
        stop = min(stop_by_pct, structural_stop) if structural_stop is not None else stop_by_pct
        if min_stop_pct > 0:
            stop = max(stop, entry * (1.0 + min_stop_pct / 100.0))
        if stop <= entry:
            stop = stop_by_pct
        risk_per_share = max(stop - entry, 0.01)
        quick_target = entry * (1.0 - quick_target_pct / 100.0)
        rr_target = entry - risk_per_share * min_rr
        target = min(quick_target, rr_target)

    rr = abs(target - entry) / risk_per_share if risk_per_share > 0 else 0.0
    return {
        'ok': True, 'side': side_c, 'order_side': v3_2_engine.order_side(side_c),
        'entry': entry, 'stop': stop, 'target': target,
        'risk_per_share': risk_per_share, 'rr': rr, 'min_risk_reward': min_rr,
        'max_stop_pct': max_stop_pct, 'quick_target_pct': quick_target_pct,
        'atr_based_stop_pct': atr_based_stop_pct, 'structural_stop': structural_stop,
        'used_strategy_profile': used_strategy_profile,
    }


def attach_intraday_trade_metrics(candidate: Dict[str, Any], settings: Dict[str, Any]) -> Dict[str, Any]:
    """Attach entry/target/stop/RR before strict learning reviews the candidate.

    Previously strict learning saw no target/stop yet, so every intraday row looked
    like reward/risk 0 and got blocked. Uses compute_intraday_risk_plan -- the same
    shared function build_intraday_plan uses for the actual order -- so what the
    reviewer/EV engine sees here IS what gets executed (report critical issue #1).
    """
    try:
        plan = compute_intraday_risk_plan(candidate, settings)
        if not plan.get('ok'):
            return candidate
        candidate['entry_price'] = round(plan['entry'], 2)
        candidate['stop_price'] = round(plan['stop'], 2)
        candidate['target_price'] = round(plan['target'], 2)
        candidate['rr_proxy'] = round(plan['rr'], 2)
        candidate['risk_reward'] = f"{round(plan['rr'], 2)}:1"
        candidate['min_risk_reward'] = plan['min_risk_reward']
        global_min_score = float(settings.get('min_score') or INTRADAY_MIN_SCORE)
        # MULTI-STRATEGY: a selected strategy has ALREADY gated its own eligibility on
        # its own min_confidence inside Signal.finalize() (strategies.py) -- e.g. Opening
        # Breakout requires 58, Trend Reversal requires 68. Re-applying the flat global
        # min_score (default 70) here on top of that made the per-strategy thresholds
        # non-authoritative: a strategy that had already cleared its own, deliberately
        # lower bar (58) could still get killed a few lines later in strict_learning_review
        # for "only" scoring 58 against a blanket 70 requirement that had nothing to do
        # with that strategy's own calibration. When a strategy has been selected, its own
        # min_confidence is the score gate; the global setting still applies as-is to
        # candidates the multi-strategy engine did not score (no strategy matched, or the
        # engine is disabled), so nothing changes there.
        if candidate.get('strategy_id') and candidate.get('strategy_min_confidence') is not None:
            candidate['min_score'] = float(candidate['strategy_min_confidence'])
        else:
            candidate['min_score'] = global_min_score
        candidate['min_volume_multiplier'] = float(settings.get('min_volume_multiplier') or INTRADAY_MIN_VOLUME_MULTIPLIER)
    except Exception as e:
        candidate['trade_metric_error'] = str(e)[:120]
    return candidate



def fetch_intraday_snapshot(ticker: str, market: Optional[str] = None) -> Dict[str, Any]:
    # Fetch a lightweight intraday snapshot for rule-based confirmation/exits.
    try:
        hist = yf.Ticker(ticker).history(period='1d', interval=INTRADAY_DATA_INTERVAL, timeout=YF_TIMEOUT)
        if hist is not None and not hist.empty:
            close = hist['Close'].dropna()
            high = hist['High'].dropna()
            low = hist['Low'].dropna()
            vol = hist['Volume'].dropna() if 'Volume' in hist else None
            last = float(close.iloc[-1]) if not close.empty else None
            open_price = float(hist['Open'].dropna().iloc[0]) if 'Open' in hist and not hist['Open'].dropna().empty else last
            session_high = float(high.max()) if not high.empty else last
            session_low = float(low.min()) if not low.empty else last
            recent_closes = [float(x) for x in close.tail(4).tolist()]
            recent_trend = 'flat'
            if len(recent_closes) >= 3:
                if recent_closes[-1] < recent_closes[-2] < recent_closes[-3]:
                    recent_trend = 'falling'
                elif recent_closes[-1] > recent_closes[-2] > recent_closes[-3]:
                    recent_trend = 'rising'
            completed_vol = vol.iloc[:-1] if vol is not None and len(vol) > 1 else vol
            avg_bar_volume = float(completed_vol.tail(20).mean()) if completed_vol is not None and not completed_vol.empty else None
            recent_window = vol.tail(3) if vol is not None else None
            last_bar_volume = float(recent_window.mean()) if recent_window is not None and not recent_window.empty else None
            vwap = None
            try:
                if vol is not None and not vol.empty and float(vol.sum()) > 0:
                    typical = (hist['High'] + hist['Low'] + hist['Close']) / 3
                    vwap = float((typical * hist['Volume']).sum() / hist['Volume'].sum())
            except Exception:
                vwap = None
            return {
                'ok': True,
                'ticker': ticker,
                'last': last,
                'open': open_price,
                'high': session_high,
                'low': session_low,
                'recent_closes': recent_closes,
                'recent_trend': recent_trend,
                'vwap': vwap,
                'last_bar_volume': last_bar_volume,
                'avg_bar_volume': avg_bar_volume,
                'bars': int(len(hist)),
            }
    except Exception as e:
        return {'ok': False, 'ticker': ticker, 'error': str(e)}
    last = fetch_last_price(ticker)
    return {'ok': bool(last), 'ticker': ticker, 'last': last, 'open': last, 'high': last, 'low': last, 'recent_trend': 'unknown', 'bars': 0}


def evaluate_opening_confirmation(plan: Dict[str, Any], settings: Dict[str, Any]) -> Dict[str, Any]:
    """Direction-aware opening confirmation shared by long and short plans."""
    if not settings.get('opening_confirmation_enabled', True):
        return {'allowed': True, 'reason': 'opening_confirmation_disabled', 'session': None, 'snapshot': None}
    market = plan.get('market') or 'IN'
    side = v3_2_engine.canonical_side(plan.get('direction') or ('SHORT' if plan.get('side') == 'SELL' else 'LONG'))
    session = get_market_session_state(market, settings.get('opening_wait_minutes'))
    if not session.get('can_enter'):
        return {'allowed': False, 'reason': session.get('state'), 'session': session, 'snapshot': None}
    snap = fetch_intraday_snapshot(plan['ticker'], market)
    if not snap.get('ok') or not snap.get('last'):
        return {'allowed': False, 'reason': 'no_intraday_confirmation_data', 'session': session, 'snapshot': snap}
    last = float(snap['last'])
    entry = float(plan.get('limit_price') or 0)
    stop = float(plan.get('stop_price') or 0)
    target = float(plan.get('target_price') or 0)
    if entry <= 0 or stop <= 0 or target <= 0:
        return {'allowed': False, 'reason': 'invalid_plan_prices', 'session': session, 'snapshot': snap}
    max_chase = float(settings.get('opening_max_entry_chase_pct') or 0)
    max_pullback = float(settings.get('opening_max_entry_pullback_pct') or 0)
    if side == 'LONG':
        if last > entry * (1 + max_chase / 100):
            return {'allowed': False, 'reason': 'price_too_far_above_entry_do_not_chase', 'session': session, 'snapshot': snap}
        if last < entry * (1 - max_pullback / 100):
            return {'allowed': False, 'reason': 'price_too_far_below_entry_or_setup_weakening', 'session': session, 'snapshot': snap}
        if last <= stop:
            return {'allowed': False, 'reason': 'price_near_or_below_stop_risk_zone', 'session': session, 'snapshot': snap}
        if target and last >= target:
            return {'allowed': False, 'reason': 'target_already_reached_before_entry', 'session': session, 'snapshot': snap}
        open_price = snap.get('open'); day_low = snap.get('low')
        if open_price and last < float(open_price) * 0.995 and snap.get('recent_trend') == 'falling':
            return {'allowed': False, 'reason': 'opening_reversal_down', 'session': session, 'snapshot': snap}
        if day_low and last <= float(day_low) * 1.002 and snap.get('recent_trend') == 'falling':
            return {'allowed': False, 'reason': 'breaking_opening_range_low', 'session': session, 'snapshot': snap}
    else:
        if last < entry * (1 - max_chase / 100):
            return {'allowed': False, 'reason': 'price_too_far_below_entry_do_not_chase', 'session': session, 'snapshot': snap}
        if last > entry * (1 + max_pullback / 100):
            return {'allowed': False, 'reason': 'price_too_far_above_entry_or_setup_weakening', 'session': session, 'snapshot': snap}
        if last >= stop:
            return {'allowed': False, 'reason': 'price_near_or_above_stop_risk_zone', 'session': session, 'snapshot': snap}
        if target and last <= target:
            return {'allowed': False, 'reason': 'target_already_reached_before_entry', 'session': session, 'snapshot': snap}
        open_price = snap.get('open'); day_high = snap.get('high')
        if open_price and last > float(open_price) * 1.005 and snap.get('recent_trend') == 'rising':
            return {'allowed': False, 'reason': 'opening_reversal_up', 'session': session, 'snapshot': snap}
        if day_high and last >= float(day_high) * 0.998 and snap.get('recent_trend') == 'rising':
            return {'allowed': False, 'reason': 'breaking_opening_range_high', 'session': session, 'snapshot': snap}
    min_vol = float(settings.get('opening_min_volume_multiplier') or 0)
    if min_vol > 0 and snap.get('avg_bar_volume') and snap.get('last_bar_volume'):
        if float(snap['last_bar_volume']) < float(snap['avg_bar_volume']) * min_vol:
            return {'allowed': False, 'reason': 'volume_confirmation_failed', 'session': session, 'snapshot': snap}
    reward = (target - last) if side == 'LONG' else (last - target)
    risk = (last - stop) if side == 'LONG' else (stop - last)
    rr = reward / risk if risk > 0 else 0
    if rr < float(settings.get('min_risk_reward') or 0):
        return {'allowed': False, 'reason': 'risk_reward_deteriorated_after_open', 'session': session, 'snapshot': snap, 'confirmed_rr': round(rr, 2)}
    return {'allowed': True, 'reason': 'opening_confirmation_passed', 'session': session, 'snapshot': snap, 'confirmed_entry': round(last, 2), 'confirmed_rr': round(rr, 2), 'side': side}



def explain_intraday_plan_skip(candidate: Dict[str, Any], trading_settings: Dict[str, Any], intraday_settings: Dict[str, Any]) -> str:
    entry = float(candidate.get('last') or 0)
    if entry <= 0:
        return 'No valid latest price for intraday paper order.'
    market = candidate.get('market') or intraday_settings.get('market') or 'IN'
    # Uses the SAME shared risk-plan function build_intraday_plan uses (report
    # critical issue #1), so this explanation reflects the strategy-specific
    # target/stop that would actually be used, not a global-settings-only proxy.
    risk_plan = compute_intraday_risk_plan(candidate, intraday_settings)
    if not risk_plan.get('ok'):
        return 'No valid latest price for intraday paper order.'
    stop = risk_plan['stop']
    target = risk_plan['target']
    rr = risk_plan['rr']
    if rr < float(intraday_settings.get('min_risk_reward') or 0):
        return f"Intraday reward/risk {rr:.2f}:1 is below minimum {intraday_settings.get('min_risk_reward')}:1."
    sizing = compute_integer_position_size(entry, stop, trading_settings, market, risk_scale=candidate.get('risk_scale', 1.0))
    if sizing['quantity'] <= 0:
        return sizing['skip_reason']
    size_reasons = apply_intraday_size_efficiency_gate(candidate, sizing, intraday_settings)
    if size_reasons:
        return 'Size filter skipped trade: ' + '; '.join(size_reasons)
    side = _candidate_side(candidate)
    cost_gate = intraday_cost_gate(entry, target, int(sizing.get('quantity') or 0), market, intraday_settings, side=side)
    if not cost_gate.get('ok'):
        sym = get_currency_info(market, candidate.get('ticker')).get('symbol', '₹')
        return 'Cost filter skipped trade: ' + '; '.join(cost_gate.get('reasons') or []) + f". Gross target {sym}{cost_gate.get('gross_target_profit')}, estimated costs {sym}{cost_gate.get('expected_round_trip_cost')}."
    return 'Intraday trade plan failed final safety checks.'


def build_intraday_plan(candidate: Dict[str, Any], trading_settings: Dict[str, Any], intraday_settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    entry = float(candidate.get('last') or 0)
    if entry <= 0:
        return None
    market = candidate.get('market') or intraday_settings.get('market') or 'IN'
    # CRITICAL FIX (report issue #1): this used to recompute stop/target from
    # global intraday_settings only, ignoring candidate['strategy_stop_pct']/
    # ['strategy_target_pct'] that the selector and EV engine had already judged
    # this candidate on -- the actual order could silently execute a different
    # risk profile than the one the historical EV number was earned on. Now uses
    # the SAME shared function attach_intraday_trade_metrics uses, so the plan
    # that gets sized, gated and opened here is the same one strict_learning_review
    # and the EV engine already reviewed. See compute_intraday_risk_plan's
    # docstring for why this also fixes Replay without a separate change there.
    risk_plan = compute_intraday_risk_plan(candidate, intraday_settings)
    if not risk_plan.get('ok'):
        return None
    stop = risk_plan['stop']
    target = risk_plan['target']
    rr = risk_plan['rr']
    max_stop_pct = risk_plan['max_stop_pct']
    if rr < float(intraday_settings.get('min_risk_reward') or 0):
        return None
    sizing = compute_integer_position_size(entry, stop, trading_settings, market, risk_scale=candidate.get('risk_scale', 1.0))
    quantity = int(sizing.get('quantity') or 0)
    if quantity <= 0:
        return None
    size_reasons = apply_intraday_size_efficiency_gate(candidate, sizing, intraday_settings)
    if size_reasons:
        candidate.setdefault('blocked_reasons', []).extend(size_reasons)
        candidate['blocked_reason'] = 'size_filter_no_edge: ' + '; '.join(size_reasons)
        return None
    side = _candidate_side(candidate)
    cost_gate = intraday_cost_gate(entry, target, quantity, market, intraday_settings, side=side)
    candidate['cost_gate'] = cost_gate
    if not cost_gate.get('ok'):
        candidate.setdefault('blocked_reasons', []).extend(cost_gate.get('reasons') or [])
        candidate['blocked_reason'] = 'cost_filter_no_edge: ' + '; '.join(cost_gate.get('reasons') or [])
        return None
    # Candidate-level rupee EV (report ask -- unify the % probability model with
    # this trade's own execution economics). Reporting/logging only -- see
    # compute_candidate_expected_value_currency's docstring for why this doesn't
    # replace the cost_gate check just above.
    candidate_ev = compute_candidate_expected_value_currency(candidate, entry, stop, target, quantity, market)
    candidate['expected_value_inr'] = candidate_ev.get('expected_value') if candidate_ev.get('ok') else None
    currency = get_currency_info(market, candidate.get('ticker'))
    return {
        'market': market,
        'horizon': 'intraday',
        'ticker': candidate['ticker'],
        'company': candidate.get('company') or candidate['ticker'],
        'side': v3_2_engine.order_side(side),
        'direction': side,
        'quantity': quantity,
        'order_type': 'LIMIT',
        'limit_price': round(entry, 2),
        'stop_price': round(stop, 2),
        'target_price': round(target, 2),
        'estimated_value': round(quantity * entry, 2),
        'currency_symbol': currency['symbol'],
        'rationale': f"Intraday {side.lower()} candidate: score {candidate.get('score')}, change {candidate.get('change_pct')}%, trend {candidate.get('recent_trend')}, VWAP confirmation {candidate.get('above_vwap')}, opening breakout {candidate.get('breakout')}.",
        'risk_notes': f"{'Strategy-specific' if risk_plan.get('used_strategy_profile') else 'Default'} intraday entry with max stop about {round(max_stop_pct, 2)}% and target about {round(risk_plan.get('quick_target_pct') or 0, 2)}%+. Uses {currency['symbol']}{sizing.get('capital')} simulation capital for {market}. Forced exit before close is enabled from the Intraday page.",
        'order_payload': {
            'engine': 'intraday',
            'side': v3_2_engine.order_side(side),
            'direction': side,
            'learning_bucket': f"{market}:intraday:intraday",
            'candidate': candidate,
            'entry': round(entry, 2),
            'target': round(target, 2),
            'stop': round(stop, 2),
            'risk_reward': round(rr, 2),
            'sizing': sizing,
            'cost_gate': cost_gate,
            'expected_round_trip_cost': cost_gate.get('expected_round_trip_cost'),
            'expected_net_profit_at_target': cost_gate.get('expected_net_profit_at_target'),
            'gross_target_profit': cost_gate.get('gross_target_profit'),
            'profit_to_cost_ratio': cost_gate.get('profit_to_cost_ratio'),
            'expected_value_currency': candidate_ev if candidate_ev.get('ok') else None,
            'profit_book_pct': max(float(intraday_settings.get('profit_book_pct') or 0), INTRADAY_PROFIT_BOOK_PCT),
            'force_exit_before_close_minutes': int(intraday_settings.get('force_exit_before_close_minutes') or INTRADAY_FORCE_EXIT_BEFORE_CLOSE_MINUTES),
            'used_strategy_risk_profile': risk_plan.get('used_strategy_profile'),
        }
    }


def _compact_intraday_plan_for_claude(item: Dict[str, Any]) -> Dict[str, Any]:
    plan = item.get('plan') or {}
    candidate = item.get('candidate') or {}
    payload = plan.get('order_payload') or {}
    cost_gate = payload.get('cost_gate') or candidate.get('cost_gate') or {}
    return {
        'ticker': plan.get('ticker') or candidate.get('ticker'),
        'market': plan.get('market') or candidate.get('market'),
        'score': candidate.get('score'),
        'move_from_open_pct': candidate.get('change_pct'),
        'last_price': candidate.get('last'),
        'vwap': candidate.get('vwap'),
        'above_vwap': candidate.get('above_vwap'),
        'opening_breakout': candidate.get('breakout'),
        'volume_multiplier': candidate.get('volume_multiplier'),
        'recent_trend': candidate.get('recent_trend'),
        'data_source': candidate.get('data_source_label') or candidate.get('data_provider'),
        'entry': plan.get('limit_price'),
        'target': plan.get('target_price'),
        'stop': plan.get('stop_price'),
        'quantity': plan.get('quantity'),
        'estimated_value': plan.get('estimated_value'),
        'risk_reward': payload.get('risk_reward'),
        'gross_target_profit': payload.get('gross_target_profit'),
        'expected_round_trip_cost': payload.get('expected_round_trip_cost'),
        'expected_net_profit_at_target': payload.get('expected_net_profit_at_target'),
        'profit_to_cost_ratio': payload.get('profit_to_cost_ratio'),
        'score_explanation': candidate.get('score_explanation'),
    }


def call_claude_intraday_controller(planned_items: List[Dict[str, Any]], intraday_settings: Dict[str, Any], trading_settings: Dict[str, Any], session: Dict[str, Any], goal_status: Dict[str, Any], trigger: str) -> Dict[str, Any]:
    """Ask Claude to choose/approve from already-safe intraday plans.

    Claude gets bounded control only after deterministic hard gates have produced
    valid plans. The response never places orders directly; it only marks plans
    ALLOW/BLOCK/WATCH and can suggest target/stop tweaks that are rechecked by
    the deterministic engine before any order is persisted.
    """
    mode = normalize_claude_intraday_mode(intraday_settings.get('claude_control_mode'))
    result = {
        'mode': mode,
        'enabled': mode != 'off',
        'used': False,
        'model': None,
        'error': None,
        'decisions': {},
        'raw_decisions': [],
        'note': None,
    }
    if mode == 'off' or not planned_items:
        return result
    max_reviews = min(max(1, int(intraday_settings.get('claude_max_reviews_per_run') or CLAUDE_INTRADAY_MAX_REVIEWS_PER_RUN)), 10, len(planned_items))
    compact = [_compact_intraday_plan_for_claude(x) for x in planned_items[:max_reviews]]
    api_key = os.environ.get('ANTHROPIC_API_KEY')
    if not api_key:
        result['error'] = 'ANTHROPIC_API_KEY not configured; Claude control cannot run.'
        result['note'] = 'Claude unavailable. In approval/full-control modes no new orders are allowed.'
        return result
    estimated_input_tokens = 3200 + len(compact) * 850
    estimated_output_tokens = min(CLAUDE_INTRADAY_MAX_TOKENS, 900 + len(compact) * 220)
    estimated_cost = calculate_claude_cost(estimated_input_tokens, estimated_output_tokens)
    budget = get_ai_budget_status(estimated_cost.get('cost_inr', 0))
    if not budget.get('allowed'):
        result['error'] = 'Claude budget guard blocked intraday control: ' + ', '.join(budget.get('reasons') or [])
        result['note'] = 'Claude unavailable due to AI budget guard. In approval/full-control modes no new orders are allowed.'
        return result
    today = datetime.datetime.now(ZoneInfo('Asia/Kolkata')).strftime('%A, %d %B %Y, %I:%M %p IST')
    min_conf = int(intraday_settings.get('claude_min_confidence') or CLAUDE_INTRADAY_MIN_CONFIDENCE)
    target_instruction = str(intraday_settings.get('claude_target_instruction') or CLAUDE_INTRADAY_TARGET_INSTRUCTION)[:1200]
    market = intraday_settings.get('market') or 'IN'
    prompt = f"""You are a bounded intraday trading controller inside a paper-trading risk engine.
Today/time: {today}
Market: {market}
Mode requested: {mode}
Trigger: {trigger}
User objective: {target_instruction}

IMPORTANT SAFETY AND CONTROL RULES:
- You are not allowed to guarantee profit.
- Prefer NO TRADE over weak trade.
- Only choose from the provided candidate plans; do not invent new tickers.
- The engine has already calculated entry, target, stop, quantity, expected total costs, and expected net profit after costs.
- You may suggest a tighter stop or more realistic target, but the engine will reject anything that breaks hard gates.
- Do not approve a trade if momentum is fading, target profit barely covers costs, data looks weak/stale, R/R is poor, or the setup is already chased.
- Minimum Claude confidence required by the engine: {min_conf}.
- Hard gates still enforced by engine after your response: fresh data, market hours, max trades, max open positions, mandatory stop-loss, cost coverage, minimum expected net profit, gross/cost ratio, daily/weekly loss guard.

Session: {json.dumps(session, default=_json_safe)}
Goal/risk guard: {json.dumps(goal_status, default=_json_safe)}
Intraday settings: {json.dumps({k: intraday_settings.get(k) for k in ['min_score','min_risk_reward','quick_target_pct','max_stop_loss_pct','min_expected_net_profit_inr','min_expected_net_profit_usd','min_gross_profit_to_cost_ratio','max_trades_per_day']}, default=_json_safe)}

Return ONLY valid JSON with this shape:
{{
  "summary": "one sentence",
  "decisions": [
    {{
      "rank": 1,
      "ticker": "SYMBOL",
      "decision": "ALLOW" | "BLOCK" | "WATCH",
      "confidence": 0-100,
      "reason": "short practical reason",
      "risk_flags": ["flag1"],
      "suggested_target_price": null or number,
      "suggested_stop_price": null or number,
      "max_hold_minutes": null or integer
    }}
  ]
}}

CANDIDATE_PLANS_JSON:
{json.dumps(compact, separators=(',', ':'), default=_json_safe)}
"""
    try:
        client = anthropic.Anthropic(api_key=api_key)
        model_name = os.environ.get('ANTHROPIC_MODEL', 'claude-sonnet-5')
        response = client.messages.create(
            model=model_name,
            max_tokens=CLAUDE_INTRADAY_MAX_TOKENS,
            messages=[{'role': 'user', 'content': prompt}],
        )
        usage = getattr(response, 'usage', None)
        if usage:
            log_api_cost(
                'anthropic_intraday_controller', market, 'intraday', model_name,
                int(getattr(usage, 'input_tokens', 0) or 0),
                int(getattr(usage, 'output_tokens', 0) or 0),
                notes='Claude bounded intraday control review',
                metadata={'candidate_count': len(compact), 'mode': mode, 'trigger': trigger}
            )
        text_blocks = [b.text for b in response.content if getattr(b, 'type', None) == 'text']
        if not text_blocks:
            raise RuntimeError(f'Claude returned no text content (stop_reason={getattr(response, "stop_reason", None)}).')
        text = re.sub(r'```json|```', '', text_blocks[0].strip()).strip()
        try:
            parsed = json.loads(text)
        except Exception:
            match = re.search(r'\{[\s\S]*\}', text)
            if not match:
                raise
            parsed = json.loads(match.group())
        raw_decisions = parsed.get('decisions') if isinstance(parsed, dict) else parsed
        if not isinstance(raw_decisions, list):
            raw_decisions = []
        decisions = {}
        allowed_tickers = {str(x.get('ticker') or '').upper() for x in compact}
        for i, d in enumerate(raw_decisions, start=1):
            if not isinstance(d, dict):
                continue
            ticker = str(d.get('ticker') or '').upper().strip()
            if not ticker or ticker not in allowed_tickers:
                continue
            decision = str(d.get('decision') or 'WATCH').upper().strip()
            if decision not in ('ALLOW', 'BLOCK', 'WATCH'):
                decision = 'WATCH'
            try:
                confidence = max(0, min(100, int(float(d.get('confidence') or 0))))
            except Exception:
                confidence = 0
            decisions[ticker] = {
                'rank': int(d.get('rank') or i) if str(d.get('rank') or '').replace('.','',1).isdigit() else i,
                'ticker': ticker,
                'decision': decision,
                'confidence': confidence,
                'reason': str(d.get('reason') or '')[:500],
                'risk_flags': d.get('risk_flags') if isinstance(d.get('risk_flags'), list) else [],
                'suggested_target_price': _safe_float(d.get('suggested_target_price')),
                'suggested_stop_price': _safe_float(d.get('suggested_stop_price')),
                'max_hold_minutes': _safe_int(d.get('max_hold_minutes')) if d.get('max_hold_minutes') is not None else None,
            }
        result.update({
            'used': True,
            'model': model_name,
            'decisions': decisions,
            'raw_decisions': raw_decisions,
            'note': (parsed.get('summary') if isinstance(parsed, dict) else None) or f'Claude reviewed {len(compact)} intraday plan(s).',
        })
        return result
    except Exception as e:
        result['error'] = str(e)[:300]
        result['note'] = 'Claude intraday control failed. In approval/full-control modes no new orders are allowed.'
        return result


def apply_claude_intraday_decision_to_plan(plan: Dict[str, Any], decision: Dict[str, Any], trading_settings: Dict[str, Any], intraday_settings: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    """Apply Claude's target/stop suggestions, then re-run hard sizing/cost gates."""
    if not decision:
        return plan, None
    entry = float(plan.get('limit_price') or 0)
    market = plan.get('market') or intraday_settings.get('market') or 'IN'
    if entry <= 0:
        return None, 'claude_control_invalid_entry'
    target = float(plan.get('target_price') or 0)
    stop = float(plan.get('stop_price') or 0)
    side = v3_2_engine.canonical_side(plan.get('direction') or ('SHORT' if plan.get('side') == 'SELL' else 'LONG'))
    suggested_target = decision.get('suggested_target_price')
    suggested_stop = decision.get('suggested_stop_price')
    if suggested_stop and float(suggested_stop) > 0:
        suggested_stop = float(suggested_stop)
        max_stop_pct = float(intraday_settings.get('max_stop_loss_pct') or INTRADAY_MAX_STOP_LOSS_PCT)
        if side == 'LONG':
            widest_allowed_stop = entry * (1 - max_stop_pct / 100)
            stop = max(suggested_stop, widest_allowed_stop)
        else:
            widest_allowed_stop = entry * (1 + max_stop_pct / 100)
            stop = min(suggested_stop, widest_allowed_stop)
    if suggested_target and float(suggested_target) > 0:
        suggested_target = float(suggested_target)
        if (side == 'LONG' and suggested_target > entry) or (side == 'SHORT' and suggested_target < entry):
            target = suggested_target
    if side == 'LONG':
        if stop <= 0 or stop >= entry: return None, 'claude_control_invalid_stop_after_suggestion'
        if target <= entry: return None, 'claude_control_invalid_target_after_suggestion'
        risk_per_share = max(entry - stop, 0.01)
        rr = (target - entry) / risk_per_share if risk_per_share > 0 else 0
    else:
        if stop <= entry: return None, 'claude_control_invalid_stop_after_suggestion'
        if target <= 0 or target >= entry: return None, 'claude_control_invalid_target_after_suggestion'
        risk_per_share = max(stop - entry, 0.01)
        rr = (entry - target) / risk_per_share if risk_per_share > 0 else 0
    min_rr = float(intraday_settings.get('min_risk_reward') or INTRADAY_MIN_RISK_REWARD)
    if rr < min_rr:
        return None, f'claude_control_rr_failed: {round(rr,2)} needs {min_rr}+'
    candidate = (plan.get('order_payload') or {}).get('candidate') or {}
    sizing = compute_integer_position_size(entry, stop, trading_settings, market, risk_scale=candidate.get('risk_scale', 1.0))
    quantity = int(sizing.get('quantity') or 0)
    if quantity <= 0:
        return None, sizing.get('skip_reason') or 'claude_control_sizing_failed'
    size_reasons = apply_intraday_size_efficiency_gate(candidate, sizing, intraday_settings)
    if size_reasons:
        return None, 'claude_control_size_filter_failed: ' + '; '.join(size_reasons)
    side = _candidate_side(candidate)
    cost_gate = intraday_cost_gate(entry, target, quantity, market, intraday_settings, side=side)
    if not cost_gate.get('ok'):
        return None, 'claude_control_cost_gate_failed: ' + '; '.join(cost_gate.get('reasons') or [])
    plan['quantity'] = quantity
    plan['stop_price'] = round(stop, 2)
    plan['target_price'] = round(target, 2)
    plan['estimated_value'] = round(quantity * entry, 2)
    plan.setdefault('order_payload', {})
    plan['order_payload'].update({
        'claude_control': decision,
        'target': round(target, 2),
        'stop': round(stop, 2),
        'risk_reward': round(rr, 2),
        'sizing': sizing,
        'cost_gate': cost_gate,
        'expected_round_trip_cost': cost_gate.get('expected_round_trip_cost'),
        'expected_net_profit_at_target': cost_gate.get('expected_net_profit_at_target'),
        'gross_target_profit': cost_gate.get('gross_target_profit'),
        'profit_to_cost_ratio': cost_gate.get('profit_to_cost_ratio'),
    })
    plan['rationale'] = (plan.get('rationale') or '') + f" Claude control: {decision.get('decision')} {decision.get('confidence')}% — {decision.get('reason')}"
    return plan, None


def prepare_intraday_plans_for_execution(scan: Dict[str, Any], trading_settings: Dict[str, Any], intraday_settings: Dict[str, Any], open_tickers: set, review_limit: int) -> List[Dict[str, Any]]:
    planned: List[Dict[str, Any]] = []
    for candidate in scan.get('eligible', []):
        if len(planned) >= review_limit:
            break
        if candidate.get('ticker') in open_tickers:
            candidate.setdefault('blocked_reasons', []).append('already_open_position')
            continue
        plan = build_intraday_plan(candidate, trading_settings, intraday_settings)
        if not plan:
            candidate.setdefault('blocked_reason', explain_intraday_plan_skip(candidate, trading_settings, intraday_settings))
            if candidate.get('blocked_reason') and candidate.get('blocked_reason') not in candidate.setdefault('blocked_reasons', []):
                candidate['blocked_reasons'].append(candidate.get('blocked_reason'))
            continue
        planned.append({'candidate': candidate, 'plan': plan})
    return planned


def execute_intraday_plans(planned_items: List[Dict[str, Any]], trading_settings: Dict[str, Any], intraday_settings: Dict[str, Any], trigger: str, goal_status: Dict[str, Any], remaining_trades: int, slots: int) -> Tuple[List[Dict[str, Any]], int, int]:
    orders = []
    for item in planned_items:
        if slots <= 0 or remaining_trades <= 0:
            break
        candidate = item.get('candidate') or {}
        plan = item.get('plan') or {}
        if not plan:
            continue
        plan['risk_notes'] = (plan.get('risk_notes') or '') + f" Weekly guard: net ₹{goal_status.get('net_after_api_inr', 0)} / target ₹{goal_status.get('target_profit_inr', 0)}; trigger={trigger}; mode={trading_settings.get('mode')}; Claude mode={normalize_claude_intraday_mode(intraday_settings.get('claude_control_mode'))}."
        try:
            order = persist_trade_order(plan, trading_settings, source='paper-auto-intraday' if trigger.startswith('paper-auto') else 'intraday-engine')
            orders.append(order)
            candidate['order_status'] = order.get('status') if isinstance(order, dict) else 'ORDER_RECORDED'
            candidate['order_id'] = order.get('id') if isinstance(order, dict) else None
            remaining_trades -= 1
            slots -= 1
        except Exception as order_error:
            candidate.setdefault('blocked_reasons', []).append('order_persist_failed: ' + str(order_error)[:180])
    return orders, remaining_trades, slots


def _intraday_json_safe(value: Any) -> Any:
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, (datetime.datetime, datetime.date)):
        return value.isoformat()
    if isinstance(value, dict):
        return {k: _intraday_json_safe(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_intraday_json_safe(v) for v in value]
    return value


def log_intraday_run(result: Dict[str, Any], started_at: datetime.datetime, finished_at: Optional[datetime.datetime] = None) -> None:
    """Persist every manual/auto intraday engine check so the UI can show when the system tried, what it checked, and why it did or did not trade."""
    conn = get_db_connection()
    if conn is None:
        return
    finished_at = finished_at or utc_now_naive()
    session = result.get('session') or {}
    settings = result.get('settings') or {}
    trading_settings = result.get('trading_settings') or {}
    candidates = result.get('candidates') or []
    watch = result.get('watch') or []
    orders = result.get('orders') or []
    exits = result.get('exits') or {}
    source_info = result.get('data_source') or result.get('source') or get_market_data_source_info(settings.get('market') or session.get('market'), 'intraday_engine_check')
    exit_count = len(exits.get('closed') or []) if isinstance(exits, dict) else 0
    scanned_count = int(result.get('scanned_count') or result.get('scan', {}).get('scanned_count') or len(candidates) + len(watch) or 0)
    eligible_count = int(result.get('eligible_count') or len(candidates) or 0)
    watch_count = int(result.get('watch_count') or len(watch) or 0)
    order_count = int(result.get('order_count') or len(orders) or 0)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO intraday_run_log
                        (started_at, finished_at, trigger, market, mode, session_state, message,
                         scanned_count, eligible_count, watch_count, order_count, exit_count,
                         can_enter, data_provider, data_source, data_source_type, claude_cost_inr, result_json)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """, (
                    started_at, finished_at, result.get('trigger'), settings.get('market') or session.get('market'),
                    trading_settings.get('mode') or settings.get('execution_mode'), session.get('state'), result.get('message'),
                    scanned_count, eligible_count, watch_count, order_count, exit_count,
                    bool(session.get('can_enter')), source_info.get('actual_provider') or source_info.get('provider'), source_info.get('source_label') or source_info.get('source_name'), source_info.get('source_type'), 0,
                    psycopg2.extras.Json(_intraday_json_safe({
                        'message': result.get('message'),
                        'data_source': source_info,
                        'session': session,
                        'trigger': result.get('trigger'),
                        'enabled': result.get('enabled'),
                        'scanned_count': scanned_count,
                        'eligible_count': eligible_count,
                        'watch_count': watch_count,
                        'order_count': order_count,
                        'selection_metadata': result.get('selection_metadata'),
                        'exit_count': exit_count,
                        'candidates': candidates[:25],
                        'watch': watch[:25],
                        'orders': orders[:25],
                        'errors': (result.get('errors') or [])[:25],
                    }))
                ))
    except Exception as e:
        print(f"[WARN] Could not log intraday run: {e}")
    finally:
        conn.close()


def get_recent_intraday_runs(limit: int = 20) -> List[Dict[str, Any]]:
    conn = get_db_connection()
    if conn is None:
        return []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""
                SELECT id, started_at, finished_at, trigger, market, mode, session_state, message,
                       scanned_count, eligible_count, watch_count, order_count, exit_count, can_enter,
                       data_provider, data_source, data_source_type, claude_cost_inr, result_json
                FROM intraday_run_log
                ORDER BY finished_at DESC
                LIMIT %s
            """, (limit,))
            rows = cur.fetchall()
    except Exception as e:
        print(f"[WARN] Could not load intraday run log: {e}")
        rows = []
    finally:
        conn.close()
    def clean(row):
        out = {}
        for k, v in dict(row).items():
            if hasattr(v, 'as_tuple'):
                out[k] = float(v)
            elif isinstance(v, (datetime.datetime, datetime.date)):
                out[k] = v.isoformat()
            else:
                out[k] = v
        return out
    return [clean(r) for r in rows]



def _clean_db_row(row: Dict[str, Any]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for k, v in dict(row).items():
        if hasattr(v, 'as_tuple'):
            out[k] = float(v)
        elif isinstance(v, (datetime.datetime, datetime.date)):
            out[k] = v.isoformat()
        else:
            out[k] = v
    return out


def run_trading_self_scan(market: str, horizon: str, settings: Dict[str, Any]) -> Dict[str, Any]:
    """Build a fresh deterministic candidate list for Trading Automation.

    This is the independent mode requested for the main Trading Automation
    engine. It uses the same public, explainable professional-analysis funnel as
    the scanner, but keeps it inside automation and does not require an existing
    locked First Scan. It does not call Claude by default; ranking is
    deterministic, then strict-learning and risk controls still decide whether
    any order is allowed.
    """
    scan_started = utc_now_naive()
    market, horizon = validate_market_horizon(market, horizon)
    # PRIORITY FIX (review round 3, #1): only the intraday horizon is subject
    # to the Large/Mid-cap restriction -- swing/positional automation keeps
    # scanning the full configured universe, since that cap requirement was
    # specifically an intraday strategy constraint.
    configured_universe = get_intraday_scan_universe(market) if horizon == 'intraday' else load_market_universe(market)
    limit = min(len(configured_universe), max(20, int(settings.get('self_scan_universe_limit') or TRADING_SELF_SCAN_UNIVERSE_LIMIT)))
    universe = configured_universe[:limit]
    source_info = get_market_data_source_info(market, 'trading_self_scan')
    snapshots = download_universe_snapshots(universe)
    liquid = liquidity_filter(snapshots, market)
    momentum = apply_momentum_stage(liquid)
    technical = apply_technical_stage(momentum)
    deep = enrich_deep_candidates(technical)
    learning_context = get_learning_context(market, horizon)
    deep = apply_learning_adjustments(deep, learning_context)
    market_context = get_market_context(market)
    deep = apply_strategy_memory_adjustments(deep, market, horizon, market_context)

    min_score = float(settings.get('self_scan_min_score') or TRADING_SELF_SCAN_MIN_SCORE)
    expert_ready = [c for c in deep if float(c.get('final_pre_ai_score') or c.get('preliminary_score') or 0) >= min_score]
    if not expert_ready:
        expert_ready = deep[:FINAL_PICK_LIMIT]
    picks = deterministic_rank_candidates(expert_ready, market, horizon)
    strict_result = apply_strict_learning_to_picks(picks, expert_ready, market, horizon, market_context)
    picks = strict_result.get('picks', picks)

    completed_at = utc_now_naive()
    counts = {
        'configured_universe': len(configured_universe),
        'self_scan_universe': len(universe),
        'price_snapshots': len(snapshots),
        'liquidity_pass': len(liquid),
        'momentum_pass': len(momentum),
        'technical_pass': len(technical),
        'deep_analysis': len(deep),
        'expert_ready': len(expert_ready),
        'final_picks': len(picks),
    }
    methodology = get_methodology(counts)
    methodology['engine'] = 'trading_automation_self_scan'
    methodology['selection_mode'] = 'self_scan'
    methodology['stages'].append({
        'stage': 'Automation self-scan mode',
        'method': 'Runs inside Trading Automation when enabled. It ranks stocks from the configured NSE/US universe using liquidity, momentum, technicals, fundamentals, news sentiment, market regime, learning memory, risk/reward and opening confirmation. It does not need a locked scanner prediction.'
    })
    return {
        'picks': picks,
        'market': market,
        'horizon': horizon,
        'timestamp': completed_at.isoformat(),
        'started_at': scan_started.isoformat(),
        'completed_at': completed_at.isoformat(),
        'cached': False,
        'locked': False,
        'self_scan': True,
        'selection_mode': 'self_scan',
        'total_scanned': len(universe),
        'funnel_counts': counts,
        'market_context': market_context,
        'methodology': methodology,
        'model': 'deterministic-professional-self-scan',
        'data_source': source_info,
        'strict_learning_mode': strict_result.get('summary'),
        'no_trade_recommendation': bool((strict_result.get('summary') or {}).get('no_trade_recommendation')),
        'errors': [INTRADAY_CAP_UNAVAILABLE_ERRORS[market]] if (horizon == 'intraday' and not configured_universe and market in INTRADAY_CAP_UNAVAILABLE_ERRORS) else [],
        'message': (INTRADAY_CAP_UNAVAILABLE_ERRORS.get(market) if (horizon == 'intraday' and not configured_universe) else
                    'Trading Automation self-scan built fresh expert-style candidates without requiring First Scan prediction data.')
    }


def resolve_trading_candidate_source(market: str, horizon: str, settings: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:
    selection_mode = settings.get('selection_mode') or 'locked_scan'
    meta: Dict[str, Any] = {'selection_mode': selection_mode, 'locked_scan_available': False, 'used_source': None}
    cached = None
    if selection_mode in ('locked_scan', 'auto'):
        cached = get_locked_cached_scan(market, horizon) or get_cached_scan(market, horizon)
        if cached:
            meta.update({'locked_scan_available': True, 'used_source': 'locked_scan', 'order_source': 'locked-scan-confirmed'})
            cached['selection_mode'] = 'locked_scan'
            return cached, meta
    if selection_mode in ('self_scan', 'auto'):
        try:
            cached = run_trading_self_scan(market, horizon, settings)
            meta.update({'locked_scan_available': False, 'used_source': 'self_scan', 'order_source': 'self-scan-confirmed'})
            return cached, meta
        except Exception as e:
            meta.update({'self_scan_error': str(e)[:240]})
            if selection_mode == 'auto':
                return None, meta
            raise
    return None, meta


def log_trading_automation_run(result: Dict[str, Any], started_at: datetime.datetime, market: str, horizon: str, finished_at: Optional[datetime.datetime] = None) -> None:
    """Persist every Trading Automation check so the UI survives refreshes, restarts, and multi-worker requests."""
    conn = get_db_connection()
    if conn is None:
        return
    finished_at = finished_at or utc_now_naive()
    settings = result.get('settings') or {}
    goal_status = result.get('goal_status') or {}
    opening_status = result.get('opening_status') or get_market_session_state(market, settings.get('opening_wait_minutes'))
    entry_checks = result.get('entry_checks') or []
    orders = result.get('orders') or []
    exits = result.get('exits') or {}
    data_source = result.get('data_source') or get_market_data_source_info(market, 'trading_automation_check')
    approved_count = len([c for c in entry_checks if c.get('allowed')])
    blocked_count = len([c for c in entry_checks if not c.get('allowed')])
    exit_count = len(exits.get('closed') or []) if isinstance(exits, dict) else 0
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO trading_automation_run_log
                        (started_at, finished_at, trigger, market, horizon, mode, message,
                         locked_scan_available, entry_check_count, approved_count, blocked_count,
                         order_count, exit_count, can_open_new_trades, session_state,
                         data_provider, data_source, data_source_type, result_json)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                """, (
                    started_at, finished_at, result.get('trigger'), market, horizon, settings.get('mode'), result.get('message') or result.get('error'),
                    bool(result.get('locked_scan_available')), len(entry_checks), approved_count, blocked_count,
                    len(orders), exit_count, bool(goal_status.get('can_open_new_trades')), opening_status.get('state'),
                    data_source.get('actual_provider') or data_source.get('provider'), data_source.get('source_label') or data_source.get('source_name'), data_source.get('source_type'),
                    psycopg2.extras.Json(_intraday_json_safe({
                        'message': result.get('message'),
                        'error': result.get('error'),
                        'trigger': result.get('trigger'),
                        'market': market,
                        'horizon': horizon,
                        'mode': settings.get('mode'),
                        'data_source': data_source,
                        'opening_status': opening_status,
                        'goal_status': goal_status,
                        'locked_scan_available': bool(result.get('locked_scan_available')),
                        'entry_checks': entry_checks[:25],
                        'orders': orders[:25],
                        'exits': exits,
                    }))
                ))
    except Exception as e:
        print(f"[WARN] Could not log trading automation run: {e}")
    finally:
        conn.close()


