def compute_strategy_correlation(market: Optional[str] = None, days: int = 90) -> Dict[str, Any]:
    """Report fix #6 -- strategy correlation: "ten strategies shouldn't all lose
    together and pretend they're diversified". Measures, for every pair of
    strategies, how correlated their DAILY net returns are and how often they
    land on a losing day at the SAME time, using the replay record (the only
    source with a reliable per-trade timestamp -- executed paper/live rows don't
    currently carry one; see _load_strategy_trade_rows_executed).

    A high positive return_correlation between two strategies means they are
    largely the same underlying market bet wearing two different rule sets --
    exactly the report's point that several strategies "depend on the same
    underlying variables" (VWAP, trend, momentum, volume) and can fail together
    even though they look like ten independent opinions. co_loss_rate_pct makes
    that concrete: the share of days BOTH strategies traded where BOTH lost money.

    Returns ok=False (never raises) if there isn't yet enough overlapping daily
    history to say anything meaningful -- a thin read here should not be
    presented with false confidence.
    """
    try:
        rows = _load_strategy_trade_rows_replay(market, days)
    except Exception as e:
        return {'ok': False, 'note': f'trade history load failed: {str(e)[:120]}'}
    if not rows:
        return {'ok': False, 'note': 'no replay trade history available yet'}

    daily: Dict[Tuple[Any, str], List[float]] = {}
    for r in rows:
        sid = r.get('strategy_id')
        et = r.get('entry_time')
        ret = _safe_float(r.get('net_return_pct'))
        if not sid or et is None or ret is None:
            continue
        try:
            day = et.date() if hasattr(et, 'date') else et
        except Exception:
            continue
        daily.setdefault((day, sid), []).append(ret)

    strategy_ids = sorted({sid for (_, sid) in daily})
    all_days = sorted({day for (day, _) in daily})
    if len(strategy_ids) < 2 or len(all_days) < 10:
        return {'ok': False,
                'note': f'only {len(all_days)} trading day(s) of replay evidence across {len(strategy_ids)} '
                        f'strategy(ies) -- need at least 10 overlapping days for a meaningful correlation read'}

    frame = pd.DataFrame(index=all_days, columns=strategy_ids, dtype=float)
    loss_frame = pd.DataFrame(index=all_days, columns=strategy_ids, dtype=float)
    for (day, sid), rets in daily.items():
        total = sum(rets)
        frame.loc[day, sid] = total
        loss_frame.loc[day, sid] = 1.0 if total < 0 else 0.0

    corr = frame.corr(min_periods=10)
    pairs = []
    for i, a in enumerate(strategy_ids):
        for b in strategy_ids[i + 1:]:
            c = corr.loc[a, b] if a in corr.index and b in corr.columns else None
            if c is None or pd.isna(c):
                continue
            both_traded = frame[[a, b]].dropna()
            overlap_days = len(both_traded)
            if overlap_days < 5:
                continue
            both_status = loss_frame[[a, b]].dropna()
            co_loss_rate = float(((both_status[a] == 1.0) & (both_status[b] == 1.0)).mean()) if len(both_status) else None
            pairs.append({
                'strategy_a': a, 'strategy_b': b,
                'name_a': STRATEGY_BY_ID.get(a, {}).get('name', a),
                'name_b': STRATEGY_BY_ID.get(b, {}).get('name', b),
                'return_correlation': round(float(c), 3),
                'co_loss_rate_pct': round(co_loss_rate * 100, 1) if co_loss_rate is not None else None,
                'overlapping_days': overlap_days,
                'highly_correlated': bool(abs(float(c)) >= 0.6),
            })
    pairs.sort(key=lambda p: abs(p['return_correlation']), reverse=True)
    return {
        'ok': True,
        'trading_days_covered': len(all_days),
        'strategies_covered': len(strategy_ids),
        'pairs': pairs,
        'highly_correlated_pairs': [p for p in pairs if p['highly_correlated']],
        'note': ("return_correlation is the Pearson correlation of each pair's DAILY net return, using only "
                 "days both strategies actually traded (days neither traded are excluded from that pair, not "
                 "treated as a zero return). co_loss_rate_pct is the share of those overlapping days where BOTH "
                 "strategies ended the day net-negative -- a high value means the pair is largely the same "
                 "underlying market bet, not two independent opinions, however different their entry rules look."),
    }


def compute_probability_calibration_report(market: Optional[str] = None, days: int = 90) -> Dict[str, Any]:
    """Report fix #9 -- out-of-sample probability calibration: the report's own
    framing is "does this system's probabilities mean anything", not "does the
    code contain the features". Buckets every replay trade that has BOTH a
    calibrated_win_prob_pct (the entry-time prediction) and a resolved outcome,
    by that predicted probability, and compares it to the ACTUAL win rate
    realized in each bucket -- the exact predicted-vs-actual table shape the
    report asks for.

    A well-calibrated system's rows sit close to the diagonal (a 55-60%-predicted
    bucket realizing roughly 55-60% actual wins). A large, one-directional drift
    across buckets means the probability number, however principled its
    derivation (see strategies._historical_edge / estimate_conditional_ev), isn't
    yet trustworthy as an actual probability.

    Uses net_return_pct > 0 as the win definition -- the same definition
    compute_strategy_performance already uses everywhere else in this app, so
    this table is directly comparable to the win rates shown elsewhere.

    NOTE ON SCOPE: this reports across the whole requested window, not yet split
    by a train/freeze/test date boundary (the fuller ask in report #11). Each
    trade's calibrated_win_prob_pct was already fixed at that trade's own entry
    time (see the INSERT that logs it), so this is genuinely out-of-sample with
    respect to that trade's own outcome; splitting by date is a natural follow-up
    once volume supports it without starving either half.
    """
    conn = get_db_connection()
    if conn is None:
        return {'ok': False, 'note': 'no database connection'}
    try:
        params: List[Any] = [days]
        market_filter = ''
        if market and market != 'all':
            market_filter = ' AND market = %s'
            params.append(market)
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"""
                SELECT calibrated_win_prob_pct, net_return_pct
                FROM intraday_replay_trades
                WHERE calibrated_win_prob_pct IS NOT NULL
                  AND net_return_pct IS NOT NULL
                  AND trading_date >= (CURRENT_DATE - (%s || ' days')::interval){market_filter}
            """, params)
            rows = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"[WARN] calibration report load failed: {e}")
        return {'ok': False, 'note': str(e)[:160]}
    finally:
        conn.close()

    if not rows:
        return {'ok': False, 'note': 'no trades yet with both a recorded predicted probability and a resolved outcome'}

    bucket_edges = [0.0, 50.0, 55.0, 60.0, 65.0, 70.0, 75.0, 80.0, 100.0001]
    buckets: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        p = _safe_float(r.get('calibrated_win_prob_pct'))
        ret = _safe_float(r.get('net_return_pct'))
        if p is None or ret is None:
            continue
        is_win = ret > 0
        label = '80-100%'
        for lo, hi in zip(bucket_edges, bucket_edges[1:]):
            if lo <= p < hi:
                label = f"{int(lo)}-{int(min(hi, 100))}%"
                break
        b = buckets.setdefault(label, {'trades': 0, 'wins': 0, 'predicted_sum': 0.0})
        b['trades'] += 1
        b['predicted_sum'] += p
        if is_win:
            b['wins'] += 1

    def _bucket_sort_key(label: str) -> float:
        try:
            return float(label.split('-')[0].rstrip('%'))
        except Exception:
            return 0.0

    table = []
    for label in sorted(buckets, key=_bucket_sort_key):
        b = buckets[label]
        n = b['trades']
        actual = round((b['wins'] / n) * 100, 1) if n else None
        predicted_avg = round(b['predicted_sum'] / n, 1) if n else None
        drift = round(actual - predicted_avg, 1) if (actual is not None and predicted_avg is not None) else None
        table.append({
            'predicted_bucket': label, 'predicted_avg_pct': predicted_avg,
            'actual_win_rate_pct': actual, 'trades': n,
            'thin_sample': n < 30,
            'drift_pct': drift,
        })
    total_trades = sum(b['trades'] for b in buckets.values())
    reliable_rows = [row for row in table if not row['thin_sample'] and row['drift_pct'] is not None]
    max_drift = max((abs(row['drift_pct']) for row in reliable_rows), default=None)
    return {
        'ok': True,
        'table': table,
        'total_trades': total_trades,
        'max_bucket_drift_pct_excluding_thin_buckets': max_drift,
        'note': ("Each bucket needs a real trade count to mean anything -- 'thin_sample' flags any bucket under "
                 "30 trades, the same evidence threshold (MIN_TRADES_FOR_EDGE) used everywhere else in this app. "
                 "drift_pct = actual_win_rate_pct - predicted_avg_pct; a large, consistently one-signed drift "
                 "across the non-thin buckets means the probabilities are miscalibrated in that direction, not "
                 "just noisy."),
    }


def _load_strategy_trade_rows_replay(market: Optional[str] = None, days: int = 90) -> List[Dict[str, Any]]:
    """Raw replay trades with strategy attribution (has full MAE/MFE + failure types)."""
    conn = get_db_connection()
    if conn is None:
        return []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            params: List[Any] = [days]
            market_filter = ''
            if market and market != 'all':
                market_filter = ' AND market = %s'
                params.append(market)
            cur.execute(f"""
                SELECT strategy_id, net_return_pct, net_pnl, mfe_pct, mae_pct, failure_type,
                       regime, entry_time, time_bucket, volatility_bucket, extension_bucket,
                       relative_strength_bucket
                FROM intraday_replay_trades
                WHERE strategy_id IS NOT NULL
                  AND trading_date >= (CURRENT_DATE - (%s || ' days')::interval){market_filter}
            """, params)
            return [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"[WARN] replay strategy rows load failed: {e}")
        return []
    finally:
        conn.close()


def _load_strategy_trade_rows_executed(mode: str, market: Optional[str] = None, days: int = 90) -> List[Dict[str, Any]]:
    """Raw paper/live trades with strategy attribution.

    These were completely absent from the Strategy Dashboard before: the dashboard
    only ever queried intraday_replay_trades, so a strategy could have a long live
    or paper record and still display as "no trades recorded yet". Executed
    positions do carry the selector's choice, but it lives inside the stored order
    payload (metadata_json -> candidate -> strategy_id) rather than in a column,
    which is why it needs extracting here.

    MFE/MAE and failure_type stay None for these rows on purpose -- they are only
    reconstructable from tick-by-tick replay, and inventing them for live trades
    would put fabricated numbers next to measured ones.
    """
    conn = get_db_connection()
    if conn is None:
        return []
    try:
        filters = ["status='CLOSED'", "horizon='intraday'", "mode=%s",
                   "COALESCE(closed_at, opened_at) >= (NOW() - (%s || ' days')::interval)"]
        params: List[Any] = [mode, days]
        if market and market != 'all':
            filters.append('market=%s')
            params.append(market)
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(f"""
                SELECT ticker, market, quantity, entry_price, exit_price, exit_reason,
                       gross_pnl_amount, cost_amount, net_pnl_amount, pnl_amount, pnl_pct, metadata_json
                FROM trade_positions
                WHERE {' AND '.join(filters)}
                ORDER BY COALESCE(closed_at, opened_at) DESC
                LIMIT 5000
            """, params)
            raw = [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"[WARN] executed strategy rows load failed ({mode}): {e}")
        return []
    finally:
        conn.close()

    rows: List[Dict[str, Any]] = []
    for r in raw:
        sid, sname = _strategy_from_metadata(r.get('metadata_json'))
        if not sid:
            continue
        qty = _safe_int(r.get('quantity'), 0)
        entry = _safe_float(r.get('entry_price'), 0) or 0.0
        exit_px = _safe_float(r.get('exit_price'))
        net = _safe_float(r.get('net_pnl_amount'))
        if net is None and exit_px is not None:
            net = calculate_net_trade_pnl(entry, exit_px, qty, r.get('market') or 'IN').get('net_pnl')
        if net is None:
            net = _safe_float(r.get('pnl_amount'), 0) or 0.0
        invested = entry * qty
        rows.append({
            'strategy_id': sid,
            'strategy_name': sname,
            'net_pnl': float(net),
            # Percent return is computed on capital actually put into the trade, so it
            # is directly comparable with replay's net_return_pct.
            'net_return_pct': round((float(net) / invested) * 100, 3) if invested else 0.0,
            'mfe_pct': None,
            'mae_pct': None,
            'failure_type': None,
            'exit_reason': r.get('exit_reason'),
        })
    return rows


def load_strategy_performance_from_db(market: Optional[str] = None, days: int = 90,
                                       source: str = 'blended',
                                       weights_spec: Optional[str] = None) -> Dict[str, Dict[str, Any]]:
    """Load recorded per-strategy performance for ONE execution source.

    source: 'blended' (the new default -- research + paper + live combined by trust
    weight, which is what the live SELECTOR now uses), or a single source:
    'replay', 'paper' or 'live'.

    The single-source modes are unchanged and are what the Strategy Dashboard
    still uses, deliberately: a strategy that is profitable in replay and
    unprofitable live is TWO facts, and a dashboard that averages them into one
    number destroys both. The selector, however, has to act -- it needs one
    posterior, not three -- so for that one caller the sources are combined with
    live weighted highest and replay lowest. See blend_strategy_performance().

    Returns {} on any failure -- the selector treats a missing record as 'unproven'
    and falls back to setup quality + regime fit, so a DB hiccup degrades the system
    to neutral rather than breaking the scan.
    """
    try:
        if source in ('blended', 'all'):
            # REPORT FIX ("Paper isn't currently feeding Live's strategy edge").
            # The live selector used to read source='replay' and nothing else, so a
            # strategy improving in Paper -- on real prices, against real costs --
            # changed Live's evidence base not at all. It now reads all three,
            # combined by trust weight rather than pooled (see
            # blend_strategy_performance for why those are different things).
            weights = parse_evidence_source_weights(weights_spec)
            per_source = {}
            for src, _w in weights:
                if src == 'replay':
                    per_source[src] = compute_strategy_performance(_load_strategy_trade_rows_replay(market, days))
                else:
                    per_source[src] = compute_strategy_performance(_load_strategy_trade_rows_executed(src, market, days))
            return blend_strategy_performance(per_source, weights)
        if source == 'replay':
            rows = _load_strategy_trade_rows_replay(market, days)
        elif source in ('paper', 'live', 'assisted'):
            rows = _load_strategy_trade_rows_executed(source, market, days)
        else:
            return {}
        return compute_strategy_performance(rows)
    except Exception as e:
        print(f"[WARN] strategy performance load failed ({source}): {e}")
        return {}


def parse_evidence_source_weights(spec: Optional[str] = None) -> List[Tuple[str, float]]:
    """Parse 'replay:0.4,paper:0.8,live:1.0' into trust-weighted sources."""
    raw = (spec if spec is not None else INTRADAY_STRATEGY_EVIDENCE_SOURCES) or ''
    out: List[Tuple[str, float]] = []
    for part in str(raw).split(','):
        part = part.strip()
        if not part:
            continue
        name, _, w = part.partition(':')
        name = name.strip().lower()
        if name not in ('replay', 'paper', 'live', 'assisted'):
            continue
        try:
            weight = float(w) if w.strip() else 1.0
        except ValueError:
            weight = 1.0
        if weight > 0:
            out.append((name, weight))
    return out


def blend_strategy_performance(per_source: Dict[str, Dict[str, Any]],
                               weights: List[Tuple[str, float]]) -> Dict[str, Dict[str, Any]]:
    """Combine research, paper and live evidence by TRUST WEIGHT.

    Report: "A strategy getting better in Paper does not automatically improve
    Live's selector... A better architecture would be research evidence + paper
    evidence + live evidence, with different trust weights rather than simply
    mixing their raw trades."

    That distinction is the whole point and it is why this is not a concatenation.
    Pooling raw trades would let 400 frictionless replay fills outvote 20 real
    ones; the previous behaviour (live reads ONLY replay, source='replay') went
    the other way and meant paper could improve indefinitely without live ever
    noticing. Here each source's trade COUNT is scaled by its trust weight before
    the posterior is formed, so:
      - live evidence is worth the most per trade (it has real fills and real costs),
      - paper next (real prices, simulated fills),
      - replay least (simulated everything, but there is a lot of it and it is the
        only evidence a new strategy has at all).
    Per-source records are preserved untouched under 'sources' so the dashboard can
    still show the three facts separately -- blending is for the SELECTOR, which
    needs one number, not for reporting, which must not hide disagreement.
    """
    blended: Dict[str, Dict[str, Any]] = {}
    all_ids = {sid for src in per_source.values() for sid in (src or {})}
    for sid in all_ids:
        w_trades = w_wins = 0.0
        w_win_sum = w_loss_sum = 0.0
        w_win_n = w_loss_n = 0.0
        raw_trades = 0
        net_pnl = 0.0
        contributing: List[Dict[str, Any]] = []
        merged_slices: Dict[str, Dict[str, Dict[str, Any]]] = {}
        name = sid
        for source, weight in weights:
            rec = (per_source.get(source) or {}).get(sid)
            if not rec:
                continue
            n = float(rec.get('total_trades') or 0)
            if n <= 0:
                continue
            name = rec.get('name') or name
            raw_trades += int(n)
            w_trades += n * weight
            w_wins += float(rec.get('wins') or 0) * weight
            net_pnl += float(rec.get('net_pnl') or 0)
            aw, al = rec.get('avg_winner_pct'), rec.get('avg_loser_pct')
            wins_n, losses_n = float(rec.get('wins') or 0), float(rec.get('losses') or 0)
            if aw is not None and wins_n:
                w_win_sum += abs(float(aw)) * wins_n * weight
                w_win_n += wins_n * weight
            if al is not None and losses_n:
                w_loss_sum += abs(float(al)) * losses_n * weight
                w_loss_n += losses_n * weight
            exp = rec.get('expectancy_pct_per_trade')
            # Context slices are merged so the conditional calibration above keeps
            # working on blended evidence, weighted the same way.
            for slice_key in ('by_regime', 'by_time_bucket', 'by_volatility', 'by_extension',
                              'by_relative_strength', 'by_regime_time'):
                for bucket, b in (rec.get(slice_key) or {}).items():
                    tgt = merged_slices.setdefault(slice_key, {}).setdefault(
                        str(bucket), {'trades': 0, 'wins': 0, 'net_pnl': 0.0,
                                      '_wsum': 0.0, '_wn': 0.0, '_lsum': 0.0, '_ln': 0.0})
                    bt = float(b.get('trades') or 0)
                    bw = float(b.get('wins') or 0)
                    bl = bt - bw
                    tgt['trades'] += bt * weight
                    tgt['wins'] += bw * weight
                    tgt['net_pnl'] += float(b.get('net_pnl') or 0)
                    if b.get('avg_winner_pct') is not None and bw:
                        tgt['_wsum'] += abs(float(b['avg_winner_pct'])) * bw * weight
                        tgt['_wn'] += bw * weight
                    if b.get('avg_loser_pct') is not None and bl:
                        tgt['_lsum'] += abs(float(b['avg_loser_pct'])) * bl * weight
                        tgt['_ln'] += bl * weight
            contributing.append({'source': source, 'weight': weight, 'trades': int(n),
                                 'win_rate_pct': rec.get('win_rate_pct'),
                                 'profit_factor': rec.get('profit_factor'),
                                 'expectancy_pct_per_trade': exp})
        if w_trades <= 0:
            continue
        for slice_key, buckets in merged_slices.items():
            for bucket, b in buckets.items():
                b['trades'] = int(round(b['trades']))
                b['wins'] = int(round(b['wins']))
                b['losses'] = max(0, b['trades'] - b['wins'])
                b['net_pnl'] = round(b['net_pnl'], 2)
                b['win_rate_pct'] = round((b['wins'] / b['trades']) * 100, 1) if b['trades'] else None
                b['avg_winner_pct'] = round(b['_wsum'] / b['_wn'], 3) if b['_wn'] else None
                b['avg_loser_pct'] = round(b['_lsum'] / b['_ln'], 3) if b['_ln'] else None
                for k in ('_wsum', '_wn', '_lsum', '_ln'):
                    del b[k]
        eff_trades = int(round(w_trades))
        eff_wins = int(round(w_wins))
        avg_win = round(w_win_sum / w_win_n, 3) if w_win_n else None
        avg_loss = round(w_loss_sum / w_loss_n, 3) if w_loss_n else None
        expectancy = None
        if avg_win is not None and avg_loss is not None and eff_trades:
            p = eff_wins / eff_trades
            expectancy = round(p * avg_win - (1 - p) * avg_loss, 3)
        _sources_label = ', '.join(f"{c['source']}x{c['weight']}" for c in contributing)
        # BUGFIX (report #3 -- blended PF math): profit factor must be built from
        # actual weighted positive/negative return totals, not from
        # "expectancy x trade_count" as a stand-in for gross wins/losses -- that proxy
        # silently produces a mathematically wrong PF (net expectancy is wins MINUS
        # losses already netted together; treating it as if it were the raw gross
        # win or gross loss total double-counts the netting and distorts the number
        # _historical_edge() then ranks strategies on). w_win_sum/w_loss_sum above are
        # already the correct ingredients: each source's (avg_winner_pct * wins) or
        # (avg_loser_pct * losses), trust-weighted -- i.e. weighted positive net
        # returns and weighted absolute negative net returns, exactly what PF needs.
        blended_profit_factor = round(w_win_sum / w_loss_sum, 2) if w_loss_sum > 0 else None
        entry = {
            'strategy_id': sid, 'name': name,
            'total_trades': eff_trades, 'raw_trades_all_sources': raw_trades,
            'wins': eff_wins, 'losses': max(0, eff_trades - eff_wins),
            'win_rate_pct': round((eff_wins / eff_trades) * 100, 1) if eff_trades else 0.0,
            'profit_factor': blended_profit_factor,
            'expectancy_pct_per_trade': expectancy,
            'net_pnl': round(net_pnl, 2),
            'avg_winner_pct': avg_win, 'avg_loser_pct': avg_loss,
            'proven': eff_trades >= MIN_TRADES_FOR_EDGE_DISPLAY,
            'evidence_note': (f'{raw_trades} raw trade(s) across {len(contributing)} source(s) -> {eff_trades} '
                              f'trust-weighted equivalent trades ({_sources_label})'),
            'evidence_sources': contributing,
            'blended': True,
        }
        entry.update(merged_slices)
        blended[sid] = entry
    return blended


STRATEGY_DASHBOARD_SOURCES = ('paper', 'live', 'replay')

STRATEGY_SOURCE_LABELS = {
    'paper': 'Paper',
    'live': 'Live',
    'replay': 'Replay',
}


def _strategy_source_metrics(perf: Dict[str, Any], sid: str, disabled: bool) -> Dict[str, Any]:
    """One source's measured record for one strategy, in display shape."""
    p = perf.get(sid) or {}
    return {
        'total_trades': p.get('total_trades', 0),
        'win_rate_pct': p.get('win_rate_pct'),
        'profit_factor': p.get('profit_factor'),
        'expectancy_pct_per_trade': p.get('expectancy_pct_per_trade'),
        'net_pnl': p.get('net_pnl'),
        'avg_winner_pct': p.get('avg_winner_pct'),
        'avg_loser_pct': p.get('avg_loser_pct'),
        'largest_loss_pct': p.get('largest_loss_pct'),
        'avg_mfe_pct': p.get('avg_mfe_pct'),
        'avg_mae_pct': p.get('avg_mae_pct'),
        'failure_breakdown': p.get('failure_breakdown') or {},
        'proven': p.get('proven', False),
        'evidence_note': p.get('evidence_note', 'no trades recorded yet'),
        'status': _strategy_status(p, disabled),
    }


@app.route('/api/intraday/strategies', methods=['GET'])
def api_intraday_strategies():
    """Strategy Dashboard data, reported SEPARATELY for paper, live and replay.

    This used to read only intraday_replay_trades, which meant paper and live
    results never appeared anywhere on the dashboard -- and, worse, that a
    strategy's replay record was silently presented as if it were the strategy's
    record, full stop. The three are different experiments with different fill
    assumptions and different costs, so each now gets its own independent column
    and they are never averaged together.

    ?source=paper|live|replay|all (default all). The flat top-level 'strategies'
    fields mirror the primary source (the requested one, or replay when 'all') so
    older clients keep working; 'by_source' carries all three.
    """
    market = request.args.get('market') or (get_intraday_settings().get('market') or 'IN')
    days = int(request.args.get('days') or 90)
    requested = str(request.args.get('source') or 'all').strip().lower()
    if requested not in STRATEGY_DASHBOARD_SOURCES and requested != 'all':
        requested = 'all'
    wanted = list(STRATEGY_DASHBOARD_SOURCES) if requested == 'all' else [requested]
    primary = 'replay' if requested == 'all' else requested

    perf_by_source = {s: load_strategy_performance_from_db(market, days, source=s) for s in wanted}
    settings = get_intraday_settings()
    disabled = [s.strip() for s in str(settings.get('disabled_strategies') or '').split(',') if s.strip()]

    rows = []
    for spec in STRATEGIES:
        sid = spec['id']
        is_disabled = sid in disabled
        by_source = {s: _strategy_source_metrics(perf_by_source.get(s) or {}, sid, is_disabled) for s in wanted}
        primary_metrics = by_source.get(primary) or _strategy_source_metrics({}, sid, is_disabled)
        rows.append({
            'strategy_id': sid,
            'name': spec['name'],
            'description': spec['description'],
            'regime_fit': spec['regime_fit'],
            'manually_disabled': is_disabled,
            'by_source': by_source,
            'total_trades_all_sources': sum(int((by_source[s] or {}).get('total_trades') or 0) for s in wanted),
            # Flattened primary-source view (backwards compatible).
            **primary_metrics,
        })
    # Sort by evidence anywhere, then by the primary source's profit factor, so a
    # strategy that has only ever traded live still rises above one with no record.
    rows.sort(key=lambda r: (r['total_trades_all_sources'] > 0, r.get('profit_factor') or 0), reverse=True)

    totals = {s: sum(int((perf_by_source.get(s) or {}).get(sid, {}).get('total_trades') or 0) for sid in STRATEGY_BY_ID)
              for s in wanted}
    return jsonify({'ok': True, 'strategies': rows, 'market': market, 'days': days,
                    'source': requested, 'primary_source': primary, 'sources': wanted,
                    'source_labels': {s: STRATEGY_SOURCE_LABELS.get(s, s) for s in wanted},
                    'source_trade_totals': totals,
                    'min_trades_for_confidence': MIN_TRADES_FOR_EDGE_DISPLAY,
                    'multi_strategy_enabled': INTRADAY_MULTI_STRATEGY_ENABLED,
                    'selector_evidence_source': 'replay',
                    'note': ('Paper, live and replay are measured separately and never averaged. '
                              'MFE/MAE and failure types are reconstructable only from tick-by-tick replay, '
                              'so those columns stay empty for paper/live rather than being estimated. '
                              'The live selector still uses the replay record as its evidence base.')})


