def _strategy_status(perf: Dict[str, Any], disabled: bool) -> str:
    if disabled:
        return 'disabled'
    n = int(perf.get('total_trades') or 0)
    if n == 0:
        return 'untested'
    pf = perf.get('profit_factor')
    if n < MIN_TRADES_FOR_EDGE_DISPLAY:
        return 'unproven'
    if pf is None:
        return 'unproven'
    if pf >= 1.3:
        return 'good'
    if pf >= 1.0:
        return 'marginal'
    return 'poor'


@app.route('/api/intraday/failure-patterns', methods=['GET'])
def api_intraday_failure_patterns():
    """Recurring weaknesses across recorded trades, with testable hypotheses.

    Every recommendation here is a candidate to BACKTEST, never an applied change --
    strategy modifications go through evidence -> hypothesis -> out-of-sample test ->
    approval, not through automatic self-editing after a bad day.
    """
    days = int(request.args.get('days') or 90)
    market = request.args.get('market')
    # Failure-pattern analysis needs MFE/MAE and classified failure types, which only
    # replay records. Paper/live rows are still surfaced as a count so the panel says
    # so plainly instead of looking like those trades had no failures.
    source = str(request.args.get('source') or 'replay').strip().lower()
    conn = get_db_connection()
    if conn is None:
        return jsonify({'ok': False, 'error': 'database unavailable'}), 503
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            params: List[Any] = [days]
            market_filter = ''
            if market and market != 'all':
                market_filter = ' AND market = %s'
                params.append(market)
            cur.execute(f"""
                SELECT ticker, strategy_id, net_return_pct, mfe_pct, mae_pct,
                       signal_fill_gap_pct, exit_reason, failure_type, diagnosis, suggested_focus
                FROM intraday_replay_trades
                WHERE trading_date >= (CURRENT_DATE - (%s || ' days')::interval){market_filter}
            """, params)
            trades = [dict(r) for r in cur.fetchall()]
    finally:
        conn.close()
    for t in trades:
        for k in ('net_return_pct', 'mfe_pct', 'mae_pct', 'signal_fill_gap_pct'):
            if t.get(k) is not None:
                t[k] = float(t[k])
    patterns = summarize_failure_patterns(trades)
    executed_counts = {}
    if source in ('all', 'paper', 'live'):
        for mode in (('paper', 'live') if source == 'all' else (source,)):
            executed_counts[mode] = len(_load_strategy_trade_rows_executed(mode, market, days))
    return jsonify({'ok': True, 'patterns': patterns, 'trades_analyzed': len(trades), 'days': days,
                    'source': 'replay', 'executed_trade_counts': executed_counts,
                    'note': ('Each recommendation is a hypothesis to backtest, not an applied change. '
                             'Patterns need at least 4 occurrences before they appear here. '
                             'This analysis is replay-only: MFE/MAE and failure classification cannot be '
                             'reconstructed from executed paper/live trades.')})


@app.route('/api/intraday/settings', methods=['POST'])
def intraday_settings_endpoint():
    body = request.get_json(silent=True) or {}
    settings = save_intraday_settings(body)
    clamped = settings.get('clamped_warnings') or []
    notice = 'Intraday settings saved. Claude can review/control paper intraday entries only when enabled; hard cost/risk gates still run before any order.'
    if clamped:
        notice += ' WARNING - some values were outside their allowed range and were adjusted: ' + '; '.join(clamped)
    return jsonify({
        'ok': True,
        'settings': settings,
        'clamped_warnings': clamped,
        'notice': notice,
    })


@app.route('/api/intraday/run', methods=['POST'])
def intraday_run_endpoint():
    body = request.get_json(silent=True) or {}
    trigger = str(body.get('trigger') or 'manual')[:40]
    try:
        result = run_intraday_engine(trigger=trigger)
        status = 500 if result.get('error') else 200
        return jsonify(result), status
    except Exception as e:
        print(f"[ERROR] Intraday run crashed: {e}")
        settings = get_intraday_settings()
        trading_settings = get_intraday_effective_trading_settings(get_trading_settings(), settings)
        market = settings.get('market') or 'IN'
        session = get_intraday_session_state(settings)
        started_at = utc_now_naive()
        result = finalize_intraday_result({
            'ok': False,
            'error': str(e)[:300],
            'trigger': trigger,
            'settings': settings,
            'trading_settings': trading_settings,
            'session': session,
            'candidates': [],
            'watch': [],
            'orders': [],
            'errors': [str(e)[:300]],
            'data_source': get_market_data_source_info(market, 'intraday_engine_check'),
            'message': 'Intraday run failed safely. No order was placed. Check the error shown in the latest cycle.',
        }, started_at)
        return jsonify(result), 200


