@app.route('/api/capital-report', methods=['GET'])
def capital_report_endpoint():
    """Capital & P&L breakdown for a selected period, per execution mode.

    Query params:
        source   paper|live|replay|all (repeatable, or comma-separated). Default all.
        start    YYYY-MM-DD (inclusive)         end   YYYY-MM-DD (inclusive)
        capital  starting capital for the period; defaults to the intraday
                 simulation capital currently configured.
        market   defaults to the configured intraday market.
        run_id   restrict the replay side to a single replay run.
        engine   'intraday' (default) or 'all' to include swing/delivery positions.
    """
    raw_sources = request.args.getlist('source') or []
    if len(raw_sources) == 1 and ',' in raw_sources[0]:
        raw_sources = raw_sources[0].split(',')
    sources = [s.strip().lower() for s in raw_sources if s.strip()]
    if not sources or 'all' in sources:
        sources = list(CAPITAL_REPORT_SOURCES)
    capital_arg = request.args.get('capital')
    try:
        capital = float(capital_arg) if capital_arg not in (None, '') else None
    except ValueError:
        capital = None
    run_id_arg = request.args.get('run_id')
    try:
        run_id = int(run_id_arg) if run_id_arg not in (None, '') else None
    except ValueError:
        run_id = None
    engine = 'all' if str(request.args.get('engine') or 'intraday').lower() == 'all' else 'intraday'
    try:
        result = get_capital_performance_report(
            sources=sources,
            start_date=request.args.get('start'),
            end_date=request.args.get('end'),
            starting_capital=capital,
            market=request.args.get('market'),
            run_id=run_id,
            engine=engine,
        )
        return jsonify(json.loads(json.dumps(result, default=_json_safe)))
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


