@app.route('/api/intraday/exit-calibration', methods=['GET'])
def exit_calibration_status_endpoint():
    """What trailing-stop calibration is CURRENTLY APPLIED, and where it came from.

    Report issue #7 was that calibration existed only as a suggestion. This
    endpoint answers "is it actually deployed" with the promoted table contents
    rather than a recommendation.
    """
    active = load_active_exit_calibration()
    return jsonify(json.loads(json.dumps({
        'ok': True,
        'auto_apply_enabled': INTRADAY_EXIT_CALIBRATION_AUTO_APPLY,
        'min_profit_factor_gain_required': INTRADAY_EXIT_CALIBRATION_MIN_PF_GAIN,
        'applied': active,
        'applied_count': len(active),
        'global_default': {'trailing_stop_activation_pct': TRAILING_STOP_ACTIVATION_PCT,
                           'trailing_stop_giveback_pct': TRAILING_STOP_GIVEBACK_PCT},
        'note': ('Strategies listed under "applied" use their own validated trailing rule in live, paper and replay. '
                 'Everything else uses the global default. A calibration only appears here after beating a baseline '
                 'on days it was not measured on -- see POST /api/intraday/exit-calibration/validate.'),
    }, default=_json_safe))), 200


@app.route('/api/intraday/exit-calibration/validate', methods=['POST'])
def exit_calibration_validate_endpoint():
    """Validate a candidate calibration out-of-sample and, if it wins, DEPLOY it.

    Body: {"baseline_run_id": N, "validation_run_id": M, "auto_promote": true}
    Both runs must have finished and must cover identical trading days -- the
    validation run being the one started with exit_calibration_override set.
    """
    body = request.get_json(silent=True) or {}
    try:
        baseline_run_id = int(body['baseline_run_id'])
        validation_run_id = int(body['validation_run_id'])
    except (KeyError, TypeError, ValueError):
        return jsonify({'ok': False, 'error': 'baseline_run_id and validation_run_id (integers) are required.'}), 400
    result = validate_exit_calibration_out_of_sample(
        baseline_run_id, validation_run_id, auto_promote=bool(body.get('auto_promote', True)))
    return jsonify(json.loads(json.dumps(result, default=_json_safe))), (200 if result.get('ok') else 400)


@app.route('/api/intraday/exit-calibration/promote', methods=['POST'])
def exit_calibration_promote_endpoint():
    """Manual override: promote a calibration without the automated validation
    step. Deliberately separate from the validated path so an unvalidated
    deployment is always a conscious, attributable act rather than something that
    can happen by accident."""
    body = request.get_json(silent=True) or {}
    calibration = body.get('calibration')
    if not isinstance(calibration, dict) or not calibration:
        return jsonify({'ok': False, 'error': 'calibration object is required.'}), 400
    result = promote_exit_calibration(
        calibration, body.get('baseline_run_id'), body.get('validation_run_id'),
        note=body.get('note') or 'Manually promoted without automated out-of-sample validation.')
    return jsonify(result), (200 if result.get('ok') else 400)


@app.route('/api/intraday/exit-calibration', methods=['DELETE'])
def exit_calibration_clear_endpoint():
    """Revert every strategy to the global trailing rule."""
    conn = get_db_connection()
    if conn is None:
        return jsonify({'ok': False, 'error': 'DATABASE_URL not set.'}), 500
    try:
        with conn, conn.cursor() as cur:
            cur.execute('DELETE FROM strategy_exit_calibration')
            removed = cur.rowcount
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500
    finally:
        conn.close()
    with _EXIT_CALIB_CACHE_LOCK:
        _EXIT_CALIB_CACHE['value'] = None
        _EXIT_CALIB_CACHE['loaded_at'] = None
    return jsonify({'ok': True, 'removed': removed,
                    'message': f'{removed} promoted calibration(s) removed; all strategies back on the global rule.'}), 200


@app.route('/api/intraday/session-state', methods=['GET'])
def intraday_session_state_endpoint():
    """The FAST adaptation layer's current view: what has closed today, which
    strategies are suspended right now, and whether the session de-risk/halt has
    engaged (report issue #5)."""
    market = request.args.get('market') or 'IN'
    mode = request.args.get('mode')
    try:
        settings = get_intraday_settings()
        trades = load_today_session_trades(market, mode)
        capital = float(get_simulation_capital_for_market(settings, market) or 0)
        risk_state = assess_session_risk_state(
            trades, capital, derisk_pct=INTRADAY_SESSION_DERISK_DRAWDOWN_PCT,
            stop_pct=INTRADAY_SESSION_STOP_DRAWDOWN_PCT)
        per_strategy = {}
        for spec in STRATEGIES:
            assessment = assess_session_adaptation(
                trades, spec['id'], now=utc_now_naive(),
                config={'loss_streak': INTRADAY_FAST_ADAPT_LOSS_STREAK,
                        'timeout_minutes': INTRADAY_FAST_ADAPT_TIMEOUT_MINUTES,
                        'max_losses_per_day': INTRADAY_FAST_ADAPT_MAX_LOSSES_PER_DAY})
            if assessment.get('block') or assessment.get('losses_today'):
                per_strategy[spec['id']] = {'name': spec['name'], **assessment}
        budget = IntradayRiskBudget(capital=capital)
        return jsonify(json.loads(json.dumps({
            'ok': True, 'market': market,
            'fast_adaptation_enabled': INTRADAY_FAST_ADAPT_ENABLED,
            'closed_trades_today': len(trades),
            'session_risk_state': risk_state,
            'suspended_or_bleeding_strategies': per_strategy,
            'risk_budget_config': budget.summary(),
            'note': ('This layer reacts within the session. The slow layer (strategy expectancy, health state, '
                     'auto-bench) still only updates across days, on validated evidence.'),
        }, default=_json_safe))), 200
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


